def importasdm2(asdm, intent=''):
    """
    Translates a specified intent into a list of scans and then only imports those
    scans into a measurement set.
    """
    f = open(asdm+'/Scan.xml')
    fc = f.read()
    f.close()

    scanBlockList = re.findall('<row>.+?</row>', fc, re.DOTALL|re.MULTILINE)

    scanNumList = []

    for i in range(len(scanBlockList)):
        scanBlocksIntents = re.findall('<scanIntent>.+?</scanIntent>', scanBlockList[i])[0]
        if re.search(intent, scanBlocksIntents) is not None:
            scanNum1 = re.findall('<scanNumber>[0-9]+</scanNumber>', scanBlockList[i])
            if len(scanNum1) != 1: continue
            scanNum1 = re.findall('[0-9]+', scanNum1[0])
            if len(scanNum1) != 1: continue
            scanNumList.append(scanNum1[0])

    scanNumList = ','.join(scanNumList)

    importasdm(asdm, scans=scanNumList)

def readwvr(sdmfile, returnPathDict=False, verbose=False):
    """
    This function reads the CalWVR.xml table from the ASDM and returns a
    dictionary containing: 'start', 'end', 'startmjd', 'endmjd',
    'startmjdsec', 'endmjdsec',
    'timerange', 'antenna', 'water', 'duration'.
    'water' is the zenith PWV in meters.
    if returnPathDict is True, it also returns 'pathCoeff' as a second
    dictionary keyed by antenna.
    This function is called by readpwv(). -- Todd Hunter
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    """
    if (not os.path.exists(sdmfile)):
        print("readwvr(): Could not find file = ", sdmfile)
        return
    if not asdmLibraryAvailable:
        scandict, pathDict = au_noASDMLibrary.readwvr_minidom(sdmfile)
    else:
        myqa = createCasaTool(qatool)
        scandict = {}
        pathDict = {}
        fid = 0
        a = ASDM()
        parser = ASDMParseOptions()
        parser.asALMA()
        parser.loadTablesOnDemand(True)
        a.setFromFile(sdmfile,parser)
        calWVRTable = a.calWVRTable().get()
        for row in calWVRTable:
            scandict[fid] = {}
            startmjdsec = row.startValidTime().get()*1e-9
            endmjdsec = row.endValidTime().get()*1e-9
            water = row.water().get()
            pathCoeff = row.pathCoeff()[0]
            antenna = row.antennaName().strip()
            if antenna not in pathDict.keys():
                pathDict[antenna] = [[]]*4
            for i in range(4): # loop over 4 channels
                pathDict[antenna][i] = pathDict[antenna][i] + [pathCoeff[i][0]]
            scandict[fid]['startmjdsec'] = startmjdsec
            scandict[fid]['startmjd'] = startmjdsec/86400.
            scandict[fid]['endmjdsec'] = endmjdsec
            scandict[fid]['endmjd'] = endmjdsec/86400.
            t = myqa.quantity(endmjdsec/86400.,'d')
            endtime = call_qa_time(t,form="ymd",prec=8)
            t = myqa.quantity(startmjdsec/86400.,'d')
            starttime = call_qa_time(t,form="ymd",prec=8)
            scandict[fid]['start'] = starttime
            scandict[fid]['end'] = endtime
            scandict[fid]['antenna'] = antenna
            scandict[fid]['water'] = water
            scandict[fid]['duration'] = endmjdsec-startmjdsec
            scandict[fid]['timerange'] = starttime+'~'+endtime
            fid += 1
        myqa.done()
    if verbose: print('  Found ',rowlist.length,' rows in CalWVR.xml')
    # return the dictionary for later use
    if returnPathDict:
        return scandict, pathDict
    else:
        return scandict

def plotwvr(sdmfile, antenna=None, channel=None, scaleFactor=1000):
    """
    Calls readwvr and plots the pathCoeff
    antenna:  'DV24' or None to make a plot page for all of them
    channel: 0..3 or None to show all of them in different colors
    """
    if not os.path.exists(sdmfile):
        print("Could not open ASDM: ", sdmfile)
        return
    scandict, pathCoeffDict = readwvr(sdmfile, True)
    if antenna is not None:
        antennas = [antenna.strip()]
    else:
        antennas = list(pathCoeffDict.keys())
        antennas = [a.strip() for a in antennas]
    pngs = []
    # find common y-axis limits
    if channel is None:
        y0 = []; y1 = []
        for antenna in antennas:
            pb.clf()
            for chan in range(4):
                y = np.array(pathCoeffDict[antenna][chan])*scaleFactor
                x = range(len(y))
                pb.plot(x,y,'k-')
            y0.append(pb.ylim()[0])
            y1.append(pb.ylim()[1])
        y0 = np.min(y0)
        y1 = np.max(y1)
    for antenna in antennas:
        pb.clf()
        if channel is not None:
            y = np.array(pathCoeffDict[antenna][channel])*scaleFactor
            x = range(len(y))
            pb.plot(x,y,'ko-')
            y0 = np.median(y) - 4*MAD(y)
            y1 = y0 + 8*MAD(y)
            pb.ylim([y0,y1])
        else:
            for chan in range(4):
                y = np.array(pathCoeffDict[antenna][chan])*scaleFactor
                x = range(len(y))
                pb.plot(x,y,'-',color=overlayColors[chan])
            pb.ylim([y0,y1])
        title = '%s, %s' % (os.path.basename(sdmfile),antenna)
        if channel is not None:
            title += ', channel %d' % (channel)
        pb.title(title)
        pb.xlabel('Solution number')
        pb.ylabel('Coefficient (in units of %.e)'%(1./scaleFactor))
        pb.draw()
        plotfile = sdmfile + '_wvrPathCoeff_%s.png' % (antenna)
        pb.savefig(plotfile)
        pngs.append(plotfile)
        print("Wrote ", plotfile)
    buildPdfFromPngs(pngs, pdfname='%s_wvrPathCoeff.pdf'%(os.path.basename(sdmfile)))

def readpwv(asdm, useMinidom=False, verbose=False):
    """
    This function returns arrays containing the PWV measurements written 
    by TelCal into the ASDM. Units are in meters.
    It will use the ASDM python bindings if available, otherwise it will
    assemble the dictionary returned by readwvr_minidom().
    verbose: if True, then print all duplicate entries, and also pass this flag
           to readwvr_minidom()
    Called by plotPWVFromASDM()
    useMinidom: if True, then parse the .xml file even if the ASDM python
                bindings are available
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    -- Todd Hunter
    """
    if not os.path.exists(asdm):
        print("readpwv(): Could not open ASDM: ", asdm)
        return
    watertime = []
    water = []
    antenna = []
    duplicates = 0
    if not asdmLibraryAvailable or useMinidom:
        import au_noASDMLibrary
        scandict, pathdict = au_noASDMLibrary.readwvr_minidom(asdm, verbose)
        dict = scandict
        for entry in dict:
            measurements = 1
            for i in range(measurements):
                newAntenna = dict[entry]['antenna'].strip() # remove spaces added in 2017
                newTime = dict[entry]['startmjdsec']+(i*1.0/measurements)*dict[entry]['duration']
                newWater = dict[entry]['water']
                idx1 = np.where(np.array(antenna, dtype=str) == newAntenna)[0]
                idx2 = np.where(np.array(watertime) == newTime)[0]
                idx3 = np.where(np.array(water) == newWater)[0]
                if len(np.intersect1d(idx1,idx2,idx3)) > 0:
                    if verbose:
                        print("Found duplicate entry: ", newAntenna, newTime, newWater)
                    duplicates += 1
                watertime.append(newTime)
                water.append(newWater)
                antenna.append(newAntenna)
    else:
        a = ASDM()
        parser = ASDMParseOptions()
        parser.asALMA()
        parser.loadTablesOnDemand(True)
        a.setFromFile(asdm,parser)
        calWVRTable = a.calWVRTable().get()
        for row in calWVRTable:
            startmjdsec = row.startValidTime().get()*1e-9
            endmjdsec = row.endValidTime().get()*1e-9
            waterValue = row.water().get()
            newAntenna = row.antennaName().strip()
            idx1 = np.where(np.array(antenna, dtype=str) == newAntenna)[0]
            idx2 = np.where(np.array(watertime) == startmjdsec)[0]
            idx3 = np.where(np.array(water) == waterValue)[0]
            if len(np.intersect1d(idx1,idx2,idx3)) > 0:
                if verbose:
                    print("Found duplicate entry: ", newAntenna, startmjdsec, waterValue)
                duplicates += 1
            antenna.append(newAntenna)
            watertime.append(startmjdsec)
            water.append(waterValue)
    if duplicates > 0:
        print("Found %d duplicates out of %d entries" % (duplicates, len(water)))
    return([watertime,water,antenna])   

def readSysCal(asdm, useMinidom=False):
    """
    This function reads the SysCal.xml table from the ASDM and checks
    how many Tsys entries there are for each combination of Antenna,
    time and spw (which should be 1). Reports the number of duplicates
    and returns a dictionary keyed by [antenna][spw] = list of timestamps
    useMinidom: if True, then parse the .xml file even if the ASDM python
                bindings are available
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    -- Todd Hunter
    """
    if (os.path.exists(asdm) == False):
        print("readSysCal(): Could not find file = ", asdm)
        return
    if not asdmLibraryAvailable or useMinidom:
        import au_noASDMLibrary
        scandict = au_noASDMLibrary.readSysCal_minidom(asdm)
    else:
        scandict = {}
        duplicates = 0
        a = ASDM()
        parser = ASDMParseOptions()
        parser.asALMA()
        parser.loadTablesOnDemand(True)
        a.setFromFile(asdm,parser)
        syscalTable = a.sysCalTable().get()
        for row in syscalTable:
            antennaId = row.antennaId().get()
            if antennaId not in scandict:
                scandict[antennaId] = {}
            spwID = row.spectralWindowId().get()
            if spwID not in scandict[antennaId]:
                scandict[antennaId][spwID] = []
            mjdsec = convertASDMTimeIntervalToMJDSeconds(str(row.timeInterval()))
            if mjdsec in scandict[antennaId][spwID]:
                print("Duplicate seen!")
                duplicates += 1
            else:
                scandict[antennaId][spwID].append(mjdsec)
        print('  Found ',len(syscalTable),' Tsys rows in SysCal.xml')
        if len(syscalTable) > 0:
            print("%d duplicates found" % (duplicates))
    return (scandict)

def replaceTsysFromSQLD(caltable, sqld, asdm, spws, verbose=False):
    """
    This is a utility to replace the Tsys spectrum for one combination
    of antenna+spw+pol+scan with the median value from the square law 
    detector Tsys located in the SysCal.xml table.
    Typically, the SysCal.xml table was produced manually by running 
    casapy-telcal offline.

    caltable: the name of the gencal-produced Tsys cal table to correct
    sqld: the path to the SysCal.xml file to get the SQLD Tsys values from
    asdm: the path to the original ASDM (with SpectralWindow.xml and Scan.xml) 
    spws: a list of spws to replace (in order of baseband number).  The number of
          spws specified must match the number of SQLDs in the SysCal.xml file.
    - Todd Hunter
    """
    tsys = getTsysFromSysCal(asdm, sqld) # binary-ready
    if tsys is None:
        return
    values = 0
    if (type(spws) == str):
        spws = spws.split(',')
    changeFactor = []
    for antenna in list(tsys.keys()):
        for spw in list(tsys[antenna].keys()):
            baseband = tsys[antenna][spw]['baseband']-1 # 1..4  converted here to 0..3
            for scan in list(tsys[antenna][spw]['scans'].keys()):
                for pol in list(tsys[antenna][spw]['scans'][scan].keys()):
                    if (pol == 0): polarization = 'X'
                    if (pol == 1): polarization = 'Y'
                    if (verbose):
                        print("Calling replaceTsysScan('%s', antenna=%d, spw=%d, pol='%s', fromscan=%d, toscan=%d, newvalue=%f)" % (caltable, antenna, int(spws[baseband]), polarization, scan, scan, np.median(tsys[antenna][spw]['scans'][scan][pol])))
                    replaced, change = replaceTsysScan(caltable, antenna, int(spws[baseband]), polarization, scan, scan, tsys[antenna][spw]['scans'][scan][pol],verbose=verbose)
                    values += replaced
                    if (replaced > 0):
                        changeFactor.append(change)
    print("Replaced %d values with a median change of a factor of %f" % (values,np.median(changeFactor)))

def getMedianTsys(asdmlist, verbose=False, useMinidom=False):
    """
    Gets the median Tsys value for each ASDM in a list, using getTsysFromSysCal.
    asdmlist: either a list of strings or a single string with wildcard character(s).
          Files containing .ms and those not starting with uid___ are ignored.
          If the string does not have a wildcard character, then interpret it as a single file.
          If the file is not a directory (i.e. not an ASDM), then interpret it as a file that
            contains a list of ASDMs to process.
    Returns:
    if a wildcard is given: returns a dictionary of Tsys values keyed by ASDM name
    otherwise: returns the single median Tsys value
    useMinidom: if True, then parse the .xml file even if the ASDM python
            bindings are available; This option only works for very old ALMA 
            data when SysCal.xml contained all the data instead of SysCal.bin
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    -Todd Hunter
    """
    wildcardPresent = False
    if (type(asdmlist) == str):
        if (asdmlist.find('*') >= 0):
            wildcardPresent = True
            asdmlist = glob.glob(asdmlist)
        elif (os.path.isdir(asdmlist)):
            asdmlist = [asdmlist]
        elif (os.path.exists(asdmlist)):
            asdmlist = getListOfFilesFromFile(asdmlist, appendms=False)
        else:
            print("File not found")
            return
    tsysdict = {}
    tsys = None
    for asdm in asdmlist:
        basename = os.path.basename(asdm.rstrip('/'))
        if (basename.find('.') < 0 and basename.find('uid___')==0):
            tsys = getTsysFromSysCal(asdm, median=True, verbose=verbose, useMinidom=useMinidom)
            if tsys is None:
                return
            tsys = tsys['median']
            tsysdict[asdm] = tsys
            print("%s:  %f" % (asdm,tsys))
        else:
            print("getMedianTsys(): Skipping file=%s because it is probably not an ASDM" % (basename))
    if (len(tsysdict) < 2 and not wildcardPresent):
        return(tsys)
    else:
        return(tsysdict)
    
def getMedianTsysForChannel(asdm, channel, spw, useMinidom=False):
    """
    Computes the median over all antennas of a single Tsys channel in one spw 
    in one ASDM.
    useMinidom: if True, then parse the .xml file even if the ASDM python
            bindings are available; This option only works for very old ALMA 
            data when SysCal.xml contained all the data instead of SysCal.bin
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    -Todd Hunter
    """
    mydict = getTsysFromSysCal(asdm, median=True, channel=channel, useMinidom=useMinidom)
    if mydict is None:
        return
    tsys = []
    for antenna in list(mydict.keys()):
        if (antenna != 'median'): 
            tsys.append(mydict[antenna][spw]['median'])
    return(np.median(tsys))

def doubleIntervalInSysCal(vis, rows=range(32,64), factor=2, shift=0.5, 
                           dryrun=False):
    """
    Double the INTERVAL in SYSCAL table, and shift *earlier* by prior
    interval.
    rows: list of rows to change (None means all rows)
    factor: value by which to multiply the interval
    shift: fraction of original interval to shift the TIME column
    -Todd Hunter
    """
    if not os.path.exists(vis):
        print("Could not find measurement set: ", vis)
        return
    mytb = tbtool()
    mytb.open(os.path.join(vis,'SYSCAL'), nomodify=False)
    if rows is None:
        i = mytb.getcol('INTERVAL')
        new = i*factor
        if dryrun:
            print("New interval would be", new)
        else:
            mytb.putcol('INTERVAL',new)
    else:
        for row in rows:
            i = mytb.getcell('INTERVAL', row)
            new = i*factor
            if dryrun:
                print("New interval would be", new)
            else:
                mytb.putcell('INTERVAL', row, new)
    mytb.close()
    if dryrun:
        print("Shift would be %f" % (-i*shift))
    else:
        adjustStartTimeInSysCal(vis, addSeconds=-i*shift, rows=rows) 
    
def adjustStartTimeInSysCal(vis, addSeconds=-1, rows=None):
    """
    Adds the specified number of seconds to the TIME value for each row of the SYSCAL table
    of a measurement set.
    rows: list of rows to change (None means all rows)
    -Todd Hunter
    """
    if not os.path.exists(vis):
        print("Could not find measurement set: ", vis)
        return
    mytb = tbtool()
    mytb.open(os.path.join(vis,'SYSCAL'), nomodify=False)
    if rows is None:
        i = mytb.getcol('TIME')
        i += addSeconds
        mytb.putcol('TIME',i)
    else:
        for row in rows:
            i = mytb.getcell('TIME', row)
            i += addSeconds
            mytb.putcell('TIME',row,i)
    mytb.close()

def extendIntervalInSysCal(vis, addSeconds=1):
    """
    Adds the specified number of seconds to the valid interval for each row of the SYSCAL table
    of a measurement set.
    -Todd Hunter
    """
    if not os.path.exists(vis):
        print("Could not find measurement set: ", vis)
        return
    mytb = tbtool()
    mytb.open(os.path.join(vis,'SYSCAL'), nomodify=False)
    i = mytb.getcol('INTERVAL')
    i += addSeconds
    mytb.putcol('INTERVAL',i)
    mytb.close()

def getFlagPercentageOutliersInTsysScans(vis):
    """
    Returns dictionary of flagging percentage of Tsys scans, keyed by antenna , spw and scan.
    Would like to search for antennas that have more flagging of Tsys integrations than the median amount
    but unfortunately pipeline flags all the Tsys data, so can only run it on raw data.
    """
    import analyzemscal as amc
    if not os.path.exists(vis):
        print("Could not find measurement set: ", vis)
        return
    mydict = {}
    mymsmd = createCasaTool(msmdtool)
    mymsmd.open(vis)
    scans = mymsmd.scansforintent('*ATMOSPHERE*')
    spws = np.intersect1d(callalmaspws(mymsmd,tdm=True,fdm=True),callspwsforintent(mymsmd, '*ATMOSPHERE*'))
    mymsmd.close()
    antennas = getAntennaNames(vis)
    for antenna in antennas:
        mydict[antenna] = {}
        for spw in spws:
            mydict[antenna][spw] = {}
            for scan in scans:
                mydict[antenna][spw][scan] = amc.getFlagdict(vis,scan=str(scan),antenna=antenna,percentOnly=True,spw=str(spw))['antenna'][antenna]['percent']
    return mydict
    
def getSpwsFromSysCal(vis):
    """
    Returns the sorted list of unique spw IDs in the SYSCAL table of a measurement set.
    """
    if not os.path.exists(vis):
        print("Could not find measurement set: ", vis)
        return
    mytb = tbtool()
    mytable = os.path.join(vis,'SYSCAL')
    if not os.path.exists(mytable):
        print("Could not find SYSCAL table")
        return
    mytb.open(mytable)
    spw = sorted(np.unique(mytb.getcol('SPECTRAL_WINDOW_ID')))
    mytb.close()
    return spw

def getTsysFromSysCal(asdm, sqld=None, median=False, verbose=True,
                      channel=None, useMinidom=False):
    """
    This function reads the Tsys values from a SysCal.xml table 
    associated with an ASDM into a dictionary keyed by antenna ID, 
    spw, scan, and pol (0 or 1).  
    asdm: the path to the original ASDM (containing Scan.xml and SpectralWindow.xml)
    sqld: the path to the SysCal.xml table to use (or its parent directory)
      If sqld is not specified, then assume it is the one inside the ASDM.
      The reason you might need to specify both is because the primary usage is
      to read values from a SysCal.xml file produced by offline casapy-telcal.
    median: if True, then compute the median across frequency on a 
            per-antenna/spw/scan/pol basis and a global basis 
    channel: use the value only from the one specified channel (0..127)
    verbose: if True, print the number of rows and channels found
    useMinidom: if True, then parse the .xml file even if the ASDM python
            bindings are available; This option only works for very old ALMA 
            data when SysCal.xml contained all the data instead of SysCal.bin
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    -- Todd Hunter
    """
    if (os.path.exists(asdm) == False):
        print("getTsysFromSysCal(): Could not find ASDM = ", asdm)
        return
    if (sqld is None):
        sqld = asdm + '/SysCal.xml'
    if (os.path.exists(sqld) == False):
        print("getTsysFromSysCal(): Could not find file = ", sqld)
        return
    if (sqld.split('/')[-1] != 'SysCal.xml'):
        sqld += '/SysCal.xml'
    scanlist = readscans(asdm)[0]
    if not asdmLibraryAvailable or useMinidom:
        import au_noASDMLibrary
        scandict = au_noASDMLibrary.getTsysFromSysCal_minidom(asdm, sqld, channel, scanlist, verbose)
        if scandict is None: return
    else:
        scandict = {}
        a = ASDM()
        parser = ASDMParseOptions()
        parser.asALMA()
        parser.loadTablesOnDemand(True)
        a.setFromFile(asdm,parser)
        wvrSpws = []
        baseband = {}
        spwTable = a.spectralWindowTable().get()
        for row in spwTable:
            name = row.name()
            spw = row.spectralWindowId().get()
            basebandName = row.basebandName()
            if str(basebandName) == "NOBB":
                baseband[spw] = -1  # NOBB
            else:
                baseband[spw] = int(str(basebandName).split('_')[1])  # BB_1
            if (name.find('WVR') >= 0):
                wvrSpws.append(spw)
        sysCalTable = a.sysCalTable().get()
        nchans = []
        for row in sysCalTable:
            antenna = row.antennaId().get()
            if antenna not in scandict:
                scandict[antenna] = {}
            asdmspw = row.spectralWindowId().get()
            subtract = len(np.where(asdmspw > np.array(wvrSpws))[0])-1 
            spw = asdmspw - subtract # translate this to actual spw number, as only 1 WVR spw is real
            if (spw not in list(scandict[antenna].keys())):
                scandict[antenna][spw] = {}
            if 'scans' not in list(scandict[antenna][spw].keys()):
                scandict[antenna][spw]['scans'] = {}
            scandict[antenna][spw]['baseband'] = baseband[asdmspw]
            # Here I am assuming the first value is the center of the scan, but it might be start or end
            mjdsec = convertASDMTimeIntervalToMJDSeconds(str(row.timeInterval()))
            timeCenterMJD = mjdsec / 86400.
            scan = -1
            for s in list(scanlist.keys()):
                if (scanlist[s]['endmjd'] >= timeCenterMJD and scanlist[s]['startmjd'] <= timeCenterMJD):
                    scan = s
#            print("scan = %d" % (scan))
            if (scan not in list(scandict[antenna][spw]['scans'].keys())):
                scandict[antenna][spw]['scans'][scan] = {}
            values = row.tsysSpectrum()
            npol, nchan = np.shape(values)
            nchans.append(nchan)
            for pol in range(npol):
                tsys = []
                for i in range(nchan):
                    tsys.append(float(values[pol][i].get()))
                if (channel is None):
                    scandict[antenna][spw]['scans'][scan][pol] = tsys
                else:
                    scandict[antenna][spw]['scans'][scan][pol] = [tsys[channel]]
        if verbose:
            print('  Found ',len(sysCalTable),' Tsys rows in SysCal.xml (median # chans = %.0f)' % (np.median(nchans)))
    if (median):
        mediandict = {}
        allvalues = []
        for antennaId in list(scandict.keys()):
            if antennaId not in list(mediandict.keys()): mediandict[antennaId] = {}
            spwvalues = []
            for spw in list(scandict[antennaId].keys()):
                if spw not in list(mediandict[antennaId].keys()): mediandict[antennaId][spw] = {}
                scanvalues = []
                for scan in list(scandict[antennaId][spw]['scans'].keys()):
                    if scan not in list(mediandict[antennaId][spw].keys()): mediandict[antennaId][spw][scan] = {}
                    polvalues = []
                    for pol in list(scandict[antennaId][spw]['scans'][scan].keys()):
                        if pol not in list(mediandict[antennaId][spw][scan].keys()): mediandict[antennaId][spw][scan][pol] = {}
                        values = scandict[antennaId][spw]['scans'][scan][pol]
                        polvalues += values
                        # Use 'median' label to allow future keys like 'mean' or 'std'
                        mediandict[antennaId][spw][scan][pol]['median'] = np.nanmedian(values)
                    mediandict[antennaId][spw][scan]['median'] = np.nanmedian(polvalues)
                    scanvalues += polvalues
                mediandict[antennaId][spw]['median'] = np.nanmedian(scanvalues)
                spwvalues += scanvalues
            mediandict[antennaId]['median'] = np.nanmedian(spwvalues)
            allvalues += spwvalues
        mediandict['median'] = np.nanmedian(allvalues)
        return (mediandict)
    else:
        return (scandict)
        
def getNonWvrSpws(mymsmd):
    """
    Uses the msmd tool instance to find a list of the non-WVR spws, in a backward-compatible way.
    -Todd Hunter
    """
    try:
        spws = list(set(range(mymsmd.nspw())).difference(set(callalmaspws(mymsmd,wvr=True))))
    except:
        spws = list(set(range(mymsmd.nspw())).difference(set(mymsmd.wvrspws())))
    return(spws)

def getNonChanAvgSpws(mymsmd):
    """
    Uses the msmd tool instance to find a list of the non-WVR spws, in a backward-compatible way.
    -Todd Hunter
    """
    try:
        spws = list(set(range(mymsmd.nspw())).difference(set(callalmaspws(mymsmd,chavg=True))))
    except:
        spws = list(set(range(mymsmd.nspw())).difference(set(mymsmd.chanavgspws())))
    return(spws)

def getFrequenciesFromASDM(asdm, spws=None, minnumchan=128):
    """
    Gets a list of the central frequencies of each spw in the ASDM. Extraneous
    WVR spws are skipped, so the order of the list should match listobs in CASA.
    spws: a list of spws to which to restrict the result
    minnumchan: limit the spws returned to those with at least this many 
                channels
    Returns:
    an array of frequencies (in Hz)
    - Todd Hunter
    """
    mydict = getSpwsFromASDM(asdm, minnumchan, dropExtraWVRSpws=True)
    if mydict is None: return
    freqs = []
    if (type(spws) == str):
        if len(spws) == 0:
            spws = None
        else:
            spws = [int(i) for i in spws.split(',')]
    elif (type(spws) == int):
        spws = [spws]
    for spw in sorted(mydict.keys()):
        if (spws is None):
            freqs.append(mydict[spw]['centerFreq'])
        elif (spw in spws):
            freqs.append(mydict[spw]['centerFreq'])
    return(np.array(freqs))

def getScienceBasebandRFRanges(vis, mymsmd=None, returnLOs=False):
    """
    Reports the 2GHz-wide ranges of ALMA science basebands.
    Returns: a dictionary keyed by baseband number, with values in Hz
    returnLOs: if True, then also return dictionaries for LO1 and LO2
    """
    needToClose = False
    if mymsmd is None:
        needToClose = True
        mymsmd = createCasaTool(msmdtool)
        mymsmd.open(vis)
    freqs = getScienceBasebandFrequencies(vis, mymsmd) # dictionary keyed by baseband
    if returnLOs:
        LO1s, LO2s = interpretLOs(vis, mymsmd=mymsmd, showOnlyScienceSpws=True, alsoReturnLO2=True)
    else:
        LO1s = interpretLOs(vis, mymsmd=mymsmd, showOnlyScienceSpws=True)
    ranges = {}
    sqldSpws = getScienceSpws(vis,sqld=True,fdm=False,tdm=False,returnString=False,mymsmd=mymsmd)
    for spw in LO1s:
        baseband = mymsmd.baseband(spw)
        basebandFreq = freqs[baseband]
        sqldspw = np.intersect1d(mymsmd.spwsforbaseband(baseband), sqldSpws)[0]
        bandwidth = mymsmd.bandwidths(sqldspw)
        ranges[baseband] = [basebandFreq-bandwidth/2, basebandFreq+bandwidth/2]
    if needToClose:
        mymsmd.close()
    if returnLOs:
        return ranges, LO1s, LO2s
    else:
        return ranges

def getScienceSpwBasebands(vis, mymsmd=None):
    """
    Reports the baseband number for each science spw
    Returns: a dictionary keyed by spw number, with values of 1..4
    -Todd Hunter
    """
    if mymsmd is None:
        needToClose = True
        mymsmd = createCasaTool(msmdtool)
        mymsmd.open(vis)
    else:
        needToClose = False
    spws = getScienceSpws(vis, returnString=False, mymsmd=mymsmd)
    mydict = {}
    for spw in spws:
        mydict[spw] = mymsmd.baseband(spw)
    if needToClose:
        mymsmd.close()
    return mydict
    
def checkScienceSpwIFRangesRelativeToBasebandIFRanges(vis, thresholdMHz=30, maxBandwidthMHz=1800, verbose=True):
    """
    Computes gap between edges of each spw and edges of its baseband, and
    reports a dictionary if values are less than the threshold.
    maxBandwidthMHz: don't report spws with wider bandwidth than this (because pipeline flags 
       ACA 2000 MHz "FDM" spws back to 1875 MHz total bandwidth)
    Returns: a dictionary, keyed by spw ID
    -Todd Hunter
    """
    if not os.path.exists(vis):
        print("Could not find measurement set: ", vis)
        return
    mymsmd = msmdtool()
    mymsmd.open(vis)
    basebandIFs = getScienceBasebandIFRanges(vis, mymsmd)
    if verbose:
        print("basebandIFs: ", basebandIFs)
    spwIFs = getScienceSpwIFRanges(vis, mymsmd)
    if verbose:
        print("spwIFs: ", spwIFs)
    basebands = getScienceSpwBasebands(vis, mymsmd)
    if verbose:
        print("basebands: ", basebands)
    sidebands = getScienceSpwSidebands(vis, mymsmd=mymsmd)
    if verbose:
        print("sidebands: ", sidebands)
    bandwidths = mymsmd.bandwidths()
    mymsmd.close()
    threshold = thresholdMHz * 1e6
    mydict = {}
    for spw in list(spwIFs.keys()):
        diffs = [abs(spwIFs[spw][0] - basebandIFs[basebands[spw]][0]),
                 abs(spwIFs[spw][0] - basebandIFs[basebands[spw]][1]),
                 abs(spwIFs[spw][1] - basebandIFs[basebands[spw]][0]),
                 abs(spwIFs[spw][1] - basebandIFs[basebands[spw]][1])]
        if np.min(diffs) < threshold and bandwidths[spw] < maxBandwidthMHz*1e6:
            mydict[spw] = np.min(diffs)
            if verbose:
                print("too close: spw %d (%s): %s MHz, baseband: %s MHz" % (spw, sidebands[spw], sorted(1e-6*np.array(spwIFs[spw])), sorted(1e-6*np.array(basebandIFs[basebands[spw]]))))
        else:
            if verbose:
                print("spw %d (%s): %s MHz, baseband: %s MHz" % (spw, sidebands[spw], sorted(1e-6*np.array(spwIFs[spw])), sorted(1e-6*np.array(basebandIFs[basebands[spw]]))))
                
    return mydict

def checkScienceSpwSamplerRanges(vis, thresholdMHz=30, maxBandwidthMHz=1800, verbose=True):
    """
    Computes the science spw sampler rangs, and reports any that are within 
    thresholdMHz of either edge.
    maxBandwidthMHz: don't report spws with wider bandwidth than this (because pipeline flags 
       ACA 2000 MHz "FDM" spws back to 1875 MHz total bandwidth)
    -Todd Hunter
    """
    samplerRanges = getScienceSpwSamplerRanges(vis, verbose=verbose)
    if samplerRanges is None: return
    spws = {}
    threshold = thresholdMHz * 1e6
    for spw in samplerRanges:
        bandwidth = np.abs(np.diff(samplerRanges[spw]))
        minOffset = np.min(np.abs(4e9 - samplerRanges[spw]))
        if (minOffset < threshold and bandwidth < maxBandwidthMHz*1e6):
            spws[spw] = {'4GHz_edge': minOffset, 'bandwidth': bandwidth}
        minOffset = np.min(np.abs(2e9 - samplerRanges[spw]))
        if (minOffset < threshold and bandwidth < maxBandwidthMHz*1e6):
            spws[spw] = {'2GHz_edge': minOffset, 'bandwidth': bandwidth}
    return spws

def getScienceSpwSamplerRanges(vis, mymsmd=None, verbose=False):
    """
    Reports the range within the baseband sampler where the science spws reside 
    (should always be somewhere within 2-4 or 4-2 GHz)
    -Todd Hunter
    """
    if mymsmd is None:
        needToClose = True
        mymsmd = createCasaTool(msmdtool)
        if verbose:
            print("opening msmd")
        mymsmd.open(vis)
    else:
        needToClose = False
    if verbose:
        print("getScienceSpwRFRanges")
    spwFreqs = getScienceSpwRFRanges(vis, mymsmd)
    if verbose:
        print("interpretLOs")
    result = interpretLOs(vis, mymsmd=mymsmd, showOnlyScienceSpws=True, alsoReturnLO2=True)
    if result is None: return
    LO1s, LO2s = result
    if needToClose:
        mymsmd.close()
    samplerFreqs = {}
    for spw in LO1s:
        if spwFreqs[spw][0] > LO1s[spw]:
            samplerFreqs[spw] = LO2s[spw] - (spwFreqs[spw] - LO1s[spw])
        else:
            samplerFreqs[spw] = LO2s[spw] - (LO1s[spw] - spwFreqs[spw])
    return samplerFreqs

def getScienceBasebandSamplerRanges(vis, mymsmd=None, verbose=False):
    """
    Reports the range within the baseband sampler where the baseband resides 
    (should always be 2-4 or 4-2 GHz)
    -Todd Hunter
    """
    if mymsmd is None:
        needToClose = True
        mymsmd = createCasaTool(msmdtool)
        if verbose:
            print("opening msmd")
        mymsmd.open(vis)
    else:
        needToClose = False
    if verbose:
        print("getScienceBasebandRFRanges")
    basebandFreqs, LO1s, LO2s = getScienceBasebandRFRanges(vis, mymsmd, returnLOs=True)
    if verbose:
        print("getScienceSpwBasebands")
    basebands = getScienceSpwBasebands(vis, mymsmd)
    if needToClose:
        mymsmd.close()
    samplerFreqs = {}
    for spw in LO1s:
        if basebandFreqs[basebands[spw]][0] > LO1s[spw]:
            samplerFreqs[spw] = LO2s[spw] - (basebandFreqs[basebands[spw]] - LO1s[spw])
        else:
            samplerFreqs[spw] = LO2s[spw] - (LO1s[spw] - basebandFreqs[basebands[spw]])
    return samplerFreqs

def getScienceBasebandIFRanges(vis, mymsmd=None, verbose=False):
    """
    Reports the 2GHz-wide ranges of ALMA science basebands in the frame after LO1 but 
    before LO2 (i.e. 4-8 or 4-12 GHz)
    Returns: a dictionary keyed by baseband number, with values in Hz
    -Todd Hunter
    """
    if mymsmd is None:
        needToClose = True
        mymsmd = createCasaTool(msmdtool)
        mymsmd.open(vis)
    else:
        needToClose = False
    freqs = getScienceBasebandFrequencies(vis, mymsmd) # dictionary keyed by baseband
    LO1s = interpretLOs(vis, mymsmd=mymsmd, showOnlyScienceSpws=True)  # dictionary keyed by science spw number
    ranges = {}
    for spw in LO1s:
        baseband = mymsmd.baseband(spw)
        basebandFreq = freqs[baseband]
        sqldspw = np.intersect1d(mymsmd.spwsforbaseband(baseband), 
                                 getScienceSpws(vis,sqld=True,fdm=False,tdm=False,returnString=False,mymsmd=mymsmd))[0]
        bandwidth = mymsmd.bandwidths(sqldspw)
        if verbose:
            print("spw %d baseband bandwidth = " % (spw), bandwidth)
        ranges[baseband] = [abs(LO1s[spw]-basebandFreq)-bandwidth/2, abs(LO1s[spw]-basebandFreq)+bandwidth/2]
    if needToClose:
        mymsmd.close()
    return ranges

def getScienceSpwIFRanges(vis, mymsmd=None, spws=None, units='Hz'):
    """
    Reports the IF ranges of the ALMA science spws of a measurement set.
    spws: if specified, limit the spws to these (python list or comma-delimited string)
    units: 'Hz', 'MHz', or 'GHz'
    Returns: a dictionary keyed by spw number, with values in Hz
    """
    if mymsmd is None:
        needToClose = True
        mymsmd = createCasaTool(msmdtool)
        mymsmd.open(vis)
    else:
        needToClose = False
    if spws is None:
        spws = getScienceSpws(vis, mymsmd=mymsmd, returnString=False) # list of integers
    else:
        spws = parseSpw(vis, spws, mymsmd=mymsmd)
    LO1s = interpretLOs(vis, mymsmd=mymsmd, showOnlyScienceSpws=True)  # dictionary keyed by science spw number
    ranges = {}
    for spw in spws:
        bandwidth = mymsmd.bandwidths(spw)
        spwFreq = mymsmd.meanfreq(spw)
        ranges[spw] = np.array([abs(LO1s[spw]-spwFreq)-bandwidth/2, abs(LO1s[spw]-spwFreq)+bandwidth/2])
        if units == 'GHz':
            ranges[spw] *= 1e-9
        elif units == 'MHz':
            ranges[spw] *= 1e-6
        ranges[spw] = list(ranges[spw])
    if needToClose:
        mymsmd.close()
    return ranges

def compareRFandIFRanges(vislist=''):
    """
    Calls getScienceSpwRFRanges and getScienceSpwIFRanges and, if there is more than one vis, it 
    computes max difference in their respective center frequencies.
    vislist: if blank then use all .ms in the current directory (avoiding target.ms if some are target and some are not)
    -Todd Hunter
    """
    if vislist == '':
        vislist = sorted(glob.glob('*.ms'))
        target = 0
        for vis in vislist:
            if vis.find('target') > 0:
                target += 1
        if target != len(vislist):
            newvislist = []
            for vis in vislist:
                if vis.find('target') < 0:
                    newvislist.append(vis)
            vislist = newvislist
    units = 'Hz'
    mymsmd = createCasaTool(msmdtool)
    ifCenter = {}
    rfCenter = {}
    for i,vis in enumerate(vislist):
        print("EB %d of %d" % (i+1, len(vislist)))
        mymsmd.open(vis)
        ifRange = getScienceSpwIFRanges(vis, mymsmd=mymsmd, units=units)
        spwlist = sorted(list(ifRange.keys()))
        spwnames = getScienceSpwNames(vis, mymsmd=mymsmd, uniqueStringOnly=True)
        nTunings = len(np.unique(spwnames))
        rfRange = getScienceSpwRFRanges(vis, mymsmd=mymsmd, units=units)
        tunings = []
        for j,spw in enumerate(spwlist):
            if spwnames[j] not in tunings:
                tunings.append(spwnames[j])
                print("\nTuning %d of %d: %s" % (len(tunings), nTunings, spwnames[j]))
            if spw not in ifCenter.keys():
                ifCenter[spw] = []
                rfCenter[spw] = []
            ifCenter[spw].append(np.mean(ifRange[spw]))
            rfCenter[spw].append(np.mean(rfRange[spw]))
            rf0, rf1 = np.array(rfRange[spw])*1e-9
            if0, if1 = np.array(ifRange[spw])*1e-9
            print("%s: spw%02d: RF: %.6f-%.6f GHz,  IF: %.6f-%.6f GHz" % (os.path.basename(vis), spw, rf0, rf1, if0, if1))
        print("\n spw pair differences:")
        for spw in spwlist[:4]:
            if len(spwlist) >= 8:
                print("spw %02d to %02d: RF difference: %+8.3f MHz   IF difference: %+8.3f MHz" % (spw, spw+20, 1e-6*(rfCenter[spw][i] - rfCenter[spw+20][i]), 1e-6*(ifCenter[spw][i] - ifCenter[spw+20][i])))
            if len(spwlist) >= 12:
                print("spw %02d to %02d: RF difference: %+8.3f MHz   IF difference: %+8.3f MHz" % (spw, spw+40, 1e-6*(rfCenter[spw][i] - rfCenter[spw+40][i]), 1e-6*(ifCenter[spw][i] - ifCenter[spw+40][i])))
        print("\n")
    mymsmd.close()
    if len(vislist) > 1:
        print("\nRF maximum differences between EBs:")
        for spw in spwlist:
            rfDiff = np.max(rfCenter[spw]) - np.min(rfCenter[spw])
            print("spw %02d: %7.3f MHz" % (spw, rfDiff*1e-6))
        print("\nIF maximum differences between EBs:")
        for spw in spwlist:
            ifDiff = np.max(ifCenter[spw]) - np.min(ifCenter[spw])
            print("spw %02d: %7.3f MHz" % (spw, ifDiff*1e-6))

def getScienceSpwRFRanges(vis, mymsmd=None, spws=None,
                          returnDistanceFromRXBandEdge=False, units='Hz'):
    """
    Reports the RF ranges of the ALMA science spws of a measurement set.
    spws: if specified, limit the spws to these (python list or comma-delimited string)
    units: Hz, GHz or MHz
    Returns: 1 or 2 dictionaries:
    1) a dictionary keyed by spw number, with values in the units specified
    2) if returnDistanceFromRXBandEdge=True, then return smallest gap to a Rx Band edge (in MHz)
    -Todd Hunter
    """
    if mymsmd is None:
        needToClose = True
        mymsmd = createCasaTool(msmdtool)
        mymsmd.open(vis)
    else:
        needToClose = False
    if spws is None:
        spws = getScienceSpws(vis, mymsmd=mymsmd, returnString=False) # list of integers
    else:
        spws = parseSpw(vis, spws, mymsmd=mymsmd)
    ranges = {}
    distanceFromRxBandEdge = {}
    for spw in spws:
        bandwidth = mymsmd.bandwidths(spw)
        spwFreq = mymsmd.meanfreq(spw)
        ranges[spw] = np.array([spwFreq-bandwidth/2, spwFreq+bandwidth/2])
        if units == 'GHz':
            ranges[spw] *= 1e-9
        elif units == 'MHz':
            ranges[spw] *= 1e-6
        ranges[spw] = list(ranges[spw])
        band = bandforspw(spw, mymsmd=mymsmd)
        distanceFromRxBandLowEdge = np.min(ranges[spw]) - bandDefinitions[band][0]
        distanceFromRxBandHighEdge = bandDefinitions[band][1] - np.max(ranges[spw]) 
        distanceFromRxBandEdge[spw] = np.min([distanceFromRxBandLowEdge, distanceFromRxBandHighEdge]) * 1e-6
    if needToClose:
        mymsmd.close()
    if returnDistanceFromRXBandEdge:
        return ranges, distanceFromRxBandEdge
    else:
        return ranges

def getScienceBasebandFrequencies(vis, mymsmd=None, keyBySQLD=False):
    """
    Uses the ALMA SQLD spws to infer the baseband center frequencies of each science spw on the RF 
    (sky frequency) scale.
    keyBySQLD: if True, then key by SQLD spw instead of baseband number
    Returns: a dictionary keyed by baseband number with values of the baseband center frequency in Hz
    """
    spws = getScienceSpws(vis, sqld=True, tdm=False, fdm=False, returnString=False, mymsmd=mymsmd)
    if len(spws) == 0:
        print("There are no SQLD spws in this dataset, so the baseband frequencies are unknown.")
        return
    freqs = {}
    needToClose = False
    if mymsmd is None:
        needToClose = True
        mymsmd = createCasaTool(msmdtool)
        mymsmd.open(vis)
    for spw in spws:
        freq = getMeanFreqOfSpwlist(vis, spw, mymsmd=mymsmd)
        baseband = mymsmd.baseband(spw)
        if keyBySQLD:
            freqs[spw] = freq
        else:
            freqs[baseband] = freq
    if needToClose:
        mymsmd.close()
    return freqs

def getSpwSelForFreqRange(vis, frequency, intent='OBSERVE_TARGET#ON_SOURCE',
                          verbose=False):
    """
    Returns a list of science spws and chans that cover a freq range
    vis: name of measurement set
    frequency: 2 LSRK freqs in Hz, GHz, or a string with units
    -Remy Indebetouw
    """
    if not os.path.exists(vis):
        print("Could not find measurement set: ", vis)
        return

    mymsmd = createCasaTool(msmdtool)
    mymsmd.open(vis)

    #spws = getScienceSpws(vis, returnString=False)
    spws = callspwsforintent(mymsmd, intent)
    almaspws = callalmaspws(mymsmd,tdm=True,fdm=True)
    if (len(almaspws) > 0):
        spws = np.intersect1d(spws,almaspws)

    datestring = getObservationStartDate(vis, measuresToolFormat=True)
    observatory = mymsmd.observatorynames()[0]
    field = mymsmd.fieldsforintent(intent)
    if (len(field) == 0):
        print("No fields with that intent")
        return
    else:
        field = field[0]
        # print "Using field %d" % field
    result = getRADecForField(vis, field, returnReferenceFrame=True)
    if result is None: return
    radec, equinox = result
    ra = radec[0][0]
    dec = radec[1][0]
    rastr,decstr=rad2radec(ra,dec,verbose=False).split(",")

    if not isinstance(frequency,list):
        frequency=[frequency]
    if len(frequency)<2:
        frequency=[frequency[0],frequency[0]]
    LSRKfrequency0 = parseFrequencyArgumentToHz(frequency[0])
    if verbose:
        print("using ",datestring, rastr, decstr, equinox, observatory)
    TOPOfreq0 = lsrkToTopo(LSRKfrequency0, datestring, rastr, decstr, equinox, observatory)
    LSRKfrequency1 = parseFrequencyArgumentToHz(frequency[1])
    TOPOfreq1 = lsrkToTopo(LSRKfrequency1, datestring, rastr, decstr, equinox, observatory)
    if TOPOfreq1<TOPOfreq0:
        tmp=TOPOfreq0
        TOPOfreq0=TOPOfreq1
        TOPOfreq1=tmp

    spws2 = []
    spwstr = ""
    for spw in spws:
        freqs = mymsmd.chanfreqs(spw)
        if (np.min(freqs) <= TOPOfreq0 and np.max(freqs) >= TOPOfreq0):
            spws2.append(spw)
            thisdelta=mymsmd.chanwidths(spw).mean()
            if verbose:
                print("spw %i"%spw, "freq ",freqs[0],"-",freqs[-1])

            if thisdelta>0:
                z0=np.where(freqs<=TOPOfreq0)[0].max()
                # increasing freq, freq1>=freq0 so could be beyond maxchan
                z1=np.where(freqs<=TOPOfreq1)[0].max()
            else:
                z1=np.where(freqs<=TOPOfreq0)[0].min()
                # decreasing freq, freq1>=freq0 so could be < 0chan
                z0=np.where(freqs<=TOPOfreq1)[0].min()
            spwstr=spwstr+("%i:%i~%i,"%(spws2[-1],z0,z1))
    mymsmd.close()
    return(spwstr[0:-1])
    
def getScienceSpwsForFrequency(vis, frequency, nearestOnly=False, mymsmd=None):
    """
    Returns a list of science spws that cover a given frequency.
    vis: name of measurement set
    frequency: in Hz, GHz, or a string with units
    nearestOnly: if True, the return only one spw (nearest to center)
    -Todd Hunter
    """
    needToClose = False
    if mymsmd is None:
        mymsmd = createCasaTool(msmdtool)
        mymsmd.open(vis)
        needToClose = True
    spws = getScienceSpws(vis, returnString=False, mymsmd=mymsmd)
    frequency = parseFrequencyArgumentToHz(frequency)
    spws2 = []
    delta = []
    for spw in spws:
        freqs = mymsmd.chanfreqs(spw)
        if (np.min(freqs) <= frequency and np.max(freqs) >= frequency):
            spws2.append(spw)
            delta.append(abs(frequency-mymsmd.meanfreq(spw)))
    if needToClose:
        mymsmd.close()
    if nearestOnly:
        return(spws2[np.argmin(delta)])
    else:
        return(spws2)

def checkScienceSpws(dir='./', intent='OBSERVE_TARGET#ON_SOURCE', tdm=True,
                     fdm=True, ignore='_target.ms'):
    """
    For all measurement sets in the specified directory, get the
    science spws and report any differences in ID number.
    dir: comma-delimited list of directories, wildcard string, or 
         list of directories
    -Todd Hunter
    """
    if type(dir) == str:
        if (dir.find('*')>=0):
            dirs = glob.glob(dir)
        else:
            dirs = dir.split(',')
    else:
        dirs = dir
    for dir in dirs:
        print(dir+":")
        vis = glob.glob(dir+'/*.ms')
        if (len(ignore) > 0):
            tvis = glob.glob(dir+'/*%s*'%(ignore))
            vis = list(set(vis) - set(tvis))
        if (len(vis) < 2):
            print("    Only %d measurement set found" % (len(vis)))
            continue
        spws = getScienceSpws(vis[0], intent, tdm=tdm, fdm=fdm)
        print("%s: %s" % (os.path.basename(vis[0]),spws))
        difference = False
        for v in vis[1:]:
            newspws = getScienceSpws(v, intent, tdm=tdm, fdm=fdm)
            print("%s: %s" % (os.path.basename(v),newspws))
            if spws != newspws:
                difference = True
                print("   Difference!")
    return difference

def getNearestScienceSpw(vis, freqGHz, mymsmd=''):
    """
    Finds the science spw whose mean freq is closest to the specified
    frequency.  - Todd Hunter
    """
    needToClose = False
    if mymsmd == '':
        mymsmd = createCasaTool(msmdtool)
        needToClose = True
    spws = getScienceSpws(vis, mymsmd=mymsmd, returnString=False)
    freqs = []
    for spw in spws:
        freqs.append(mymsmd.meanfreq(spw)*1e-9)
    spw = spws[np.argmin(np.abs(freqs-freqGHz))]
    if needToClose:
        mymsmd.close()
    return spw

def getScienceTimeRanges(vis, field=None, intent='OBSERVE_TARGET*', 
                         mymsmd=None, roundToSmallestRange=False):
    """
    Gets a list of string-formatted time ranges corresponding to the
    scans on the specified field or intent.  Similar to tt.scanTimeRanges.
    roundToSmallestRange: if True, then ceil start and floor end
                            else, then floor start and ceil end
    Returns:  ['2017/10/07/22:18:41~2017/10/07/22:20:07', ...]
    -Todd Hunter
    """
    needToClose = False
    if mymsmd is None:
        needToClose = True
        mymsmd = createCasaTool(msmdtool)
        mymsmd.open(vis)
    scans = getScienceScans(vis, field, intent, mymsmd)
    times = []
    for scan in scans:
        t = mymsmd.timesforscan(scan)
        if roundToSmallestRange:
            times.append(mjdsecToTimerange(np.ceil(np.min(t)), np.floor(np.max(t))))
        else:
            times.append(mjdsecToTimerange(np.floor(np.min(t)),np.ceil(np.max(t))))
    return times

def getNonScienceTimeRanges(vis, intent='OBSERVE_TARGET*', obsID=0, tbuffer=0.048):
    """
    Returns a list of timeranges (suitable for flagdata commands) which
    correspond to all times that are not contained by a scan of the
    specified intent. The opposite of this function is getScienceTimeRanges.
    Coped from to tt.nonScanTimeRanges.
    tbuffer: in seconds, flag this much *less* time to avoid flagging good data
           default value is one ALMA timing event
    """
    mymsmd = createCasaTool(msmdtool)
    mymsmd.open(vis)
    scans = mymsmd.scansforintent(intent)
    print("Found %d matching scans: " % (len(scans)), scans)
    startTime = 86400*mymsmd.timerangeforobs(obsID)['begin']['m0']['value']
    endTime = 86400*mymsmd.timerangeforobs(obsID)['end']['m0']['value']
    timeranges = []
    for scan in scans:
        t = mymsmd.timesforscan(scan)
        if scan == scans[0]:  # first scan, start from beginning of obs.
            timeranges.append(mjdsecToTimerange(startTime, np.min(t)-tbuffer))
            endOfPreviousGoodScan = np.max(t) + tbuffer
        elif scan == scans[-1]:  # final scan: finish and then go to end of obs.
            timeranges.append(mjdsecToTimerange(endOfPreviousGoodScan, np.min(t)-tbuffer))
            timeranges.append(mjdsecToTimerange(np.max(t)+tbuffer, endTime))
        else:
            timeranges.append(mjdsecToTimerange(endOfPreviousGoodScan, np.min(t)-tbuffer))
            endOfPreviousGoodScan = np.max(t) + tbuffer
    mymsmd.close()
    return timeranges

def pipelinePointingFieldOtherIntents(workingdir):
    """
    Finds all primary .ms files in a pipeline directory and runs
    getPointingFieldOtherIntents, compiling the results into a unique list
    of one-word intents.
    -Todd Hunter
    """
    vislist = findEBsInPipeline(workingdir)
    intents = []
    for vis in vislist:
        newintents = getPointingFieldOtherIntents(vis)
        intents += newintents
    return list(np.unique(intents))

def getPointingFieldOtherIntents(vis, mymsmd=None, indicateBPFlux=True):
    """
    Runs msmd.fieldsforintent('POINTING'), then msmd.intentsforfield, then
    remove CALIBRATE_WVR and CALIBRATE_POINTING
    indicateBPFlux, if True, then condense ['BANDPASS','FLUX'] to ['BP/FLUX']
    """
    if mymsmd is None:
        needToClose = True
        mymsmd = createCasaTool(msmdtool)
        mymsmd.open(vis)
    fields = mymsmd.fieldsforintent('*POINTING*')
    otherIntents = []
    for field in fields:
        intents = mymsmd.intentsforfield(field)  # this is a list
        otherIntentsForThisField = []
        for intent in intents:
            if intent.find('POINTING') < 0 and intent.find('WVR') < 0 and intent.find('ATMOS') < 0:
                otherIntentsForThisField.append(getOneWordIntent(intent))
        if indicateBPFlux:
            #replace the BANDPASS and FLUX entries for this field with BP/FLUX
            if 'BANDPASS' in otherIntentsForThisField and 'FLUX' in otherIntentsForThisField:
                otherIntentsForThisField = list(np.unique([otherIntent.replace('FLUX','BP/FLUX').replace('BANDPASS','BP/FLUX') for otherIntent in otherIntentsForThisField]))
        otherIntents += otherIntentsForThisField
    return list(np.unique(otherIntents))

def getPointingScans(vis, field=None, mymsmd=None, debug=False):
    """
    Calls getScienceScans using the intent='CALIBRATE_POINTING#ON_SOURCE'
    field: one name or ID
    -Todd Hunter
    """
    return getScienceScans(vis, field, 'CALIBRATE_POINTING#ON_SOURCE', mymsmd, debug)

def getScienceScans(vis, field=None, intent='OBSERVE_TARGET*', 
                    mymsmd=None, debug=False):
    """
    Return a list of scans with the specified intent (and optionally limited 
    to one field).  
    field: one name or integer ID
    intent: either the full name ('CALIBRATE_PHASE#ON_SOURCE', or partial name with wildcard ('*PHAS*'), 
           or a complete abbreviated key like 'PHASE'
    -Todd Hunter
    """
    needToClose = False
    if mymsmd is None:
        needToClose = True
        mymsmd = createCasaTool(msmdtool)
        mymsmd.open(vis)
    intents = mymsmd.intents()
    if (intent not in intents):
        for i in intents:
            if i.find(intent) >= 0:
                intent = i
                if debug:
                    print("Translated intent to ", i)
                break
    # minimum match OBSERVE_TARGET or OBSERVE_TARGET* to OBSERVE_TARGET#UNSPECIFIED
    value = [i.find(intent.replace('*','')) for i in intents]
    # If any intent gives a match, the mean value of the location list will be > -1
    if np.mean(value) == -1:
        print("%s not found in this dataset. Available intents: " % (intent), intents)
        if needToClose: 
            mymsmd.close()
        return
    sciscans = mymsmd.scansforintent(intent)
    scispws = callspwsforintent(mymsmd, intent)
    if debug:
        print("sciscans = ", sciscans)
        print("scispws = ", scispws)
    if field is not None:
        ids, names = parseFieldArgument(vis, field, mymsmd=mymsmd)
        fieldscans = mymsmd.scansforfields()
        spwscans = mymsmd.scansforspws()
        scispwscans = spwscans[str(scispws[0])]
        if debug:
            print("scispwscans = ", scispwscans)
        sciscans2 = []
        for field in [str(i) for i in ids]:
            if debug:
                print("scansforfield%s = " % field, fieldscans[field])
            sciscans2 += list(np.intersect1d(scispwscans,fieldscans[field]))
        sciscans2 = np.unique(sciscans2)
        if debug:
            print("sciscans2 = ", sciscans2)
        sciscans = np.intersect1d(sciscans,sciscans2)
    if needToClose:
        mymsmd.close()
    return sciscans

def getScienceSpwTypes(vis, mymsmd=None):
    """
    Returns a dictionary giving the number of 'TDM' and 'FDM' spws.
    -Todd Hunter
    """
    if (mymsmd is None):
        mymsmd = createCasaTool(msmdtool)
        mymsmd.open(vis)
        needToClose = True
    else:
        needToClose = False
    tdm = len(getScienceSpws(vis, tdm=True, fdm=False, mymsmd=mymsmd, returnString=False))
    fdm = len(getScienceSpws(vis, tdm=False, fdm=True, mymsmd=mymsmd, returnString=False))
    if needToClose: mymsmd.close()
    return {'TDM': tdm, 'FDM': fdm}

def getScienceSpwChanwidths(vis, intent='OBSERVE_TARGET#ON_SOURCE', 
                            tdm=True, fdm=True, mymsmd=None, sqld=False, 
                            verbose=False, returnDict=False, returnMHz=False,
                            absoluteValue=True, velocity=False):
    """
    intent: find spws with this intent
    tdm, fdm, sqld: passed to msmd.almaspws()
    mymsmd: an existing instance of the msmd tool with an opened MS
    returnMHz: if Treu, return the value in MHz instead of Hz
    returnDict: if True, then return a dictionary keyed by spw ID
    absoluteValue: if True, take the abs() of the bandwidth
    velocity: if True, convert to velocity in km/s
    Returns: an array of channel widths (in Hz) in order sorted by spw ID
    -Todd Hunter
    """
    if mymsmd is None:
        mymsmd = createCasaTool(msmdtool)
        mymsmd.open(vis)
        needToClose = True
    else:
        needToClose = False
    spws = sorted(getScienceSpws(vis, intent, False, False, tdm, fdm, mymsmd, sqld, verbose))
    bandwidths = []
    for spw in spws:
        bandwidths.append(mymsmd.chanwidths(spw)[0])
    bandwidths = np.array(bandwidths)
    if returnMHz:
        bandwidths *= 1e-6
    if absoluteValue:
        bandwidths = np.abs(bandwidths)
    if velocity:
        spwfreqs = np.array(getScienceFrequencies(vis, mymsmd=mymsmd))
        bandwidths *= c_kms / spwfreqs
    if needToClose:
        mymsmd.close()
    if returnDict:
        mydict = {}
        for i, spw in enumerate(spws):
            mydict[spw] = bandwidths[i]
        return mydict
    else:
        return bandwidths

def getScienceSpwBandwidths(vis, intent='OBSERVE_TARGET#ON_SOURCE', 
                             tdm=True, fdm=True, mymsmd=None, sqld=False, 
                             verbose=False, returnDict=False, returnMHz=False):
    """
    Returns: an array of bandwidths (in Hz) in order sorted by spw ID
    returnDict: if True, then return a dictionary keyed by spw ID
    -Todd Hunter
    """
    if mymsmd is None:
        mymsmd = createCasaTool(msmdtool)
        mymsmd.open(vis)
        needToClose = True
    else:
        needToClose = False
    spws = sorted(getScienceSpws(vis, intent, False, False, tdm, fdm, mymsmd, sqld, verbose))
    bandwidths = mymsmd.bandwidths(spws)
    if needToClose:
        mymsmd.close()
    mymsmd.close()
    if returnMHz:
        bandwidths *= 1e-6
    if returnDict:
        mydict = {}
        for i, spw in enumerate(spws):
            mydict[spw] = bandwidths[i]
        return mydict
    else:
        return bandwidths

def getScienceSpwNChannels(vis, intent='OBSERVE_TARGET#ON_SOURCE', 
                           tdm=True, fdm=True, mymsmd=None, sqld=False, 
                           verbose=False, returnDict=False, includeBandwidth=False):
    """
    Returns: an array of nchan in order sorted by spw ID
    returnDict: if True, then return a dictionary keyed by spw ID
    includeBandwidth: if True, then sets returnDict=True and returns 2 keys per spw:
              'nchan' and 'bandwidth'
    -Todd Hunter
    """
    if mymsmd is None:
        mymsmd = createCasaTool(msmdtool)
        mymsmd.open(vis)
        needToClose = True
    else:
        needToClose = False
    spws = sorted(getScienceSpws(vis, intent, False, False, tdm, fdm, mymsmd, sqld, verbose))
    nchan = []
    bandwidth = []
    for spw in spws:
        nchan.append(mymsmd.nchan(spw))
        if includeBandwidth:
            bandwidth.append(mymsmd.bandwidths(spw))
    if needToClose:
        mymsmd.close()
    mymsmd.close()
    if includeBandwidth:
        returnDict = True
    if returnDict:
        mydict = {}
        for i, spw in enumerate(spws):
            if includeBandwidth:
                mydict[spw] = {'nchan': nchan[i], 'bandwidth': bandwidth[i]}
            else:
                mydict[spw] = nchan[i]
        return mydict
    else:
        return nchan

def getTsysSpwsForScan(vis, scan, intent='CALIBRATE_ATMOSPHERE#OFF_SOURCE', 
                       tdm=True, fdm=True, mymsmd=None, sqld=False, 
                       verbose=False):
    """
    A wrapper for getScienceSpwsForScan with intent set to ATMOSPHERE
    Returns: list of integer IDs
    -Todd Hunter
    """
    spws = getScienceSpwsForScan(vis, scan, intent, tdm, fdm, mymsmd, sqld, verbose)
    return spws

def getScienceScansForSpw(vis, spw, field=None, intent='OBSERVE_TARGET*', 
                          mymsmd=None, debug=False):
    """
    Takes the intersection of msmd.scansforspws() and msmd.scansforintent()
    Returns: list of integer scan numbers
    -Todd Hunter
    """
    needToClose = False
    if mymsmd is None:
        mymsmd = createCasaTool(msmdtool)
        mymsmd.open(vis)
        needToClose = True
    scienceScans = mymsmd.scansforintent(intent)
    spwScans = mymsmd.scansforspws()[str(spw)]
    scans = np.intersect1d(scienceScans,spwScans)
    return scans

def getScienceSpwsForScan(vis, scan, intent='OBSERVE_TARGET#ON_SOURCE', 
                          tdm=True, fdm=True, mymsmd=None, sqld=False, 
                          verbose=False):
    """
    Takes the intersection of msmd.spwsforscan with getScienceSpws()
    Returns: list of integer IDs
    -Todd Hunter
    """
    needToClose = False
    if mymsmd is None:
        mymsmd = createCasaTool(msmdtool)
        mymsmd.open(vis)
        needToClose = True
    scanSpws = mymsmd.spwsforscan(scan)
    scienceSpws = getScienceSpws(vis, intent, tdm=tdm, fdm=fdm, mymsmd=mymsmd, sqld=sqld, verbose=verbose, returnString=False)
    if verbose:
        print("scan spws: ", scanSpws)
        print("intent spws: ", scienceSpws)
    if needToClose:
        mymsmd.close()
    return np.intersect1d(scanSpws, scienceSpws)

def getOnlineFlagsForScienceSpws(vis, spwnames=[], verbose=False):
    """
    Searches the pipeline-generated *flagonline.txt file for any flag that
    is applied to a subset of science spws, but not all of them.
    It first finds the full name of the science spws.
    vis:  a measurement set name which has a flagonline.txt file in the same parent directory
    spwnames: if you already know the names, you can pass them as a list
    verbose: if True, then print all flags that include any science spw
             if False, then only print flags that have a subset of science spws
    """
    if not os.path.exists(vis):
        print("Could not find vis: ", vis)
        return
    flagfile = vis.replace('.ms','.flagonline.txt').replace('_target','')
    if len(spwnames) == 0:
        spwnames = getScienceSpwNames(vis)
    f = open(flagfile,'r')
    flags = f.readlines()
    f.close()
    partialFlags = 0  # that flag a subset of the science spws
    spwFlags = 0 # that flag any or all science spws
    if verbose:
        f = open('scienceSpwFlags.txt','w')
    for flag in flags:
        spws = 0
        for name in spwnames:
            if flag.find(name) >= 0:
                spws += 1
        if spws > 0:
            spwFlags += 1
            if verbose:
                print(flag)
                f.write(flag)
            if spws < len(spwnames):
                partialFlags += 1
                print("subset flag: ", flag)
    print("Found %d flags that include science spws" % (spwFlags))
    print("Found %d flags where only a subset of science spws are flagged" % (partialFlags))
    if verbose:
        f.close()
    return partialFlags

def spectralDynamicRangeBandwidth(repFreq, linewidth):
    """
    Returns 1/3 of the linewidth in frequency units (MHz).
    repFreq: in GHz, Hz, or a string with units
    linewidth:  in km/s
    """
    repFreq = parseFrequencyArgumentToHz(repFreq)
    bandwidthHz = linewidth*repFreq/(3*c_kms)
    return bandwidthHz*1e-6
    
def getSpectralSpecNames(vis, intent='OBSERVE_TARGET#ON_SOURCE', tdm=True,
                         fdm=True, mymsmd=None, sqld=False):
    """
    Gets a list of unique prefixes of the spw names, i.e the SpectralSpec names
    by calling getScienceSpwNames(uniqueStringOnly=True)
    intent: either full intent name including #subIntent, or an abbreviated key, like 'PHASE', or blank (for all intents)
    -Todd Hunter
    """
    return np.unique(getScienceSpwNames(vis, intent, tdm=tdm, fdm=fdm, mymsmd=mymsmd, sqld=sqld, uniqueStringOnly=True))

def getScienceSpwNames(vis, intent='OBSERVE_TARGET#ON_SOURCE', 
                       returnString=True, returnListOfStrings=False,
                       tdm=True, fdm=True, mymsmd=None, sqld=False, 
                       verbose=False, uniqueStringOnly=False, returnDict=False):
    """
    intent: either full intent name including #subIntent, or an abbreviated key, like 'PHASE', or blank (to get all intents except WVR spws)
    sqld: setting this true will give BB_1,BB+2, etc. for old datasets (pre Cycle 7)
    Returns: a list of science spw names using getScienceSpws and 
    msmd.namesforspw.
    uniqueStringOnly: if True, then return only the leading string of gibberish 
             that originates in OT
    -Todd Hunter
    """
    mymsmd = createCasaTool(msmdtool)
    mymsmd.open(vis)
    spwlist = getScienceSpws(vis, intent, False, False, tdm, fdm, mymsmd, 
                             sqld, verbose)
    names = mymsmd.namesforspws(spwlist)
    mymsmd.close()
    mydict = {}
    for i,name in enumerate(names):
        mydict[spwlist[i]] = name
    if uniqueStringOnly:
        newnames = []
        mydict = {}
        for i,name in enumerate(names):
            newnames.append(name.split('#')[0])
            mydict[spwlist[i]] = name.split('#')[0]
        names = newnames
    if returnDict:
        return mydict
    else:
        return names

def getScienceSpwFreqRanges(vis, mymsmd=None):
    """
    Calls getScienceSpws with returnFreqRanges=True
    Returns: a dictionary keyed by spw ID, with ranges of TOPO frequency
    """
    mydict = getScienceSpws(vis, returnFreqRanges=True, mymsmd=mymsmd)
    return mydict 

def getScienceSpws(vis, intent='OBSERVE_TARGET#ON_SOURCE', returnString=True, 
                   returnListOfStrings=False, tdm=True, fdm=True, mymsmd=None, 
                   sqld=False, verbose=False, returnFreqRanges=False,
                   chavg=False, quiet=False):
    """
    Return a list of spws with the specified intent.  For ALMA data,
    it ignores channel-averaged and SQLD spws.
    intent: either full intent name including #subIntent, or an abbreviated key, like 'PHASE'
    returnString: if True, return '1,2,3'
                  if False, return [1,2,3]
    returnListOfStrings: if True, return ['1','2','3']  (amenable to tclean spw parameter)
                         if False, return [1,2,3]
    returnFreqRanges: if True, returns a dictionary keyed by spw ID, with values
          equal to the frequency of the middle of the min and max channel (Hz)
    -- Todd Hunter
    """
    if returnString and returnListOfStrings:
        print("You can only specify one of: returnString, returnListOfStrings")
        return
    needToClose = False
    if (mymsmd is None):
        mymsmd = createCasaTool(msmdtool)
        mymsmd.open(vis)
        needToClose = True
    allIntents = mymsmd.intents()
    if (intent not in allIntents and intent != ''):
        for i in allIntents:
            if i.find(intent) >= 0:
                intent = i
                print("Translated intent to ", i)
                break
    # minimum match OBSERVE_TARGET to OBSERVE_TARGET#UNSPECIFIED
    value = [i.find(intent.replace('*','')) for i in allIntents]
    # If any intent gives a match, the mean value of the location list will be > -1
    if np.mean(value) == -1 and intent != '':
        if not quiet:
            print("%s not found in this dataset. Available intents: " % (intent), allIntents)
        if needToClose: 
            mymsmd.close()
        if returnString:
            return ''
        else:
            return []
    if intent == '':
        spws = callspwsforintent(mymsmd,'*')
    else:
        spws = callspwsforintent(mymsmd,intent)
    if (getObservatoryName(vis).find('ALMA') >= 0 or getObservatoryName(vis).find('OSF') >= 0):
        if chavg and not sqld:
            sqldspws = callalmaspws(mymsmd,sqld=True)
        if verbose:
            print("Calling almaspws(chavg=%s, tdm=%s, fdm=%s, sqld=%s)" % (chavg, tdm, fdm, sqld))
        almaspws = callalmaspws(mymsmd, chavg=chavg, tdm=tdm, fdm=fdm, sqld=sqld)
        if chavg and not sqld:
            if verbose:
                print("removing SQLD (%s) from list" % (sqldspws))
            almaspws = list(set(almaspws) - set(sqldspws))
        if (len(spws) == 0 or len(almaspws) == 0):
            scienceSpws = []
        else:
            scienceSpws = [int(i) for i in np.intersect1d(spws,almaspws)]
    else:
        scienceSpws = spws
    mydict = {}
    for spw in scienceSpws:
        mydict[spw] = sorted([mymsmd.chanfreqs(spw)[0],mymsmd.chanfreqs(spw)[-1]])
    if needToClose:
        mymsmd.close()
    if returnFreqRanges:
        return mydict
    if returnString:
        return(','.join(str(i) for i in scienceSpws))
    elif returnListOfStrings:
        return list([str(i) for i in scienceSpws])
    else:
        return(list(scienceSpws))

def getScienceTargetFieldIDsFromASDM(asdm, n=-1, returnDict=False):
    """
    Returns an array of the integer field IDs that correspond to the
    nth science target.  If n < 0,  return all field IDs.
    For the ms version, see getScienceTargets(returnNames=False)
    -Todd Hunter
    """
    names = np.array(getScienceTargetsFromASDM(asdm))
    if n >= len(names):
        print("There are only %d science target names in this ASDM." % (len(names)))
        return
    mydict, ignore = getFieldsFromASDM(asdm)
    # mydict has keys of field IDs and values of field names
    targetdict = {}
    if n < 0:
        scienceNames = np.intersect1d(list(mydict.values()), names)
        fieldIDs = []
        stringValues = np.array([str(i) for i in list(mydict.values())]) # convert np.bytes_ to str
        for name in scienceNames:
            idx = np.where(stringValues == name)[0]
            fieldIDs += list(np.array(list(mydict.keys()))[idx])
            targetdict[name] = sorted(list(np.array(list(mydict.keys()))[idx]))
    else:
        idx = np.where(np.array(list(mydict.values())) == names[n])
        fieldIDs = np.array(list(mydict.keys()))[idx]
        targetdict[names[n]] = sorted(list(fieldIDs))
    if returnDict:
        return targetdict
    else:
        return sorted(fieldIDs)

def getScienceTargetRADecsFromASDM(asdm, sexagesimal=False, returndict=False, degrees=False):
    """
    Returns: list of RA, Dec tuples in radians
    sexagesimal: if True, then a list of strings
    returndict: if True, then return dictionary keyed by field ID
    """
    fieldIDs = getScienceTargetFieldIDsFromASDM(asdm)
    print("science field IDs: ", fieldIDs)
    radec = []
    mydict = {}
    for fieldID in fieldIDs:
        r = getRADecForFieldFromASDM(asdm, fieldID)
        if sexagesimal:
            r = rad2radec(r, verbose=False)
        elif degrees:
            r = np.degrees(r)
        radec.append(list(r))
        mydict[fieldID] = r
    if returndict:
        radec = mydict
    return radec

def getScienceTargetsFromASDM(asdm):
    """
    Get a list of unique names of the science targets from an ASDM
    -Todd Hunter
    """
    mydict = readscans(asdm)[0]
    targets = []
    for key in list(mydict.keys()):
        if (mydict[key]['intent'].find('OBSERVE_TARGET') >= 0):
            targets.append(mydict[key]['source'])
    return np.unique(targets)

def getScienceTargets(vis, intent='OBSERVE_TARGET*', mymsmd=None, 
                      returnNames=True, checkSpw=True, unique=False):
    """
    Get a list of names of the science targets from a measurement set (using 
    msmd).
    checkSpw: if True, confirm that field name was observed in first science spw
       Note: if not all sources share the same tuning, then you need to set
             checkSpw=False if you want to retrieve all science targets.
    unique: if True, then return unique list of names, and a corresponding list
       of first fieldID of this name that was observed with the specified intent
    For the ASDM version, see getScienceTargetFieldIDsFromASDM()
    -Todd Hunter
    """
    needToClose = False
    if mymsmd is None:
        if not os.path.exists(vis):
            print("Could not open ms: %s" % (vis))
            return
        needToClose = True
        mymsmd = createCasaTool(msmdtool)
        mymsmd.open(vis)
    ids = mymsmd.fieldsforintent(intent)
    if checkSpw:
        spws = callspwsforintent(mymsmd, intent)
        fieldIDs_spw = mymsmd.fieldsforspw(spws[0])
        ids = np.intersect1d(ids,fieldIDs_spw)
    if len(ids) == 0: 
        fields = []
    else:
        fields = mymsmd.namesforfields(ids)
    if unique:
        fields = np.unique(fields)
        firstFieldIDs = []
        for field in fields:
            firstField = sorted(np.intersect1d(mymsmd.fieldsforintent(intent),mymsmd.fieldsforname(field)))[0]
            firstFieldIDs.append(firstField)
    if needToClose:
        mymsmd.close()
    if returnNames:
        if unique:
            return fields, firstFieldIDs
        else:
            return fields
    else:
        return ids

def getCalibrators(vis, intent=['BANDPASS','FLUX','PHASE','AMP','POLARIZATION','CHECK_SOURCE'],
                   mymsmd=None, returnNames=True, returnDict=False, returnListForSingleCalibrator=False,
                   invertDictionary=False):
    """
    Get a list of names of the calibrators from a measurement set (using msmd)
    intent: can be a comma-delimited string or a python list of strings
    invertDictionary: if True, then make the intents be the values and the name or ID as the key
    Returns: 
    a list of names or integers (if returndDict is False), else
    a dictionary keyed by intent with <value> equal to field name or integer ID
         <value> will be a list if it is longer than one name or integer
    """
    needToClose = False
    if mymsmd is None:
        needToClose = True
        mymsmd = createCasaTool(msmdtool)
        mymsmd.open(vis)
    ids = []
    intents = mymsmd.intents()
    if type(intent) == str:
        intent = intent.split(',')
    mydict = {}
    for i in intent:
        if 'CALIBRATE_' + i.replace('*','') + '#ON_SOURCE' in intents or 'OBSERVE_' + i.replace('*','') + '#ON_SOURCE' in intents:
            newlist = list(mymsmd.fieldsforintent('*' + i + '*'))
            ids += newlist
            if len(newlist) == 1 and not returnListForSingleCalibrator:
                mydict[i] = newlist[0]
            else:
                mydict[i] = newlist
    if len(ids) == 0: 
        fields = []
    else:
        fields = mymsmd.namesforfields(ids)
    for key in mydict:
        if returnNames:
            mydict[key] = mymsmd.namesforfields(mydict[key])
            if len(mydict[key]) == 1 and not returnListForSingleCalibrator:
                mydict[key] = mydict[key][0]
    if needToClose:
        mymsmd.close()
    if returnDict:
        if invertDictionary:
            newdict = {}
            for key in mydict.keys():
                newdict[mydict[key]] = key
            mydict = newdict
        return mydict
    elif returnNames:
        return fields
    else:
        return ids

def getWeightedMeanScienceFrequency(vis):
    """
    Computes the mean frequency of all science spws, weighted by the mean data-weigths of each spw
    vis: single or multiple measurement sets, as a python list of strings, or comma-delimited string
    -Todd Hunter
    """
    weights = []
    meanfreqs = []
    if type(vis) != list:
        if vis.find('*') >= 0:
            vislist = glob.glob(vis)
        else:
            vislist = vis.split(',')
    else:
        vislist = vis
    for vis in vislist:
        if not os.path.exists(vis):
            print("Could not find measurement set: ", vis)
            return
        print("Processing vis: ", os.path.basename(vis))
        mymsmd = msmdtool()
        mymsmd.open(vis)
        freqs = getScienceFrequencies(vis, returnDict=True, mymsmd=mymsmd)
        for spw in list(freqs.keys()):
            meanfreqs.append(freqs[spw])
            weights.append(getMeanWeights(vis, spw=spw, mymsmd=mymsmd))
        mymsmd.close()
    return np.average(meanfreqs, weights=weights)

def getExtremeSpws(vis, intent='OBSERVE_TARGET#ON_SOURCE', verbose=False, mymsmd=None, spw=''):
    """
    Returns the spws IDs containing the minimum and maximum frequencies for the specified intent.
    spw: if specified, then use that spw or list of spws (comma-delimited string or int list)
         if not specified, then use all with the specified intent
         If none have that intent, then use all the spws with more than 4 channels
         i.e. not the WVR data nor the channel-averaged data.  
    -- Todd Hunter
    """
    minfreqs = []
    maxfreqs = []
    if (casaVersion >= casaVersionWithMSMD):
        needToClose = False
        if mymsmd is None or mymsmd == '':
            needToClose = True
            mymsmd = createCasaTool(msmdtool)
            mymsmd.open(vis)
        if (intent not in mymsmd.intents()):
            if intent.split('#')[0] in [i.split('#')[0] for i in mymsmd.intents()]:
                # VLA uses OBSERVE_TARGET#UNSPECIFIED
                intent = intent.split('#')[0]+'*'
            else:
                print("Intent %s not in dataset (nor is %s*)." % (intent,intent.split('#')[0]))

        if (spw == ''):
            argument = [i.find(intent.replace('*','')) for i in mymsmd.intents()]
            if len(argument) == 0:
                spws = []
            elif (np.max(argument) == -1):
                spws = []
            else:
                spws = callspwsforintent(mymsmd, intent)
        elif (type(spw) == str):
            spws = [int(i) for i in spw.split(',')]
        elif (type(spw) != list):  
            # i.e. integer
            spws = [spw]
        else:
            spws = spw
        if verbose:
            print("Using spws: ", spws)
        if (getObservatoryName(vis).find('ALMA') >= 0 or getObservatoryName(vis).find('OSF') >= 0):
            almaspws = callalmaspws(mymsmd,tdm=True,fdm=True)
            if (len(spws) == 0):
                nonwvrspws = getNonWvrSpws(mymsmd)
                for spw in nonwvrspws:
                    minfreqs.append(np.min(mymsmd.chanfreqs(spw)))
                    maxfreqs.append(np.max(mymsmd.chanfreqs(spw)))
            else:
                spws = np.intersect1d(spws,almaspws)
                for spw in spws:
                    minfreqs.append(np.min(mymsmd.chanfreqs(spw)))
                    maxfreqs.append(np.max(mymsmd.chanfreqs(spw)))
        else:
            for spw in spws:
                minfreqs.append(np.min(mymsmd.chanfreqs(spw)))
                maxfreqs.append(np.max(mymsmd.chanfreqs(spw)))
        if needToClose:
            mymsmd.close()
    else:
        mytb = createCasaTool(tbtool)
        try:
            mytb.open("%s/SPECTRAL_WINDOW" % vis)
        except:
            print("Could not open ms table = %s" % (vis))
            return(freqs)
        numChan = mytb.getcol("NUM_CHAN")
        for i in range(len(numChan)):
            if (numChan[i] > 4):
                chanFreq = mytb.getcell("CHAN_FREQ",i)
                minfreqs.append(np.min(chanFreq))
                maxfreqs.append(np.max(chanFreq))
        mytb.close()
    minspw = np.argmin(minfreqs)
    maxspw = np.argmax(maxfreqs)
    return spws[minspw], spws[maxspw]

def getScienceFrequencies(vis, spw='', intent='OBSERVE_TARGET#ON_SOURCE', verbose=False, mymsmd=None, 
                          returnDict=False, returnGHz=False):
    """
    Return a list of the mean frequencies (in Hz) of each spw 
    returnGHz: if True, return values in units of GHz
    spw: if specified, then use that spw or list of spws (comma-delimited string or int list)
         if not specified, then use all with the specified intent
         If none have that intent, then use all the spws with more than 4 channels
         i.e. not the WVR data nor the channel-averaged data.  
    returnDict: if True, return a dictionary keyed by spw ID
    -- Todd Hunter
    """
    freqs = []
    mydict = {}
    if (casaVersion >= casaVersionWithMSMD):
        needToClose = False
        if mymsmd is None or mymsmd == '':
            needToClose = True
            mymsmd = createCasaTool(msmdtool)
            mymsmd.open(vis)
        if (intent not in mymsmd.intents()) and intent != '':
            if intent.split('#')[0] in [i.split('#')[0] for i in mymsmd.intents()]:
                # VLA uses OBSERVE_TARGET#UNSPECIFIED
                intent = intent.split('#')[0]+'*'
            else:
                print("Intent %s not in dataset (nor is %s*)." % (intent,intent.split('#')[0]))

        if (spw == ''):
            argument = [i.find(intent.replace('*','')) for i in mymsmd.intents()]
            if len(argument) == 0:
                spws = []
            elif (np.max(argument) == -1):
                spws = []
            else:
                spws = callspwsforintent(mymsmd, intent)
        elif (type(spw) == str):
            spws = [int(i) for i in spw.split(',')]
        elif (type(spw) != list):  
            # i.e. integer
            spws = [spw]
        else:
            spws = spw
        if len(spws) == 0: 
            print("using all spws")
            spws = range(mymsmd.nspw())
        if verbose:
            print("Using spws: ", spws)
        if (getObservatoryName(vis).find('ALMA') >= 0 or getObservatoryName(vis).find('OSF') >= 0):
            almaspws = callalmaspws(mymsmd,tdm=True,fdm=True)
            if (len(spws) == 0):
                nonwvrspws = getNonWvrSpws(mymsmd)
                for spw in nonwvrspws:
                    freqs.append(mymsmd.meanfreq(spw))
                    mydict[spw] = mymsmd.meanfreq(spw)
            else:
                spws = np.intersect1d(spws,almaspws)
                for spw in spws:
                    freqs.append(mymsmd.meanfreq(spw))
                    mydict[spw] = mymsmd.meanfreq(spw)
        else:
            for spw in spws:
                freqs.append(mymsmd.meanfreq(spw))
                mydict[spw] = mymsmd.meanfreq(spw)
        if returnGHz:
            freqs = list(np.array(freqs)*1e-9)
            for spw in spws:
                mydict[spw] *= 1e-9
        if needToClose:
            mymsmd.close()
        if returnDict:
            return mydict
        else:
            return freqs
    else:
        mytb = createCasaTool(tbtool)
        try:
            mytb.open("%s/SPECTRAL_WINDOW" % vis)
        except:
            print("Could not open ms table = %s" % (vis))
            return(freqs)
        numChan = mytb.getcol("NUM_CHAN")
        for i in range(len(numChan)):
            if (numChan[i] > 4):
                chanFreq = mytb.getcell("CHAN_FREQ",i)
                freqs.append(np.mean(chanFreq))
        mytb.close()
        if returnGHz:
            freqs = list(np.array(freqs)*1e-9)
        return freqs
    
def listConditionsFromASDM(asdm, station=1, verbose=True):
    """
    This function extracts the weather conditions for the specified ASDM,
    and computes and returns a dictionary containing the median values.
    The default weather station to use is 1.
    For further help and examples, see https://safe.nrao.edu/wiki/bin/view/ALMA/ListConditionsFromASDM
    Todd Hunter
    """
    [conditions, medianConditions, stationName] = getWeatherFromASDM(asdm,station=station)
    if (verbose):
        print("Median weather values for %s to %s" % (plotbp3.utstring(conditions[0][0]),plotbp3.utstring(conditions[0][-1])))
        print("  Pressure = %.2f mb" % (medianConditions['pressure']))
        print("  Temperature = %.2f C" % (medianConditions['temperature']))
#        print "  Dew point = %.2f C" % (medianConditions['dewpoint'])
        print("  Relative Humidity = %.2f %%" % (medianConditions['humidity']))
        print("  Wind speed = %.2f m/s" % (medianConditions['windSpeed']))
        print("  Wind max = %.2f m/s" % (np.max(conditions[6])))
        print("  Wind direction = %.2f deg" % (medianConditions['windDirection']))
    return(medianConditions)

def listconditions(vis='', scan='', antenna='0',verbose=True,asdm='',reffreq=0,
                   byscan=False, vm=0, mymsmd='',field='',debug=False, getSolarDirection=True):
    """
    Compiles the mean weather, pwv and opacity values for the given scan
    number or scan list for the specified ms.  If a scan number
    is not provided it returns the average over all science spws in whole ms.
    byscan: setting this True will return a dictionary with conditions per scan.
    field: setting this will run msmd.scansforfield, and use only those scans.
    reffreq: value in GHz (use this to restrict to one spw)
    Note: In casa 4.4 and 4.5, when run on concatenated measurement sets, 
          only the scans from the first obsid are detected due to a change 
          in msmd, a behavior which was fixed in casa 4.6.
    Scan can be a single list: [1,2,3] or '1,2,3' or a single range: '1~4'.
    For further help and examples, see https://safe.nrao.edu/wiki/bin/view/ALMA/Listconditions
    Todd Hunter
    """
    if (os.path.exists(vis)==False):
        print("Could not find the ms = %s." % (vis))
        return
    if (os.path.exists(vis+'/table.dat') == False):
        print("No table.dat.  This does not appear to be an ms.")
        return
    if (type(scan) == str):
        if (scan.find(',')>0):
            scan = [int(k) for k in scan.split(',')]
        elif (scan.find('~')>0):
            scan = range(int(scan.split('~')[0]),int(scan.split('~')[1])+1)
    if (casaVersion >= casaVersionWithMSMD):
        if mymsmd == '':
            mymsmd = createCasaTool(msmdtool)
            mymsmd.open(vis)
            needToClose = True
        else:
            needToClose = False
        if (field != ''):
            scan = mymsmd.scansforfield(int(field))
            print("Will use scans: ", str(scan))
    else:
        if (field != ''):
            print("The field parameter is not supported for this old of a CASA.")
            return
    if (reffreq==0):
        freqs = 1e-9*np.array(getScienceFrequencies(vis, mymsmd=mymsmd))
    else:
        freqs = [reffreq]
    if (byscan and (type(scan) == list or scan=='')):
        conditions = {}
        if (scan == ''):
            if (casaVersion >= casaVersionWithMSMD):
                scan = callscannumbers(mymsmd)
            else:
                if (vm == 0):
                    vm = ValueMapping(vis)
                scan = np.unique(vm.scans)
            print("Scans = ", scan)
        pwvstd = 1 # get into the loop the first time, but do not repeat if no WVR file present
        for i in scan:
            if debug:
                print("Calling au.getWeather('%s',%d,'%s',%s)" % (vis,i,antenna,verbose))
            [cond,myTimes,vm] = getWeather(vis,i,antenna,verbose,vm,mymsmd,getSolarDirection=getSolarDirection)
            if (len(myTimes) > 0 and pwvstd>0):
                [pwv,pwvstd] = getMedianPWV(vis,myTimes,asdm,verbose=False)
                if (pwvstd > 0):
                    if (pwv > 0):
                        tau = []
                        zenithtau = []
                        for myfreq in range(len(freqs)):
                            reffreq = freqs[myfreq]
                            [z,t] = estimateOpacity(pwv, reffreq, cond, verbose)
                            zenithtau.append(z)
                            tau.append(t)
                        d2 = {}
                        d2['tauzenith'] = np.mean(zenithtau)
                        d2['tau'] = np.mean(tau)
                        d2['transmissionzenith'] = np.exp(-np.mean(zenithtau))
                        d2['transmission'] = np.exp(-np.mean(tau))
                        d2['pwv'] = pwv
                        d2['pwvstd'] = pwvstd
                        cond = dict(list(cond.items()) + list(d2.items()))
            conditions[i] = cond
    else:
        if debug:
            print("Calling getWeather('%s','%s','%s',%s), len(freqs)=%d" % (vis,str(scan),antenna,verbose,len(freqs)))
        [conditions,myTimes,vm] = getWeather(vis,scan,antenna,verbose,vm,mymsmd,getSolarDirection=getSolarDirection)
        if debug:
            print("len(myTimes) = %d" % (len(myTimes)))
        if (len(myTimes) < 1):
            return(conditions)
        [pwv,pwvstd] = getMedianPWV(vis,myTimes,asdm,verbose=False)
        if debug:
            print("pwv = %f" % (pwv))
        if (pwvstd < 0):
            return(conditions)
        if (pwv > 0):
            tau = []
            zenithtau = []
            for i in range(len(freqs)):
                reffreq = freqs[i]
                [z,t] = estimateOpacity(pwv, reffreq, conditions,verbose)
                zenithtau.append(z)
                tau.append(t)
            d2 = {}
            d2['tauzenith'] = np.mean(zenithtau)
            d2['tau'] = np.mean(tau)
            d2['transmissionzenith'] = np.exp(-np.mean(zenithtau))
            d2['transmission'] = np.exp(-np.mean(tau))
            d2['pwv'] = pwv
            d2['pwvstd'] = pwvstd
            conditions = dict(list(conditions.items())+list(d2.items()))
    if needToClose:
        mymsmd.close()
    return(conditions)

def buildCalDataIdDictionary(vis, tol=10, debug=False, sbr=True, atm=True, mymsmd=None):
    """
    Provides the mapping from cal data ID to scan number via the times, as an alternative
    to using readCalData which requires the ASDM_CALDATA table.
    vis: string name of ms
    tol: tolerance in seconds (should not have to change this)
    sbr: include SIDEBAND_RATIO scans
    atm: include CALIBRATE_ATMOSPHERE scans
    """
    mytable = vis+'/ASDM_CALATMOSPHERE'
    mytb = createCasaTool(tbtool)
    mytb.open(mytable)
    startValidTime = mytb.getcol('startValidTime')
    calDataId = np.array([int(c.split('_')[-1]) for c in mytb.getcol('calDataId')])
    mytb.close()
    # these range from 2-40 seconds after the first integration of the scan
    # so do a rough correction for this
    startValidTime -= 10  
    needToClose = False
    if mymsmd is None:
        needToClose = True
        mymsmd = createCasaTool(msmdtool)
        mymsmd.open(vis)
    scans = callscannumbers(mymsmd)
    times = mymsmd.timesforscans(scans)
    if ('CALIBRATE_ATMOSPHERE#ON_SOURCE' in mymsmd.intents()):
        calscans = mymsmd.scansforintent('CALIBRATE_ATMOSPHERE#ON_SOURCE')
    elif ('CALIBRATE_ATMOSPHERE#HOT' in mymsmd.intents()):   
        calscans = mymsmd.scansforintent('CALIBRATE_ATMOSPHERE#HOT')
    else:
        calscans = []
    if ('CALIBRATE_SIDEBAND_RATIO#ON_SOURCE' in mymsmd.intents()):
        sbrscans = mymsmd.scansforintent('CALIBRATE_SIDEBAND_RATIO#ON_SOURCE')
    else:
        sbrscans = []
    if (debug):
        print("%d calscans=%s,  %d sbrscans=%s" % (len(calscans),str(calscans), len(sbrscans), str(sbrscans)))
    if (sbr and atm):
        cal_sbr_scans = np.unique(np.union1d(calscans, sbrscans))
    elif (sbr):
        cal_sbr_scans = sbrscans
    else:
        cal_sbr_scans = calscans
        
    calscantimesdict = {}
    for i in range(len(calDataId)):
        cal = calDataId[i]
        if (cal not in list(calscantimesdict.keys())):
            calscantimesdict[cal] = []
        calscantimesdict[cal].append(startValidTime[i])
    for key in list(calscantimesdict.keys()):
        mylen = len(np.unique(calscantimesdict[key]))
        if (mylen > 1):
            print("Cal data ID %d has multiple startValidTimes (%d). Taking the minimum." % (key, mylen))
        calscantimesdict[key] = np.min(calscantimesdict[key])
        if (debug):
            print("%2d = %s" % (key, mjdsecToUTHMS(calscantimesdict[key])))
        
    calscandict = {}
    scansAssigned = []
    stopTol = 6.01*tol
    for tolerance in np.arange(tol, stopTol, tol):
        if (debug):
            print("tolerance = %.0f sec, calscandict=%s" % (tolerance,str(calscandict)))
        for i in range(len(calDataId)):
            cal = calDataId[i]
#            if (debug):
#                print "Working on row %d, calDataId=%d" % (i,cal)
            if (cal not in list(calscandict.keys())):
                calscandict[cal] = []
            if (tolerance == tol or len(calscandict[cal]) == 0):
                trialscans = mymsmd.scansfortimes(calscantimesdict[cal]+tolerance, tol=tolerance)
                for scan in sorted(list(trialscans)):
                    if (scan not in calscandict[cal] and
                        scan not in scansAssigned):
                        if (scan in cal_sbr_scans):
                            calscandict[cal].append(scan)
                            scansAssigned.append(scan)
                            if (debug):
                                print("tol=%.0f: calscandict[%d].append(%d) of %s (%s-%s)" % (tolerance,cal,scan,str(trialscans), mjdsecToUTHMS(calscantimesdict[cal]), mjdsecToUTHMS(calscantimesdict[cal]+tolerance*2)))
        # loosen the tolerance until all are filled with a value
        if (len(scansAssigned) == len(cal_sbr_scans)):
            allFilled = True
            for key in list(calscandict.keys()):
                if (len(calscandict[key]) == 0):
                    allFilled = False
            if (allFilled): break
        unassigned = np.setdiff1d(cal_sbr_scans, scansAssigned) 
        if (tolerance+tol < stopTol):
            scansAssigned = []
            calscandict = {}
        if ((debug or tolerance+tol > stopTol) and sbr and atm and len(unassigned)>0):
            print("not all scans assigned (%d vs. %d), unassigned = %s" % (len(scansAssigned), len(calscans)+len(sbrscans), str(unassigned)))
    csd = {}
    for key in list(calscandict.keys()):
        if (len(calscandict[key]) > 0):
            csd[key] = np.array(calscandict[key],np.int32)
    if needToClose:
        mymsmd.close()
    if (debug):
        print("returning from buildCalDataIdDictionary, %d/%d scans assigned" % (len(scansAssigned),len(cal_sbr_scans)))
    return(csd)
    
def readCalData(vis, calType='CAL_ATMOSPHERE'):
    """
    Provides the mapping from cal data ID to scan number
    Returns:
       a translation dictionary from calDataId to scan numbers
    Todd Hunter
    """
    mytb = createCasaTool(tbtool)
    if (os.path.exists(vis+'/ASDM_CALDATA') == False):
        print("No ASDM_CALDATA file.  Either importasdm(asis='CalData') or try readCalDataFromASDM instead.")
        return 
    mytb.open(vis+'/ASDM_CALDATA')
    calDataId = np.array([int(c.split('_')[-1]) for c in mytb.getcol('calDataId')])
    calibType = mytb.getcol('calType')
    if (calType not in calibType):
        print("%s is not a calibration type in this dataset.\nAvailable types = %s" % (calType,str(np.unique(calibType))))
        return
    scanSet = []
    for row in range(len(calibType)):
        scanSet.append(mytb.getcell('scanSet',row))
    mytb.close()
    mymsmd = createCasaTool(msmdtool)
    mymsmd.open(vis)
    if (calType == 'CAL_ATMOSPHERE'):
        calatmscans = mymsmd.scansforintent('CALIBRATE_ATMOSPHERE#ON_SOURCE')
    else:
        calatmscans = mymsmd.scansforintent(calType)
    mymsmd.close()
    mydict = {}
    for row in range(len(calibType)):
        cDI = calDataId[row]
        mydict[cDI] = scanSet[row]
    return(mydict)
    
def readCalDataFromASDM(sdmfile, useMinidom=False):
    """
    Builds a dictionary relating the calDataId to the scan number of an ASDM.
    useMinidom: if True, then parse the .xml file even if the ASDM python
                bindings are available
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    Todd Hunter
    """
    if (os.path.exists(sdmfile) == False):
        print("readCalDataFromASDM(): Could not find file = ", sdmfile)
        return
    if not asdmLibraryAvailable or useMinidom:
        import au_noASDMLibrary
        scandict = au_noASDMLibrary.readCalDataFromASDM_minidom(sdmfile)
    else:
        a = ASDM()
        parser = ASDMParseOptions()
        parser.asALMA()
        parser.loadTablesOnDemand(True)
        a.setFromFile(sdmfile,parser)
        calDataTable = a.calDataTable().get()
        scandict = {}
        for fid,row in enumerate(calDataTable):
            scandict[fid] = {}
            scandict[fid]['calDataId'] = str(row.calDataId())
            scandict[fid]['scan'] = row.scanSet()
            fid += 1
    return(scandict)

def readCalPointingTable(sdmfile, useMinidom=False):
    """
    Reads the CalPointing.xml table for the specified ASDM
    and returns a dictionary of values.
    useMinidom: if True, then parse the .xml file even if the ASDM python
                bindings are available
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    Todd Hunter
    """
    if (not os.path.exists(sdmfile)):
        print("readCalPointingTable(): Could not find ASDM = ", sdmfile)
        return(None)
    if (not os.path.exists(sdmfile+'/CalPointing.xml')):
        print("readCalPointingTable(): Could not find %s/CalPointing.xml." % (sdmfile))
        return(None)
    if not asdmLibraryAvailable or useMinidom:
        import au_noASDMLibrary
        scandict = au_noASDMLibrary.readCalPointingTable_minidom(sdmfile)
    else:
        a = ASDM()
        parser = ASDMParseOptions()
        parser.asALMA()
        parser.loadTablesOnDemand(True)
        a.setFromFile(sdmfile, parser)
        calPointingTable = a.calPointingTable().get()
        scandict = {}
        for fid,row in enumerate(calPointingTable):
            scandict[fid] = {}
            scandict[fid]['antenna'] = row.antennaName()
            rowDirection = row.direction()
            scandict[fid]['azimuth'] = AnglesToRadians(rowDirection)[0]
            scandict[fid]['elevation'] = AnglesToRadians(rowDirection)[1]
            scandict[fid]['startValidTime'] = row.startValidTime().get()
            scandict[fid]['endValidTime'] = row.endValidTime().get()
            startmjd = row.startValidTime().get()*1e-9/86400
            endmjd = row.endValidTime().get()*1e-9/86400
            scandict[fid]['startmjd'] = startmjd
            scandict[fid]['endmjd'] = endmjd
            scandict[fid]['duration'] = (endmjd-startmjd)*86400
            scandict[fid]['start'] = mjdToDatestring(scandict[fid]['startmjd'], '/','/')
            scandict[fid]['end'] = mjdToDatestring(scandict[fid]['endmjd'], '/','/')
            scandict[fid]['frequency'] = np.mean([parseFrequencyArgumentToHz(str(i)) for i in row.frequencyRange()])
            scandict[fid]['azOffset'] = parseAngleArgumentToRadians(row.collOffsetRelative()[0][0])
            scandict[fid]['elOffset'] = parseAngleArgumentToRadians(row.collOffsetRelative()[0][1])
            scandict[fid]['azOffset2'] = parseAngleArgumentToRadians(row.collOffsetRelative()[1][0])
            scandict[fid]['elOffset2'] = parseAngleArgumentToRadians(row.collOffsetRelative()[1][1])
            scandict[fid]['azError'] = parseAngleArgumentToRadians(row.collError()[0][0])
            scandict[fid]['elError'] = parseAngleArgumentToRadians(row.collError()[0][1])
            scandict[fid]['azError2'] = parseAngleArgumentToRadians(row.collError()[1][0])
            scandict[fid]['elError2'] = parseAngleArgumentToRadians(row.collError()[1][1])
            scandict[fid]['scan'] = int(row.calDataId().get())
            scandict[fid]['polarizationTypes'] = [str(i) for i in list(row.polarizationTypes())]
    return scandict
# end of readCalPointingTable(sdmfile):

def AnglesToDegrees(angles):
    """
    Converts a tuple of Angle objects (as returned by ASDM library) to a list of degrees:
    (1.159267e+00rad, 9.601918e-01rad) --> [x.xxxxx, y.yyyyyy]
    -Todd Hunter
    """
    azim = parseAngleArgumentToDegrees(str(angles[0]))
    elev = parseAngleArgumentToDegrees(str(angles[1]))
    return [azim,elev]
    
def AnglesToRadians(angles):
    """
    Converts a tuple of Angle objects (as returned by ASDM library) to a list of radians:
    (1.159267e+00rad, 9.601918e-01rad) --> [x.xxxxx, y.yyyyyy]
    -Todd Hunter
    """
    azim = np.radians(parseAngleArgumentToDegrees(str(angles[0])))
    elev = np.radians(parseAngleArgumentToDegrees(str(angles[1])))
    return [azim,elev]
    
def readCalPointing(asdm, useMinidom=False):
    """
    Calls readCalPointingTable() and converts the returned dictionary to a list
    of lists that is subsequently used by plotPointingResultsFromASDM().
    useMinidom: if True, then parse the .xml file even if the ASDM python
                bindings are available
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    -Todd Hunter
    """
    dict = readCalPointingTable(asdm, useMinidom)
    if (dict is None):
        return
    colOffsetRelative = []
    colError = []
    antennaName = []
    pols = []
    scans = []
    startValidTime = []
    azim = []
    elev = []
    frequency = []
    for entry in dict:
        colOffsetRelative.append([[dict[entry]['azOffset'],dict[entry]['elOffset']],[dict[entry]['azOffset2'],dict[entry]['elOffset2']]])
        antennaName.append(dict[entry]['antenna'].strip())
        startValidTime.append(dict[entry]['startValidTime'])
        pols.append(dict[entry]['polarizationTypes'])
        scans.append(dict[entry]['scan'])
        azim.append(dict[entry]['azimuth'])
        elev.append(dict[entry]['elevation'])
        frequency.append(dict[entry]['frequency']*1e-9)
        colError.append([[dict[entry]['azError'], dict[entry]['elError']], [dict[entry]['azError2'], dict[entry]['elError2']]])
    return([ARCSEC_PER_RAD*np.array(colOffsetRelative), antennaName, startValidTime, pols, scans,
            np.array(azim)*180/math.pi,np.array(elev)*180/math.pi, ARCSEC_PER_RAD*np.array(colError), np.array(frequency)])   


def getMedianPWV(vis='.', myTimes=[0,999999999999], asdm='', verbose=False):
    """
    Extracts the PWV measurements from the WVR on all antennas for the
    specified time range.  The time range is input as a two-element list of
    MJD seconds (default = all times).  You can specify either the vis or 
    the asdm.
    if vis is set, then first it tries to find the ASDM_CALWVR
    table in the ms.  If that fails, it then tries to find the 
    ASDM_CALATMOSPHERE table in the ms.  If that fails, it then tries to find 
    the CalWVR.xml in the specified ASDM, or failing that, an ASDM of the 
    same name (minus the .ms).  If neither of these exist, then it tries to find 
    a CalWVR.xml in the present working directory. If it still fails, it looks 
    for CalWVR.xml in the .ms directory.  Thus, you only need to copy this 
    single xml file from the ASDM into your ms, rather than the entire ASDM.
    For the asdm option, you can set ASDM_LIBRARY_PATH in ~/.casa/startup.py 
    to point to ASDM python bindings.
    Returns:
    The median PWV, and the median absolute deviation (scaled to match rms) in mm
    For further help and examples, see https://safe.nrao.edu/wiki/bin/view/ALMA/GetMedianPWV
    -- Todd Hunter
    """
    pwvmean = 0
    success = False
    if (verbose):
        print("in getMedianPWV with myTimes = ", myTimes)
    try:
      if (os.path.exists("%s/ASDM_CALWVR"%vis)):
          mytb = tbtool()
          mytb.open("%s/ASDM_CALWVR" % vis)
          pwvtime = mytb.getcol('startValidTime')  # mjdsec
          antenna = mytb.getcol('antennaName')
          pwv = mytb.getcol('water')
          mytb.close()
          success = True
          if (len(pwv) < 1):
              if (os.path.exists("%s/ASDM_CALATMOSPHERE" % vis)):
                  pwvtime, antenna, pwv = readPWVFromASDM_CALATMOSPHERE(vis)
                  success = True
                  if (len(pwv) < 1):
                      print("Found no data in ASDM_CALWVR nor ASDM_CALATMOSPHERE table")
                      return(0,-1)
              else:
                  if (verbose):
                      print("Did not find ASDM_CALATMOSPHERE in the ms")
                  return(0,-1)
          if (verbose):
              print("Opened ASDM_CALWVR table, len(pwvtime)=", len(pwvtime))
      else:
          if (verbose):
              print("Did not find ASDM_CALWVR table in the ms. Will look for ASDM_CALATMOSPHERE next.")
          if (os.path.exists("%s/ASDM_CALATMOSPHERE" % vis)):
              pwvtime, antenna, pwv = readPWVFromASDM_CALATMOSPHERE(vis)
              success = True
              if (len(pwv) < 1):
                  print("Found no data in ASDM_CALATMOSPHERE table")
                  return(0,-1)
          else:
              if (verbose):
                  print("Did not find ASDM_CALATMOSPHERE in the ms")
    except:
        if (verbose):
            print("Could not open ASDM_CALWVR table in the ms")
    finally:
    # try to find the ASDM table
     if (success == False):
       if (len(asdm) > 0):
           if (os.path.exists(asdm) == False):
               print("Could not open ASDM = ", asdm)
               return(0,-1)
           try:
               [pwvtime,pwv,antenna] = readpwv(asdm)
           except:
               if (verbose):
                   print("Could not open ASDM = %s" % (asdm))
               return(pwvmean,-1)
       else:
           try:
               tryasdm = vis.split('.ms')[0]
               if (verbose):
                   print("No ASDM name provided, so I will try this name = %s" % (tryasdm))
               [pwvtime,pwv,antenna] = readpwv(tryasdm)
           except:
               try:
                   if (verbose):
                       print("Still did not find it.  Will look for CalWVR.xml in current directory.")
                   [pwvtime, pwv, antenna] = readpwv('.')
               except:
                   try:
                       if (verbose):
                           print("Still did not find it.  Will look for CalWVR.xml in the .ms directory.")
                       [pwvtime, pwv, antenna] = readpwv('%s/'%vis)
                   except:
                       if (verbose):
                           print("No CalWVR.xml file found, so no PWV retrieved. Copy it to this directory and try again.")
                       return(pwvmean,-1)
    try:
        matches = np.where(np.array(pwvtime)>myTimes[0])[0]
    except:
        print("Found no times > %d" % (myTimes[0]))
        return(0,-1)
    if (len(pwv) < 1):
        print("Found no PWV data")
        return(0,-1)
    if (verbose):
        print("%d matches = " % (len(matches)), matches)
        print("%d pwv = " % (len(pwv)), pwv)
    ptime = np.array(pwvtime)[matches]
    matchedpwv = np.array(pwv)[matches]
    matches2 = np.where(ptime<=myTimes[-1])[0]
    if (verbose):
        print("matchedpwv = %s" % (matchedpwv))
        print("pwv = %s" % (pwv))
    if (len(matches2) < 1):
        # look for the value with the closest start time
        mindiff = 1e12
        for i in range(len(pwvtime)):
            if (abs(myTimes[0]-pwvtime[i]) < mindiff):
                mindiff = abs(myTimes[0]-pwvtime[i])
#                pwvmean = pwv[i]*1000
        matchedpwv = []
        for i in range(len(pwvtime)):
            if (abs(abs(myTimes[0]-pwvtime[i]) - mindiff) < 1.0):
                matchedpwv.append(pwv[i])
        pwvmean = 1000*np.median(matchedpwv)
        if (verbose):
            print("Taking the median of %d pwv measurements from all antennas = %.3f mm" % (len(matchedpwv),pwvmean))
        pwvstd = 1000*MAD(matchedpwv)
    else:
        pwvmean = 1000*np.median(matchedpwv[matches2])
        pwvstd = 1000*MAD(matchedpwv[matches2])
        if (verbose):
            print("Taking the median of %d pwv measurements from all antennas = %.3f mm" % (len(matches2),pwvmean))
    return(pwvmean,pwvstd)
# end of getMedianPWV

def getAntennaIDsFromWeatherTable(vis):
    """
    Reads the unique list of antenna IDs from the WEATHER table of a measurement set.
    For ALMA, this will be [-1].
    -Todd Hunter
    """
    mytb = createCasaTool(tbtool)
    mytb.open(vis+'/WEATHER')
    ids = mytb.getcol('ANTENNA_ID')
    print("Read %d rows" % (len(ids)))
    mytb.close()
    uniqueIDs = np.unique(ids)
    return uniqueIDs

def ReadWeatherStation(scandict, station):
    """
    Parses a dictionary returned by readWeatherFromASDM and returns a list of
    lists of weather quantities.
    station: station ID (integer)
    """
    timeInterval = []
    pressure = []
    relHumidity = []
    temperature = []
    windDirection = []
    windSpeed = []
    windMax = []
    for entry in range(len(scandict)):
        if (scandict[entry]['stationId'] == station):
            timeInterval.append(scandict[entry]['timeInterval'])
            pressure.append(scandict[entry]['pressure'])
            relHumidity.append(scandict[entry]['relHumidity'])
            temperature.append(scandict[entry]['temperature'])
            windDirection.append(scandict[entry]['windDirection'])
            windSpeed.append(scandict[entry]['windSpeed'])
            windMax.append(scandict[entry]['windMax'])
#        else:
#            print "scandict=%d != %d" % (scandict[entry]['stationId'],station)
    d1 = [timeInterval, pressure, relHumidity, temperature, windDirection,
          windSpeed, windMax, station]
    return(d1)

def convertASDMTimeIntervalToMJDSeconds(s):
    """
    converts a string of format: 'start=2013-11-10T07:44:17.552000000, duration=369.180000'
    to MJD seconds using only the start time.
    -Todd Hunter
    """
    ymdhms = s.split('=')[1].split(',')[0]
    return(dateStringToMJDSec(ymdhms,verbose=False))

def asdmspwmap(asdm, useMinidom=False):
    """
    Generate a list that maps the spw number that will be found in the
    measurement set to the corresponding value in the ASDM xml files.
    In general, the order will be [0,n+1,n+2,....] where n=number of antennas
    with WVR data.  
    Example return list:  [0,5,6,7...] if n=4 antennas, meaning
           that spw 1 in the ms = spw 5 in the ASDM xml files.
    useMinidom: if True, then parse the .xml file even if the ASDM python
                bindings are available
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    -Todd Hunter
    """
    if (not asdmLibraryAvailable or useMinidom):
        import au_noASDMLibrary
        spwmap = au_noASDMLibrary.asdmspwmap_minidom(asdm)
        return spwmap
    a = ASDM()
    parser = ASDMParseOptions()
    parser.asALMA()
    parser.loadTablesOnDemand(True)
    a.setFromFile(asdm,parser)
    spwTable = a.spectralWindowTable().get()
    spwmap = []
    for row in range(len(spwTable)):
        if (spwTable[row].name().find('WVR#Antenna') < 0):
            spwmap.append(row)
    return(spwmap)

def readTcal(asdm, antenna, spw, meantime=None, spectrum='tcal', verbose=False):
    """
    Read Tcal, Trx, Tsky, or Tsys spectrum for a specific antenna, spw & time. 
    If the time is not specified, it will return a dictionary of spectra keyed
    by the time (in MJD seconds).  The spw should be an spw number
    in the measurement set that is associated with a CALIBRATE_ATMOSPHERE scan.
    A conversion will be made to the spw number
    in the ASDM. If the spw is FDM, it is up to the user to find
    the associated TDM spw (e.g. via tsysspwmap) and pass it in.
    antenna: the antenna ID (string or integer, not the name)
    spw: the spw ID (string or integer)
    spectrum: 'tsys', 'trx' or 'tcal'
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings

    Returns:
    A dictionary keyed by the MJD in seconds, with values equal to a list of
    arrays (one per polarization) each with N channels.
    
    Todd Hunter
    """
    spectrum = spectrum.lower()
    antenna = str(antenna)
    spw = int(spw)
    if (not asdmLibraryAvailable):
        print("The ASDM bindings library is not available on this machine and there is no .xml version of this table.")
        return
    a = ASDM()
    parser = ASDMParseOptions()
    parser.asALMA()
    parser.loadTablesOnDemand(True)
    a.setFromFile(asdm,parser)
    sysCalTable = a.sysCalTable().get()
    # find offset (usually it is the number of antennas with WVR data)
    spwmap = asdmspwmap(asdm)
    if (verbose):
        print("Spwmap = ", spwmap)
    spectra = {}
    timeDelta = 1e20
    for row in sysCalTable:
        antennaId = str(row.antennaId()).split('_')[1]
        if (antennaId == antenna):
            spectralWindowId = str(row.spectralWindowId()).split('_')[1]
            myspw = int(spectralWindowId)
            if (verbose):
                print("spw %d in the MS is spw %d in the ASDM, comparing to ASDM spw %d" % (spw, spwmap[spw], myspw))
            if (spwmap[spw] == myspw):
                mjdsec = convertASDMTimeIntervalToMJDSeconds(str(row.timeInterval()))
                if (spectrum == 'tcal'):
                    values = row.tcalSpectrum()
                elif (spectrum == 'trx'):
                    values = row.trxSpectrum()
                elif (spectrum == 'tsys'):
                    values = row.tsysSpectrum()
                elif (spectrum == 'tsky'):
                    values = row.tskySpectrum()
                elif (spectrum == 'tant'):
                    values = row.tantSpectrum()
                else:
                    print("Unrecognized spectrum type (%s)" % (spectrum))
                    return
                spectra[mjdsec] = []
                for v in values: # there will be one per polarization
                    spectra[mjdsec].append(np.array([v[f].get() for f in range(row.numChan())]))
                if (meantime is not None):
                    if (abs(mjdsec-meantime) < timeDelta):
                        timeDelta = abs(mjdsec-meantime)
                        closestTime = mjdsec
    if (verbose):
        print("Found %d spectra" % (len(spectra)))
    if (meantime is None):
        return(spectra)
    else:
        return(spectra[closestTime], closestTime)

def readStationFromASDMKeyedByAntennaName(sdmfile, station=None):
    """
    Similar to readStationFromASDM and readStationsFromASDM, but returns a dictionary keyed
    by antenna name (instead of antenna ID or pad name).
    Todd Hunter
    """
    mydict = readStationFromASDM(sdmfile, station)
    newdict = {}
    antennaNames = readAntennasFromASDM(sdmfile,verbose=False)
    for key in list(mydict.keys()):
        if (key < len(antennaNames)):
            antennaName = antennaNames[key]
            newdict[antennaName] = mydict[key]
    return(newdict)
    
def getAntennaAmbientTemperaturesFromASDM(asdmFile,  debugPlot=False):
    """
    Access the TMCDB for the antenna amibent temperatures recorded during
    an observation.
    Returns: 4 lists:
        timeList, antennaTemps, meanAntennaTemps, meanAntennaTempsErr
    - Denis Barkats.
    """
    from dateutil import rrule
    
    # get the start time of the ASDM
    dateStart, dateStart_mjdSec = getObservationStartDateFromASDM(asdmFile)
    dateEnd, dateEnd_mjdSec = getObservationEndDateFromASDM(asdmFile)
    antList = readAntennasFromASDM(asdmFile)
    start = dateStart.split(' UT')[0].replace(' ','T')
    end = dateEnd.split(' UT')[0].replace(' ','T')
    
    s = datetime.datetime.strptime(start, '%Y-%m-%dT%H:%M:%S')
    e = datetime.datetime.strptime(end, '%Y-%m-%dT%H:%M:%S')

    # time range to interpolate the other monitor points on.
    timeList = list(rrule.rrule(rrule.SECONDLY,interval=30, dtstart=s,until=e))
    ftimeList = pb.date2num(timeList)

    antennaTemps = {}
    meanAntennaTemps = {}
    meanAntennaTempsErr = {}
    for ant in antList:
        if ant[0:2]=='CM':
            # from ICT-1797
            # CM antennas: quadrapod, 4 total:
            # GET_METR_TEMPS_04[0]...[3]
            mpts = {'METR_TEMPS_04': [0,1,2,3]}
            antennaTemps[ant]=[[],[],[],[]]
                        
        elif  ant[0:2]=='DA':
            # DA antennas: apex, 3 total:
            # GET_METR_TEMPS_14[3] + GET_METR_TEMPS_15[0] + GET_METR_TEMPS_15[1]
            mpts = {'METR_TEMPS_14': [3], 'METR_TEMPS_15':[0,1]}
            antennaTemps[ant]=[[],[],[]]
                                               
        elif  ant[0:2]=='DV':
            # DV antennas: hexapod-subreflector interface cylinder, 8 total:
            # GET_METR_TEMPS_00[0]...[3] + GET_METR_TEMPS_01[0]...[3]
            mpts = {'METR_TEMPS_00': [0,1,2,3], 'METR_TEMPS_01': [0,1,2,3]}
            antennaTemps[ant]=[[],[],[],[],[],[],[],[]]
            time = [[],[],[],[],[],[],[],[]]
            
        elif  ant[0:2]=='PM':
            # PM antennas: 'ambient' temperature, 1 total:
            # GET_METR_TEMPS_1B[0]
            mpts = {'METR_TEMPS_1B': [0]}
            antennaTemps[ant]=[[]]

        meanAntennaTempsErr[ant]=[]
        meanAntennaTempsErr[ant]=[]

        # TODO: Put an offset in DV07 sensors before Nov 25th
        # TODO put offset in CM06 until a certain date.
        
        i = 0
        for m in list(mpts.keys()):
            print(start, end, ant, m)
            t = tmu.get_tmc_data(ant,'Mount',m,start,end, removefile=True, verbose=True)
            q = find((np.array(t['datetime']) > s) & (np.array(t['datetime']) < e))
            time = np.array(t['datetime'])[q]
            # interpolate the temperatures to common timeList range (once every 10s)
            for k in mpts[m]:
                antennaTemps[ant][i]= interp(ftimeList,date2num(time),array(t['value'])[q,k]/100.)
                i +=1
                
        if (debugPlot):
            pb.figure(1); pb.clf()
            for k in range(np.shape(antennaTemps[ant])[0]):
                pb.plot(timeList,antennaTemps[ant][k], '.')
            
        # take the average over monitorpoints.
        std1 = pb.mean(pb.std(antennaTemps[ant],axis=0))  # std from averaging over monitor points
        antennaTemps[ant] = pb.mean(antennaTemps[ant],axis=0)
        if (debugPlot): pb.plot(timeList,antennaTemps[ant], 'ko')
        
        # take the average over time
        if debugPlot: print(ant, pb.mean(antennaTemps[ant]), pb.std(antennaTemps[ant]))
        # the err is the quadratic sum of uncertainty over monitor points and uncertainty over time
        meanAntennaTempsErr[ant]= pb.sqrt(pb.std(antennaTemps[ant])**2+std1**2)
        meanAntennaTemps[ant] = pb.mean(antennaTemps[ant])

        if (debugPlot):
            pb.title('%s-%s, T=%3.2f +- %3.2f'%(asdmFile,ant,antennaTemps[ant],antennaTempsErr[ant]))
            pb.savefig('%s_%s_ambientTemp.png'%(asdmFile,ant))
                
    return timeList, antennaTemps, meanAntennaTemps,meanAntennaTempsErr
    
def plotAntennaAmbientTemperatures(asdm, weatherStation='MeteoTB2'):
    """
    Makes two plots of antenna ambient temperature: vs. time and vs. height
    Inputs:
    asdm: name of the ASDM
    -Denis Barkats
    """
    # TODO: add Nanten temps when discrepancy with ASTE is resolved ?
    stations = [i.strip() for i in list(getWeatherStationNamesFromASDM(asdm).values())]
    if weatherStation not in stations:
        print("%s is not in this dataset" % (weatherStation))
        print("Available: ", str(stations))
        return
    antList = readAntennasFromASDM(asdm, verbose = False)
    print("antList = ", antList)
    baselineLength = getBaselineLengthsFromASDM(asdm,weatherStation)
    heightDiff = getBaselineHeightFromASDM(asdm, weatherStation, verbose=False)
    pads = getAntennaPadsFromASDM(asdm)
    
    h = np.sort(heightDiff.values())
    ant_by_h = sorted(heightDiff,key=heightDiff.get)
    scaled_h = (h - h.min()) / h.ptp()
    colors_h = matplotlib.cm.coolwarm(scaled_h)

    bl= np.sort(baselineLength.values())
    ant_by_bl = sorted(baselineLength,key=baselineLength.get)
    scaled_bl = (bl - bl.min()) / bl.ptp()
    colors_bl = matplotlib.cm.jet(scaled_bl)
    
    # get antenna ambient temperatures
    time, temps, meanTemp, meanTempErr = getAntennaAmbientTemperaturesFromASDM(asdm)

    # Get Weather station data. 
    [conditions, medianConditions,stationName] = getWeatherFromASDM(asdm,station=1,verbose=False)
    mjdsec = np.array(conditions[0])
    weatherTime = mjdSecondsListToDateTime(mjdsec)
    temperature = kelvinToCelsius(np.array(conditions[3]))

    # plot temperatures vs time
    figure(1,figsize=(12,9));clf()
    i=0
    for ant in ant_by_h:
        pb.plot(time,temps[ant],'o',color=tableau20[i], markeredgecolor=tableau20[i])
        i+=1
    pb.plot(weatherTime, temperature,'k')
    pb.legend(ant_by_h+[weatherStation], prop={'size':9}, ncol=1,bbox_to_anchor=(1.1,1.02))
    pb.title(asdm+' Weather station and antenna ambient temperatures')
    pb.xlabel('UT time')
    pb.ylabel('Temperature (C)')
    pb.grid()
    fig1 = '%s_ambientTemp_vs_time.png'%(asdm)
    pb.savefig(fig1)

    # plot temperatures vs height diff
    pb.figure(2,figsize=(12,9));clf()
    legendtxt = []
    for ant in ant_by_h:
        marker = 'bo'
        if pads[ant][0] == 'P': marker='ro'
        if pads[ant][0] == 'S': marker='go'
        if pads[ant][0] == 'W': marker='mo'
        if (pads[ant][0] == 'N') or (pads[ant][0] == 'J'): marker='co'
        if pads[ant][0:2] == 'A1': marker='yo'
        pb.errorbar(heightDiff[ant],meanTemp[ant],meanTempErr[ant],fmt= marker)
        legendtxt.append('%s-%s:%2.1f'%(ant,pads[ant],meanTemp[ant]))
    pb.errorbar([0],np.mean(temperature),np.std(temperature),fmt= 'ko')
    x = -500+arange(600)
    pb.plot(x, -0.0065*x+np.mean(temperature),'k-')
    legendtxt.append('%s:%2.1f'%(weatherStation,np.mean(temperature)))
    pb.title(asdm+' Temperature vs height difference wrt Weather station ')
    pb.legend(legendtxt, prop={'size':9}, ncol=1,bbox_to_anchor=(1.1,1.02))
    pb.xlabel('Height Diff [m]')
    pb.ylabel('Temperature (C)')
    pb.grid()
    fig2 = '%s_ambientTemp_vs_height.png'%(asdm)
    pb.savefig(fig2)

    # plot temperatures vs height diff, color coded with distance to Weather station
    fig = pb.figure(3,figsize=(12,9));clf()
    legendtxt = []
    i=0
    for ant in ant_by_bl:
        m = 'o'
        pb.errorbar(heightDiff[ant],meanTemp[ant],meanTempErr[ant],marker=m, mfc=colors_bl[i], mec=colors_bl[i], ecolor=colors_bl[i])
        legendtxt.append('%s-%s:%2.1f'%(ant,pads[ant],meanTemp[ant]))
        i+=1
    pb.errorbar([0],np.mean(temperature),np.std(temperature),fmt= 'ko')
    x = -500+arange(600)
    pb.plot(x, -0.0065*x+np.mean(temperature),'k-')
    legendtxt.append('WSTB1:%2.1f'%(np.mean(temperature)))
    pb.title(asdm+' Temperature vs height difference wrt Weather station')
    pb.legend(legendtxt, prop={'size':9}, ncol=1,bbox_to_anchor=(1.1,1.02))
    pb.xlabel('Height Diff [m]')
    pb.ylabel('Temperature (C)')
    pb.grid()
    ax1 = fig.add_axes([0.17, 0.87, 0.65, 0.02])
    cmap = matplotlib.cm.jet
    norm = matplotlib.colors.Normalize(vmin=min(bl)/1e3, vmax = max(bl)/1e3)
    cb1 = matplotlib.colorbar.ColorbarBase(ax1,cmap=cmap,orientation='horizontal', norm=norm)
    cb1.set_label('Distance to Weather station [km]')
    fig3 = '%s_ambientTemp_vs_height_distance.png'%(asdm)
    pb.savefig(fig3)
    print("Plots left in: ", fig1)
    print("               ", fig2)
    print("               ", fig3)
    
def getWeatherStationNamesFromASDM(asdm, prefix=['WSTB','Meteo','OSF'], 
                                   returnNearestAntennas=False, useMinidom=False):
    """
    Gets the names of the weather stations in an ASDM.
    Returns: a dictionary keyed by station ID
    useMinidom: if True, then parse the .xml file even if the ASDM python
                bindings are available
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    -Todd Hunter
    """
    asdm = uidToUnderscores(asdm)
    if (not os.path.exists(asdm)):
        print("Could not find ASDM: ", asdm)
        return
    if (not os.path.exists(asdm + '/Station.xml')):
        print("Could not find Station.xml, is this really an ASDM?")
        return
    if (type(prefix) != list):
        prefix = [prefix]
    mydict = readStationFromASDM(asdm, useMinidom=useMinidom)
    names = []
    ids = []
    newdict = {}
    for s in list(mydict.keys()):
        for p in prefix:
            if (mydict[s]['name'].lower().find(p.lower()) >= 0):
                names.append(mydict[s]['name'])
                ids.append(s)
                newdict[s] = mydict[s]['name']
    if (returnNearestAntennas):
        stations = getWeatherStationPositionsFromASDM(asdm)
        posdict = getPadPositionsFromASDM(asdm)
        pads = getAntennaPadsFromASDM(asdm,keyByPadName=True)
        for pad in list(posdict.keys()):
            antennaName = pads[pad]
            antennaPosition = readAntennaPositionFromASDM(asdm)[antennaName]['position']
            posdict[pad] += computeITRFCorrection(posdict[pad], antennaPosition)
        newdict = {}
        for station in stations:
            mindistance = 1e12
            for pad in list(posdict.keys()):
                distance = np.linalg.norm([posdict[pad][0] - stations[station][0],
                                           posdict[pad][1] - stations[station][1],
                                           posdict[pad][2] - stations[station][2]])
                if (mindistance > distance):
                    mindistance = distance
                    closestPad = pad
            closestAntenna = pads[closestPad]
            newdict[station] = {'antenna': closestAntenna, 'distance': round(mindistance,1), 'pad': closestPad}
    return(newdict)

def exportAndGetWeatherStationPositionFromASDM(asdm, station='WSOSFLab', outfile=''):
    """
    Returns the position of the specified weather station from an ASDM.
    If asdm is not find, it first exports its metadata from the archive.
    outfile: if specified then append a line with the date, UID and station position vector.
    -Todd Hunter
    """
    if not os.path.exists(asdm):
        asdmExport(asdm, '-m')
    asdm = uidToUnderscores(asdm)
    if not os.path.exists(asdm):
        return
    positions = getWeatherStationPositionsFromASDM(asdm, prefix=station)
    if positions is None:
        print("That weather station was not found.  Present are: ", end=' ') 
        return
    for i in list(positions.keys()):
        if i.find(station) >= 0:
            if outfile != '':
                f = open(outfile,'a')
                date = getObservationStartDateFromASDM(asdm)[0]
                f.write('%s %s %s\n' % (date,asdm,positions[i]))
            return positions[i]
    
def getWeatherStationPositionsFromASDM(asdm, prefix=['WSTB','Meteo','OSF'],
                                       returnDeltaHeights=False,
                                       returnClosestPads=False,
                                       returnNearbyPads=False, radius=100,
                                       referenceStation=None):
    """
    Gets the geocentric XYZ positions of the weather stations in an ASDM.
    Returns: a dictionary keyed by station ID
    returnDeltaHeights: if True, then return height (in m) relative to highest one
           in a dictionary keyed by station name, and the name of the highest station
    referenceStation: the station name from which to base the zero point of deltaHeights
    radius: threshold in meters for associating with a nearby pad
    -Todd Hunter
    """
    asdm = uidToUnderscores(asdm)
    if (not os.path.exists(asdm)):
        print("Could not find ASDM: ", asdm)
        return
    if (not os.path.exists(asdm + '/Station.xml')):
        print("Could not find Station.xml, is this really an ASDM?")
        return
    if (type(prefix) != list):
        prefix = [prefix]
    mydict = readStationFromASDM(asdm)
    antennaPads = getPadPositionsFromASDM(asdm)
    newdict = {}
    closestPads = {}
    nearbyPads = {}
    stations = []
    for s in list(mydict.keys()):
        for p in prefix:
            if (mydict[s]['name'].lower().find(p.lower()) >= 0):
                newdict[mydict[s]['name']] = np.array(mydict[s]['position'])
                stations.append(mydict[s]['name'])
                minDistance = 1e9
                nearbyPadlist = []
                nearbyAntennas = []
                for pad in antennaPads:
                    distance = np.linalg.norm(np.array(antennaPads[pad])-newdict[mydict[s]['name']])
                    if (distance < minDistance):
                        minDistance = distance
                        closestPad = pad
                        deltaHeight = geocentricXYZToEllipsoidalHeight(np.array(antennaPads[pad]))-\
                                      geocentricXYZToEllipsoidalHeight(newdict[mydict[s]['name']])
                    if (distance < radius):
                        nearbyPadlist.append(pad)
                        nearbyAntennas.append(getAntennaPadsFromASDM(asdm,keyByPadName=True)[pad])
                closestPads[mydict[s]['name']] = {'closestOccupiedPad': closestPad, 
                                                  'distance': minDistance, 
                                                  'deltaHeight': deltaHeight,
                                                  'closestAntenna': getAntennaPadsFromASDM(asdm,keyByPadName=True)[closestPad]}
                nearbyPads[mydict[s]['name']] = {'nearbyPads': nearbyPadlist,
                                                 'nearbyAntennas': nearbyAntennas}
    if (returnDeltaHeights):
        return(computeDeltaEllipsoidalHeights(newdict, referenceStation))
    elif (returnClosestPads):
        return(closestPads)
    elif (returnNearbyPads):
        return(nearbyPads)
    else:
        return(newdict)

def readStationFromASDM(sdmfile, station=None, useMinidom=False):
    """
    This function uses the ASDM bindings from casapy-telcal and reads the 
    Station  position from the Station.xml file ( in the ASDM) and returns 
    a dictionary of station positions if no station is specified.  The 
    dictionary format is:  {0: {'name':'J503',position:[x,y,z]}, 1:  etc.}.  
    If a station is specified, then 
    it returns the name and location as a simple list: ['J503',[x,y,z]].  
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    - dbarkats & Todd Hunter
    """
    if not asdmLibraryAvailable or useMinidom:
        import au_noASDMLibrary
        mydict = au_noASDMLibrary.readStationFromASDM_minidom(sdmfile)
        if (station is None):
            return(mydict)
        else:
            return(mydict[station]['name'],mydict[station]['position'])
    a = ASDM()
    parser = ASDMParseOptions()
    parser.asALMA()
    parser.loadTablesOnDemand(True)
    a.setFromFile(sdmfile,parser)
    stationTable = a.stationTable().get()  
    staPos = {}
    for row in stationTable:
        stationName = row.name()
        position = [row.position()[0].get(),row.position()[1].get(),row.position()[2].get()]
        id = row.stationId().get()
        if (id not in staPos):  staPos[id] = {}
        staPos[id] = {'position':position, 'name':stationName}
    if (station is not None):
        return(staPos[station]['name'], staPos[station]['position'])
    return staPos

def getPadPositions(vis, includeWeatherStations=False):
    """
    Reads the pad positions in geocentric XYZ coordinates from an ms using tbtool,
    (excluding the weather stations).
    Returns a dictionary keyed by pad name, with value = its XYZ position.
    - Todd Hunter
    """
    if (not os.path.exists(vis)):
        print("Could not find measurement set: ", vis)
        return
    antTable = vis+'/ASDM_STATION'
    if (not os.path.exists(antTable)):
        print("Could not find ASDM_STATION table: %s" % (antTable))
        return
    mytb = createCasaTool(tbtool)
    mytb.open(antTable)
    position = np.transpose(mytb.getcol('position'))
    names = list(mytb.getcol('name'))
    types = list(mytb.getcol('type'))
    mytb.close()
    padDict = {}
    for i,name in enumerate(names):
        if (types[i] == 'ANTENNA_PAD' or includeWeatherStations):
            padDict[name] = position[i]
    return padDict

def getPadHeight(vis, pad=None, LOC=False):
    """
    Reads the XYZ geocentric coordinates for the specified pad and computes
    the Pythagorean distance from the center of the Earth.
    vis: name of measurement set
    pad: name of pad, e.g. 'W207'
    -Todd Hunter
    """
    if (not os.path.exists(vis)):
        print("getPadHeight: Could not find measurement set = ", vis)
        return
    padDict = getPadPositions(vis) # uses tbtool
    if (padDict is None): return
    names = list(padDict.keys())
    position = list(padDict.values())
    if (pad is None):
        mydict = {}
        for i,pad in enumerate(names):
            mydict[pad] = np.linalg.norm(position[i])
        return mydict
    elif (pad not in names):
        print("Pad %s not in dataset" % pad)
        return
    else:
        idx = names.index(pad)
        return(np.linalg.norm(position[idx]))
        
def getPadHeightFromASDM(asdm, pad=None, LOC=False):
    """
    Reads the XYZ geocentric coordinates for the specified pad and computes
    the Pythagorean distance from center of the Earth.
    asdm: name of ASDM
    pad: name of pad, e.g. 'W207'
    LOC: if True, use getPadLOC to get local tangent plane
         if False, use raw distance from geocenter
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    """
    if LOC:
        return(getPadLOC(pad)[2])
    else:
        result = getPadXYZFromASDM(asdm, pad)  # binary-ready
        if result is None: return
        return(np.linalg.norm(result))
    
def getPadXYZFromASDM(asdm, pad=None):
    """
    Reads the XYZ geocentric coordinates for the specified pad
    asdm: name of ASDM
    pad: name of pad, e.g. 'W207'
    """
    if (asdmLibraryAvailable == False):
        mydict = au_noASDMLibrary.readStationsFromASDM_minidom(asdm)
    else:
        mydict = readStationsFromASDM(asdm) # binary-ready
    if (pad is None):
        print("Select one of the available pads: ", list(mydict.keys()))
    if (pad not in list(mydict.keys())):
        print("This pad is not in the ASDM. Available pads: ", list(mydict.keys()))
        return
    position = mydict[pad]
    return(position)

def getDistanceFromMedianPadLOCFromASDM(asdm):
    """
    Computes a dictionary of distance of each antenna pad (in meters) from the 
    median pad location in ENU coordinates, keyed by antenna name.
    -Todd Hunter
    """
    medianENU = np.array(getMedianPadLOCFromASDM(asdm))
    locs = getPadLOCsFromASDM(asdm)
    antennaNames = list(locs.keys())
    distance = {}
    for antennaName in antennaNames:
        distance[antennaName] = np.linalg.norm(locs[antennaName]-medianENU)
    return distance
    
def getMedianPadLOCFromASDM(asdm):
    """
    Computes the median of pad locations in an ASDM in local tangent plane 
    coordinates (in meters).  
    Returns: east, north, up 
    - Todd Hunter
    """
    mydict = getPadLOCsFromASDM(asdm)
    east,north,up = np.transpose(list(mydict.values()))
    return [np.median(east), np.median(north), np.median(up)]

def getPadLOCsFromASDM(asdm):
    """
    Gets a dictionary of pad locations in an ASDM in local tangent plane
    coordinates (in meters), keyed by antenna name.
    -Todd Hunter
    """
    mydict = readStationFromASDMKeyedByAntennaName(asdm)
    cx,cy,cz,clong,clat = getCOFAForASDM(asdm)
    antennaNames = list(mydict.keys())
    locs = {}
    for antennaName in antennaNames:
        x,y,z = mydict[antennaName]['position']
        x,y,z = simutil.simutil().itrf2loc(x,y,z,cx,cy,cz)
        locs[antennaName] = np.array([x[0],y[0],z[0]])
    return locs
    
def readAntennaPositionFromASDM(sdmfile, antennaType='', useMinidom=False):
    """
    This function uses the ASDM bindings from casapy-telcal and reads the
    Antenna position (relative to its pad) from the Antenna.xml file 
    (in the ASDM) and returns a dictionary of Antenna positions in the 
    ENU coordinate system (relative to its pad).
    antennaType: restrict to 'DA' or 'DV' or 'PM' or 'CM'
    useMinidom: if True, then parse the .xml file even if the ASDM python
                bindings are available
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    - dbarkats & Todd Hunter
    """
    if not asdmLibraryAvailable or useMinidom:
        import au_noASDMLibrary
        return(au_noASDMLibrary.readAntennaPositionFromASDM_minidom(sdmfile,antennaType))
    a = ASDM()
    parser = ASDMParseOptions()
    parser.asALMA()
    parser.loadTablesOnDemand(True)
    a.setFromFile(sdmfile,parser)
    antennaTable = a.antennaTable().get()  
    antPos = {}
    for row in antennaTable:
        antName = row.name().strip()
        id = row.stationId().get()
        position = [row.position()[0].get(),row.position()[1].get(),row.position()[2].get()]
        if (antName not in antPos):  antPos[antName] = {}
        antPos[antName] = {'position':position, 'id':id}
        
    return antPos

def getAntennaPadsForObsID(vis, obsid=0, keyByAntennaName=False):
    """
    For a concatenated dataset, this function allows you to break the degeneracy when
    a given antenna name occupies more than one pad.  CAS-9358 was created to add this
    ability to msmd.antennaids and msms.antennastations.
    keyByAntennaName: if True, then return a dictionary keyed by antenna name
    Returns: an array of station names
    -Todd Hunter
    """
    if not os.path.exists(vis):
        print("Could not find ms")
        return
    mytb = createCasaTool(tbtool)
    mytb.open(vis)
    myt = mytb.query('OBSERVATION_ID==%d'%obsid)
    ant1 = list(np.unique(myt.getcol('ANTENNA1')))
    ant2 = list(np.unique(myt.getcol('ANTENNA2')))
    myt.close()
    mytb.close()
    mytb.open(vis+'/ANTENNA')
    pads = mytb.getcol('STATION')
    names = mytb.getcol('NAME')
    mytb.close()
    ants = np.unique(ant1 + ant2)
    if keyByAntennaName:
#        return(dict(itertools.izip(names[ants],pads[ants]))) # izip is not in python3
        return(dict(zip(names[ants],pads[ants])))
    else:
        return(pads[ants])

def convertPadDictionaryToAntenna(mydict, vis):
    """
    Takes a dictionary keyed by pad name and converts it to one keyed
    by antenna name.
    -Todd Hunter
    """
    mymsmd = createCasaTool(msmdtool)
    mymsmd.open(vis)
    names = np.array(mymsmd.antennanames())
    stations = mymsmd.antennastations()
    mymsmd.close()
    newdict = {}
    for i in mydict:
        idx = list(stations).index(i)
        newdict[names[idx]] = mydict[i]
    return newdict

def convertAntennaDictionaryToPad(mydict, vis):
    """
    Takes a dictionary keyed by antenna name and converts it to one keyed
    by pad name.
    -Todd Hunter
    """
    mymsmd = createCasaTool(msmdtool)
    mymsmd.open(vis)
    names = np.array(mymsmd.antennanames())
    stations = mymsmd.antennastations()
    mymsmd.close()
    newdict = {}
    for i in mydict:
        idx = list(names).index(i)
        newdict[stations[idx]] = mydict[i]
    return newdict

def getAntennaPads(vis, exclude='', keyByAntennaName=False, keyByPadName=False, mymsmd=''):
    """
    Gets a list of antenna pads from a measurement set using msmd, excluding
    weather stations.
    exclude: a comma-separated list of pads to exclude
       'LBC' will remove the 21 pads of the ALMA LB campaign
    keyByAntennaName: will return a dictionary keyed by antenna name
    keyByPadName: will return a dictionary keyed by pad
    - Todd Hunter
    """
    stationList = exclude.split(',')
    if stationList[0] == 'LBC':
        stationList = ['P410','P405','P404','P402','P401','W204',
                       'W206','W207','W210','S301','S305','S306',
                       'A113','A118','A121','A122','A124','A127',
                       'A131','A132','A133']
        print("Ignoring LBC stations: ", stationList)
    if (not os.path.exists(vis)):
        print("Could not find measurement set: ", vis)
        return
    needToClose = False
    if mymsmd == '':
        mymsmd = createCasaTool(msmdtool)
        mymsmd.open(vis)
    stations = np.array(mymsmd.antennastations())
    antennas = np.array(mymsmd.antennanames())
    if needToClose:
        mymsmd.close()
    if keyByAntennaName:
        if (keyByPadName): 
            print("keyByPadName and keyByAntennaName are mutually exclusive options")
            return
        mydict = {}
        for i,station in enumerate(stations):
            mydict[antennas[i]] = station
        return(mydict)
    elif keyByPadName:
        mydict = {}
        for i,station in enumerate(stations):
            mydict[station] = antennas[i]
        return(mydict)
    else:
        mylist = [x for x in stations if x not in stationList]
        return(mylist)

def padDifferencesFromASDM(asdm1, asdm2, showStableAntennas=False):
    """
    Describes the differences in antennas and pads between two
    datasets by looking at the ASDMs.  It then looks at antennaMoves.txt
    and shows what it thinks was the most recent move for each antenna.
    -Todd Hunter
    """
    obsA = getObservationStartDateFromASDM(asdm1)
    obsB = getObservationStartDateFromASDM(asdm2)
    if (obsA[1] < obsB[1]):
        asdm1dict = getAntennaPadsFromASDM(asdm1, keyByPadName=False)
        asdm2dict = getAntennaPadsFromASDM(asdm2, keyByPadName=False)
        date1 = obsA[0]
        date2 = obsB[0]
    else:
        asdm2dict = getAntennaPadsFromASDM(asdm1, keyByPadName=False)
        asdm1dict = getAntennaPadsFromASDM(asdm2, keyByPadName=False)
        date2 = obsA[0]
        date1 = obsB[0]
    antennas1 = list(asdm1dict.keys())
    antennas2 = list(asdm2dict.keys())
    for antenna in antennas1:
        if (antenna not in antennas2):
            print("Antenna %s (on pad %s) is not in the newer dataset. Last move = %s" % (antenna,asdm1dict[antenna],getMostRecentMove(antenna)))
        else:
            if (asdm1dict[antenna] == asdm2dict[antenna]):
                if (showStableAntennas):
                    print("Antenna %s is on pad %s in both datasets" % (antenna,asdm1dict[antenna]))
            else:
                print("Antenna %s moved from pad %s to %s between datasets (%s to %s). Last move = %s" % (antenna,asdm1dict[antenna], asdm2dict[antenna], date1, date2, getMostRecentMove(antenna)))
    for antenna in antennas2:
        if (antenna not in antennas1):
            print("Antenna %s (on pad %s) is not in the older dataset. Last move = %s" % (antenna,asdm2dict[antenna],getMostRecentMove(antenna)))

def getAntennaPadsFromASDMs(asdmlist, keyByPadName=False):
    """
    Calls getAntennaPadsFromASDM for a list of ASDMs and produces
    a combined dictionary where the values are lists, which will allow it
    to indicate if an antenna appears on multiple stations, or vice-versa.
    asdmlist: a list of ASDMs, a comma-delimeted string,
         or a string with a wildcard ('*.ms')
    keyByPadName: if True, the reverse the dictionary:  {'S301': ['DA41']}
    -Todd Hunter
    """
    if type(asdmlist) == str:
        asdmlist = asdmlist.split(',')
        final_asdmlist = []
        for asdm in asdmlist:
            if (asdm.find('*') >= 0):
                myasdmlist = glob.glob(asdm)
                print("Found %d ASDMs" % (len(myasdmlist)))
                final_asdmlist += myasdmlist
            else:
                final_asdmlist.append(asdm)
        asdmlist = final_asdmlist

    for i,asdm in enumerate(asdmlist):
        if (i == 0):
            mydict = getAntennaPadsFromASDM(asdm, keyByPadName)
            for key in mydict:
                mydict[key] = [mydict[key]]
        else:
            newdict = getAntennaPadsFromASDM(asdm, keyByPadName)
            for key in newdict:
                if key not in mydict:
                    mydict[key] = [newdict[key]]
                elif newdict[key] not in mydict[key]:
                    if keyByPadName:
                        print("Pad %s hosts a second antenna: %s" % (key, newdict[key]))
                    else:
                        print("Antenna %s appears on a second pad: %s" % (key, newdict[key]))
                    mydict[key].append(newdict[key])
    return mydict

def getAntennaPadsFromASDM(asdm, keyByPadName=False):
    """
    Returns a dictionary of antennas-pads association for that ASDM
    e.g.  {'DA41': 'S301'}
    keyByPadName: if True, the reverse the dictionary:  {'S301': 'DA41'}
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    -Todd Hunter
    """
    pads = {}
    asdm = asdm.rstrip('/')
    antList = readAntennasFromASDM(asdm, verbose = False)  # binary-ready
    antPos = readAntennaPositionFromASDM(asdm)   # binary-ready
    if (antPos is None):
        mydict = au_noASDMLibrary.getAntennaPadsFromASDM_minidom(asdm)
        return mydict
    padPos = readStationFromASDM(asdm)   # binary-ready
    for ant in antList:
        if (keyByPadName):
            pads[padPos[antPos[ant]['id']]['name']] = ant
        else:
            pads[ant] = padPos[antPos[ant]['id']]['name']
    return pads

def estimateSynthesizedBeamFromASDM(asdm, useL80method=True, verbose=False):
    """
    Estimates the synthesized beam from the L80 percentile length and
    representative frequency in an ASDM.
    useL80method: if True, use .574lambda/L80; if False, then use the max baseline
    -Todd Hunter
    """
    representativeFrequency = representativeFrequencyFromASDM(asdm,verbose=verbose)
    if representativeFrequency is None: return
    if useL80method:
        L80 = getBaselineStatsFromASDM(asdm, percentile=80, verbose=verbose)[-1] # meters
        arcsec = 3600*np.degrees(1)*0.574*c_mks/(representativeFrequency*1e9*L80)
    else:
        maxBaseline = getBaselineStatsFromASDM(asdm, verbose=False)[2] # meters
        arcsec = printBaselineAngularScale(maxBaseline, representativeFrequency)
    return arcsec

def estimateMRS(vis, field='', verbose=False, includeIDs=True):
    """
    Estimates the maximum recoverable scale (a.k.a. LAS) from the max baseline length and
    representative frequency (or mean of science spw frequencies) in a measurement set.
    field: if not blank, then find the first integration on the specified
           field ID or name, get its az&el and compute the projected baseline
           lengths rather than the unprojected baseline lengths
    includeIDs: passed to getBaselineStats
    Reports the ALMA Cycle-4 approved formula: 0.983*lambda/L5
       and the Cycle-8 tech. handbook formula: 0.6*lambda/Lmin
       and returns the smaller of the two values
    -Todd Hunter
    """
    result = getBaselineStats(vis, field=field, percentile=5, verbose=verbose, includeIDs=includeIDs)
    if (result is None): return
    L5 = result[0] # meters
    Lmin = result[2]
    if os.path.exists(vis+'/ASDM_SBSUMMARY'):
        freqHz = representativeFrequency(vis, verbose=verbose) * 1e9
        print("Using representative frequency")
    else:
        freqHz = np.mean(getScienceFrequencies(vis)) 
        print("Using mean of the science spw mean frequencies.")
    arcsec = 3600*np.degrees(1)*0.983*c_mks/(freqHz*L5)
    print("Cycle 4 handbook:  0.984*lambda/L5 = %g arcsec (L5 = %g m)" % (arcsec, L5))
    arcsec8 = 3600*np.degrees(1)*0.983*c_mks/(freqHz*Lmin)
    print("Cycle 8 handbook:  0.6*lambda/Lmin = %g arcsec (Lmin = %g m)" % (arcsec8, Lmin))
    return np.min([arcsec8,arcsec])

def estimateSynthesizedBeam(vis, field='', useL80method=True, verbose=False, 
                            spw=None, mymsmd=None):
    """
    Estimates the synthesized beam from the max baseline length and
    representative frequency in a measurement set.
    field: if not blank, then find the first integration on the specified
           field ID or name, get its az&el and compute the projected baseline
           lengths rather than the unprojected baseline lengths
    useL80method: if True, use .574lambda/L80; if False, then use the max baseline
    spw: if specified (string or int), then use its meanfreq instead of representative freq
    -Todd Hunter
    """
    needToClose = False
    if mymsmd is None:
        needToClose = True
        mymsmd = createCasaTool(msmdtool)
        mymsmd.open(vis)
    if useL80method:
        result = getBaselineStats(vis, field=field, percentile=80, verbose=verbose, mymsmd=mymsmd)
    else:
        result = getBaselineStats(vis, field=field, verbose=verbose)
    if (result is None): 
        if needToClose:
            mymsmd.close()
        return
    if useL80method:
        L80 = result[0] # meters
        if spw is None:
            repFreqGHz = representativeFrequency(vis,verbose=verbose)
        else:
            repFreqGHz = mymsmd.meanfreq(int(spw)) * 1e-9
        if repFreqGHz is None:
            print("There is no representative frequency. Using mean of science windows...")
            myfreqs = getScienceFrequencies(vis, mymsmd=mymsmd)
            if myfreqs is None:
                print("There are no science windows, using first spw")
                repFreqGHz = mymsmd.meanfreq(0) * 1e-9
            else:
                repFreqGHz = np.mean(myfreqs) * 1e-9
            print("which is %f GHz." % (repFreqGHz))
        arcsec = 3600*np.degrees(1)*0.574*c_mks/(repFreqGHz*1e9*L80)
    else:
        maxBaseline = result[2] # meters
        arcsec = printBaselineAngularScale(maxBaseline, representativeFrequency(vis,verbose=verbose))
    if needToClose:
        mymsmd.close()
    return arcsec

def makeFixephem(vis, scriptname='fixephem.py'):
    """
    Builds a script to fix the target measurement sets for multi-execution ephemeris
    projects of Cycle 3 and 4.  See CAS-8984.
    vis: a single measurement set, or a string with a wildcard ('*.ms')
    -Todd Hunter
    """
    if (vis.find('*') >= 0):
        vis = glob.glob(vis)[0]
        print("Using ", vis)
    fieldnames = getEphemerisFields(vis)
    f = open(scriptname,'w')
    f.write('from recipes.ephemerides import concatephem\n')
    f.write('import glob\n')
    f.write("myvis = glob.glob('*target.ms')\n")
    f.write("concatephem.concatreplaceephem(vis=myvis, field='%s', commontime=True)\n" % fieldnames)
    f.close()

def makeFlagTemplateOutlierAntennas(asdms, templateType='targets', 
       requestedResolution=None, useUvrange=False, verbose=False):
    """
    Builds a flagtemplate file for the pipeline which flags outlier
    antennas.  If the file already exists, it will be appended to.
    asdms: a single ASDM, a list of ASDMs as a python list of strings, or as a
           single comma-delimited string
    templateType: '' or 'targets' 
                  '':  will produce <asdm>_flagtemplate.txt
           'targets':  will produce <asdm>_flagtargetstemplate.txt
    requestedResolution: if specified, then use this value to override what is
           in the ASDM (which in Cycle 3 was the range provided by the 
           configuration that the OT assigned to the SB, and in Cycle 4 is
           the PI requested value).
    useUvrange: if True, then produce a uvrange flag command instead of an
           an antenna name flag command.  This is not recommended as it can
           produce a sharp edge in the uv coverage which will cause ringing
           in the image plane.
    -Todd Hunter
    """
    if (type(asdms) != list):
        asdms = asdms.split(',')
    for asdm in asdms:
        if (not os.path.exists(asdm)):
            print("Could not find ASDM: ", asdm)
            return
        if (templateType not in ['','targets']):
            print("invalid templateType")
            return
        result = findOutlierAntennas(asdm, requestedResolution, returnSensitivityLoss=True)
        if result is None:  # resolution not found in ASDM
            return
        antennas, sensitivityLoss, maxuvdist = result
        if len(antennas) > 0:
            fname = os.path.basename(asdm) + '_flag%stemplate.txt' % (templateType)
            f = open(fname,'a')
            if (useUvrange):
                print("WARNING!: using a uvrange flag can result in a sharp edge in the uv coverage, which will produce ringing in the image domain.")
                if (sensitivityLoss < 20):
                    print("    You should consider flagging by antenna because it will result in only %.1f%% loss in sensitivity." % (sensitivityLoss))
                myline = "mode='manual' uvrange='0~%d' reason='too_many_outlier_antennas'\n" % int(np.round(maxuvdist))
            else:
                myline = "mode='manual' antenna='%s' reason='outlier_antenna'\n" % ';'.join(antennas)
            f.write(myline)
            f.close()
            print("Wrote %s :" % fname)
            print(myline)
        else:
            print("No outliers found in %s." % (asdm))

def findOutlierAntennas(asdm, requestedResolution=None, 
                        returnSensitivityLoss=False, verbose=False):
    """
    Finds outlier antennas in an ASDM by considering the requested
    angular resolution, representative frequency, and minimum elevation of
    the science targets.
    requestedResolution: if specified (in arcsec), then use this value instead
           of what is in the ASDM
    returnSensitivityLoss: if True, then also return the percentage loss in
           sensitivity and the desired max baseline (in meters)
    -Todd Hunter
    """
    if (not os.path.exists(asdm)):
        print("Could not find ASDM: ", asdm)
        return
    baseline = maxBaselineForRequestedResolutionFromASDM(asdm, requestedResolution)
    ignoreAntennas = []
#    if baseline <= 0:
#        if returnSensitivityLoss:
#            return ignoreAntennas, 0.0, baseline
#        else:
#            return ignoreAntennas
    actualMaxBaseline = getBaselineStatsFromASDM(asdm)[2]
    print("Required max baseline: %.1fm.  Actual max baseline: %.1fm" % (baseline,actualMaxBaseline))
    mydict = getMedianBaselinePerAntenna(asdm, ignoreAntennas)
    idx = np.argsort(list(mydict.values()))[::-1]
    antennaNames = np.array(list(mydict.keys()))[idx]
    nAntennas = len(antennaNames)
    medianBaselines = np.array(list(mydict.values()))[idx]
    if baseline <= 0:
        for antennaName in antennaNames:
            if (antennaName.find('CM') >= 0):
                print("Since a 7m antenna is present, setting baseline to 45m")
                baseline = 45
                break
    if baseline > 0:
        while (medianBaselines[0] > baseline):
            ignoreAntennas.append(antennaNames[0])
            mydict = getMedianBaselinePerAntenna(asdm, ignoreAntennas)
            idx = np.argsort(list(mydict.values()))[::-1]
            antennaNames = np.array(list(mydict.keys()))[idx]
            medianBaselines = np.array(list(mydict.values()))[idx]
            if verbose:
                print("Dropping %s, new max median baseline=%.1f" % (antennaNames[0],np.max(medianBaselines)))
    keepAntennas = nAntennas - len(ignoreAntennas)
    baselinePercentage = 100*(1-keepAntennas*(keepAntennas-1)/(nAntennas*(nAntennas-1.0)))
    sensitivityLossPercentage = 100*(1-np.sqrt(keepAntennas*(keepAntennas-1)/(nAntennas*(nAntennas-1.0))))
    print("%d/%d antennas are outliers, representing %.1f%% of the baselines and %.1f%% of the sensitivity."  % (len(ignoreAntennas), nAntennas, baselinePercentage, sensitivityLossPercentage))
    if returnSensitivityLoss:
        return sorted(ignoreAntennas), sensitivityLossPercentage, baseline
    else:
        return sorted(ignoreAntennas)

def plotExtremeBaselinePerAntenna(asdm='', statistic='max', ignoreAntennas=[], 
                                  percentile=0, config='', plotfile='',
                                  labelLengthsLongerThan=100):
    """
    Runs getExtremeBaselinePerAntenna and plots a histogram.
    -Todd Hunter
    """
    mydict = getExtremeBaselinePerAntenna(asdm, statistic, ignoreAntennas, percentile, sort=False, config=config)
    names = list(mydict.keys())
    lengths = np.array(list(mydict.values()))*0.001
    pb.clf()
    desc = pb.subplot(111)
    bins = [.030,.100,.300,1.000,3.000,10.000,30.000,100.000,300.000]
    pb.hist(lengths,bins=bins)
    pb.xscale('log')
    pb.xlabel('Minimum baseline length (km)')
    pb.ylabel('Number of antennas')
#    majorFormatter = matplotlib.ticker.FormatStrFormatter('%g')
#    desc.xaxis.set_major_formatter(majorFormatter)
    pb.xticks(bins,bins)
    pb.xlim([0.9*bins[0],bins[-1]*1.1])
    desc.yaxis.set_minor_locator(MultipleLocator(2))
    pb.title(config,size=18)
    idx = np.where(lengths > labelLengthsLongerThan)[0]
    y1 = pb.ylim()[1]
    for i,j in enumerate(idx):
        pb.plot(2*[lengths[j]], pb.ylim(), 'k:')
        x = lengths[j]
        y = (1-(i+0.22)*0.13)*y1
        pb.text(x,y, names[j], rotation=90, transform=desc.transData, ha='center',size=13.5)
    pb.draw()
    if plotfile != '':
        if plotfile == True:
            plotfile = config + '.png'
        pb.savefig(plotfile)
        print("Wrote ", plotfile)

def getExtremeBaselinePerAntenna(asdm='', statistic='max', ignoreAntennas=[], percentile=0, sort=False, config=''):
    """
    Compute the statistcal extreme baseline length per antenna of the specified ASDM.
    statistic: 'median', 'min', 'max', 'mean', or 'std'
    percentile: only return antennas whose median is > L(percentile,e.g. 80) of the array
    sort: if True, then sort by statistic rather than by antenna name
    Returns: a dictionary keyed by antenna name (if sort=False)
              otherwise, a list of tuples [('name', length)...]
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    -Todd Hunter
    """
    if asdm == '' and config == '':
        print("You must specify either asdm or config")
        return
    medians = {}
    if config == '':
        antList = readAntennasFromASDM(asdm, verbose = False)
        antPos = readAntennaPositionFromASDM(asdm)
#        print "antPos: ", antPos # e.g.  {'DV12': {'position': [-0.001052, -1.9e-05, 7.000737], 'id': 32}}
        padPos = readStationFromASDM(asdm)  
#        print "padPos: ", padPos # e.g. {0: {'position': [2225050.61527, -5440086.969379, -2481632.711731], 'type': 'ANTENNA_PAD', 'name': 'A023'}} 
    else:
        returnValue = readPadConfigurationFile(config, verbose=False)
        if (returnValue is None): return
        stations, positions, names, nAntennas, diameters, observatory = returnValue
        padPos = {}
        antPos = {}
        antList = []
        for i,pad in enumerate(stations):
            padPos[i] = {'position': positions[i], 'type': 'ANTENNA_PAD', 'name': stations[i]}
            antPos[stations[i]] = {'position': positions[i], 'id': i}
            antList.append(stations[i])
    if (percentile > 0 and config == ''):
        L80 = getBaselineStatsFromASDM(asdm, percentile=percentile, verbose=False)[-1]
        print("L80 = ", L80)
    else:
        L80 = 0
    for ant in antList:
        if (ant in ignoreAntennas): continue
        lengths = []
        for ant2 in antList:
            if (ant2 in ignoreAntennas): continue
            if (ant2 != ant):
                lengths.append(computeBaselineLength(padPos[antPos[ant]['id']]['position'], 
                                                     padPos[antPos[ant2]['id']]['position']))
        if (statistic == 'median'):
            mymedian = np.median(lengths)
        elif (statistic == 'min'):
            mymedian = np.min(lengths)
        elif (statistic == 'max'):
            mymedian = np.max(lengths)
        elif (statistic == 'mean'):
            mymedian = np.mean(lengths)
        elif (statistic == 'std'):
            mymedian = np.std(lengths)
        else:
            print("Statistic must be one of: 'median', 'min', 'max', 'mean', 'std'")
            return
        if (mymedian > L80):
            medians[ant] = mymedian
    if sort:
        medians = sorted(list(medians.items()), key=operator.itemgetter(1))
    return medians

def getMedianBaselinePerAntenna(asdm, ignoreAntennas=[], percentile=0, sort=False):
    """
    Compute median baseline length per antenna of the specified ASDM.
    percentile: only return antennas whose median is > L80 of the array
    sort: if True, then sort by statistic rather than by antenna name
    Returns: a dictionary keyed by antenna name (if sort=False)
           otherwise, a list of tuples [('name', length)...]
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    """
    if (not os.path.exists(asdm+'/Antenna.xml')):
        print("Could not find Antenna.xml.")
        return
    return(getExtremeBaselinePerAntenna(asdm, 'median', ignoreAntennas, percentile, sort))

def getBaselineStatsFromASDM(asdm, percentile=None, verbose=False, units='m', useMinidom=False): 
    """
    Compute statistics on the baseline lengths of the specified ASDM.
    unitsL 'm' or 'kl' for kilolambda
    Returns: a list of: number, min, max, median, mean, st.dev, 20%ile, 
             25%ile, 30%ile, 75%ile, 90%ile
    If percentile is specified, then it is appended to the returned list.
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    """
    if (not os.path.exists(asdm+'/Antenna.xml')):
        print("Could not find Antenna.xml.")
        return
    if (units not in ['m','kl']):
        print("length units must be either 'm' or 'kl'.")
        return
    antList = readAntennasFromASDM(asdm, verbose=verbose, useMinidom=useMinidom)
    antPos = readAntennaPositionFromASDM(asdm, useMinidom=useMinidom)
    padPos = readStationFromASDM(asdm, useMinidom=useMinidom)
    lengths = []
    for ant in antList:
        for ant2 in antList:
            if (ant2 > ant):
                lengths.append(computeBaselineLength(padPos[antPos[ant]['id']]['position'], 
                                                     padPos[antPos[ant2]['id']]['position']))
    lengths = np.array(lengths)
    if units == 'kl':
        wavelength = c_mks / getMeanFreqFromASDM(asdm, useMinidom=useMinidom)['mean']['meanfreq']
        lengths /= wavelength
        lengths *= 0.001 # convert lambda to klambda
    twenty = scoreatpercentile(lengths, 20)    
    twentyfive = scoreatpercentile(lengths, 25)    
    thirty = scoreatpercentile(lengths, 30)    
    seventyfive = scoreatpercentile(lengths, 75)
    ninety = scoreatpercentile(lengths, 90)
    number = len(lengths)
    mylist = [number,np.min(lengths),np.max(lengths),np.median(lengths),
           np.mean(lengths), np.std(lengths),twenty,twentyfive,thirty,
           seventyfive,ninety]
    if (percentile is not None):
        value = scoreatpercentile(lengths, percentile)
        if verbose: print("%.0f percentile baseline length is %f %s" % (percentile, value, units))
        mylist = [value] + mylist
    return(mylist)

def getBaselineLengthsFromASDM(asdm, refAnt):
    """
    returns a dictionary of antennas, baseline length from all antennas to
    refAnt.
    refAnt is either antenna name or a weather station name: WSTB1, WSTB2
    -Denis Barkats
    See also: au.getAllBaselineLengthsFromASDM which is analogous to 
              au.getBaselineLengths for measurement sets
    """
    bl = {}
    antList = readAntennasFromASDM(asdm, verbose = False)
    antPos = readAntennaPositionFromASDM(asdm)
    if (antPos == None): return
    padPos = readStationFromASDM(asdm)
    if refAnt.startswith('WSTB1') or refAnt.startswith('Meteo'):
        key = [mykey for mykey,val in list(padPos.items()) if val['name'].find(refAnt)>=0]
        refAntPos = padPos[key[0]]['position']
    else:
        refAntPos = padPos[antPos[refAnt]['id']]['position']
    for ant in antList:
        bl[ant]= computeBaselineLength(padPos[antPos[ant]['id']]['position'], refAntPos)
        #print ant, int(bl[ant]*100)/100.
    return bl

def getAllBaselineLengthsFromASDM(asdm, histogram=False, nbins=None, 
                                  linear=True, plotfile=None,):
    """
    Returns a list of unprojected baseline lengths in meters
    histogram: if True, then produce a histogram
    nbins: number of bins in histogram, default = automatic
    linear: if True, use linear bins along x-axis, otherwise use log
    plotfile: name of plotfile to produce, or True for automatic naming
    -Todd Hunter
    """
    asdm = asdm.rstrip('/')
    antList = readAntennasFromASDM(asdm, verbose=False)
    antPos = readAntennaPositionFromASDM(asdm)
    if (antPos is None): return
    padPos = readStationFromASDM(asdm)
    bl = []
    for ant in antList:
        for ant2 in antList:
            if ant != ant2:
                bl.append(computeBaselineLength(padPos[antPos[ant]['id']]['position'], padPos[antPos[ant2]['id']]['position']))
    if (histogram):
        flatlengths = bl
        if (nbins is None):
            nbins = len(flatlengths)/10
        if linear:
            bins = np.linspace(0,np.max(flatlengths),nbins)
        else:
            bins = np.logspace(0,np.log10(np.max(flatlengths)),nbins)
            print("bins = ", bins)
        pb.clf()
        pb.hist(flatlengths, bins=bins) 
        pb.ylabel('Number of baselines')
        units = 'm'
        pb.xlabel('Baseline length (%s)'%units)
        pb.title(asdm+'  '+getObservationStartDateFromASDM(asdm)[0])
        if (plotfile is not None):
            if plotfile == True:
                png = '%s_baseline_histogram.png' % asdm
            else:
                png = plotfile
            pb.savefig(png)
            print("Left histogram in %s" % png)
    return sorted(bl)

def getBaselineHeightFromASDM(asdm, refAnt, verbose=True):
    """
    -Denis Barkats
    """
    hDiff = {}
    antList = readAntennasFromASDM(asdm, verbose = False)
    antPos = readAntennaPositionFromASDM(asdm)
    padPos = readStationFromASDM(asdm)
    if refAnt.startswith('WSTB1') or refAnt.startswith('Meteo'):
        [key for key,val in list(padPos.items()) if val['name'].find(refAnt) >= 0]
        refAntPos = padPos[key]['position']
    else:
        refAntPos = padPos[antPos[refAnt]['id']]['position']
    for ant in antList:
        hDiff[ant]= computeBaselineHeightDiff(padPos[antPos[ant]['id']]['position'], refAntPos)
        if verbose == True: print('%s, %7.2f'%(ant, hDiff[ant]))
    return hDiff

def readTimesFromAnnotationTable_minidom(asdm):
    print("Observation start date: ", getObservationStartDateFromASDM(asdm)[0])
    print("Representative frequency: %.3f GHz" % (representativeFrequencyFromASDM(asdm,verbose=False)))
    xmlscans = minidom.parse(asdm+'/Annotation.xml')
    scandict = {}
    rowlist = xmlscans.getElementsByTagName("row")
    spws = getScienceSpwsFromASDM(asdm)
    mydict = {}
    previousIntent = None
    spectralSpec = 0
    for i,rownode in enumerate(rowlist):
        row = rownode.getElementsByTagName("issue")
        issue = str(row[0].childNodes[0].nodeValue)
        row = rownode.getElementsByTagName("details")
        details = str(row[0].childNodes[0].nodeValue)
        if issue == "Parameter Optimization":
#            print "Parsing line: ", details
            intent, sourcename, originalIntegration, optimumIntegration, adoptedIntegration = details.split(',')
            intent = intent.upper()
            if intent != previousIntent and previousIntent is not None:
                spectralSpec = 0
            previousIntent = intent
            if spectralSpec not in mydict:
                mydict[spectralSpec] = {}
            elif intent in mydict[spectralSpec]:
                spectralSpec += 1
                if spectralSpec not in mydict:
                    mydict[spectralSpec] = {}
            if intent not in list(mydict[spectralSpec].keys()):
                mydict[spectralSpec][intent] = {'sourcename': sourcename, 'originalIntegration': float(originalIntegration), 
                                                'optimumIntegration': float(optimumIntegration), 'adoptedIntegration': float(adoptedIntegration)}
    return mydict

def printSwVersionFromASDM(asdm, useMinidom=False):
    """
    Reads and prints the contents of the ASDM's Annotation.xml table.
    useMinidom: if True, then parse the .xml file even if the ASDM python
                bindings are available
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    -Denis Barkats and Todd Hunter
    """
    if (useMinidom or not asdmLibraryAvailable):
        print("The ASDM bindings library is not available on this machine. Using the minidom code instead.")
        return(au_noASDMLibrary.readSoftwareVersionFromASDM_minidom(asdm))
    a = ASDM()
    parser = ASDMParseOptions()
    parser.asALMA()
    parser.loadTablesOnDemand(True)
    a.setFromFile(asdm,parser)
    at = a.annotationTable().get()
    print('\n### Annotation table for ASDM: %s contains sw version, atm delayModel... ### \n' %asdm)
    for row in at:
        print("%s: %s" %(row.issue(),row.details()))
    print("\n####")
    return

def compareTimesFromAnnotationTableToBandpassPreAverage(vis, asdm='', atmcal=None, maxvis=-1):
    """
    Computes the change in SNR of the bandpass solution if the "optimized" integration times
    reported by SSR Cycle 6 were to be used instead of the actual integration times.
    vis: single measurement set, comma-delimited list, or pipeline parent directory, 
           e.g. 'E2E6.1.00030.S_yyyy_mm_ddThh_mm_ss.sss'
    asdm: corresponding ASDM(s), not necessary if vis is a directory
    atmcal: for cases of a single vis, you can pass in an existing instance of Atmcal to speed it up
    Returns: bandpassPreAverage dictionary for final vis
    -Todd Hunter
    """
    if os.path.isdir(vis):
        mydir = os.path.join(vis,'S*/G*/M*')
        asdm = sorted(glob.glob(os.path.join(mydir,'rawdata/uid*')))
        vis = [os.path.join(os.path.dirname(myasdm).replace('rawdata','working'),os.path.basename(myasdm)+'.ms') for myasdm in asdm]
    if type(vis) == str:
        vis = vis.split(',')
    if type(asdm) == str:
        asdm = asdm.split(',')
    if len(vis) > 1 and atmcal is not None:
        print("The atmcal option is only supported for single vis datasets.")
        return
    mydict = None
    for i in range(len(vis)):
        if maxvis > 0 and i >= maxvis:
            break
        if not os.path.exists(vis[i]):
            print(vis[i])
            return
        asdmdict = readTimesFromAnnotationTable(asdm[i])
        if asdmdict == {}:
            print("No SSR times found for ", asdm[i])
            continue
        mydict = bandpassPreAverage(vis[i], atmcal=atmcal)
        if mydict is None:
            print(vis[i])
            return
        for spectralSpec in asdmdict:
            ssrOptimumBandpassTime = asdmdict[spectralSpec]['BANDPASS']['optimumIntegration']
            ssrAdoptedBandpassTime = asdmdict[spectralSpec]['BANDPASS']['adoptedIntegration']
        print('\n'+vis[i])
        print('SSR determined times: "optimum"=%.2f sec  adopted=%.2fsec' % (ssrOptimumBandpassTime, ssrAdoptedBandpassTime))
        observedTime = np.min(list(mydict['timeOnSourceMinutes'].values()))
        snr = []
        solint = []
        bandwidth = []
        channels = []
        actualChannelsInSolution = []
        channelsInSolution = []
        actualSnr = []
        bandpassTable = sorted(glob.glob(vis[i]+'*bcal.final.tbl'))
        if len(bandpassTable) > 0:
            actualChannels = getNChanFromCaltable(bandpassTable[0])
        for spw in mydict['spws']:
            snr.append(mydict[spw]['snrPerChannel'])
            solint.append(parseFrequencyArgumentToHz(mydict[spw]['solint']))
            bandwidth.append(mydict[spw]['bandwidth'])
            channels.append(mydict[spw]['totalChannels'])
            channelsInSolution.append(mydict[spw]['channelsInSolution'])
            if len(bandpassTable) > 0:
                result = snrFromCaltable(bandpassTable[0])
                if spw not in list(result.keys()):
                    print("Unexpected error: spw %d not in the solution table" % (spw))
                    return
                result = result[spw]
                fieldIDs = list(result.keys())
                fieldID = fieldIDs[0]
                actualSnr.append(result[fieldID]['median'])
                actualChannelsInSolution.append(actualChannels[spw])
        timetype = ['optimum','adopted']
        idx = np.argmax(solint)
        print("Actual observed time: %.2f minutes = %.1f seconds" % (observedTime, observedTime*60))
        spw = mydict['spws'][idx]
        outputChannels = channelsInSolution[idx]
        print("Pipeline recommended solint in lowest SNR spw%d: %s = %s channels yielding %d output channels" % (spw, mydict[spw]['solint'], mydict[spw]['solintChannelsEvenlyDivisible'], outputChannels))
        print("Pipeline predicted SNR in each spw: ", str([round(s,2) for s in snr]))
        if len(bandpassTable) > 0:
            achievedSnr = [round(s,2) for s in actualSnr]
            print("Pipeline achieved SNR in each spw: ", str(achievedSnr))
            # Fill dictionary entries for use by the analyze=True option of readTimesFromAnnotationTables
            mydict['achievedSnr'] = actualSnr
            mydict['snr'] = snr
            mydict['channelsInSolution'] = channelsInSolution
            mydict['actualChannelsInSolution'] = actualChannelsInSolution
        for i,ssrBandpassTime in enumerate([ssrOptimumBandpassTime, ssrAdoptedBandpassTime]):
            print('Ramifications of using SSR "%s" time:' % (timetype[i]))
            ssrsnrReductionFactor = (ssrBandpassTime/(60*observedTime))**0.5
            snr = np.array(snr)
            ssrsnr = snr*ssrsnrReductionFactor
            spw = mydict['spws'][idx]
            ssrsolint = solint[idx] / (ssrsnrReductionFactor**2)
            nchan = bandwidth[idx] / ssrsolint  # predicted for SSR bandpass solution
            totalChannels = channels[idx]
            print("    SNR reduction factor if SSR-determined time (%.1f sec) were to be used: " % (ssrBandpassTime), ssrsnrReductionFactor)
            print("    Predicted SNR in each spw using SSR-determined time: ", ssrsnr)
            nchanEven = np.min([nextHighestIntegerDivisible(totalChannels, int(np.ceil(nchan))), totalChannels])
            print("    Number of output channels pipeline would choose for spw%d if SSR-determined time were to be used: %.1f --> %d" % (spw,nchan,nchanEven))
            print("----------------------------------------------------------------------------------------------------------------")   
    return mydict
    
def readTimesFromAnnotationTables(mydir, analyze=False, maxvis=-1):
    """
    Given a parent directory, e.g. 'pipeline/root/E2E6*', finds all
    asdms in the containted rawdata directories and runs readTimesFromAnnotationTable on them
    mydir: either the full path ending in '/rawdata', or a wildcard string like 'E2E6*'
    -Todd Hunter
    """
    if mydir.find('*') >= 0:
        asdms = sorted(glob.glob(os.path.join(mydir,'S*/G*/M*/rawdata/uid*')))
    else:
        asdms = sorted(glob.glob(os.path.join(mydir,'uid*')))
    if len(asdms) < 1:
        print("No ASDMs found")
        return
    justasdm = []
    mydirs = []
    for asdm in asdms:
        if asdm not in justasdm: # do not repeat the analysis of repeated executions
            mydict = readTimesFromAnnotationTable(asdm)
            project = os.path.dirname(asdm).split('/')[0]
            print(project, os.path.basename(asdm), mydict)
            justasdm.append(os.path.basename(asdm))
            mydirs.append(project)
    if analyze:
        outline = []
        for mydir in mydirs:
            mydict = compareTimesFromAnnotationTableToBandpassPreAverage(mydir, maxvis=maxvis)
            if mydict is None: continue
            if 'achievedSnr' in mydict:
                outline.append(mydict['vis'])
                outline.append('predicted SNRs for %s-channel solutions: %s' % (str(mydict['channelsInSolution']),str([round(s,2) for s in mydict['snr']])))
                outline.append('actual SNRs for %s-channel solutions: %s' % (str(mydict['actualChannelsInSolution']), str([round(s,2) for s in mydict['achievedSnr']])))
                outline.append('')
        filename = 'readTimesFromAnnotationTables.txt'
        f = open(filename,'w')
        for line in outline:
            print(line)
            f.write(line+'\n')
        f.close()

def readTimesFromAnnotationTable(asdm, useMinidom=False):
    """
    For data from Cycle 6 onward, reads the Parameter Optimization entries 
    from the ASDM's Annotation.xml and returns a dictionary keyed by 
    spectralSpec number (starting at zero), then by calibration intent: 
    'BANDPASS', 'PHASE', etc.
    useMinidom: if True, then parse the .xml file even if the ASDM python
                bindings are available
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    -Todd Hunter
    """
    if (os.path.exists(asdm) == False):
        print("readTimesFromAnnotationTable(): Could not find ASDM = ", asdm)
        return(None)
    if (os.path.exists(asdm+'/Annotation.xml') == False):
        print("readTimesFromAnnotationTable(): Could not find Annotation.xml. This dataset was probably taken prior to R10.6.")
        return(None)
    if not asdmLibraryAvailable:
        return(au_noASDMLibrary.readTimesFromAnnotationTable_minidom(asdm))
    mydict = {}
    previousIntent = None
    spectralSpec = 0
    a = ASDM()
    parser = ASDMParseOptions()
    parser.asALMA()
    parser.loadTablesOnDemand(True)
    a.setFromFile(asdm,parser)
    annotationTable = a.annotationTable().get()
    for row in annotationTable:
        issue = row.issue()
        details = row.details()
        if issue == "Parameter Optimization":
            intent, sourcename, originalIntegration, optimumIntegration, adoptedIntegration = details.split(',')
            intent = intent.upper()
            if intent != previousIntent and previousIntent is not None:
                spectralSpec = 0
            previousIntent = intent
            if spectralSpec not in mydict:
                mydict[spectralSpec] = {}
            elif intent in mydict[spectralSpec]:
                spectralSpec += 1
                if spectralSpec not in mydict:
                    mydict[spectralSpec] = {}
            if intent not in list(mydict[spectralSpec].keys()):
                mydict[spectralSpec][intent] = {'sourcename': sourcename, 'originalIntegration': float(originalIntegration), 
                                                'optimumIntegration': float(optimumIntegration), 'adoptedIntegration': float(adoptedIntegration)}
    return mydict

def plotDecorrelation(asdm, scan=[], ylim=[0,1], plotfile='', doplot=True,
                      baseband=0, field=-1, corrected=False, useMinidom=False):
    """
    Plots decorrelation vs. baseline length from the CalPhase.xml file.
    baseband: 0 means all, otherwise 1,2,3, or 4
    field: which field to plot (-1 means all)
           This will be used to find the list of scans to plot.
    corrected: if True, show AP_CORRECTED data, otherwise AP_UNCORRECTED
    Returns:
    The median decorrelation over all measurements.
    -Todd Hunter
    """
    mydict = readDecorrelationFromASDM(asdm, useMinidom=useMinidom)
    scandict = readscans(asdm, useMinidom=useMinidom)[0]  # each entry contains key='source' with value=fieldname
    fielddict, fieldnamedict = getFieldsFromASDM(asdm, useMinidom=useMinidom) # [1]: key=fieldname, value=fieldid
    for i in list(scandict.keys()):
        scandict[i]['fieldid'] = fieldnamedict[scandict[i]['source']]
    uniqueFieldIDs = list(fielddict.keys())
    scansforfields = {}
    for f in uniqueFieldIDs:
        scansforfields[f] = []
        for i in list(scandict.keys()):
            if scandict[i]['fieldid'] == f:
                scansforfields[f].append(i)
    if (field != -1 and field not in uniqueFieldIDs):
        print("Field %s is not in the xml file." % (str(field)))
        return
    asdm = asdm.rstrip('/')
    if (mydict == None): return
    if (doplot):
        pb.clf()
    if (scan == []):
        scan = range(len(mydict['baselineLengths']))
    medianDecorrelation = []
    elevation = []
    measurements = 0
    for s in scan:
        if ((corrected and mydict['atmPhaseCorrection'][s] == 'AP_CORRECTED') or
            (not corrected and mydict['atmPhaseCorrection'][s] == 'AP_UNCORRECTED')):
            if (baseband == 0 or baseband == int(mydict['basebandName'][s].split('_')[1])):
                if (field==-1 or s in scansforfields[field]):
                    measurements += 1
                    medianDecorrelation.append(mydict['decorrelationFactor'][s])
                    elevation.append(mydict['elevation'][s])
                    if (doplot):
                        length = len(mydict['decorrelationFactor'][s])
                        numReceptor = mydict['numReceptor'][s]
                        for r in range(numReceptor):
                            polLength = length//numReceptor
                            first = r*polLength
                            last = (r+1)*polLength
                            pb.plot(mydict['baselineLengths'][s],
#                                    np.array(mydict['decorrelationFactor'][s])[range(r,length,numReceptor)], # interleaved
                                    np.array(mydict['decorrelationFactor'][s])[first:last], # serial
                                    'o',color=overlayColors[r])
    print("Processed %d measurements" % (measurements))
    if doplot:
        pb.xlabel('Baseline length (m)')
        pb.ylabel('Decorrelation')
        if (ylim != [0,0]):
            pb.ylim(ylim)
        if baseband==0:
            basebands = 'all basebands'
        else:
            basebands = 'baseband ' + str(baseband)
        elevationString = 'elev %.0f-%.0f' % (np.min(elevation),np.max(elevation))
        pb.title(os.path.basename(asdm) + '  (%s, %s)' % (basebands,elevationString))
        pb.draw()
        if (plotfile != ''):
            if plotfile==True:
                plotfile = asdm.rstrip('/') + '.decorrelation.png'
            pb.savefig(plotfile)
            print("Plot saved in ", plotfile)
    if (measurements > 0):
        medianDecorrelation = np.median(medianDecorrelation)
    else:
        medianDecorrelation = 0
    return(medianDecorrelation)
    
def readDecorrelationFromASDM(asdm, useMinidom=False):
    """
    This function reads the decorrelation information from the CalPhase.xml file.
    Returns a dictionary with keys:
    'baselineLengths'
    'decorrelationFactor'
    'startValidTime'
    'endValidTime'
    'atmPhaseCorrection'
    'receiverBand'
    'basebandName'
    'numReceptor'
    'calDataId'
    'integrationTime'
    'azimuth'
    'elevation'
    -Todd Hunter
    """
    if (not asdmLibraryAvailable or useMinidom):
        if not useMinidom:
            print("The ASDM bindings library is not available on this machine. Using minidom instead.")
        import au_noASDMLibrary
        mydict = au_noASDMLibrary.readDecorrelationFromASDM_minidom(asdm)
    else:
        a = ASDM()
        parser = ASDMParseOptions()
        parser.asALMA()
        parser.loadTablesOnDemand(True)
        a.setFromFile(asdm,parser)
        calPhaseTable = a.calPhaseTable().get()
        mydict = {'baselineLengths': [], 'decorrelationFactor': [], 'startValidTime': [],
                  'endValidTime': [], 'atmPhaseCorrection': [], 'calDataId': [], 'numReceptor': [],
                  'integrationTime': [], 'receiverBand': [], 'basebandName': [], 'azimuth': [], 'elevation': []}
        for i in calPhaseTable:
            mydict['startValidTime'].append(int(1e9*dateStringToMJDSec(str(i.startValidTime()), verbose=False)))
            mydict['endValidTime'].append(int(1e9*dateStringToMJDSec(str(i.endValidTime()), verbose=False)))
            mydict['atmPhaseCorrection'].append(str(i.atmPhaseCorrection()))
            mydict['receiverBand'].append(i.receiverBand())
            mydict['basebandName'].append(i.basebandName())
            mydict['numReceptor'].append(int(i.numReceptor()))
            mydict['calDataId'].append(int(str(i.calDataId()).strip().split('_')[1]))
            timeInterval = float(str(i.integrationTime()).replace('s','')) # 1.00800s
            mydict['integrationTime'].append(timeInterval)
            mydict['baselineLengths'].append([float(str(j).replace('m','')) for j in i.baselineLengths()])
#            print("shape(decorrelationFactor) = ", np.shape(i.decorrelationFactor()))
            mydict['decorrelationFactor'].append(np.array(list(i.decorrelationFactor())).flatten()) # pol0 results, then pol1
#            mydict['direction'].append(i.direction())  # (1.23e+00rad, 2.22e-01rad)
            mydict['azimuth'].append(math.degrees(float(str(i.direction()[0]).replace('rad',''))))
            mydict['elevation'].append(math.degrees(float(str(i.direction()[1]).replace('rad',''))))
            
    scandict = readCalDataFromASDM(asdm, useMinidom=useMinidom)
    # insert scan number lists into dictionary
    mydict['scan'] = mydict['calDataId']
    for i in range(len(mydict['calDataId'])):
        mydict['scan'][i] = scandict[mydict['calDataId'][i]]['scan']
    return(mydict)

def plotSeeing(asdm, plotfile='', useMinidom=False):
    """
    Reads and plots the seeing from the CalPhase.xml file of an ASDM.
    -Todd Hunter
    """
    mydict = readSeeingFromASDM(asdm, useMinidom)
    pb.clf()
    adesc = pb.subplot(111)
    c = {'AP_UNCORRECTED': 'r', 'AP_CORRECTED': 'g'}
    nMeasurements = len(mydict['atmPhaseCorrection'])
    x = []
    y = []
    for n in range(nMeasurements):
        x.append(mydict['startValidTime'][n]*1e-9)
        y.append(mydict['seeing'][n])
    print("len(x)=%d, min(x)=%f, max(x)=%f, median=%f" % (len(x), np.min(x), np.max(x), np.median(x)))
#    list_of_date_times = mjdSecondsListToDateTime(x)
#    timeplot = pb.date2num(list_of_date_times)
#    pb.plot(timeplot, y, 'o', color = c[mydict['atmPhaseCorrection'][n]])
    pb.plot(x-np.min(x), y, 'o', color = c[mydict['atmPhaseCorrection'][n]])
    x0,x1 = pb.xlim()
    print("x0=%f, x1=%f" % (x0,x1))
    pb.xlim([x0-5, x1+5])
    pb.xlabel('Time')
    ymin,ymax = pb.ylim()
    pb.ylim([0,ymax])
    pb.ylabel('Seeing (arcsec)')
    pb.title(asdm)
    adesc.xaxis.set_major_locator(matplotlib.dates.MinuteLocator(byminute=range(0,60,30)))
    adesc.xaxis.set_minor_locator(matplotlib.dates.MinuteLocator(byminute=range(0,60,10)))
    adesc.xaxis.set_major_formatter(matplotlib.dates.DateFormatter('%H:%M'))
    adesc.fmt_xdata = matplotlib.dates.DateFormatter('%H:%M')
    RescaleXAxisTimeTicks(pb.xlim(), adesc)
    pb.draw()
    if (plotfile != ''):
        if (plotfile == True):
            plotfile = asdm + '.seeing.png'
        pb.savefig(plotfile)
        print("Plot left in ", plotfile)
        
def readSeeingFromASDM(asdm, useMinidom=False):
    """
    This function reads the seeing information from the CalSeeing.xml file.
    Returns a dictionary with the following keys:
    atmPhaseCorrection: AP_UNCORRECTED or AP_CORRECTED
    baselineLengths: typically 3 values (in meters)
    startValidTime: MJD seconds
    endValidTime: MJD seconds
    phaseRMS:  a value for each baselineLength (in radians) for each timestamp
    seeing: one value per timestamp (arcseconds)
    useMinidom: if True, then parse the .xml file even if the ASDM python
                bindings are available
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    - thunter
    """
    if (not asdmLibraryAvailable or useMinidom):
        import au_noASDMLibrary
        print("The ASDM bindings library is not available on this machine. Using minidom instead.")
        mydict = au_noASDMLibrary.readSeeingFromASDM_minidom(asdm)
        return(mydict)
    a = ASDM()
    parser = ASDMParseOptions()
    parser.asALMA()
    parser.loadTablesOnDemand(True)
    a.setFromFile(asdm,parser)
    calSeeingTable = a.calSeeingTable().get()
    mydict = {}
    mydict['seeing'] = []
    mydict['phaseRMS'] = []
    mydict['startValidTime'] = []
    mydict['endValidTime'] = []
    mydict['atmPhaseCorrection'] = []
    mydict['baselineLengths'] = []
    mydict['phaseRMS'] = []
    for row in calSeeingTable:
        mydict['seeing'].append(206264.8*row.seeing().get())
        mydict['startValidTime'].append(row.startValidTime().get()*1e-9)
        mydict['endValidTime'].append(row.endValidTime().get()*1e-9)
        mydict['atmPhaseCorrection'].append(str(row.atmPhaseCorrection()))
        r = [i.get() for i in row.baselineLengths()]  # the .get() converts from Length to flaot
        baselineLengths = []
        for i in range(len(r)):
            baselineLengths.append(r[i])
        mydict['baselineLengths'].append(baselineLengths)
        r = [i.get() for i in filter(None,row.phaseRMS())] # the .get() converts from Angle to float
        phaseRMS = []
        for i in range(len(r)):
            phaseRMS.append(r[i])
        mydict['phaseRMS'].append(phaseRMS)
    return(mydict)

def getPolarizationsFromASDM(asdm, useMinidom=False):
    """
    Reads the Polarization.xml file of an ASDM and reports the number of
    polarization products in each polarization ID.
    useMinidom: if True, then parse the .xml file even if the ASDM python
                bindings are available
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    -Todd Hunter
    """
    if (not os.path.exists(asdm)):
        print("Could not find ASDM: ", asdm)
        return
    if not asdmLibraryAvailable or useMinidom:
        import au_noASDMLibrary
        mydict = au_noASDMLibrary.getPolarizationsFromASDM_minidom(asdm)
    else:
        mydict = {}
        a = ASDM()
        parser = ASDMParseOptions()
        parser.asALMA()
        parser.loadTablesOnDemand(True)
        a.setFromFile(asdm,parser)
        polarizationTable = a.polarizationTable().get()
        for row in polarizationTable:
            numCorr = row.numCorr()
            corrs = row.corrType()
            corrTypes = [str(i) for i in corrs]
            polarizationId =  row.polarizationId().get()
            mydict[polarizationId] = {'numCorr': numCorr, 'corrTypes': corrTypes}
    return(mydict)

def wvrdata(asdm, useMinidom=False):
    """
    Checks whether a dataset contains WVR corrected visibility data, 
    uncorrected data, or both, by examining the names in the atmPhaseCorrection
    tag of ConfigDescription.xml.  Both types of data were
    nominally present from Cycle 3 through Cycle 5 (see ICT-4698 and 
    ICT-12638 and the February 2018 comparison report by J. D. Meyer, 
    B. Dent on SCIREQ-973).  The online correction visibilities were not 
    available for Cycle 0, 1 and most of Cycle 2.
    Returns: a tuple of two Booleans (uncorrected present and corrected present)
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    useMinidom: if True, then parse the .xml file even if the ASDM python
                bindings are available
    -Todd Hunter
    """
    if (not os.path.exists(asdm)):
        print("Could not find ASDM: ", asdm)
        return
    corrected = False
    uncorrected = False
    if not asdmLibraryAvailable or useMinidom:
        import au_noASDMLibrary
        for line in open(asdm+'/ConfigDescription.xml'):
            if 'AP_CORRECT' in line:
                corrected = True
            elif 'AP_UNCORRECT' in line:
                uncorrected = True
    else:
        a = ASDM()
        parser = ASDMParseOptions()
        parser.asALMA()
        parser.loadTablesOnDemand(True)
        a.setFromFile(asdm,parser)
        calPhaseTable = a.configDescription().get()
        corrected = False
        uncorrected = False
        for row in calPhaseTable:
            atmPhaseCorrection = row.atmPhaseCorrection()
            if str(atmPhaseCorrection) == 'AP_CORRECT':
                corrected = True
            elif str(atmPhaseCorrection) == 'AP_UNCORRECT':
                uncorrected = True
    if (uncorrected and not corrected):
        print("This ASDM contains only WVR-uncorrected data.")
    elif (corrected and not uncorrected):
        print("This ASDM contains only WVR-corrected data.")
    else:
        print("This ASDM contains both WVR-uncorrected and corrected data.")
    return(uncorrected, corrected)

def wvrdataOldstyle(asdm, useMinidom=False):
    """
    Checks whether a dataset contains WVR corrected visibility data, 
    uncorrected data, or both, by examining the names of 
    the solutions present in the CalPhase table.  Both were
    nominally present from Cycle 3 through Cycle 5 (see ICT-4698 and 
    ICT-12638 and the February 2018 comparision report by J. D. Meyer, 
    B. Dent on SCIREQ-973).  The online correction visibilities were not 
    available for Cycle 0, 1 and most of Cycle 2.
    Note that this function will show both present in Cycle 6 onward even 
    though only uncorrected data were stored. This is probably because 
    QA0 eventually required the corrected data solutions to be stored and 
    so they were left in place (and are now computed and written by TelCal).
    See au.wvrdata for a different method which should work for all datasets.
    Returns: a tuple of two Booleans (uncorrected present and corrected present)
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    useMinidom: if True, then parse the .xml file even if the ASDM python
                bindings are available
    -Todd Hunter
    """
    if (not os.path.exists(asdm)):
        print("Could not find ASDM: ", asdm)
        return
    corrected = False
    uncorrected = False
    if not asdmLibraryAvailable or useMinidom:
        import au_noASDMLibrary
        for line in open(asdm+'/CalPhase.xml'):
            if 'AP_CORRECT' in line:
                corrected = True
            elif 'AP_UNCORRECT' in line:
                uncorrected = True
    else:
        a = ASDM()
        parser = ASDMParseOptions()
        parser.asALMA()
        parser.loadTablesOnDemand(True)
        a.setFromFile(asdm,parser)
        calPhaseTable = a.calPhaseTable().get()
        corrected = False
        uncorrected = False
        for row in calPhaseTable:
            atmPhaseCorrection = row.atmPhaseCorrection()
            if str(atmPhaseCorrection) == 'AP_CORRECT':
                corrected = True
            elif str(atmPhaseCorrection) == 'AP_UNCORRECT':
                uncorrected = True
    if (uncorrected and not corrected):
        print("This ASDM contains only WVR-uncorrected data.")
    elif (corrected and not uncorrected):
        print("This ASDM contains only WVR-corrected data.")
    else:
        print("This ASDM contains both WVR-uncorrected and corrected data.")
    return(uncorrected, corrected)

def printFluxesFromASDM(sdmfile, sourcename='', field=-1, useCalFlux=False, spw=-1, 
                        asdmspw=-1, showCenterFreqs=False, fluxprec=4, freqprec=1,
                        scienceSpws=False):
    """
    Calls readFluxesFromASDM, organizes the output and prints it to
    the screen.  Normally this function will read from the Source.xml table,
    but setting useCalFlux=True will force it to read from CalFlux.xml.
    spw: if specified, (or if neither spw nor asdmspw are specified), then 
         the spw numbers will be assumed to be ms spws numbers,
         they will be mapped to ASDM spw numbers to retrieve the flux value
    asdmspw: if specified, the spw numbers will be assumed to be ASDM spw 
             numbers
    fluxprec: precision of frequency display (3 = 1mJy etc.)
    freqprec: precision of frequency display (1 = 0.1 Hz, 2 = 0.01 Hz, etc.)
    -Todd Hunter
    """
    result = readFluxesFromASDM(sdmfile, sourcename, field, useCalFlux)
    if (result == None):
        print("readFluxesFromASDM returns None")
        return
    spwmap = asdmspwmap(sdmfile)
    if (scienceSpws):
        spw = getScienceSpwsFromASDM(sdmfile)
    if (((spw == -1 or spw=='') and (asdmspw == -1 or asdmspw=='')) or (spw != -1)):
        if (spw == -1 or spw == '') and (asdmspw == -1 or asdmspw == ''):
            # Make a list of all ms spws
            spw = list(range(len(spwmap)))
        if (type(spw) == list):
            spwlist = spw
        elif (type(spw) == str):
            spwlist = [int(n) for n in spw.split(',')]
        else:
            spwlist = [spw]
        asdm_spwlist = []
        for spw in spwlist:
            asdm_spwlist.append(spwmap[spw])
        spwlist = asdm_spwlist
    else:
        # Make a list of all asdm spws
        if (type(asdmspw) == list):
            spwlist = asdmspw
        elif (type(asdmspw) == str):
            spwlist = [int(n) for n in asdmspw.split(',')]
        else:
            spwlist = [asdmspw]

    mylist, mydict = result
    if (mylist == []): return
    srcName = list(mydict.keys())[0]
    stokes = ''
    stokesParameters = mydict[srcName][0]['stokesParameters']
    for sp in stokesParameters:
        stokes += sp + ' '
    intents = getIntentsFromASDM(sdmfile,stripPrefix=True)
    for source in list(mydict.keys()):
        if (source in list(intents.keys())):
            print("%s intents = %s" % (source, intents[source]))
    if ('frequency' in list(mydict[srcName][0].keys())):
        print("Sourcename    spw     Freq(GHz)  Flux densities (%s)" % (stokes))
        if showCenterFreqs:
            print("           ASDM  ms  FreqOfFlux" + 4*(fluxprec-3)*' ' + freqprec*' ' + "                                  CenterFreq      Difference")
        else:
            print("           ASDM  ms  FreqOfFlux")
    else:
        print("Sourcename  Freq(GHz)  Flux densities (%s)" % (stokes))
    if showCenterFreqs:
        centerFreq = getFrequenciesFromASDM(sdmfile, minnumchan=1)
    for source in list(mydict.keys()):
        for entry in mydict[source]:
          if (entry['spw'] in spwlist or spwlist == [-1]):
            if ('frequency' in list(entry.keys())):
                for f in range(len(entry['frequency'])):
                    if (entry['spw'] in spwmap):
                        spw_in_ms = spwmap.index(entry['spw'])
                    else:
                        spw_in_ms = ' n/a'
                    line = "%s %3d %4s  " % (source, entry['spw'], spw_in_ms)
                    freq = entry['frequency'][f]
                    line +=  '%.*f  ' % (freqprec, freq)
                    for stokes in range(len(entry['stokesParameters'])):
                        line +=  '%.*f  ' % (fluxprec, entry['fluxDensity'][f][stokes])
                    if showCenterFreqs:
                        line +=  '%.*f %*.*f ' % (freqprec, centerFreq[spw_in_ms], freqprec+13, freqprec, freq-centerFreq[spw_in_ms])
                    print(line)
            else:  # These results are from the CalFlux.xml file
                for f in range(len(entry['frequencyRange'])):
                    line = "%s  " % (source)
                    freq = entry['frequencyRange'][f]
                    line +=  '%.*f-%.*f  ' % (freqprec, freq[0], freqprec, freq[1])
                    for stokes in range(len(entry['stokesParameters'])):
                        print("entry['fluxDensity'][f] = ", entry['fluxDensity'][f])
                        print("stokes = ", stokes)
                        line +=  '%.*f  ' % (fluxprec,entry['fluxDensity'][f][stokes])
                    print(line)

def checkScienceSpwsFromASDM(dir='./', ignore='.ms'):
    """
    For all ASDMs in the specified directory, get the
    science spws and report any differences in ID number.
    dir: comma-delimited list of directories, wildcard string, or 
         list of directories
    -Todd Hunter
    """
    if type(dir) == str:
        if (dir.find('*')>=0):
            dirs = glob.glob(dir)
        else:
            dirs = dir.split(',')
    else:
        dirs = dir
    if dirs[0][:6] == 'uid___':
        vis = dirs
        dirs = ['./']
    else:
        vis = ''
    print("Processing directories: ", dirs)
    for dir in dirs:
        print(dir+":")
        if vis == '':
            vis = glob.glob(dir+'/uid___*')
        if (len(ignore) > 0):
            tvis = glob.glob(dir+'/*%s*'%(ignore))
            vis = list(set(vis) - set(tvis))
        if (len(vis) < 2):
            print("    Only %d ASDM found" % (len(vis)))
            continue
        spws = getScienceSpwsFromASDM(vis[0])
        print("%s: %s" % (os.path.basename(vis[0]),spws))
        difference = False
        for v in vis[1:]:
            newspws = getScienceSpwsFromASDM(v)
            print("%s: %s" % (os.path.basename(v),newspws))
            if spws != newspws:
                difference = True
                print("   Difference!")
    return difference

def getScienceSpwsFromASDM(asdm, returnTransitions=False, useMinidom=False):
    """
    Gets the spw IDs for the science target spws in an ASDM. The single-channel 
    spws are ignored.  The IDs are those that will appear in the listobs of a 
    measurement set once it is imported.  It determines science spws by the 
    presence of the "velRefCode" tag, which does not
    work for the image sidebands of 90deg Walsh SpectralSpecs in Cycle 5 and 6.
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    useMinidom: if True, then parse the .xml file even if the ASDM python
                bindings are available
    -Todd Hunter
    """
    scienceSpwsASDM = []
    transitions = []
    if not asdmLibraryAvailable or useMinidom:
        import au_noASDMLibrary
        result = au_noASDMLibrary.getScienceSpwsFromASDM_minidom(asdm, returnTransitions)
        return result
    else:
        a = ASDM()
        parser = ASDMParseOptions()
        parser.asALMA()
        parser.loadTablesOnDemand(True)
        a.setFromFile(asdm,parser)
        sourceTable = a.sourceTable().get()
        for i,row in enumerate(sourceTable):
            try:
                velRefCode = str(row.velRefCode())
                if len(velRefCode) > 0:
                    spw = row.spectralWindowId().get()
                    scienceSpwsASDM.append(spw)
                    transition = str(row.transition())
                    transitions.append(transition)
            except:
#                print("%d: velRefCode undefined" % (i))
                pass
    scienceSpwsASDM = np.unique(scienceSpwsASDM)
#    print("getScienceSpwsFromASDM(): scienceSpws in ASDM: ", scienceSpwsASDM)
    spwmap = asdmspwmap(asdm, useMinidom=useMinidom)
    scienceSpws = []
    scienceTransitions = []
    mydict = getSpwsFromASDM(asdm, useMinidom=useMinidom)
    for i,spw in enumerate(scienceSpwsASDM):
        if spw not in spwmap:
            print("%d not in %s" % (spw,spwmap))
            continue
        myspw = spwmap.index(spw)  
        if mydict[myspw]['numChan'] > 1:
            scienceSpws.append(myspw)
            if returnTransitions:
                scienceTransitions.append(transitions[i])
#    print("getScienceSpwsFromASDM(): scienceSpws in ms: ", scienceSpws)
    if returnTransitions:
        return scienceSpws, scienceTransitions
    else:
        return scienceSpws

def getScienceSpwTransitionsFromASDM(asdm, useMinidom=False):
    """
    Gets the transitions for the science target spws in an ASDM.  Single-channel spws are
    ignored.  The IDs are those that will appear in a measurement set once it is imported.
    It determines science spws by the presence of the "velRefCode" tag.
    useMinidom: if True, then parse the .xml file even if the ASDM python
                bindings are available
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    -Todd Hunter
    """
    if not asdmLibraryAvailable or useMinidom:
        import au_noASDMLibrary
        transitions, scienceSpwsASDM = au_noASDMLibrary.getScienceSpwTransitionsFromASDM_minidom(asdm)
    else:
        a = ASDM()
        parser = ASDMParseOptions()
        parser.asALMA()
        parser.loadTablesOnDemand(True)
        a.setFromFile(asdm,parser)
        sourceTable = a.sourceTable().get()
        transitions = {}
        scienceSpwsASDM = []
        for i,row in enumerate(sourceTable):
            try:
                velRefCode = row.velRefCode()
                spw = row.spectralWindowId().get()
                scienceSpwsASDM.append(spw)
                transition = row.transition()
                transitions[spw] = ','.join(list(transition))
            except:
                pass
    scienceSpwsASDM = np.unique(scienceSpwsASDM)
    spwmap = asdmspwmap(asdm)
    scienceSpws = []
    scienceTransitions = {}
    mydict = getSpwsFromASDM(asdm)
    for spw in scienceSpwsASDM:
        myspw = spwmap.index(spw)
        if mydict[myspw]['numChan'] > 1:
            mytransition = transitions[spw]
            scienceSpws.append(myspw)
            scienceTransitions[myspw] = mytransition
    return scienceTransitions

def readFluxesFromASDM(sdmfile, sourcename='', field=-1, useCalFlux=False, spw=-1, useMinidom=False):
    """
    Read the flux densities from an ASDM.  If useCalFlux=False,
    look for fluxes in the Source.xml table, otherwise, look in CalFlux.xml.
    Returns a raw list of dictionaries (one per row) and a dictionary of
    the information keyed by the field name. Specify a sourcename or
    field ID to limit the results to a specific source. Inserting the
    wildcard character (*) into sourcename will return partial matches.
            {'sourceName': sourceName, 'stokes': stokesParameters,
            'frequencyRange': frequency, 'fluxDensity': fluxDensity,
            'fluxDensityError': fluxDensityError}
    - Todd Hunter
    """
    if (type(spw) != list):
        if (type(spw) == str):
            spw = [int(a) for a in spw.split(',')]
        else:
            spw = [spw]
    if not os.path.exists(sdmfile):
        print("readFluxesFromASDM(): Could not find file = ", sdmfile)
        return(None)
    if not asdmLibraryAvailable or useMinidom:
        import au_noASDMLibrary
        result = au_noASDMLibrary.readFluxesFromASDM_minidom(sdmfile, useCalFlux, sourcename, field, spw)
        if result is not None:
            sources, noFrequencyKeywords, useCalFlux = result
        else:
            sources = []
    else:
        a = ASDM()
        parser = ASDMParseOptions()
        parser.asALMA()
        parser.loadTablesOnDemand(True)
        a.setFromFile(sdmfile, parser)
        if useCalFlux:
            calflux = sdmfile + '/CalFlux.xml'
            if not os.path.exists(os.path.join(sdmfile,"CalFlux.xml")):
                print("readFluxesFromASDM(): Could not find file = ", calflux)
                sourcefile = sdmfile + '/Source.xml'
                print("Looking for %s instead" % (sourcefile))
                if not os.path.exists(sourcefile):
                    print("readFluxesFromASDM(): Could not find file = ", sourcefile)
                    return(None)
                useCalFlux = False
                print("Setting useCalFlux = ", useCalFlux)
        else:
            sourcefile = sdmfile + '/Source.xml'
            if not os.path.exists(sourcefile):
                print("readFluxesFromASDM(): Could not find file = ", sourcefile)
                return(None)
        fid = 0
        sources = []
        if useCalFlux:
            calFluxTable = a.calFluxTable().get()
            print("using calFlux table")
            for row in calFluxTable:
                print("dir(row) = ", dir(row))
                sourceId = row.sourceId()
                sourceName = row.sourceName()
                spectralWindowId = row.spectralWindowId().get()
                try:
                    stokesParameters = row.stokesParameter
                    frequency = row.frequency()
                    fluxDensity = row.flux()
                    if (spectralWindowId in spw or spw==[-1]):
                        sources.append({'sourceId': sourceId, 'sourceName': sourceName,
                                        'spw': spectralWindowId,
                                        'stokesParameters': stokesParameters,
                                        'frequency': frequency, 'fluxDensity': fluxDensity})
                        fid += 1
                except:
                    pass
            if len(sources) == 0:
                print("No measurements found in CalFlux table")
        else:  # Source table
            sourceTable = a.sourceTable().get()
            print("using Source table")
            for row in sourceTable:
                sourceId = row.sourceId()
                sourceName = row.sourceName()
                spectralWindowId = row.spectralWindowId().get()
                try:
                    stokesParameters = row.stokesParameter()
                    frequency = row.frequency()
                    fluxDensity = row.flux()
                    if (spectralWindowId in spw or spw==[-1]):
                        sources.append({'sourceId': sourceId, 'sourceName': sourceName,
                                        'spw': spectralWindowId,
                                        'stokesParameters': stokesParameters,
                                        'frequency': frequency, 'fluxDensity': fluxDensity})
                        fid += 1
                except:
                    pass
            if len(sources) == 0:
                print("No measurements found in Source table")
    mydict = {}
    for src in sources:
        if (src['sourceName'] not in list(mydict.keys())):
            mydict[src['sourceName']] = []
        if (useCalFlux == False):
            subdict = {'fluxDensity': src['fluxDensity'], 'frequency': src['frequency'], 'spw': src['spw'],
                       'stokesParameters': src['stokesParameters']}
        else:
            subdict = {'fluxDensity': src['fluxDensity'], 'frequencyRange': src['frequencyRange'],
                       'stokesParameters': src['stokes']}
        mydict[src['sourceName']].append(subdict)
    if not useCalFlux and (not asdmLibraryAvailable or useMinidom):
        if noFrequencyKeywords:
            print("No frequency keywords found in the Source.xml file. Try setting useCalFlux=True.")
    return(sources, mydict)

def getWeatherFromASDM(sdmfile='',verbose=False, station='WSTB1', useMinidom=False):
    """
    Reads the weather table in the ASDM.
    Inputs:
    station:  name of station, default = WSTB1
    Returns three things:
    * a list of value arrays
       0=timeInterval, 1=pressure, 2=relHumidity, 3=temperature,
       4=windDirection, 5=windSpeed, 6=windMax, 7=station
    * a dictionary of the median values
    * the weather station name
    useMinidom: if True, then parse the .xml file even if the ASDM python
                bindings are available
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    - T. Hunter
    """
    scandict = readWeatherFromASDM(sdmfile, useMinidom)
    if (scandict == None):
        return({},{},'')
    if (verbose):
        print("len(scandict) = ", len(scandict))
    mydict = getWeatherStationNamesFromASDM(sdmfile, useMinidom=useMinidom)
    found = False
    for stationid in list(mydict.keys()):
        if (mydict[stationid] == station):
            found = True
            break
    if (not found):
        print("Station %s is not in the dataset. Available stations: " % (station), list(getWeatherStationNamesFromASDM(sdmfile).values()))
        return
    stationName = station
    d1 = ReadWeatherStation(scandict, station=stationid)
    medians = {}
    if (len(d1[0]) < 1):
        print("No data found from any stations")
        return(d1,medians,'')

    timeInterval, pressure, relHumidity, temperature, windDirection, windSpeed, windMax, station = d1
    medians['pressure'] = np.median(pressure)
    medians['humidity'] = np.median(relHumidity)
    medians['temperature'] = np.median(temperature)
    sinWindDirection = np.sin(np.array(windDirection)*np.pi/180)
    cosWindDirection = np.cos(np.array(windDirection)*np.pi/180)
    medians['windDirection'] = (180./np.pi)*np.arctan2(np.mean(sinWindDirection),
                                                  np.mean(cosWindDirection))
    if (medians['windDirection'] < 0):
        medians['windDirection'] += 360
    medians['windSpeed'] = np.median(windSpeed)
    medians['windMax'] = np.max(windMax)
    return(d1,medians,stationName)

def readWeatherFromASDM(sdmfile, useMinidom=False):
    """
    Reads the weather table in the ASDM, and returns a dictionary containing:
    timeInterval, pressure, relHumidity, temperature, windDirection, windSpeed,
    windMax and stationId.
    useMinidom: if True, then parse the .xml file even if the ASDM python
                bindings are available
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    - T. Hunter
    """
    if (os.path.exists(sdmfile) == False):
        print("readWeatherFromASDM(): Could not find file = ", sdmfile)
        return(None)
    scandict = {}
    if not asdmLibraryAvailable or useMinidom:
        import au_noASDMLibrary
        scandict = au_noASDMLibrary.readWeatherFromASDM_minidom(sdmfile)
    else:
        a = ASDM()
        parser = ASDMParseOptions()
        parser.asALMA()
        parser.loadTablesOnDemand(True)
        a.setFromFile(sdmfile,parser)
        weatherTable = a.weatherTable().get()
        fid = 0
        for row in weatherTable:
            scandict[fid] = {}
            timeInterval = str(row.timeInterval())
            dateString = timeInterval.split(',')[0].split('=')[1]
            scandict[fid]['timeInterval'] = dateStringToMJDSec(dateString, verbose=False) + 0.5*float(timeInterval.split(',')[1].split('=')[1])
            scandict[fid]['pressure'] = 0.01*row.pressure().get()
            scandict[fid]['relHumidity'] = row.relHumidity().get()
            scandict[fid]['temperature'] = row.temperature().get()
            scandict[fid]['windDirection'] = np.degrees(row.windDirection().get())
            scandict[fid]['windSpeed'] = row.windSpeed().get()
            scandict[fid]['windMax'] = row.windMax().get()
            scandict[fid]['stationId'] = row.stationId().get()
            fid += 1
    return scandict

def readFeedFromASDM(asdm, useMinidom=False):
    """
    Reads Feed.xml from the ASDM, and returns a list of unique values
    from the timeInterval tag (in units of MJD seconds)
    useMinidom: if True, then parse the .xml file even if the ASDM python
                bindings are available
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    - T. Hunter
    """
    if (not os.path.exists(asdm)):
        print("readFeedFromASDM(): Could not find file = ", asdm)
        return(None)
    if not asdmLibraryAvailable or useMinidom:
        import au_noASDMLibrary
        values0, values1 = au_noASDMLibrary.readFeedFromASDM_minidom(asdm)
    else:
        a = ASDM()
        parser = ASDMParseOptions()
        parser.asALMA()
        parser.loadTablesOnDemand(True)
        a.setFromFile(asdm,parser)
        feedTable = a.feedTable().get()
        values0 = []; values1 = []
        for row in feedTable:
            timeInterval = str(row.timeInterval())
            dateString = timeInterval.split(',')[0].split('=')[1]
#            values0.append(dateStringToMJDSec(dateString, verbose=False) + 0.5*float(timeInterval.split(',')[1].split('=')[1]))
            values0.append(dateStringToMJDSec(dateString, verbose=False))
            values1.append(float(timeInterval.split(',')[1].split('=')[1]))
        values0 = np.unique(values0)
        values1 = np.unique(values1)
    return(values0,values1)

def readStationsFromASDM(sdmfile):
    """
    Similar to readStationFromASDM, but returns different format dictionary
    {'J503': [x,y,z], 'N605': etc.}
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    -Todd Hunter
    """
    if not asdmLibraryAvailable:
        mydict = au_noASDMLibrary.readStationsFromASDM_minidom(sdmfile)
    else:
        mydict = readStationFromASDM(sdmfile)
        newdict = {}
        for station in list(mydict.keys()):
            name = mydict[station]['name']
            position = mydict[station]['position']
            newdict[name] = position
        mydict = newdict
    return(mydict)

def readAntennasFromASDM(sdmfile, stations=False, diameters=False, 
                         verbose=True, useMinidom=False):
    """
    Reads the list of antenna names from the ASDM.
    stations: if True, also return the (zero-based integer) station IDs in a second integer list
    diameters: if True, also return the dish diameters in a second (or third) integer list
    useMinidom: if True, then parse the .xml file even if the ASDM python
                bindings are available
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    - D Barkats & Todd Hunter
    """
    antList = []
    stationList = []
    dishDiameterList = []
    if not asdmLibraryAvailable or useMinidom:
        import au_noASDMLibrary
        antList, stationList, dishDiameterList = au_noASDMLibrary.readAntennasFromASDM_minidom(sdmfile, stations, diameters, verbose)
    else:
        a = ASDM()
        parser = ASDMParseOptions()
        parser.asALMA()
        parser.loadTablesOnDemand(True)
        a.setFromFile(sdmfile,parser)
        antennaTable = a.antennaTable().get()
        for row in antennaTable:
            name = row.name()
            antList.append(name)
            if stations:
                station = row.stationId()
                stationList.append(station)
            if diameters:
                diameter = row.dishDiameter().get()
                dishDiameterList.append(diameter)
    if verbose:
        print('%s'%', '.join(map(str, antList)))
    if (stations and diameters):
        return antList, stationList, dishDiameterList
    elif (stations):
        return antList, stationList
    elif (diameters):
        return antList, dishDiameterList
    else:
        return antList

def meanAirmassForScan(vis, scan, mymsmd=None, verbose=True):
    """
    Uses msmd, getRADecForSource, and computeAzElFromRADecMJD to compute airmass
    -Todd Hunter
    """
    if not os.path.exists(vis):
        print("Could not find measurement set: ", vis)
        return
    if mymsmd is None:
        mymsmd = msmdtool()
        mymsmd.open(vis)
        needToClose = True
    else:
        needToClose = False
    fieldID = mymsmd.fieldsforscan(scan, asnames=False)[0]
    if verbose:
        sourcename = mymsmd.fieldsforscan(scan, asnames=True)[0]
        print("Sourcename = %s, scan = %d, first field ID = %d" % (sourcename, scan, fieldID))
        print("Running au.getRADecForField('%s', %d)" % (vis,fieldID))
    raDec = getRADecForField(vis, fieldID, mymsmd=mymsmd)
    mytimes = mymsmd.timesforscan(scan)
    mytime0 = np.min(mytimes)
    mytime1 = np.max(mytimes)
    observatory = mymsmd.observatorynames()[0]
    azim,elev = computeAzElFromRADecMJD(raDec, mytime0/86400., observatory, degrees=True)
    airmass0 = elevationToAirmass(elev)
    azim,elev = computeAzElFromRADecMJD(raDec, mytime1/86400., observatory, degrees=True)
    airmass1 = elevationToAirmass(elev)
    airmass = np.mean([airmass0, airmass1])
    if needToClose:
        mymsmd.close()
    return airmass
    
def meanAirmassForSource(vis, sourcename, fast=True, verbose=False, mymsmd=None):
    """
    Uses msmd to convert sourcename to list of fields, then list of observed times.
    Then uses computeAzElFromRADecMJD to get a list of elevations, then elevationToAirmass.
    fast: if True, then use only the earliest and latest time and compute the mean of the
       two corresponding airmasses
    -Todd Hunter
    """
    if not os.path.exists(vis):
        print("Could not find measurement set: ", vis)
        return
    if mymsmd is None:
        mymsmd = msmdtool()
        mymsmd.open(vis)
        needToClose = True
    else:
        needToClose = False
    print("sourcename = ", sourcename)
    fieldIDs = mymsmd.fieldsforname(sourcename)
    raDec = getRADecForSource(vis, sourcename, mymsmd=mymsmd)
    if len(fieldIDs) == 0:
        print("No fields found for this source name")
        return
    alltimes = []
    for fieldID in fieldIDs:
        alltimes += list(mymsmd.timesforfield(fieldID))
    if needToClose:
        mymsmd.close()
    observatory = getObservatoryName(vis) # uses tbtool, not msmd
    if fast:
        mintime = np.min(alltimes)
        maxtime = np.max(alltimes)
        alltimes = [mintime,maxtime]
    airmass = []
    for mytime in alltimes:
        if verbose:
            print("Calling au.computeAzElFromRADecMJD('%s', %f, '%s', degrees=True)" % (raDec, mytime, observatory))
        azim,elev = computeAzElFromRADecMJD(raDec, mytime/86400., observatory, degrees=True)
        airmass.append(elevationToAirmass(elev))
    airmass = np.mean(airmass)
    return airmass

def getWeather(vis, scan='', antenna='0',verbose=False, vm=0, mymsmd='',
               debug=False, obsid=0, preferredStation='TB2,Central', 
               getSolarDirection=True):
    """
    Queries the WEATHER and ANTENNA tables of an .ms by scan number or
    list of scan numbers in order to return a dictionary.
    Inputs:
    * antenna: name string, ID string or integer ID
    * preferredStation: minimum match, i.e. 'TB2' or 'MeteoTB2', single value
          or a comma-delimited list, e.g. 'TB2,Central'
    Returns:
    * a dictionary of mean values of: angleToSun (deg),
      pressure (mb), temperature (C), humidity (%), dewpoint (C), windspeed (m/s), wind dir (deg),
      azimuth (deg), elevation (deg), solarangle (deg), solarelev (deg), solarazim (deg).
    * a list of science data timestamps in MJD seconds (not weather data times!)
    * zero, or the ValueMapping object
    If the sun is below the horizon, the solarangle return value is negated.
    If run in casa 4.4 or 4.5, and a concatenated measurement set is used, then the
       obsid must be specified for the desired scan, due to a change in msmd.  This
       behavior is fixed in casa 4.6.
    If run in casa < 4.1.0, this function needs to run ValueMapping, unless
    a ValueMapping object is passed via the vm argument. Otherwise it will
    run mymsmd.open, unless an msmd tool is passed via the mymsmd argument.
    The azimuth and elevation is found from the pointing table using the
    first antenna.  If the elevation is <= 0, subsequent antennas are tried.
    If the final antenna is still zero, then it uses au.computeAzElForScan().
    -- Todd Hunter
    """
    if (debug):
        print("Entered getWeather with vis,scan,antenna,preferredStation = ", vis, ",", scan, ",", antenna, ",", preferredStation)
    if (os.path.exists(vis) == False):
        print("au.getWeather(): Measurement set not found")
        return
    if (os.path.exists(vis+'/table.dat') == False):
        print("No table.dat.  This does not appear to be an ms.")
        return
    try:
        antennaNames = getAntennaNames(vis)
        if str(antenna).isdigit():
            antennaName = antennaNames[int(str(antenna))]
        else:
            antennaName = antenna
            try:
                antenna = getAntennaIndex(vis,antennaName)
            except:
                antennaName = string.upper(antenna)
                antenna = getAntennaIndex(vis,antennaName)
    except:
        print("Either the ANTENNA table does not exist or antenna %s does not exist" % (antenna))
        return([0,[],vm])
    mytb = createCasaTool(tbtool)
    try:
        mytb.open("%s/POINTING" % vis)
    except:
        print("POINTING table does not exist")
        return([0,0,vm])
    subtable = mytb.query("ANTENNA_ID == %s" % antenna)
    mytb.close()
    needToClose_mymsmd = False
    if (vm == 0 or vm==''):
        if (casaVersion < casaVersionWithMSMD):
            print("getWeather: Running ValueMapping... (this may take a minute)")
            vm = ValueMapping(vis)
        elif (mymsmd == ''):
            mymsmd = createCasaTool(msmdtool)
            mymsmd.open(vis)
            needToClose_mymsmd = True
    else:
        if (verbose):
            print("getWeather: Using current ValueMapping result")
    try:
        mytb.open("%s/OBSERVATION" % vis)
        observatory = mytb.getcell("TELESCOPE_NAME",0)
        mytb.close()
    except:
        print("OBSERVATION table does not exist, assuming observatory == ALMA")
        observatory = "ALMA"
    if (scan == ''):
        if (mymsmd != '' and casaVersion >= casaVersionWithMSMD):
            scan = callscannumbers(mymsmd)
        else:
            scan = vm.uniqueScans
    conditions = {}
    conditions['pressure']=conditions['temperature']=conditions['humidity']=conditions['dewpoint']=conditions['windspeed']=conditions['winddirection'] = 0
    conditions['scan'] = scan
    if (type(scan) == str):
        if (scan.find('~')>0):
            tokens = scan.split('~')
            scan = [int(k) for k in range(int(tokens[0]),int(tokens[1])+1)]
        else:
            scan = [int(k) for k in scan.split(',')]
    if (type(scan) == np.ndarray):
        scan = list(scan)
    if (type(scan) == list):
        myTimes = np.array([])
        for sc in scan:
            try:
                if (mymsmd != '' and casaVersion >= casaVersionWithMSMD):
                    if debug: print("1) Calling mymsmd.timesforscan(%d)" % (sc))
                    if (casaVersion >= '4.4' and casaVersion < '4.6'):
                        newTimes = mymsmd.timesforscan(sc, obsid=obsid)
                    else:
                        newTimes = mymsmd.timesforscan(sc)
                else:
                    if debug: print("1) Calling vm.getTimesForScan(%d)" % (sc))
                    newTimes = vm.getTimesForScan(sc)
            except:
                print("1) Error reading scan %d, is it in the data?" % (sc))
                if (needToClose_mymsmd): mymsmd.close()
                return([conditions,[],vm])
            myTimes = np.concatenate((myTimes,newTimes))
    elif (scan is not None):
        try:
            if (mymsmd != '' and casaVersion >= casaVersionWithMSMD):
                if debug: print("2) Calling mymsmd.timesforscan(%d)" % (scan))
                if (casaVersion >= '4.4' and casaVersion < '4.6'):
                    myTimes = mymsmd.timesforscan(scan, obsid=obsid)
                else:
                    myTimes = mymsmd.timesforscan(scan)
            else:
                if debug: print("2) Calling vm.getTimesForScan(%d)" % (scan))
                myTimes = vm.getTimesForScan(scan)
        except:
            print("2) Error reading scan %d, is it in the data?" % (scan))
            if (needToClose_mymsmd): mymsmd.close()
            return([conditions,[],vm])
    else:
        print("scan = ", scan)
        if (needToClose_mymsmd): mymsmd.close()
        return([conditions,[],vm])
    if (type(scan) == str):
        scan = [int(k) for k in scan.split(',')]
    if (type(scan) == list):
        listscan = ""
        listfield = []
        for sc in scan:
            if debug: print("Processing scan ", sc)
            if (mymsmd != '' and casaVersion >= casaVersionWithMSMD):
                if (casaVersion >= '4.4' and casaVersion < '4.6'):
                    listfield.append(mymsmd.fieldsforscan(sc,obsid=obsid))
                else:
                    listfield.append(mymsmd.fieldsforscan(sc))
            else:
                listfield.append(vm.getFieldsForScan(sc))
            listscan += "%d" % sc
            if (sc != scan[-1]):
                listscan += ","
        if debug: print("listfield = ", listfield)
        listfields = np.unique(listfield[0])
        listfield = ""
        for field in listfields:
            listfield += "%s" % field
            if (field != listfields[-1]):
                listfield += ","
    else:
        listscan = str(scan)
        if (mymsmd != '' and casaVersion >= casaVersionWithMSMD):
            if (casaVersion >= '4.4' and casaVersion < '4.6'):
                listfield = mymsmd.fieldsforscan(scan, obsid=obsid)
            else:
                listfield = mymsmd.fieldsforscan(scan)
        else:
            listfield = vm.getFieldsForScan(scan)
    if getSolarDirection:
        [az,el] = ComputeSolarAzEl(myTimes[0], observatory)
        [az2,el2] = ComputeSolarAzEl(myTimes[-1], observatory)
        azsun = np.mean([az,az2])
        elsun = np.mean([el,el2])
    direction = subtable.getcol("DIRECTION")
    azeltime = subtable.getcol("TIME")
    subtable.close()
    telescopeName = getObservatoryName(vis)
    if (len(direction) > 0 and telescopeName.find('VLA') < 0 and telescopeName.find('NRO') < 0):
        azimuth = direction[0][0]*180.0/math.pi  # a list of values
        elevation = direction[1][0]*180.0/math.pi # a list of values
        if debug:
            print("len(azimuth) = %d, len(myTimes)=%d" % (len(azimuth), len(myTimes)))
            print("azimuth = ", azimuth)
            print("elevation = ", elevation)
        npat = np.array(azeltime)
        matches = np.where(npat>=myTimes[0])[0]
        matches2 = np.where(npat<=myTimes[-1])[0]
        if (len(matches2) > 0 and len(matches) > 0):
            if debug: print("azel time matches[0]=%d, matches2[-1]=%d" % (matches[0],matches[-1]))
            matchingIndices = range(matches[0],matches2[-1]+1)
        else:
            matchingIndices = []
        if (len(matchingIndices) > 0):
            if debug: print("azel time matches[0]=%d, matches2[-1]=%d" % (matches[0],matches[-1]))
            conditions['azimuth'] = np.median(azimuth[matches[0]:matches2[-1]+1])
            conditions['elevation'] = np.median(elevation[matches[0]:matches2[-1]+1])
            if debug: print("elevation = ", conditions['elevation'])
        elif (len(matches) > 0):
            conditions['azimuth'] = np.median(azimuth[matches[0]])
            conditions['elevation'] = np.median(elevation[matches[0]])
        else:
            conditions['azimuth'] = np.median(azimuth)
            conditions['elevation'] = np.median(elevation)
        conditions['airmass'] = elevationToAirmass(conditions['elevation'])
        while (antennaName != antennaNames[-1] and (np.abs(conditions['elevation']) < 0.001 or conditions['elevation'] != conditions['elevation'])):
            # Try the next antenna (needed for uid___A002_Xad565b_X20c4)
            nextAntenna = int(antenna)+1
            nextAntennaName = antennaNames[nextAntenna]
            print("Requested antenna = %s shows elevation at/near zero (%f). Trying next antenna = %s." % (antennaName,conditions['elevation'],nextAntennaName))
            antenna = str(nextAntenna)
            antennaName = nextAntennaName
            mytb.open(vis+'/POINTING')
            subtable = mytb.query("ANTENNA_ID == %s" % antenna)
            direction = subtable.getcol("DIRECTION")
            azeltime = subtable.getcol("TIME")
            subtable.close()
            azimuth = np.degrees(direction[0][0])
            elevation = np.degrees(direction[1][0])
            npat = np.array(azeltime)
            matches = np.where(npat >= myTimes[0])[0]
            matches2 = np.where(npat <= myTimes[-1])[0]
            if debug: print("matches[0]=%d, matches2[-1]=%d" % (matches[0],matches[-1]))
            conditions['azimuth'] = np.median(azimuth[matches[0]:matches2[-1]+1])
            conditions['elevation'] = np.median(elevation[matches[0]:matches2[-1]+1])
            print("mean Elevation = %f deg" % (conditions['elevation']))
            mytb.close()
        if conditions['elevation'] <= 0.0:
            (azimuth,elevation) = computeAzElForScan(vis, scan, mymsmd=mymsmd)
            conditions['azimuth'] = azimuth
            conditions['elevation'] = elevation
            print("Elevation of all antennas is zero.  Using au.computeAzElForScan() = %f" % (elevation))
        if debug:
            print("%d matches after %f, %d matches before %f" % (len(matches), myTimes[0], len(matches2), myTimes[-1]))
            print("%d matchingIndices" % (len(matchingIndices)))
        if getSolarDirection:
            conditions['solarangle'] = angularSeparation(azsun,elsun,conditions['azimuth'],conditions['elevation'])
            conditions['solarelev'] = elsun
            conditions['solarazim'] = azsun
        else:
            conditions['solarangle'] = 0
            conditions['solarelev'] = 0
            conditions['solarazim'] = 0
        if (verbose):
            print("Used antenna = %s to retrieve mean azimuth and elevation" % (antennaName))
        if getSolarDirection:
            if (verbose):
                print("Separation from sun = %f deg" % (abs(conditions['solarangle'])))
            if (elsun<0):
                conditions['solarangle'] = -conditions['solarangle']
                if (verbose):
                    print("Sun is below horizon (elev=%.1f deg)" % (elsun))
            else:
                if (verbose):
                    print("Sun is above horizon (elev=%.1f deg)" % (elsun))
        if (verbose):
            print("Average azimuth = %.2f, elevation = %.2f degrees" % (conditions['azimuth'],conditions['elevation']))
    else:
      if (verbose):
          print("The POINTING table is either blank or does not contain Azim/Elev.")
      if (type(scan) in [int, np.int32, np.int64]):
          # compute Az/El for this scan
          if (mymsmd != '' and casaVersion >= casaVersionWithMSMD):
              if (casaVersion >= '4.4' and casaVersion < '4.6'):
                  myfieldId = mymsmd.fieldsforscan(scan,obsid=obsid)
              else:
                  myfieldId = mymsmd.fieldsforscan(scan)
              if (type(myfieldId) == list or type(myfieldId) == type(np.ndarray(0))):
                  myfieldId = myfieldId[0]
              fieldName = mymsmd.namesforfields(myfieldId)
              if (type(fieldName) == list):
                  fieldName = fieldName[0]
          else:
              fieldName = vm.getFieldsForScan(scan)
              if (type(fieldName) == list):
                  fieldName = fieldName[0]
              myfieldId = vm.getFieldIdsForFieldName(fieldName)
              if (type(myfieldId) == list or type(myfieldId) == type(np.ndarray(0))):
                  # If the same field name has two IDs (this happens in EVLA data)
                  myfieldId = myfieldId[0]
  #            print "type(myfieldId) = ", type(myfieldId)
          if (mymsmd != '' and casaVersion >= casaVersionWithMSMD):
              if (casaVersion >= '4.4' and casaVersion < '4.6'):
                  myscantime = np.mean(mymsmd.timesforscan(scan,obsid=obsid))
              else:
                  myscantime = np.mean(mymsmd.timesforscan(scan))
          else:
              myscantime = np.mean(vm.getTimesForScans(scan))
          mydirection = getRADecForField(vis, myfieldId, usemstool=True)
          if (len(telescopeName) < 1):
              telescopeName = 'ALMA'
          if debug:
              print("Running computeAzElFromRADecMJD(%s, %f, %s)" % (str(mydirection),myscantime/86400.,telescopeName))
          myazel = computeAzElFromRADecMJD(mydirection, myscantime/86400., telescopeName, verbose=False)
          if (debug): print("myazel = ", myazel)
          conditions['elevation'] = np.degrees(myazel[1])
          conditions['airmass'] = elevationToAirmass(conditions['elevation'])
          conditions['azimuth'] = np.degrees(myazel[0])
          if getSolarDirection:
              conditions['solarangle'] = angularSeparation(azsun,elsun,conditions['azimuth'],conditions['elevation'])
              conditions['solarelev'] = elsun
              conditions['solarazim'] = azsun
              if (verbose):
                  print("Separation from sun = %f deg" % (abs(conditions['solarangle'])))
              if (elsun<0):
                  conditions['solarangle'] = -conditions['solarangle']
                  if (verbose):
                      print("Sun is below horizon (elev=%.1f deg)" % (elsun))
              else:
                  if (verbose):
                      print("Sun is above horizon (elev=%.1f deg)" % (elsun))
          else:
              conditions['solarangle'] = 0
              conditions['solarelev'] = 0
              conditions['solarazim'] = 0
          if (verbose):
              print("Average azimuth = %.2f, elevation = %.2f degrees" % (conditions['azimuth'],conditions['elevation']))
      elif (type(scan) == list):
          myaz = []
          myel = []
          if (verbose):
              print("Scans to loop over = ", scan)
          for s in scan:
              if (mymsmd != '' and casaVersion >= casaVersionWithMSMD):
                  if (casaVersion >= '4.4' and casaVersion < '4.6'):
                      fieldName = mymsmd.fieldsforscan(s,obsid=obsid)
                  else:
                      fieldName = mymsmd.fieldsforscan(s)
              else:
                  fieldName = vm.getFieldsForScan(s)
              if (type(fieldName) == list or type(fieldName)==np.ndarray):
                  # take only the first pointing in the mosaic
                  fieldName = fieldName[0]
              if (mymsmd != '' and casaVersion >= casaVersionWithMSMD):
                  if (type(fieldName) in [int, np.int32, np.int64]):
                      myfieldId = fieldName
                  else:
                      myfieldId = mymsmd.fieldsforname(fieldName)
              else:
                  myfieldId = vm.getFieldIdsForFieldName(fieldName)
              if (type(myfieldId) == list or type(myfieldId)==np.ndarray):
                  # If the same field name has two IDs (this happens in EVLA data)
                  myfieldId = myfieldId[0]
              if (mymsmd != '' and casaVersion >= casaVersionWithMSMD):
                  if (casaVersion >= '4.4' and casaVersion < '4.6'):
                      myscantime = np.mean(mymsmd.timesforscan(s,obsid=obsid))
                  else:
                      myscantime = np.mean(mymsmd.timesforscan(s))
              else:
                  myscantime = np.mean(vm.getTimesForScans(s))
              mydirection = getRADecForField(vis, myfieldId, usemstool=True)
              telescopeName = getObservatoryName(vis)
              if (len(telescopeName) < 1):
                  telescopeName = 'ALMA'
              myazel = computeAzElFromRADecMJD(mydirection, myscantime/86400., telescopeName, verbose=False)
              myaz.append(myazel[0]*180/math.pi)
              myel.append(myazel[1]*180/math.pi)
          if debug: print("myel = ", myel)
          conditions['azimuth'] = np.median(myaz)
          conditions['elevation'] = np.median(myel)
          conditions['airmass'] = elevationToAirmass(np.median(myel))
          conditions['solarangle'] = angularSeparation(azsun,elsun,conditions['azimuth'],conditions['elevation'])
          conditions['solarelev'] = elsun
          conditions['solarazim'] = azsun
          if (verbose):
              print("*Using antenna = %s to retrieve mean azimuth and elevation" % (antennaName))
              print("Separation from sun = %f deg" % (abs(conditions['solarangle'])))
          if (elsun<0):
              conditions['solarangle'] = -conditions['solarangle']
              if (verbose):
                  print("Sun is below horizon (elev=%.1f deg)" % (elsun))
          else:
              if (verbose):
                  print("Sun is above horizon (elev=%.1f deg)" % (elsun))
          if (verbose):
              print("Average azimuth = %.2f, elevation = %.2f degrees" % (conditions['azimuth'],conditions['elevation']))
          
    # now, get the weather
    if not os.path.exists('%s/WEATHER' % vis):
        print("There is no WEATHER table for this ms.")
        if (needToClose_mymsmd): mymsmd.close()
        return([conditions,myTimes,vm])
    try:
        mytb.open("%s/WEATHER" % vis)
    except:
        print("Could not open the WEATHER table for this ms.")
        if (needToClose_mymsmd): mymsmd.close()
        return([conditions,myTimes,vm])
    if (True):
        mjdsec = mytb.getcol('TIME')
        indices = np.argsort(mjdsec)
        mjd = mjdsec/86400.
        pressureRaw = mytb.getcol('PRESSURE')
        pressureUnit = mytb.getcolkeywords('PRESSURE').get('QuantumUnits', ['mbar'])[0] # CAS-12844
        myqa = createCasaTool(qatool)
        pressure = myqa.convert(myqa.quantity(pressureRaw, pressureUnit), 'mbar')['value'] # CAS-12844
        if np.median(pressure) < 100:
            pressure = pressureRaw     ### added 2024Aug
            casalog.post("Ignoring pressure units '%s' because the value implied would be less than 100 mbar."%(pressureUnit))         ### added 2024Aug
        
        myqa.done()
        relativeHumidity = mytb.getcol('REL_HUMIDITY')
        temperature = mytb.getcol('TEMPERATURE')
        if (np.median(temperature) > 100):
            # it must be in units of Kelvin, so convert to C
            temperature = kelvinToCelsius(temperature)
        if 'DEW_POINT' in mytb.colnames():
            dewPoint = mytb.getcol('DEW_POINT')
            if (np.median(dewPoint) > 100):
                # must be in units of Kelvin, so convert to C
                dewPoint = kelvinToCelsius(dewPoint)
            if (np.median(dewPoint) == 0):
                # assume it is not measured and use NOAA formula to compute from humidity:
                dewPoint = ComputeDewPointCFromRHAndTempC(relativeHumidity, temperature)
        else:
            dewPoint = None  # Nobeyama measurement sets do not have a dewpoint column
        sinWindDirection = np.sin(mytb.getcol('WIND_DIRECTION'))
        cosWindDirection = np.cos(mytb.getcol('WIND_DIRECTION'))
        windSpeed = mytb.getcol('WIND_SPEED')
        if 'NS_WX_STATION_ID' in mytb.colnames():
            stations = mytb.getcol('NS_WX_STATION_ID')
        else:
            stations = None
        mytb.close()

        # put values into time order (they mostly are, but there can be small differences)
        mjdsec = np.array(mjdsec)[indices]
        pressure = np.array(pressure)[indices]
        relativeHumidity = np.array(relativeHumidity)[indices]
        temperature = np.array(temperature)[indices]
        if dewPoint is not None:
            dewPoint = np.array(dewPoint)[indices]
        windSpeed = np.array(windSpeed)[indices]
        sinWindDirection = np.array(sinWindDirection)[indices]
        cosWindDirection = np.array(cosWindDirection)[indices]
        if stations is not None:
            stations = np.array(stations)[indices]

        if preferredStation not in ['', None]:
            if type(preferredStation) in [str, np.bytes_]:
                preferredStations = preferredStation.split(',')
            else:
                preferredStations = preferredStation
            if debug: print("Calling getWeatherStationNames('%s')" % (vis))
            wsdict = getWeatherStationNames(vis)
            if wsdict is not None:
                preferredStationID = None
                for pStation in preferredStations:
                    if preferredStationID is None:
                        for w in list(wsdict.keys()):
                            if wsdict[w].find(pStation) >= 0:
                                preferredStationID = w
                                preferredStation = wsdict[w]
                if preferredStationID is None:
                    print("Preferred stations (%s) not found in this dataset. Using all stations: %s" % (preferredStations, list(wsdict.keys())))
                else:
                    if verbose:
                        print("ID of preferred station (%s) is %d" % (preferredStation, preferredStationID))
                    indices = np.where(stations == preferredStationID)
                    mjdsec = np.array(mjdsec)[indices]
                    pressure = np.array(pressure)[indices]
                    relativeHumidity = np.array(relativeHumidity)[indices]
                    temperature = np.array(temperature)[indices]
                    dewPoint = np.array(dewPoint)[indices]
                    windSpeed = np.array(windSpeed)[indices]
                    sinWindDirection = np.array(sinWindDirection)[indices]
                    cosWindDirection = np.array(cosWindDirection)[indices]
                    stations = np.array(stations)[indices]

        # find the overlap of weather measurement times and scan times
        matches = np.where(mjdsec>=np.min(myTimes))[0]
        matches2 = np.where(mjdsec<=np.max(myTimes))[0]
        if debug:
            print("len(matches)=%d, len(matches2)=%d, len(myTimes)=%d, len(mjdsec)=%d" % (len(matches), len(matches2), len(myTimes), len(mjdsec)))
            print("min-max time: %s - %s" % (mjdsecToUTHMS(np.min(myTimes)), mjdsecToUTHMS(np.max(myTimes))))
        noWeatherData = False
        if (len(matches)>0 and len(matches2) > 0):
            # average the weather points enclosed by the scan time range
            selectedValues = range(matches[0], matches2[-1]+1)
            if debug:
                print("--- matches = ", matches)
                print("--- matches2 = ", matches2)
                print("--- selectedValues = ", selectedValues)
            if (len(selectedValues) == 0):
                # there was a either gap in the weather data, or an incredibly short scan duration
                if debug:
                    print("----  Finding the nearest weather value --------------------------- ")
                selectedValues = findClosestTime(mjdsec, myTimes[0])
            else:
                if debug: 
                    print("--- Taking the %d values within the scan time range of %.1f seconds -----" % (len(selectedValues),np.max(myTimes)-np.min(myTimes)))
        elif (len(matches)>0):
            # all points are greater than myTime, so take the first one
            if debug: print("--- Taking the closest value to the scan time range (after it) -----")
            selectedValues = matches[0]
        elif (len(matches2)>0):
            # all points are less than myTime, so take the last one
            if debug: print("--- Taking the closest value to the scan time range (before it) -----")
            selectedValues = matches2[-1]
        else:
            # table has no weather data!
            noWeatherData = True
        if (noWeatherData):
            conditions['pressure'] = 563.0
            conditions['temperature'] = 0  # Celsius is expected
            conditions['humidity'] = 20.0
            conditions['dewpoint'] = -20.0
            conditions['windspeed'] = 0
            conditions['winddirection'] = 0
            print("WARNING: No weather data found in the WEATHER table!")
        else:
            if (type(selectedValues) in [np.int64, np.int32, int]):
                conditions['readings'] = 1
                if (verbose):
                    print("selectedValues=%d, myTimes[0]=%.0f, len(matches)=%d, len(matches2)=%d" % (selectedValues,
                                                 myTimes[0], len(matches), len(matches2)))
                    if (len(matches) > 0):
                        print("matches[0]=%f, matches[-1]=%f" % (matches[0], matches[-1]))
                    if (len(matches2) > 0):
                        print("matches2[0]=%f, matches2[-1]=%d" % (matches2[0], matches2[-1]))
            else:
                conditions['readings'] = len(selectedValues)
            conditions['pressure'] = np.median(pressure[selectedValues])
            if (conditions['pressure'] != conditions['pressure']):
                # A nan value got through, due to no selected values (should be impossible)"
                if (verbose):
                    print(">>>>>>>>>>>>>>>>>>>>>>>>  selectedValues = ", selectedValues)
                    print("len(matches)=%d, len(matches2)=%d" % (len(matches), len(matches2)))
                    print("matches[0]=%f, matches[-1]=%f, matches2[0]=%f, matches2[-1]=%d" % (matches[0], matches[-1], matches2[0], matches2[-1]))
            conditions['temperature'] = np.median(temperature[selectedValues])
            conditions['humidity'] = np.median(relativeHumidity[selectedValues])
            if dewPoint is not None:
                conditions['dewpoint'] = np.median(dewPoint[selectedValues])
            conditions['windspeed'] = np.median(windSpeed[selectedValues])
            conditions['winddirection'] = (180./math.pi)*np.arctan2(np.median(sinWindDirection[selectedValues]),np.median(cosWindDirection[selectedValues]))
            if (conditions['winddirection'] < 0):
                conditions['winddirection'] += 360
            if (verbose and noWeatherData==False):
                print("Median weather values for scan %s (field %s)" % (listscan,listfield))
                print("  Pressure = %.2f mb" % (conditions['pressure']))
                print("  Temperature = %.2f C" % (conditions['temperature']))
                if dewPoint is not None:
                    print("  Dew point = %.2f C" % (conditions['dewpoint']))
                print("  Relative Humidity = %.2f %%" % (conditions['humidity']))
                print("  Wind speed = %.2f m/s" % (conditions['windspeed']))
                print("  Wind direction = %.2f deg" % (conditions['winddirection']))

    if (needToClose_mymsmd): mymsmd.close()
    return([conditions,myTimes,vm])
    # end of getWeather   forscan   np.mean

def correlatorDatarate(antennas, Nchannels=14880*80/2, nbytes=2, Npols=2, 
                       visint=3.072, Napc=1, method='memo', verbose=True):
    """
    Computes expected ALMA data rate in terms of the value on a correlator node
    which scales as N_antennas ** 2, rather than N_baselines+N_antennas.
    See also asdmDatarate.
    nbytes: number of bytes for real integer and for imaginary integer of the
        cross-correlation data, note that autocorrelation data is assumbed to 
        be 4 bytes (relevant for method='memo')
    visint: integration time in seconds (should be a multiple of 0.128 for ATAC)
    Nchannels: per polarization
    Napc: number of WVR streams (1=offline correction only)
    method: 'memo' for Estimated data rates for the Wideband Sensitivity Upgrade
         or 'java' for validateBasebandDataRate
    verbose: if True, prints coefficient before scaling by Nchannels/visint
        where the *2 is for real and imaginary values of the visibility
    Returns: value in MB/sec of Nchannels*coefficient/visint, 
        where in 'java' method: 1 MB = 1024**2 bytes (to match bbDataRate 
            computation in validateBasebandDataRate function (see PRTSIR-879) in
    ICD/CORR/Validator/src/alma/correlatorSrc/CorrConfigValidator/CorrConfigValidator.java
        while in 'memo' method: 1 MB = 1000**2 bytes
    -Todd Hunter
    """
    if method == 'java':
        coefficient = antennas**2*Napc*Npols*2*nbytes/(1024*1024.)
        if verbose:
            print("Value scales as N_antennas**2 (according to code in CorrConfigValidator.java)")
        print("coefficient = %f MB/s" % (coefficient))
    elif method == 'memo':
        coefficient = (2*nbytes*Napc*antennas*(antennas-1)/2 + 4*antennas)*Npols*1e-6
    else:
        print("method must be either memo or java")
        return
    print("coefficient = %f MB/s * Nchannels/visint" % (coefficient))
    return Nchannels*coefficient/visint

def getIntegrationTimeFromASDM(asdm, useMinidom=False):
    """
    Reads all integration times from Main.xml and returns the maximum
    value, which will usually be the science integration time.
    useMinidom: if True, then parse the .xml file even if the ASDM python
                bindings are available
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    -Todd Hunter
    """
    if not os.path.exists(asdm):
        print("Could not find ASDM: ", asdm)
        return
    if not asdmLibraryAvailable or useMinidom:
        import au_noASDMLibrary
        integrationTimes = au_noASDMLibrary.getIntegrationTimeFromASDM_minidom(asdm)
    else:
        a = ASDM()
        parser = ASDMParseOptions()
        parser.asALMA()
        parser.loadTablesOnDemand(True)
        a.setFromFile(asdm,parser)
        mainTable = a.mainTable().get()
        integrationTimes = []
        for row in mainTable:
            n = row.numIntegration()
            interval = row.interval().get() * 1e-9 # convert nanosec to sec
            integrationTimes.append(interval / n)
    return np.max(integrationTimes)

def dataratesForASDM(asdm, nbytes=2, verbose=False, antennas=None):
    """
    Reads number of antennas, channels and integration time from ASDM and
    sends it to asdmDatarate and correlatorDataRate.
    nbytes: number of bytes for real part of visibility
    """
    if not os.path.exists(asdm):
        print("Could not find ASDM: ", asdm)
        return
    if antennas is None:
        antennas = len(readAntennasFromASDM(asdm, verbose=False))
        print("Found %d antennas" % (antennas))
    else:
        print("Using %d antennas (regardless of what is in the data)" % (antennas))
    channels = getNumChanFromASDM(asdm,scienceOnly=True)
    channels = sum(channels.values())
    print("Found %d channels" % (channels))
    napc = sum(wvrdata(asdm))
    mydict = getPolarizationsFromASDM(asdm)
    pols = max([mydict[i]['numCorr'] for i in mydict])
    print("Found %d pols" % (pols))
    visint = getIntegrationTimeFromASDM(asdm)
    print("Found integration time = %s seconds" % (visint))
    totalTime = np.diff(getObservationMJDSecRangeFromASDM(asdm))[0]
    asdm = asdmDatarate(antennas, channels, nbytes, pols, visint, napc, verbose)
    correlator = correlatorDatarate(antennas, channels, nbytes, pols, visint, verbose)
    print("Total observing time = %s seconds" % (totalTime))
    volume = asdm*totalTime*0.001
    print("Data rate in terms of ASDM size: %f MB/s (volume=%.2f GB)" % (asdm,volume))
    volume = correlator*totalTime*0.001
    print("Data rate in terms of correlator node: %f MB/s (volume=%.2f GB)" % (correlator,volume))

def asdmDatarate(antennas, channels=4*3840, nbytes=2, pols=2, visint=2.016, napc=2, verbose=True):
    """
    Computes expected ALMA data rate in terms of the size of the ASDM, which
    scales as N_baselines+N_antennas, rather than N_antennas**2.
    See also correlatorDatarate.
    nbytes: number of bytes for real integer and for imaginary integer
    napc: number of atmospheric phase correction streams (1 or 2)
    visint: integration time in seconds
    Prints coefficient = (baselines+antennas)*pols*2*nbytes
        where the +antennas is for the autocorrelations and the *2 is
        for real and imaginary values of the visibility
    Returns: value in MB, where 1 MB = 1024**2 bytes
    -Todd Hunter
    """
    baselines = antennas*(antennas-1)/2.
    coefficient = (baselines+antennas)*napc*pols*2*nbytes/(1024*1024.)
    if verbose:
        print("Value scales as N_baselines (crosscorr) + N_antennas (autocorr).")
        print("coefficient = %f MB/s" % (coefficient))
    return channels*coefficient/visint

def asdmbitsHistograms(mydict, projectCodes=['2013','2015','2016','E2E5'],
                       bins=np.arange(17.5,105,5), plotfile='', xlim=[16,104]):
    """
    Calls asdmbitsHistogram for each set of cycles to produce the plot in ICT-6114.
    mydict: dictionary produced by au.asdmbits
    bins, xlim: passed to asdmbitsHistogram
    plotfile: name of montaged png to produce
    -Todd Hunter
    """
    pngs = []
    for projectCode in projectCodes:
        png = projectCode+'.png'
        asdmbitsHistogram(mydict, bins, png, projectCode)
        pngs.append(png)
    montagePngs(pngs,geometry='auto+10',outname=plotfile,background='white')

def asdmbitsHistogram(mydict, bins=np.arange(17.5,105,5), plotfile='', 
                      projectCode='',xlim=[16,104]):
    """
    Plots a histogram of a dictionary returned by asdmbits.
    projectCode: only show results for project codes containing this string
    bin: integer or list
    -Todd Hunter
    """
    bit16 = []
    projects = []
    for project in mydict:
        for asdm in mydict[project]:
            if projectCode == '' or project.find(projectCode) >= 0:
                print(mydict[project])
                bit16.append(mydict[project][asdm][0])
                projects.append(project)
    projects = np.unique(projects)
    if len(bit16) < 1:
        print("No matching datasets found.")
        return
    pb.clf()
    pb.hist(bit16,bins)
    pb.xlabel('Percent of values that are 16 bit')
    pb.ylabel('Number of occurrences')
    pb.title('%d ASDMs from %d projects in %s' % (len(bit16),len(projects),projectCode))
    pb.xlim(xlim)
    if plotfile != '':
        if plotfile == True:
            if projectCode == '':
                plotfile = 'asdmbits.png'
            else:
                plotfile = 'asdmbits_%s.png' % (projectCode)
                plotfile = plotfile.replace('..','.')
        pb.savefig(plotfile)

def asdmbits(asdm, verbose=True):
    """
    Searches each ASDMBinary file and tabulates how many
    integrations containing CROSS data are 16 bit vs. 32 bit.
    asdm: single ASDM or a python list, or a string with a wildcard
    Returns: 
    * if single ASDM: 2 percentages: 16 bit and 32 bit
    * if multi ASDM: a dictionary keyed by project code, then asdm name 
          with values being list of 2 percentages: 16 bit and 32 bit
    -Todd Hunter
    """
    if type(asdm) == str:
        if (asdm.find('*')>=0):
            asdms = sorted(glob.glob(asdm))
        else:
            asdms = asdm.split(',')
    else:
        asdms = asdm
    asdms = [i.rstrip('/') for i in asdms]
    mydict = {}
    print("Operating on %d ASDMs" % (len(asdms)))
    project = ''
    for asdm in asdms:
        if (not os.path.exists(asdm)):
            print("Could not find asdm: ", asdm)
            continue
        asdmBasename = os.path.basename(asdm)
        print("Operating on %s" % (asdmBasename))
        if (asdmBasename.find('201') == 0 or asdmBasename.find('E2E') == 0):
            project = asdm.split('/')[0]
            if project not in mydict:
                mydict[project] = {}
        if not os.path.exists(asdm+'/ASDMBinary'):
            print("This is not an ASDM: ", asdm)
            continue
        uidlist = glob.glob(asdm+'/ASDMBinary/*')
        i32 = 0
        i16 = 0
        i32size = 0
        i16size = 0
        fast = False  # this is an inaccurate approach
        for i,uid in enumerate(uidlist):
            if casaVersion >= '5.9.9':
                f = open(uid, 'r', encoding='latin-1')
            else:
                f = open(uid, 'r')
            if fast:
                line = f.read(3000)
                f.close()
                if (line.find('CROSS')>0):
                    if (line.find('INT32')>0):
                        i32 += 1
                        i32size += os.path.getsize(uid)
                    elif (line.find('INT16')>0):
                        i16 += 1
                        i16size += os.path.getsize(uid)
            else:
                lines = f.readlines()
                if verbose:
                    if ((i+1)%100 == 0):
                        print("Working on %d of %d" % (i+1,len(uidlist)))
                f.close()
                for line in lines:
                    loc = line.find('INT')
                    if (loc > 0):
                        if (line[loc:].find('INT16')>=0):
                            i16 += 1
                        elif (line[loc:].find('INT32')>=0):
                            i32 += 1
        if fast:
            print("%d/%d BDFs are 16 bits" % (i16,i16+i32))
            print("%d/%d BDFs are 32 bits" % (i32,i16+i32))
        else:
            print("%d/%d integrations are 16 bits (%.1f%%)" % (i16,i16+i32,100.*i16/(i16+i32)))
            print("%d/%d integrations are 32 bits (%.1f%%)" % (i32,i16+i32,100.*i32/(i16+i32)))
        if (fast):
            totsize = i16size+i32size
            print("In terms of total size, %.1f%% is 16-bit, %.1f%% is 32-bit." % (i16size*100./totsize, i32size*100./totsize))
            print("But this assumes the integer type is the same within a BDF, but it may not be.")
        if project in list(mydict.keys()):
            mydict[project][asdmBasename] = [100.*i16/(i16+i32), 100.*i32/(i16+i32)]
        else:
            mydict[asdm] = [100.*i16/(i16+i32), 100.*i32/(i16+i32)]
        print("mydict = ", mydict)
    if len(asdms) == 1:
        return mydict[asdms[0]]
    else:
        return mydict

def correlationBits(vis, spw='', avoidExtraWVRSpws=True, intent='OBSERVE_TARGET#ON_SOURCE', returnDict=True):
    """
    Reads the SDM_CORR_BIT column of a measurement set using the tb tool and returns 
    a list of values (typically one of: 'UNKNOWN', 'BITS_2x2', 'BITS_3x3', 'BITS_4x4')
    corresponding to the spw order.  Values are populated in the SpectralWindow.xml
    table of ALMA data beginning with ONLINE-2021MAR.
    spw:  if blank, then return the full list, if an int then return a scalar; 
          if a list, then return a limited list
    avoidExtraWVRSpws: relevant only if spw==''; 
          considers only spws returned by msmd.almaspws(True,True,True,True,True)
    intent: relevant only if spw=='';  limit spws to this intent
    Returns: a dictionary keyed by spw ID
    -Todd Hunter
    """
    if not os.path.exists(vis):
        print("Cannot find measurement set.")
        return
    mytb = createCasaTool(tbtool)
    mytb.open(os.path.join(vis,'SPECTRAL_WINDOW'))
    if 'SDM_CORR_BIT' not in mytb.colnames():
        print("The SDM_CORR_BIT column does not exist in this ms.")
        mytb.close()
        return
    bits = mytb.getcol('SDM_CORR_BIT')
    mytb.close()
    if spw == '':
        if avoidExtraWVRSpws:
            mymsmd = createCasaTool(msmdtool)
            mymsmd.open(vis)
            spw = callalmaspws(mymsmd,True,True,True,True,True)
            if intent != '':
                myspw = getScienceSpws(vis, mymsmd=mymsmd, returnString=False)
                spw = np.intersect1d(spw,myspw)
            mymsmd.close()
        else:
            return list(bits)
    elif spw == 'science':
        spw = getScienceSpws(vis, returnString=False)
    elif type(spw) in [int, np.int32, np.int64]:
        return list(bits[spw])
    elif type(spw) in [str, np.bytes_]:
        spw = [int(i) for i in spw.split(',')]
    if returnDict:
        mydict = {}
        for myspw in spw:
            mydict[myspw] = bits[myspw]
        return mydict
    else:
        return list(bits[spw])

def azelSeparation(vis, intent1='OBSERVE_TARGET', intent2='CALIBRATE_PHASE', 
                   field1=None, field2=None):
    """
    Computes the azim/elev separation between scans of two intents.
    -Todd Hunter
    """
    if not os.path.exists(vis):
        print("Cannot find measurement set.")
        return
    mymsmd = createCasaTool(msmdtool)
    mymsmd.open(vis)
    if intent1 is not None and intent2 is not None:
        intent1 = '*' + intent1 + '*'
        intent2 = '*' + intent2 + '*'
        scans = list(mymsmd.scansforintent(intent1))
        scans += list(mymsmd.scansforintent(intent2))
    elif field1 is not None and field2 is not None:
        scans = list(mymsmd.scansforfield(field1))
        scans += list(mymsmd.scansforfield(field2))
    else:
        print("You must specify intent1 and intent2, or field1 and field2.")
        mymsmd.close()
        return
    scans = sorted(scans)
    az0, el0 = listazel(vis, scan=scans[0], mymsmd=mymsmd, verbose=False)
    # timesforscans fails for np.int32 - CAS-10956
    times = mymsmd.timesforscans(int(scans[0]))
    t0 = np.mean(times)
    for i,scan in enumerate(scans[1:]):
        az, el = listazel(vis, scan=scan, mymsmd=mymsmd, verbose=False)
        t = np.mean(mymsmd.timesforscans(int(scan)))
        azdiff = (az-az0)*np.cos(np.radians(el))
        eldiff = el-el0
        print("Scan %3d-%3d: deltaAzim=%+6.2f,  deltaElev=%+5.2f deg  deltaTime=%.2f minutes" % (scans[i],scans[i+1],azdiff,eldiff,(t-t0)/60.))
        az0 = az
        el0 = el
        t0 = t
    mymsmd.close()

def listazel(vis, scan=None, antenna='0', vm=0, verbose=True, value='mean', 
             obsid=0, mymsmd=''):
    """
    Extracts the mean, min, or max azimuth and elevation for the specified 
    'scan' in the specified ms (whose name is passed in by the vis argument)
    from the POINTING table.  Note: this does not work for VLA data because the 
    POINTING table is not populated!  For VLA, you can use au.computeAzElForMS.
    scan: can be a single scan or a list, as in [1,2,3], or in '1,2,3'
       If it is not specified, then all scans are used
    antenna: can be either the antenna number or its name.
    value: 'mean', 'min', 'median', or 'max' for single values, 
        or 'all' for a list of each
    This function uses msmd (or ValueMapping if casa < 4.1.0).
    obsid: only used for casa versions 4.4 and 4.5 because the forscan methods of 
           msmd required obsid if multiple obsids were present in the data
    Returns:
    selected statistical value for [azimuth, elevation] in degrees
    returnDifferences: if True, then also statistical value of the 
                       per-scan differences
    -- Todd Hunter
    """
    if (not os.path.exists(vis+'/POINTING')):
        print("POINTING table does not exist")
        return
    try:
        if str(antenna).isdigit():
            antennaName = getAntennaNames(vis)[int(str(antenna))]
        else:
            try:
                antenna = getAntennaIndex(vis,antennaName)
            except:
                antennaName = string.upper(antenna)
                antenna = getAntennaIndex(vis,antennaName)
                if (antenna == -1): return([0,0])
    except:
        print("Antenna %s does not exist in this dataset" % str(antenna))
        return([0,0])
    try:
        mytb = createCasaTool(tbtool)
        mytb.open("%s/POINTING" % vis)
    except:
        print("Cannot open the POINTING table.")
        return([0,0])
    subtable = mytb.query("ANTENNA_ID == %s" % antenna)
    mytb.close()
    if (casaVersion >= casaVersionWithMSMD):
        closeMymsmd = False
        if mymsmd == '':
            mymsmd = createCasaTool(msmdtool)
            mymsmd.open(vis)
            closeMymsmd = True
        scans = callscannumbers(mymsmd)
    else:
        if (vm==0):
            vm = ValueMapping(vis)
        scans = vm.uniqueScans
    if (scan is None):
        scan = scans
    if (type(scan) == str):
        scan = [int(k) for k in scan.split(',')]
    if (type(scan) == list or type(scan) == np.ndarray):
        myTimes = []
        for sc in scan:
            if (casaVersion >= casaVersionWithMSMD):
                if (sc not in callscannumbers(mymsmd)):
                    print("A: Scan %s is not in the data." % (str(sc)))
                    return([0,0])
                if (casaVersion >= '4.4' and casaVersion < '4.6'):
                    newTimes = mymsmd.timesforscan(sc,obsid=obsid)
                else:
                    newTimes = mymsmd.timesforscan(sc)
            else:
                try:
                    newTimes = vm.getTimesForScan(sc)
                except:
                    print("3) Error reading scan %d, is it in the data?" % (sc))
                    return([0,0])
#            print "Appending times for scan ", sc
            myTimes.append(list(newTimes)) #  = np.concatenate((myTimes,newTimes))
    elif (scan is not None):
        if (casaVersion >= casaVersionWithMSMD):
            if (scan not in callscannumbers(mymsmd)):
                print("B: Scan %s is not in the data." % (str(scan)))
                return([0,0])
            if (casaVersion >= '4.4' and casaVersion < '4.6'):
                myTimes = [mymsmd.timesforscan(scan,obsid=obsid)]
            else:
                myTimes = [mymsmd.timesforscan(scan)]
        else:
            try:
                myTimes = [vm.getTimesForScan(scan)]
            except:
                print("4) Error reading scan %d, is it in the data?" % (scan))
                return([0,0])
    else:
        print("scan = ", scan)
        return([0,0])
    direction = subtable.getcol("DIRECTION")
    if (len(direction) == 0):
        print("listazel: Pointing table is empty")
        return
    time = subtable.getcol("TIME")
    azimuth = direction[0][0]*180.0/math.pi
    elevation = direction[1][0]*180.0/math.pi
    npat = np.array(time)
    if value == 'mean':
        func = np.mean
    elif value == 'median':
        func = np.median
    elif value == 'min':
        func = np.min
    elif value == 'max':
        func = np.max
    elif value == 'all':
        func = np.array
    else:
        func = np.mean

    if (len(myTimes) == 1):
        myTimes = myTimes[0]
        # This logic assumes that scan lists do not have holes in them.
        matches = np.where(npat>myTimes[0])[0]
        matches2 = np.where(npat<myTimes[-1])[0]
        azimuth = func(azimuth[matches[0]:matches2[-1]+1])
        elevation = func(elevation[matches[0]:matches2[-1]+1])
    else:
        # There might be gaps in scan lists
        myazimuth = []
        myelevation = []
        for myTime in myTimes:
            matches = np.where(npat>myTime[0])[0]
            matches2 = np.where(npat<myTime[-1])[0]
#            print("matches: ", matches)
#            print("matches2: ", matches2)
            if len(matches) == 0:
                # not sure why this can sometimes be blank list, but if so, use final value of matches2
                matches = matches2[-1:]
            myazimuth.append(func(azimuth[matches[0]:matches2[-1]+1]))
            myelevation.append(func(elevation[matches[0]:matches2[-1]+1]))
        # implement a scan-based mean, rather than time-based mean
        azimuth = func(myazimuth)
        elevation = func(myelevation)
    if (type(scan) == list or type(scan) == np.ndarray):
        listscan = ""
        listfield = []
        for sc in scan:
            if (casaVersion >= casaVersionWithMSMD):
                if (casaVersion >= '4.4' and casaVersion < '4.6'):
                    fields = mymsmd.fieldsforscan(sc,obsid=obsid)
                else:
                    fields = mymsmd.fieldsforscan(sc)
            else:
                fields = vm.getFieldsForScan(sc)
            for f in fields:
                listfield.append(f)
            listscan += "%d" % sc
            if (sc != scan[-1]):
                listscan += ","
        listfields = np.unique(listfield)
        listfield = ""
        for field in listfields:
            listfield += "%s" % field
            if (field != listfields[-1]):
                listfield += ","
    else:
        listscan = str(scan)
        if (casaVersion >= casaVersionWithMSMD):
            if (casaVersion >= '4.4' and casaVersion < '4.6'):
                listfield = mymsmd.fieldsforscan(scan,obsid=obsid)
            else:
                listfield = mymsmd.fieldsforscan(scan)
        else:
            listfield = vm.getFieldsForScan(listscan)
    if verbose and func != 'all':
        print("Scan %s (field=%s): azim = %.2f,  elev = %.2f  (degrees)" % (listscan, listfield, azimuth, elevation))
    if (casaVersion >= casaVersionWithMSMD):
        if closeMymsmd:
            mymsmd.close()
    return([azimuth, elevation])
# end of listazel()

def plotAzimuthElevationPolar(vis, antenna='0', plotfile='', colorByHalf=False):
    """
    Polar plot of the azimuth and elevation for a specified antenna in an ms
    from the POINTING table.  Note: This will not work for VLA data.
    - Todd Hunter
    """
    if (os.path.exists(vis) == False):
        print("Could not find the ms = %s" % (vis))
        return
    if (os.path.exists(vis+'/table.dat') == False):
        print("No table.dat.  This does not appear to be an ms.")
        return
    try:
      if str(antenna).isdigit():
          antennaName = getAntennaNames(vis)[int(str(antenna))]
      else:
          antennaName = antenna
          try:
              antenna = getAntennaIndex(vis,antennaName)
          except:
              antennaName = string.upper(antenna)
              antenna = getAntennaIndex(vis,antennaName)
    except:
        print("Either the ANTENNA file or antenna %s does not exist" % (antennaName))
        return
    mytb = createCasaTool(tbtool)
    mytb.open("%s/POINTING" % vis)
    ref = mytb.getcolkeywords('DIRECTION')['MEASINFO']['Ref']
    if (ref.upper().find('AZEL') < 0):
        print("Sorry, the POINTING table is in %s format, not AZELGEO" % (ref))
        return
    subtable = mytb.query("ANTENNA_ID == %s" % antenna)
    direction = subtable.getcol("DIRECTION")
    mjdsec = (subtable.getcol("TIME"))
    subtable.close()
    mytb.close()        
    if (len(direction) == 0):
        print("The POINTING table appears to be empty.")
        return
    elevation = np.degrees(direction[1][0])
    mymsmd = createCasaTool(msmdtool)
    if (colorByHalf):
        mymsmd.open(vis)
        scans = mymsmd.scansforintent('CALIBRATE_DELAY*')
        firstHalf = scans[:len(scans)/2]
        ts = np.array(mymsmd.timesforscan(firstHalf[-1]), dtype=float)
        breakPointMJDSec = np.max(ts,axis=0)
        mymsmd.close()
    za = 90-elevation
    azimuth = np.degrees(direction[0][0])
    azimuth[np.where(azimuth < 0)[0]] += 2*np.pi
    ax = pb.subplot(111, polar=True, projection='polar')
    ax.set_theta_zero_location('N')
    ax.set_theta_direction(-1)
    ax.plot(azimuth, za,'k+',ms=10,color='k',mew=1)
    if (colorByHalf):
        idx = np.where(mjdsec > breakPointMJDSec)[0]
        ax.plot(azimuth[idx], za[idx],'k+',ms=10,color='r',mew=1)
        pb.text(0.0,1.0,'First half',color='k',transform=ax.transAxes)
        pb.text(0.0,0.95,'Second half',color='r',transform=ax.transAxes)
    pb.ylim([0,90])
    pb.text(np.radians(15),100,'Zenith angle (deg)',va='top')
    pb.title(vis+' (%s)'%getObservationStartDate(vis).split()[0])
    if (plotfile != ''):
        if (plotfile == True):
            plotfile = vis + '.azel_polar.png'
        pb.savefig(plotfile)
    
def plotAzimuthElevation(vis, antenna='0', xrangeAz=None, yrangeAz=None,
                         xrangeEl=None, yrangeEl=None,
                         plotfile=''):
    """
    Plots the azimuth and elevation vs. time for a specified antenna in an ms
    from the POINTING table.  Note: This will not work for VLA data.
    The antenna parameter can be either the number, the number string,
    or the name string of the antenna.  xrange and yrange can be
    used to set the plot range.
    Produces a plot called  <vis>.azel_vs_time.png, unless otherwise
    specified via the plotfile parameter.
    -- Todd Hunter
    """
    plotAzimuth(vis, antenna, xrangeAz, yrangeAz, plotfile, subplot=211)
    plotElevation(vis, antenna, xrangeEl, yrangeEl, plotfile, subplot=212)
    if (plotfile != ''):
        if (plotfile == True):
            plotfile = vis + '.azel_vs_time.png'
        pb.savefig(plotfile)
        print("Wrote ", plotfile)
    
def plotElevation(vis, antenna='0', Xrange=None, Yrange=None, plotfile='',
                  subplot=111):
    """
    Plots the elevation vs. time for a specified antenna in an ms from
    the POINTING table.  Note: This will not work for VLA data.
    The antenna parameter can be either the number, the number string,
    or the name string of the antenna.  xrange and yrange can be
    used to set the plot range.
    Produces a plot called  <vis>.elev.png, unless otherwise
    specified via the plotfile parameter.
    -- Todd Hunter
    """
    plotPosition(vis,1,antenna,Xrange,Yrange,plotfile, subplot=subplot)

def plotAzimuth(vis, antenna='0',Xrange=None,Yrange=None,plotfile='',
                forcePositive=True, subplot=111):
    """
    Plots the azimuth vs. time for a specified antenna in an ms from
    the POINTING table.  Note: This will not work for VLA data.
    The antenna parameter can be either the number, the number string,
    or the name string of the antenna.  xrange and yrange can be
    used to set the plot range.  
    Produces a plot called <vis>.azim.png, unless otherwise
    specified via the plotfile parameter.
    See also plotElevation.
     -- Todd Hunter
    """
    plotPosition(vis,0,antenna,Xrange,Yrange,plotfile,forcePositive,subplot)

def plotPosition(vis, azel, antenna='0', Xrange=None, Yrange=None,
                 plotfile='', forcePositive=False, subplot=111):
    """
    Plots the azimuth or elevation vs. time for a specified antenna in an ms
    from the POINTING table.  azel=0 means azimuth,  1 means elevation
    This function is useful for showing the az/el of planetary bodies which
    might appear with RA,dec = 0,0 in plotms (in older ALMA data).
    Produces a plot called  <vis>.elev.png or <vis>.azim.png, unless otherwise
    specified via the plotfile parameter.
    -- Todd Hunter
    """
    if (os.path.exists(vis) == False):
        print("Could not find the ms = %s" % (vis))
        return
    if (os.path.exists(vis+'/table.dat') == False):
        print("No table.dat.  This does not appear to be an ms.")
        return
    try:
      if str(antenna).isdigit():
          antennaName = getAntennaNames(vis)[int(str(antenna))]
      else:
          antennaName = antenna
          try:
              antenna = getAntennaIndex(vis,antennaName)
          except:
              antennaName = string.upper(antenna)
              antenna = getAntennaIndex(vis,antennaName)
    except:
        print("Either the ANTENNA file or antenna %s does not exist" % (antennaName))
        return
    mytb = createCasaTool(tbtool)
    mytb.open("%s/POINTING" % vis)
    ref = mytb.getcolkeywords('DIRECTION')['MEASINFO']['Ref']
    if (ref.upper().find('AZEL') < 0):
        print("Sorry, the POINTING table is in %s format, not AZELGEO" % (ref))
        return
    subtable = mytb.query("ANTENNA_ID == %s" % antenna)
    mytb.close()        
    direction = subtable.getcol("DIRECTION")
    if (len(direction) == 0):
        print("The POINTING table appears to be empty.")
        return
    elevation = np.degrees(direction[azel][0])
    if (azel==0 and forcePositive):
        elevation[np.where(elevation < 0)[0]] += 360
    mjdsec = (subtable.getcol("TIME"))
    mjd  = mjdsec/86400.
    elevTime = (mjd-math.floor(mjd[0]))*24.
    if (subplot == 211 or subplot == 111):
        pb.clf()
    pb.subplot(subplot)
    pb.plot(elevTime,elevation,'r.')
    if (azel == 1):
        pb.ylabel('Elevation (deg)')
        pb.ylim([0,90])
    else:
        pb.ylabel('Azimuth (deg)')
    if (Yrange is not None):
        pb.ylim(Yrange)
    if (Xrange is not None):
        pb.xlim(Xrange)
    (mjd, datestring) = mjdSecondsToMJDandUT(mjdsec[0])
    pb.xlabel('UT hour on %s'%(datestring[0:10]))
    if (subplot==111 or subplot==211):
        pb.title('%s  %s'%(vis,antennaName))
    if (subplot==111):
        if (azel==1):
            if (plotfile == ''):
                plotfile= vis+'.elev.png'
            pb.savefig(plotfile)
        else:
            if (plotfile == ''):
                plotfile= vis+'.azim.png'
            pb.savefig(plotfile)

    return elevation

def getMJDSec():
    """
    Returns the current MJD in seconds.
    Todd Hunter
    """
    return(getCurrentMJDSec())

def getCurrentUnixTime():
    """
    Returns the current unix time (seconds since 1970)
    """
    return(timeUtilities.time())

def getCurrentMJDSec():
    """
    Returns the current MJD in seconds.
    Todd Hunter
    """
    mjdsec = getMJD() * 86400
    return(mjdsec)

def getCurrentDate(delimiter='/'):
    """
    returns date in format: 'YYYY/MM/DD'
    delimiter: which character to use as the delimiter
    -Todd Hunter
    """
    return(timeUtilities.strftime('%Y/%m/%d').replace('/',delimiter))

def ComputeNRAODopsetLST(vis):
    """
    For a specified ms, computes the LST day and time string required by 
    the fortran program NRAO Dopset.
    -Todd Hunter
    """
    hhmmss = ComputeLST(vis=vis, hms=True).replace(':',',')
    day = str(ComputeLSTDay(vis=vis))
    return ','.join([day,hhmmss]) 

def ComputeLSTDay(mjdsec=-1, date='', longitude=ALMA_LONGITUDE, 
                  verbose=True, observatory=None, vis=''):
    """
    Computes the LST day (useful for running NRAO dopset)
    and LST (in hours) for a specified time/date and longitude.
    If mjdsec is a string, it will be assumed to be a date string.
    observatory: if specified (i.e. not None), then ignore the longitude parameter
    vis: if neither mjdsec nor date are not specified, then pull observation 
         start time from this measurement set
    For date, either of these formats is valid: 2011/10/15
                                                2011/10/15 05:00:00
                                                2011/10/15-05:00:00
    longitude: degrees, where east of Greenwich is positive (default=ALMA).
    -- Todd Hunter
    """
    if (date == ''):
        if (type(mjdsec) == str):
            mjdsec = dateStringToMJDSec(mjdsec,verbose=verbose)
        else:
            if (mjdsec<0):
                if vis == '':
                    mjdsec = getCurrentMJDSec()
                    print("Using current date/time")
                else:
                    if not os.path.exists(vis):
                        print("Could not find measurement set: ", vis)
                        return
                    mjdsec = getObservationStart(vis)
    else:
        mjdsec = dateStringToMJDSec(date,verbose=verbose)

    LST = ComputeLST(mjdsec, longitude, observatory=observatory)
    if (observatory is not None):
        longitude = getObservatoryLongitude(observatory)
        if (longitude is None): return
    MJD = mjdsec/86400.
    JD = mjdToJD(MJD)
# See http://gge.unb.ca/Pubs/TR171.pdf
    siderealDay = int(np.floor(JD*(0.002737909350795) + MJD) )
    if (verbose):
        print("LST day = %d,  LST = %.4f hours (at longitude=%f)" % (siderealDay,
                                                                     LST,longitude))
        print("Julian day = %f, MJD = %f, MJD seconds = %f" % (JD,MJD,mjdsec))
    return(siderealDay)

def unixtimeToSiderealTime(unixtime, longitude=ALMA_LONGITUDE, observatory=None):
    """
    Converts unixtime to sidereal time at specified observatory
    """
    mjd = unixTimeToMJD(unixtime)
    hours = ComputeLST(mjd*86400, longitude, observatory=observatory)
    return hours
      
def ComputeLST(mjdsec=None, longitude=ALMA_LONGITUDE, ut=None, hms=False,
               observatory=None, date=None, verbose=False, prec=0, vis=''):
    """
    Computes the LST (in hours) for a specified time and longitude. 
    The input longitude is in degrees, where east of Greenwich is > 0.
    Two options to specify the time:
    mjdsec: MJD seconds
    ut: ut time on the current day as a HH:MM:SS string or floating point hours
    hms: if True, return the time as a HH:MM:SS string
    observatory: if specified (i.e. not None), ignore the longitude argument
    prec: digits of fractional seconds to show
    date: a date/time string
    vis: if neither mjdsec nor ut, nor date are not specified, then pull the
         observation start time from this measurement set and convert to LST
    Either of these formats is valid: 2011/10/15 05:00:00
                                      2011/10/15-05:00:00
                                      2011-10-15 05:00:00
                                      2011-10-15T05:00:00
                                      2011-Oct-15T05:00:00
    If mjdsec, ut and date are all None and vis=='', then it uses the current date+time.
    -- Todd Hunter
    """
    if (mjdsec is None and ut is None and date is None and vis == ''):
        mjdsec = getMJDSec()
    elif (ut is not None):
        if (date is None):
            datestring = getCurrentDate()
        else:
            datestring = date
        if (type(ut) == str):
            datestring += ' ' + ut
        else:
            minutes = int(60*(ut-int(ut)))
            datestring += ' %02d:%02d:%02.0f' % (int(ut),minutes,3600*(ut-int(ut)-minutes/60.))
        mjdsec = dateStringToMJDSec(datestring, verbose=False)
    elif (date is not None):
        mjdsec = dateStringToMJDSec(date, verbose=False)
    elif vis != '':
        if os.path.exists(vis):
            mjdsec = getObservationStart(vis)
        else:
            print("Could not find measurement set: ", vis)
            return

    if verbose: print("MJD seconds = ", mjdsec)
    JD = mjdToJD(mjdsec/86400.)
    T = (JD - 2451545.0) / 36525.0
    sidereal = 280.46061837 + 360.98564736629*(JD - 2451545.0) + 0.000387933*T*T - T*T*T/38710000.

    # now we have LST in Greenwich, need to scale back to site
    if (observatory is not None):
        longitude = getObservatoryLongitude(observatory)
        if (longitude is None): return
    sidereal += longitude
    sidereal /= 360.
    sidereal -= np.floor(sidereal)
    sidereal *= 24.0
    if (sidereal < 0):
        sidereal += 24
    if (sidereal >= 24):
        sidereal -= 24
    if (hms):
        return(hoursToHMS(sidereal, prec=prec))
    else:
        return(sidereal)

def getCalibrationIntents(vis, field, mymsmd=None, briefNames=True, drop='WVR,ATMOSPHERE'):
    """
    Returns a list of calibration intents  (if any) for specified field.
    briefNames: if True, then return ['BANDPASS'] instead of ['CALIBRATE_BANDPASS#ON_SOURCE']
    -Todd Hunter
    """
    if not os.path.exists(vis):
        print("Could not find measurement set: ", vis)
        return
    drop = drop.split(',')
    needToClose = False
    if mymsmd is None:
        needToClose = True
        mymsmd = createCasaTool(msmdtool)
        mymsmd.open(vis)
    intents = mymsmd.intentsforfield(field)
    fullIntents = []
    briefIntents = []
    for intent in intents:
        if intent.find('CALIBRATE') >= 0:
            # the split on . is needed for really old ALMA data
            briefIntent = intent.replace('CALIBRATE_','').split('#')[0].split('.')[0]
            if briefIntent not in drop:
                fullIntents.append(intent)
                briefIntents.append(briefIntent)
    if needToClose:
        mymsmd.close()
    if briefNames:
        intents = np.unique(briefIntents)
    else:
        intents = np.unique(fullIntents)
    return intents
    
def nearestCalibratorToScienceTargets(vis, excludeTargetMS=True, 
             maxScienceTargets=-1, mymsmd=None, 
             intent=['BANDPASS','FLUX','PHASE','AMP','POLARIZATION']):
    """
    Reports a dictionary keyed by science target name, with values for 
    'nearest' calibrator name, and 'separation' in degrees.
    vis: single measurement set, or comma-delimited list or wildcard, or a 
         python list
    excludeTargetMS: if True and wildcard vis is used, will not pick *target.ms
    mymsmd: only relevant if vis is not a list
    if vis is a list, then dictionary returned is keyed by vis
    -Todd Hunter
    """
    if type(vis) == str:
        if vis.find('*') >= 0:
            vislist = sorted(glob.glob(vis))
            if excludeTargetMS:
                newvislist = []
                for vis in vislist:
                    if vis.find('target.ms') < 0:
                        newvislist.append(vis)
                vislist = newvislist
        else:
            vislist = vis.split(',')
    else:
        vislist = vis
    results = {}
    print("vislist: ", vislist)
    if mymsmd is not None and len(vislist) == 1:
        needToClose = False
    else:
        mymsmd = createCasaTool(msmdtool)
        needToClose = True
    for vis in vislist:
        if not os.path.exists(vis):
            print("Could not find measurement set: %s" % (vis))
            return
        if needToClose:
            mymsmd.open(vis)
        results[vis] = {}
        fields = getScienceTargets(vis, mymsmd=mymsmd, returnNames=False)
        fieldNames = mymsmd.namesforfields()
        calibrators = getCalibrators(vis, mymsmd=mymsmd, returnNames=False, intent=intent)
        if maxScienceTargets > 0:
            fields = fields[:maxScienceTargets]
        for field1 in fields:
            minSeparation = 1e9
            for calibrator in calibrators:
                separation = angularSeparationOfTwoFields(vis, field1, calibrator, usemsmd=mymsmd)
                if separation < minSeparation:
                    intents = getCalibrationIntents(vis, calibrator, mymsmd=mymsmd)
                    results[vis][fieldNames[field1]] = {'nearest': fieldNames[calibrator], 'separation': separation, 'intent': intents}
                    minSeparation = separation
        if needToClose:
            mymsmd.close()
    if len(vislist) == 1:
        return results[vis]
    else:
        return results

def checksourceOffsetUncertainty(imageCenterPosition, fittedPosition, 
                                 raUncertainty, decUncertainty, useRefval=True,
                                 verbose=False):
    """
    imageCenterPosition: sexagesimal string of RA/Dec, or an image name
    fittedPosition: sexagesimal string of RA/Dec
    raUncertainty: in arcsec on a great circle
    decUncertainty: in arcsec on a great circle
    useRefval: passed to imageCenter(), only relevant if imageCenterPosition 
          is an image name
    Returns: uncertainty in arcsec
    -Todd Hunter
    """
    if os.path.isdir(imageCenterPosition):
        imageName = imageCenterPosition[:]
        imageCenterPosition = imageCenter(imageName, useRefval=useRefval, verbose=False)
        print("Using imageCenter = ", imageCenterPosition)
    else:
        imageName = ''
    result = angularSeparationOfStrings(imageCenterPosition, fittedPosition, 
                                        returnComponents=True, 
                                        returnArcsec=True, verbose=verbose)
    offset = result[0]
    simpleOffset = np.linalg.norm([result[2],result[3]])
    decSeparation = result[2]
    raSeparation = result[3]
    if imageName == '':
        print("Separation: %f milliarcsec" % (offset*1000))
        geometricMeanBeam = 0
    else:
        beamresult = getFitsBeam(imageName)
        if beamresult[0] > 0 and beamresult[1] > 0:
            geometricMeanBeam = (beamresult[0]*beamresult[1])**0.5
            beamFraction = offset/geometricMeanBeam
            simpleBeamFraction = simpleOffset/geometricMeanBeam
#            print "Simple separation: %f milliarcsec = %.2f beams" % (simpleOffset*1000, simpleBeamFraction)
            print("Separation:  %f milliarcsec = %.2f beams" % (offset*1000, beamFraction))
        else:
            geometricMeanBeam = 0
            print("Exact separation: %f milliarcsec" % (offset*1000))
    uncertainty = angularOffsetUncertainty(raSeparation, decSeparation, 
                                           raUncertainty, decUncertainty, geometricMeanBeam)
    return uncertainty

def angularOffsetUncertainty(offsetX, offsetY, uncertaintyX, uncertaintyY, beam=0):
    """
    Computes uncertainty of angular offset measurement using two methods.
    Simple: quadrature sum of offsetX and offsetY
    Correct: true propagation of uncertainty formula (with no covariance)
    offsetX: in pixels or arcsec
    offsetY: in same units as offsetX
    uncertaintyX: in same units as offsetX
    uncertaintyY: in same units as offsetX
    -Todd Hunter
    """
    simpleUncertainty = np.linalg.norm([uncertaintyX, uncertaintyY])
    offset = np.linalg.norm([offsetX, offsetY])
    correctUncertainty = np.linalg.norm([offsetX*uncertaintyX/offset,
                                         offsetY*uncertaintyY/offset])
    if beam > 0:
        print("Simple uncertainty:  %f arcsec = %.3f beams" % (simpleUncertainty,simpleUncertainty/beam))
        print("Correct uncertainty: %f arcsec = %.3f beams" % (correctUncertainty, correctUncertainty/beam))
    else:
        print("Simple uncertainty:  %f arcsec" % (simpleUncertainty))
        print("Correct uncertainty: %f arcsec" % (correctUncertainty))
    return correctUncertainty

def imageCenterVsFieldCenter(vis, field, img, useRefval=True):
    """
    vis: measurement set
    field: field name or ID
    img: an image of the field produced from this vis
    -Todd Hunter
    """
    if not os.path.exists(vis):
        print("Could not find measurement set: ", vis)
        return
    if not os.path.exists(img):
        print("Could not find image: ", vis)
        return
    separation = angularSeparationOfStrings(getRADecForField(vis, field, hms=True), imageCenter(img, useRefval=useRefval), returnArcsec=True)
    return separation

def angularSeparationOfTwoFields(vis, field1, field2, usemsmd='', vis2='', returnComponents=False, returnArcsec=False):
    """
    Copmutes the angular separation (in degrees) between 2 specified fields
    in a measurement set, using msmd.phasecenter.
    field1, field2: the field IDs
    usemsmd: if specified, use this existing instance of msmd
    vis2: if specified, then look for field2 in this other measurement set
    Returns:
    returnComponents=False: single value in degrees
    returnComponents=True: 4 values: [separation, raSeparation, decSeparation, raSeparationCosDec]
    returnArcsec: if True, return the four separations in arcsec
    -Todd Hunter
    """
    if (usemsmd == ''):
        mymsmd = createCasaTool(msmdtool)
        mymsmd.open(vis)
    else:
        mymsmd = usemsmd
    phasecenter1 = mymsmd.phasecenter(field1)
    if (vis2 == ''):
        phasecenter2 = mymsmd.phasecenter(field2)
    else:
        mymsmd2 = createCasaTool(msmdtool)
        mymsmd2.open(vis2)
        phasecenter2 = mymsmd2.phasecenter(field2)
        mymsmd2.close()
    if (usemsmd == ''):
        mymsmd.close()
    degrees = np.degrees(angularSeparationOfDirections(phasecenter1,
                                                       phasecenter2, returnComponents))
    if returnArcsec:
        value = degrees*3600
    else:
        value = degrees
    return value

def plotPhaseCheckTargetOnSky(dataset, plotfile='', checksource='', science='',
                              phase='', catalogues=[ALMA_CATALOG], useMinidom=False,
                              showAllScienceTargets=False):
    """
    For an ASDM or ms, plots the relative locations on the sky of the phase 
    calibrator, check source, and first science target.  The first science target
    appears at (0,0) in the plot, unless showAllScienceTargets=True.
    for ephemeris objects (which will appear at 0,0).
    dataset: name of ASDM or ms file
    checksource: override the checksource with this source (e.g. J0217-0820)
    science: override the science target with this source (e.g. J0217-0820)
    phase: override the phasecal target with this source (e.g. J0217-0820)
    showAllScienceTargets: if True, then put phasecal at (0,0) instead of the first
        science target, and show/label all science targets, and all ATMOSPHERE
        targets whose first letter is not 'J' (to avoid showing quasar calibrator Tsys)
    catalogues: list of catalogs to use (default is ALMA_CATALOG), options are: 
       ALMA_CATALOG: [5], or ALMA_QA2_CATALOG: [61], or ALMA_QA0_CATALOG: [121]
       or a combination: [5,61]
    useMinidom: if True, then parse the .xml file even if the ASDM python
                bindings are available
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    -Todd Hunter
    """
    dataset = dataset.rstrip('/')
    if not os.path.exists(dataset):
        print("Could not find dataset.")
        return
    if not os.path.exists(dataset+'/ASDM.xml'):
        asdm = False
        mymsmd = createCasaTool(msmdtool)
        mymsmd.open(dataset)
    else:
        asdm = True
    if phase == '':
        if asdm:
            phase = getTargetsForIntentFromASDM(dataset, 'PHASE', useMinidom)
        else:
            phase = getTargetsForIntent(dataset, 'PHASE', mymsmd=mymsmd)
        if len(phase) < 1:
            print("No PHASE calibrator.")
            return
    else:
        # phase[0] is a numpy.string_ which 
        phase = [str(phase)]
    if asdm:
        ephemerisFieldDict = getEphemerisFieldsFromASDM(dataset, keyBy='name', verbose=False, useMinidom=useMinidom)
        phasepos = getRADecForFieldFromASDM(dataset, phase[0], sexagesimal=True, useMinidom=useMinidom)
    else:
        ephemerisFieldDict = getEphemerisFields(dataset, verbose=False)
        phasepos = getRADecForField(dataset, str(phase[0]), hms=True, mymsmd=mymsmd)
    print("phasepos = ", phasepos)

    if checksource == '':
        if asdm:
            check = getTargetsForIntentFromASDM(dataset, 'CHECK', useMinidom)
        else:
            check = getTargetsForIntent(dataset, 'CHECK', mymsmd=mymsmd)
        if len(check) < 1:
            print("No CHECK source calibrator.")
            checkpos = None
        else:
            if asdm:
                checkpos = getRADecForFieldFromASDM(dataset, check[0], sexagesimal=True, useMinidom=useMinidom)
            else:
                checkpos = getRADecForField(dataset, check[0], hms=True)
    else:
        check = [checksource]
        checkpos = searchFlux(checksource, returnPosition=True, verbose=False, catalogues=catalogues)
    if science == '':
        if asdm:
            science = getTargetsForIntentFromASDM(dataset, 'TARGET', useMinidom)
            atms = getTargetsForIntentFromASDM(dataset, 'ATMOSPHERE', useMinidom)
        else:
            science = getTargetsForIntent(dataset, 'TARGET', mymsmd=mymsmd)
            atms = getTargetsForIntent(dataset, 'ATMOSPHERE', mymsmd=mymsmd)
        print("atms = ", atms)
        if len(science) < 1:
            print("No TARGET source.")
            return
    else:
        science = [science]
    nScienceTargets = len(science)
    if showAllScienceTargets:
        scienceList = list(range(nScienceTargets))
    else:
        scienceList = [0]
    pb.clf()
    desc = pb.subplot(111)
    for sc in scienceList:
        if asdm:
            sciencepos = getRADecForFieldFromASDM(dataset, science[sc], sexagesimal=True, useMinidom=useMinidom)
        else:
            sciencepos = getRADecForField(dataset, science[sc], hms=True)
        if sc == 0:
            print("first sciencepos = ", sciencepos)
        if showAllScienceTargets:
            phaseDeg = angularSeparationOfStrings(sciencepos, phasepos, True)
            if checkpos is not None:
                checkDeg = angularSeparationOfStrings(checkpos, phasepos, True)
            if checkpos is not None:
                x = [0, phaseDeg[3], checkDeg[3]]
                y = [0, phaseDeg[2], checkDeg[2]]
            else:
                x = [0, phaseDeg[3]]
                y = [0, phaseDeg[2]]
            pb.plot(x, y, 'b+', ms=10, mew=2)
            pb.text(phaseDeg[3],phaseDeg[2],'science='+science[sc], ha='center', va='top', size=8)
            for atm in atms:
                if atm[0] != 'J':
                    print("atm = ", atm)
                    if asdm:
                        atmpos = getRADecForFieldFromASDM(dataset, atm, sexagesimal=True, useMinidom=useMinidom)
                    else:
                        atmpos = getRADecForField(dataset, atm, hms=True)
                    atmDeg = angularSeparationOfStrings(atmpos, phasepos, True)
                    print("Found matching Tsys field that does not start with 'J': ", atm)
                    pb.plot([atmDeg[3]], [atmDeg[2]], 'r+', ms=10, mew=2)
                    pb.text(atmDeg[3], atmDeg[2], 'atm='+atm, ha='center', va='top', size=10, color='r')
        else:
            phaseDeg = angularSeparationOfStrings(phasepos,sciencepos,True)
            if checkpos is not None:
                checkDeg = angularSeparationOfStrings(checkpos,sciencepos,True)
            if checkpos is not None:
                x = [0, phaseDeg[3], checkDeg[3]]
                y = [0, phaseDeg[2], checkDeg[2]]
            else:
                x = [0, phaseDeg[3]]
                y = [0, phaseDeg[2]]
            pb.plot(x, y, 'b+', ms=10, mew=2)
            pb.text(0,0,'science='+science[sc], ha='center', va='top')
    if not asdm:
        mymsmd.close()
    if checkpos is not None:
        pb.text(checkDeg[3],checkDeg[2],'check='+check[0], ha='center', va='top')
    if showAllScienceTargets:
        pb.xlabel('Right Ascension offset from phasecal (deg)')
        pb.ylabel('Declination offset from phasecal (deg)')
        pb.text(0,0,'phase='+phase[0], ha='center', va='top')
    else:
        pb.text(phaseDeg[3],phaseDeg[2],'phase='+phase[0], ha='center', va='top')
        pb.xlabel('Right Ascension offset from science target (deg)')
        pb.ylabel('Declination offset from science target (deg)')
    padPlotLimits(0.2)
    # reverse x-axis so the RA increases to the left
    pb.xlim([pb.xlim()[1], pb.xlim()[0]])
    pb.title(os.path.basename(dataset))
    pb.draw()
    if plotfile == True:
        plotfile = dataset + '_plotPhaseCheckTarget.png'
    if plotfile != '':
        pb.savefig(plotfile)
        print("Wrote ", plotfile)

def addDateToPlot(size=10):
    """
    Adds the current date/time to the bottom right of a pylab plot.
    -Todd Hunter
    """
    pb.text(0.95, 0.03, mjdsecToDatestring(), ha='right', va='bottom', transform=pb.gcf().transFigure,size=size)

def padPlotLimits(fraction=0.1, xbottom=True, xtop=True, ybottom=True, ytop=True):
    """
    Expand the current pylab plot limits by 10% on each edge.
    -Todd Hunter
    """
    x0,x1 = pb.xlim()
    if xbottom or xtop:
        xspan = x1-x0
        if xbottom:
            x0 = x0-xspan*fraction
        if xtop:
            x1 = x1+xspan*fraction
        pb.xlim([x0,x1])
    y0,y1 = pb.ylim()
    if ybottom or ytop:
        yspan = y1-y0
        if ybottom:
            y0 = y0-yspan*fraction
        if ytop:
            y1 = y1+yspan*fraction
        pb.ylim([y0,y1])

def angularSeparationOfFieldsFromASDM(asdm, intents='PHASE,CHECK', verbose=False):
    """
    Determines angular separation between two intents (i.e between the first 
    objects observed for those intents).  Works correctly for SSOs because it 
    determines field name from intent, then matches it with the source name in the
    Source.xml dictionary returned by readscans rather than Field.xml (which has 0,0).
    -Todd Hunter
    """
    if not os.path.exists(asdm):
        print("Could not find ASDM:", asdm)
        return
    if type(intents) == str:
        intents = intents.split(',')
    if len(intents) < 2:
        print("Need at least 2 intents")
        return
    targets = {}
    radec = []
    for intent in intents:
        targets[intent] = getTargetsForIntentFromASDM(asdm, '*'+intent+'*')
        if len(targets[intent]) < 1:
            print("No %s targets" % (intent))
            return
        radec.append(getRADecForFieldFromASDM(asdm, targets[intent][0], sexagesimal=True))
        if verbose:
            print("%s: %s %s" % (targets[intent][0], intent, radec[-1]))
    separationDeg = angularSeparationOfStrings(radec[0], radec[1], verbose=False)
    print("Separation of %s (%s) from %s (%s)  = %.2f deg" % (targets[intents[0]][0], intents[0], targets[intents[1]][0], intents[1], separationDeg))
    return separationDeg

def intentsforfield(mymsmd, name):
    """
    Workaround for msmd bug reported in CAS-12164.
    -Todd Hunter
    """
    fieldIDs = mymsmd.fieldsforname(name)
    intents = []
    for fieldID in fieldIDs:
        intents += list(mymsmd.intentsforfield(fieldID))
    return list(np.unique(intents))

def angularSeparationOfFields(vis, fields=[], doplot=False, 
                              plotintents=['OBSERVE_TARGET*','CALIBRATE_PHASE*'], 
                              allMosaicFields=True, strict=False, mymsmd=None,
                              prec=3, verbose=False, blendByName=False):
    """
    Reads an ms and computes the angular separation of all combinations
    of fields, or if the fields parameter is given, only those field
    names or IDs specified in the fields parameter, which can be either
    a list of IDs or names, or an individual ID or name.
    It computes great circle angle using the Vincenty formula.
    doplot: if True, then also make a plot of Declination vs. RA
       The plot aspect ratio is scaled by cos(mean_dec) to reflect sky separation.
    plotintents: only plot fields with these intents, colorized by intent
    allMosaicFields: if False, then only compute for one field of multi-field targets
    strict: if True, then both fields must be in fields list for separation to be shown
    prec: precision for the arcsec display
    blendByName: passed to au.getRADecForField()
    verbose: if True, show the sexagesimal position for all fields
    Returns:  the max separation of phase cal to science target
    -- Todd Hunter
    """
    if (not os.path.exists(vis)):
        print("vis does not exist = ", vis)
        return
    if (type(fields) != list and type(fields) != np.ndarray):
        if type(fields) == str:
            fields = fields.split(',')
        else:
            fields = [fields]
    if mymsmd is None:
        mymsmd = createCasaTool(msmdtool)    
        mymsmd.open(vis)
        needToClose = True
    else:
        needToClose = False
    if (casaVersion < casaVersionWithMSMDFieldnames):
        name = mymsmd.namesforfields()
    else:
        name = mymsmd.fieldnames()
    pos = []
    myms = createCasaTool(mstool)
    myms.open(vis)
    for i in range(len(name)):
        pos.append([getRADecForField(vis, i, usemstool=True, myms=myms, mymsmd=mymsmd, blendByName=blendByName)])
        if verbose:
            print(i,getRADecForField(vis, i, usemstool=True, myms=myms, mymsmd=mymsmd, hms=True, blendByName=blendByName))
    myms.close()
    nfields = len(pos)
    if (nfields < 2):
        print("There is only one field in this dataset.")
    else:
        print("Field =         Names (*=phasecal)           Separations")
    if doplot:
        if (type(plotintents) == str):
            plotintents = [plotintents]
        pb.clf()
        desc = pb.subplot(111)
        pb.xlabel('RA (hours)')
        pb.ylabel('Dec (deg)')
        plotfields = []
        for intent in plotintents:
            myfields = list(mymsmd.fieldsforintent(intent))
            plotfields.append(myfields)
        colors = ['k','r','g','b','c','m']
    separations = []
    doneFields = []
    for i in range(nfields):
      if (name[i] not in doneFields) or allMosaicFields:
        if doplot:
            for col, plotfield in enumerate(plotfields):
                print("col=%s, plotfield=%s" % (col, plotfield))
                if i in plotfield:
                    hours = np.degrees(pos[i][0][0])/15.
                    if (np.mean(hours) < 0):
                        hours += 24
                    pb.plot(hours, 
                            np.degrees(pos[i][0][1]), 'o', color=colors[col], mec=colors[col],mfc='white',mew=2)
                    break
        doneFields2 = []
        for j in range(i+1,len(pos)):
          if allMosaicFields or (name[j] not in doneFields2):
            if strict:
                mytest = fields == [] or fields == [''] or (i in fields and j in fields) or (name[i] in fields and name[j] in fields)
            else:
                mytest = fields == [] or fields == [''] or (i in fields or j in fields) or (name[i] in fields or name[j] in fields)
            if mytest:
                radians = angularSeparationRadiansTuples(pos[i][0], pos[j][0])
                degrees = radians*180/np.pi
                arcsec = 3600*degrees
                namei = name[i]
                namej = name[j]
                phasecalScience = ''
                if ('CALIBRATE_PHASE#ON_SOURCE' in intentsforfield(mymsmd,name[i])):
                    mynames = intentsforfield(mymsmd, name[j])
                    namei = '*'+namei
                    if ('OBSERVE_TARGET#ON_SOURCE' in mynames):
                        phasecalScience = '(phasecal-science)'
                        separations.append(degrees)
                    if ('OBSERVE_CHECK_SOURCE#ON_SOURCE' in mynames or
                        'CALIBRATE_DELAY#ON_SOURCE' in mynames):
                        phasecalScience = '(phasecal-checksource)'
                    if ('CALIBRATE_BANDPASS#ON_SOURCE' in mynames):
                        phasecalScience = '(phasecal-bandpass)'
                    if ('CALIBRATE_FLUX#ON_SOURCE' in mynames or
                        'CALIBRATE_AMPLI#ON_SOURCE' in mynames):
                        phasecalScience = '(phasecal-flux)'
                    if ('CALIBRATE_PHASE#ON_SOURCE' in mynames):
                        phasecalScience = '(phasecal-phasecal)'
                if ('CALIBRATE_PHASE#ON_SOURCE' in intentsforfield(mymsmd,name[j])):
                    namej = '*'+namej
                    mynames = intentsforfield(mymsmd,name[i])
                    if ('OBSERVE_TARGET#ON_SOURCE' in mynames):
                        separations.append(degrees)
                        phasecalScience = '(science-phasecal)'
                    if ('CALIBRATE_BANDPASS#ON_SOURCE' in mynames):
                        phasecalScience = '(bandpass-phasecal)'
                    if ('CALIBRATE_FLUX#ON_SOURCE' in mynames or
                        'CALIBRATE_AMPLI#ON_SOURCE' in mynames):
                        phasecalScience = '(flux-phasecal)'
                    if ('OBSERVE_CHECK_SOURCE#ON_SOURCE' in mynames or
                        'CALIBRATE_DELAY#ON_SOURCE' in mynames):
                        phasecalScience = '(checksource-phasecal)'
                    if ('CALIBRATE_PHASE#ON_SOURCE' in mynames):
                        phasecalScience = '(phasecal-phasecal)'
                if ('OBSERVE_CHECK_SOURCE#ON_SOURCE' in intentsforfield(mymsmd,name[i])):
                    namei = '*'+namei
                    if ('OBSERVE_TARGET#ON_SOURCE' in intentsforfield(mymsmd,name[j])):
                        phasecalScience = '(checksource-science)'
                if ('OBSERVE_TARGET#ON_SOURCE' in intentsforfield(mymsmd,name[j])):
                    if ('OBSERVE_CHECK_SOURCE#ON_SOURCE' in intentsforfield(mymsmd,name[i])):
                        phasecalScience = '(science-checksource)'
                print("%02d-%02d = %15s-%15s: %8g deg = %*.*f arcsec %s" % (i,j,namei,namej,degrees,7+prec,prec,arcsec,phasecalScience))
            doneFields2.append(name[j])
        doneFields.append(name[i])
    if needToClose:
        mymsmd.close()
    if doplot:
        desc.set_aspect(np.abs(np.cos(np.radians(np.mean(pb.ylim()))))/15.0)
        pb.title(os.path.basename(vis))
        x1,x0 = pb.xlim()
        pb.xlim([x0,x1])
        for i,plotintent in enumerate(plotintents):
            pb.text(1,0.95-i*0.05,plotintent,ha='right',color=colors[i],transform=desc.transAxes)
        pb.draw()
        png = vis+'.fieldlayout.png'
        pb.savefig(png)
        print("Plot left in ", png)
    if (len(separations) > 0):
        return(np.max(separations))

def checksourcePresent(vis, mymsmd=None, intent='OBSERVE_CHECK_SOURCE#ON_SOURCE',
                       returnBoolean=True):
    """
    Checks whether a checksource is present in a dataset.
    returnBoolean: if False, then return an integer count of unique check sources
    -Todd Hunter
    """
    if not os.path.exists(vis):
        print("Could not find measurement set: ", vis)
        return
    if mymsmd == '' or mymsmd is None:
        needToClose = True
        mymsmd = createCasaTool(msmdtool)
        mymsmd.open(vis)
    if intent in mymsmd.intents():
        if returnBoolean:
            result = True
        else:
            result = len(mymsmd.fieldsforintent(intent))
    else: 
        if returnBoolean:
            result = False
        else:
            result = 0
    if needToClose:
        mymsmd.close()
    return result

def checksourceImage(vis, img, radius=15):
    """
    Accepts a measurement set and an image of a calibrator and
    reports the difference between the imfitted position (in the central 30 pixel
    diameter) and the catalog position.
    radius: in pixels
    -Todd Hunter
    """
    if not os.path.exists(vis):
        print("Could not find measurement set: ", vis)
        return
    if not os.path.exists(img):
        print("Could not find image: ", vis)
        return
    info = getFitsBeam(img)
    synthBeam = (info[0]*info[1])**0.5
    sourcename = imageSource(img)
    imsize = info[5]  # size in RA direction
    region = 'circle[[%dpix , %dpix], %dpix ]' % (imsize/2,imsize/2, radius)
    imagefit = imfit(imagename=img, region=region)
    fitresults = imfitparse(imagefit)

    # Compare the Positions
    mymsmd = createCasaTool(msmdtool)
    mymsmd.open(vis)
    fields = mymsmd.fieldsforname(sourcename)
    phasepos = mymsmd.phasecenter(fields[0])
    phasepos_obs = direction2radec(phasepos)
    print("Using field %d = %s = %s" % (fields[0], sourcename, phasepos_obs))
    if len(fields) > 1:
        for f in fields[1:]:
            pc = mymsmd.phasecenter(f) 
            if pc != phasepos_obs:
                print("Multiple fields with different directions: ", direction2radec(pc))
    mymsmd.close()
    if fitresults is not None:
        phasepos_fit = ','.join(fitresults.split()[:2])
        phasepos_diff = angularSeparationOfStrings(phasepos_obs,phasepos_fit,verbose=False, returnComponents=True)
        separation, longsep, latsep, longsepcosdec, posangle = phasepos_diff
        separation *= 3600
        latsep *= 3600
        longsepcosdec *= 3600
        line = "%s: Position difference = %s arcsec = %s synth.beam: (%+.3f,%+.3f) PA=%.1fdeg"%(sourcename, roundFiguresToString(separation,3), roundFiguresToString(separation/synthBeam,3), longsepcosdec, latsep, posangle)
    else:
        line = "%s: imfit failed" % (phase)
    print(line)

def checksourceOffset(workingdir, vis='', plotfile='', imfitlog=False, spw=''):
    """
    Takes a pipeline working directory and find all images of the checksource 
    and produces a plot showing the relative directions of the first science 
    target, the phase calibrator, and the checksource, and a vector
    showing the offset of the checksource from its catalog position, and
    text showing the RAO and DECO offsets.
    workingdir: path to pipeline working directory
    vis: alternate location for a measurement set to consult (ignores *_target.ms)
    Looks first for *chk*iter2.image; if not found, then *chk*iter1.image
    plotfile: default = img+'_offset.png'
    imfitlog: if True, then tell imfit to generate log files (*.imfit')
    spw: int or comma-delimited string, if specified, limit to this or these spws
    """
    return checksource.offset(workingdir, vis, plotfile, imfitlog, spw)

def angularSeparationPhaseScience(vis, mymsmd=None, verbose=False):
    """
    Computes angular separation of first phase cal from first science target
    """
    if (not os.path.exists(vis)):
        print("vis does not exist = ", vis)
        return
    needToClose = False
    if mymsmd == '' or mymsmd is None:
        needToClose = True
        mymsmd = createCasaTool(msmdtool)
        mymsmd.open(vis)
    scienceTargets = getScienceTargets(vis, mymsmd=mymsmd)
    scienceTargets = np.unique(scienceTargets)
    phasecal = getScienceTargets(vis, 'CALIBRATE_PHASE#ON_SOURCE', mymsmd)
    nscience = len(scienceTargets)
    if nscience < 1:
        print("No science targets")
        if needToClose: mymsmd.close()
        return
    elif nscience > 1:
        print("Using first science target: ", scienceTargets[0])
    nphase = len(phasecal)
    if nphase < 1:
        print("No phase calibrator")
        if needToClose: mymsmd.close()
        return
    elif nphase > 1:
        print("Using first of %d phase targets" % nphase)
    sep = angularSeparationOfFields(vis, [scienceTargets[0], phasecal[0]], strict=True, allMosaicFields=False)
    return sep

def elevationSeparationPhaseScience(vis, mymsmd='', verbose=False, returnSeparation='signed'):
    """
    Determines the first phase calibrator and computes mean elevation separation
    to each science target using elevationSeparationOfFields and computes median.
    vis: name of measurement set, or 'working' directory in which case the first EB will be chosen
    returnSeparation: 'signed' or 'unsigned'
    verbose: if True, then also print("phase (%s) - science %d (%s): %.2f deg (%s)")
    -Todd Hunter
    """
    if (not os.path.exists(vis)):
        print("vis does not exist = ", vis)
        return
    if vis.find('/working') > 0:
        vislist = sorted(glob.glob(os.path.join(vis,'uid___A002*ms')))
        # remove the _targets.ms and _targets_line.ms
        vislist = np.unique([vis.split('.ms')[0].split('_targets')[0]+'.ms' for vis in vislist])
        vis = vislist[0]
        print("Picked first of %d measurement sets: %s" % (len(vislist),os.path.basename(vis)))
    needToClose = False
    if mymsmd == '':
        needToClose = True
        mymsmd = createCasaTool(msmdtool)
        mymsmd.open(vis)
    scienceTargets = getScienceTargets(vis, mymsmd=mymsmd)
    scienceTargets = np.unique(scienceTargets)
    phasecal = getScienceTargets(vis, 'CALIBRATE_PHASE#ON_SOURCE', mymsmd)
    nscience = len(scienceTargets)
    if nscience < 1:
        print("No science targets")
        if needToClose: mymsmd.close()
        return
    nphase = len(phasecal)
    if nphase < 1:
        print("No phase calibrator")
        if needToClose: mymsmd.close()
        return
    elif nphase > 1:
        print("Using first of %d phase targets" % nphase)
    seps = []
    for i,science in enumerate(scienceTargets):
        sep = elevationSeparationOfFields(vis, [science, phasecal[0]], mymsmd=mymsmd, 
                                          exclusive=True, verbose=verbose, returnSeparation=returnSeparation)
        if sep > 0: 
            sense = "science lower than phasecal"
        else:
            sense = "science higher than phasecal"
        if verbose:
            print("phase (%s) - science %d (%s): %.2f deg (%s)" % (phasecal[0], i,science,sep, sense))
        seps.append(sep)
    if needToClose: mymsmd.close()
    return np.median(seps)

def elevationSeparationBandpassScience(vis, mymsmd='', verbose=False, returnSeparation='unsigned', returnAirmass=True):
    """
    Determines the first bandpass calibrator and computes the (per-scan) mean 
    elevation separation to each science target using 
    au.elevationSeparationOfFields and computes median.
    vis: name of measurement set, or 'working' directory in which case the first EB will be chosen
    returnSeparation: 'signed' or 'unsigned'
    returnAirmass: if True, then also return absolute delta of airmass
    verbose: if True, then also print("bandpass (%s) - science %d (%s): %.2f deg (%s)")
    Returns: either 1 value (separation in deg) or 2 (separation in deg, airmass)
    -Todd Hunter
    """
    if (not os.path.exists(vis)):
        print("vis does not exist = ", vis)
        return
    if vis.find('/working') > 0:
        vislist = sorted(glob.glob(os.path.join(vis,'uid___A002*ms')))
        # remove the _targets.ms and _targets_line.ms
        vislist = np.unique([vis.split('.ms')[0].split('_targets')[0]+'.ms' for vis in vislist])
        vis = vislist[0]
        print("Picked first of %d measurement sets: %s" % (len(vislist),os.path.basename(vis)))
    needToClose = False
    if mymsmd == '':
        needToClose = True
        mymsmd = createCasaTool(msmdtool)
        mymsmd.open(vis)
    scienceTargets = getScienceTargets(vis, mymsmd=mymsmd)
    scienceTargets = np.unique(scienceTargets)
    phasecal = getScienceTargets(vis, 'CALIBRATE_BANDPASS#ON_SOURCE', mymsmd)
    nscience = len(scienceTargets)
    if nscience < 1:
        print("No science targets")
        if needToClose: mymsmd.close()
        return
    nphase = len(phasecal)
    if nphase < 1:
        print("No phase calibrator")
        if needToClose: mymsmd.close()
        return
    elif nphase > 1:
        print("Using first of %d phase targets" % nphase)
    seps = []; airmassSeps = []
    for i,science in enumerate(scienceTargets):
        result = elevationSeparationOfFields(vis, [science, phasecal[0]], mymsmd=mymsmd, 
                                          exclusive=True, verbose=verbose, returnSeparation=returnSeparation,
                                          returnAirmass=returnAirmass)
        if returnAirmass and result is not None:
            if type(result) in [list, tuple]:
                sep, airmassSep = result
                airmassSeps.append(airmassSep)
            else:
                sep = result
        else:
            sep = result
        if result is not None:
#            print("sep = ", sep)
            if sep > 0: 
                sense = "science lower than bandpass"
            else:
                sense = "science higher than bandpass"
            if verbose:
                print("bandpass (%s) - science %d (%s): %.2f deg (%s)" % (phasecal[0], i,science,sep, sense))
            seps.append(sep)
    if needToClose: mymsmd.close()
    if len(seps) < 1:
        return None
    if returnAirmass:
        if len(airmassSeps) > 0:
            return np.median(seps), np.median(airmassSeps)
        else:
            return np.median(seps), 0
    else:
        return np.median(seps)

def elevationSeparationOfFields(vis, fields=[], verbose=True, value='mean',
                                exclusive=False, mymsmd='', returnSeparation='', returnAirmass=False):
    """
    Reads an ms and computes the mean of the per-scan elevation separation 
    of all combinations of fields, or if the fields parameter is given, only 
    those field names or IDs specified in the fields parameter, which can be 
    either a list of IDs or names, or an individual ID or name.
    value: 'all' (for per-scan mean) or 'mean' (for global mean)
           'all' only works if there is an equal number of scans per field
    exclusive: if True, then only report the separation between the listed fields
    returnSeparation: '', 'signed', 'unsigned'
    Returns:
    The field ID of the field with minimum separation from the specified field.
    if returnSeparation != '', then instead return the (minimum) separation 
       in degrees.  The sense of the subtraction is field2 - field1.
       if returnAirmass == True, then also return the minimum airmass separation
    -- Todd Hunter
    """
    if (not os.path.exists(vis)):
        print("vis does not exist = ", vis)
        return
    fieldTable = vis+'/FIELD'
    if (not os.path.exists(fieldTable)):
        print("FIELD table does not exist = ", fieldTable)
        return
    if (type(fields) != list):
        fields = [fields]
    mytb = createCasaTool(tbtool)
    mytb.open(fieldTable)
    name = mytb.getcol('NAME')
    if verbose: print("Field =              Names                 Separations")
    sid = mytb.getcol('SOURCE_ID')
    pos = mytb.getcol('PHASE_DIR')
    mytb.close()
    pos = np.transpose(pos)
    nfields = len(pos)
    needToClose = False
    if mymsmd == '':
        needToClose = True
        mymsmd = createCasaTool(msmdtool)
        mymsmd.open(vis)
    minSeparation = 1e9
    minSeparationSigned = 1e9
    airmassSep = None
    fieldWithMinimumSeparation = 0
    if exclusive:
        myfieldlist = fields
    else:
        myfieldlist = range(nfields)
    for ith,i in enumerate(myfieldlist):
        if exclusive:
            myfieldlist2 = myfieldlist[ith+1:]
        else:
            myfieldlist2 = range(i+1,len(pos))
        for j in myfieldlist2:
            if (fields == [] or fields == [''] or (i in fields or j in fields) or
                (name[i] in fields or name[j] in fields)):
                result = listazel(vis, mymsmd.scansforfield(i),verbose=False,
                                  value=value, mymsmd=mymsmd)
                if result is None:
                    return
                az, el = result
                azj, elj = listazel(vis, mymsmd.scansforfield(j),verbose=False,
                                    value=value, mymsmd=mymsmd)
                if value == 'all':
                    if (len(azj) != len(az)):
                        print("value='all' only works if there are equal number of scans on the fields")
                        return
                degrees = np.mean(np.abs(elj-el))
                if (degrees < minSeparation):
                    minSeparation = degrees
                    minSeparationSigned = np.mean(elj-el)
                    airmassSep = np.median(elevationToAirmass(elj) - elevationToAirmass(el))
                    if (i in fields):
                        fieldWithMinimumSeparation = j
                    elif (j in fields):
                        fieldWithMinimumSeparation = i
                arcsec = 3600*degrees
                if verbose:
                    print("%02d-%02d = %15s-%15s: %8g deg = %8g arcsec" % (i,j,name[i],name[j],degrees,arcsec))
    if needToClose: mymsmd.close()
    if verbose: print("minimum separation = %f degrees" % (minSeparation))
    if returnSeparation == 'signed':
        if returnAirmass and airmassSep is not None:
            return(minSeparationSigned, airmassSep)
        else:
            return(minSeparationSigned)
    elif returnSeparation == 'unsigned':
        if returnAirmass and airmassSep is not None:
            return(minSeparation, airmassSep)
        else:
            return(minSeparation)
    else:
        return(fieldWithMinimumSeparation)

def angularSeparationOfScans(vis, scans=[], skipConsecutive=True,
                             observatory='ALMA', verbose=False, forceVM=False):
    """
    Reads an ms and computes the angular separation of each transition between
    scans.  If only one pair of scans is given, then return the angle in 
    degrees.
    -- Todd Hunter
    """
    if (os.path.exists(vis) == False):
        print("ms does not exist = ", vis)
        return
    if (os.path.exists(vis+'/table.dat') == False):
        print("No table.dat.  This does not appear to be an ms.")
        return
    if (type(scans) != list):
        print("The scans parameter must be a list.")
        return
    if (len(scans) == 1):
        print("You must give at least two scans (or none, which means all).")
        return
    if (casaVersion >= casaVersionWithMSMD and forceVM==False):
        mymsmd = createCasaTool(msmdtool)
        mymsmd.open(vis)
        if (scans == []):
            scans = callscannumbers(mymsmd)
            if (verbose): print("scans = ", scans)
        fieldsForScans = []
        timesForScans = []
        for j in scans:
            fieldsForScans.append(mymsmd.fieldsforscan(j)[0]) # assume first field
            timesForScans.append(mymsmd.timesforscans(j))
            if (verbose):
                print("type(j) = ", str(type(j)))
                print("type(tfs) = ", str(type(timesForScans[-1])))
                print("timesForScans (scan=%d)" % (int(j)))
                print(list(timesForScans[-1]))  # will crash unless you convert to list
        mymsmd.close()
    else:
        vm = ValueMapping(vis)
        if (scans == []):
            scans = vm.uniqueScans
        fieldNamesForScans = vm.getFieldsForScans(scans)
        fieldsForScans = []
        for fn in fieldNamesForScans:
            fieldsForScans.append(vm.getFieldIdsForFieldName(fn)[0]) # assume first field
        timesForScans = vm.getTimesForScans(scans)
    if (verbose):
        print("%d scans = " % (len(scans)), scans)
        print("%d fieldsForScans = " % (len(fieldsForScans)), fieldsForScans)
    mytb = createCasaTool(tbtool)
    mytb.open(vis+'/FIELD')
    name = mytb.getcol('NAME')
    print("                                      Angular separations")
    print("Scan slew         Field Names      on-the-sky (deg)  (arcsec)  dAz(deg) dEl(deg)")
    pos = mytb.getcol('PHASE_DIR')
    mytb.close()
    pos = np.transpose(pos)
    linesShown = 0
    for i in range(len(scans)-1):
        field = []
        field.append(fieldsForScans[i])
        field.append(fieldsForScans[i+1])
        radians = angularSeparationRadiansTuples(pos[field[0]][0], pos[field[1]][0])
        degrees = radians*180/np.pi
        if (degrees == 0 and skipConsecutive): continue
        linesShown += 1
        arcsec = 3600*degrees
        mjd = []
        mjd.append(np.max(timesForScans[i])/86400.)
        mjd.append(np.min(timesForScans[i+1])/86400.)
        if (verbose):
            print("Computing separation of field %d-%d at %.5f-%.5f" % (field[0], field[1], mjd[0], mjd[1]))
        azel = []
        for j in range(2):
            azel.append(computeAzElFromRADecMJD(pos[field[j]][0],mjd[j],observatory=observatory,verbose=False))
        deltaaz = (azel[1][0]-azel[0][0])*180/np.pi
        deltael = (azel[1][1]-azel[0][1])*180/np.pi
        outline = "%02d-%02d = %14s to %14s %8g = %8g %+8.3f %+8.3f" % (scans[i],scans[i+1],name[fieldsForScans[i]],name[fieldsForScans[i+1]]+' '*(15-len(name[fieldsForScans[i+1]])),degrees,arcsec,deltaaz,deltael)
        if (verbose):
            outline += "  %.5f %.5f" % (mjd[0],mjd[1])
        print(outline)
    if (linesShown == 0):
        print("*** Specified scans are all on the same field position. ***")
        print("Set skipConsecutive=False to show all transitions.")
    if (len(scans) == 2):
        return(degrees)

def medianWavelengthOfIntent(vis, intent='OBSERVE_TARGET#ON_SOURCE', 
                             verbose=False, ignoreChanAvgSpws=True):
    """
    Calls medianFrequencyOfIntent and returns wavelength in meters.
    -Todd Hunter
    """
    frequency = medianFrequencyOfIntent(vis, intent, verbose, 
                                        ignoreChanAvgSpws)
    return c_mks/frequency

def medianFrequencyOfIntent(vis, intent='OBSERVE_TARGET#ON_SOURCE', 
                            verbose=False, ignoreChanAvgSpws=True, mymsmd=None):
    """
    Returns the median of the mean frequency (in Hz) of the spws observed with
    the specified intent (default = OBSERVE_TARGET#ON_SOURCE).
    ignoreChanAvgSpws: if True, then ignore single channel spws, unless they 
                       are the only ones present!
    -Todd Hunter
    """
    if (not os.path.exists(vis)):
        print("Could not find measurement set: ", vis)
        return
    if (casaVersion >= casaVersionWithMSMD):
        needToClose = False
        if mymsmd is None:
            mymsmd = createCasaTool(msmdtool)
            mymsmd.open(vis)
            needToClose =  True
        try:
            if intent == '':
                spws = getNonWvrSpws(mymsmd)
            else:
                if len(mymsmd.intents()) == 0:
                    print("There are no intents in this dataset.")
                    return None
                spws = callspwsforintent(mymsmd, intent)
            wvrspws = mymsmd.wvrspws()
            if len(wvrspws) > 0:
                if mymsmd.namesforspws(wvrspws[0])[0].find('VLA') >= 0:
                    wvrspws = []
            spws = list(set(spws).difference(set(wvrspws)))
            myspws = spws[:]
            if (ignoreChanAvgSpws):
                spws = list(set(spws).difference(set(callalmaspws(mymsmd,chavg=True))))
                if (len(spws) == 0):
                    spws = list(set(myspws).difference(set(mymsmd.wvrspws())))
        except:
            spws = []
        if (len(spws) < 1):
            print("medianFrequencyOfIntent(): No spws with intent = '%s'" % (intent))
            print("intents = ", mymsmd.intents())
            if needToClose: mymsmd.close()
            return None
        if verbose: print("spws = ", spws)
        freq = []
        for spw in spws:
            freq.append(mymsmd.meanfreq(spw))
            if verbose: print("spws %d = %f GHz" % (spw,freq[-1]*1e-9))
        if needToClose: mymsmd.close()
    else:
        vm = ValueMapping(vis)
        spws = vm.getSpwsForIntent(intent)
        if (len(spws) < 1):
            print("medianFrequencyOfIntent(): No spws with intent = '%s'" % (intent))
            return None
        if verbose: print("spws = ", spws)
        freq = []
        for spw in spws:
            if (spw in list(vm.spwInfo.keys())):
                if verbose: print("spw = %d, " % (spw), vm.spwInfo[spw])
                freq.append(vm.spwInfo[spw]['meanFreq'])
    return(np.median(freq))

def rotationEuler(Pl, rLong, rLat):
    Ps = [np.cos(rLong)*np.cos(rLat)*Pl[0] - np.sin(rLong)*Pl[1] - np.cos(rLong)*np.sin(rLat)*Pl[2],
          np.sin(rLong)*np.cos(rLat)*Pl[0] + np.cos(rLong)*Pl[1] - np.sin(rLong)*np.sin(rLat)*Pl[2],
          np.sin(rLat)*Pl[0]                                     + np.cos(rLat)*Pl[2]]
    return(Ps)

def radecOffsetFileToRadec(filename, origin, raColumn=0, decColumn=1, velocityColumn=None,
                           intensityColumn=None, delimiter=' ', output='',
                           rao=0, deco=0, mas=False, outputDegrees=False):
    """
    Converts an ASCII file of RA/Dec offsets in arcseconds into absolute coordinates.
    Lines beginning with # are ignored. Commas and spaces are ignored in data lines.
    filename: ASCII file
    origin: absolute coordinate for the offset origin as RADec string, e.g. 'hh:mm:ss.ssss +dd:mm:ss.sss'
    delimiter: the string to use to delimit the RA and Dec strings output
    rao, deco: additional offset to apply (in arcseconds)
    mas: if True, then interpret offsets as milliarcsecond instead of arcsec
    outputDegrees: if True, then write out RA and Dec in degrees instead of sexagesimal
    """
    f = open(filename,'r')
    lines = f.readlines()
    f.close()
    if output == '':
        output = filename + '.j2000'
    o = open(output,'w')
    for line in lines:
        if line[0] == '#': continue
        line = line.replace(',',' ')
        token = line.split()
        myrao = float(token[raColumn])
        mydeco = float(token[decColumn])
        if mas:
            myrao *= 0.001; mydeco *= 0.001
        myrao += rao
        mydeco += deco
        if velocityColumn is not None:
            velocity = ' %s' % (token[velocityColumn])
        else:
            velocity = ''
        if intensityColumn is not None:
            intensity = ' %s' % (token[intensityColumn])
        else:
            intensity = ''
        myPosition = radecOffsetToRadec(origin, myrao, mydeco, verbose=False, delimiter=delimiter)
        if outputDegrees:
            myPosition = radec2deg(myPosition, True, delimiter)
        o.write(myPosition+velocity+intensity+'\n')
    o.close()
    print("Wrote ", output)

def radecOffsetToRadec(radec, rao, deco, replaceDecDotsWithColons=True,
                       mas=False, prec=5, useEulerAngles=True, verbose=True,
                       delimiter=', ',hms=False):
    """
    Converts an absolute J2000 position and offset into a new absolute position.
    radec: either a string ('hh:mm:ss.s dd:mm:ss') or a tuple of radians
    rao, deco: offset in arcseconds (floating point values)
    replaceDotsWithColons: change CASA's Dec string from xx.yy.zz to xx:yy:zz
    mas: if True, then treat rao and deco as milliarcsec
    prec: desired number of digits of precision after the seconds decimal point
    delimiter: string to use between RA and Dec
    useEulerAngles: if True, then use the expression of the control system;
      if False, then use the small-angle formula:   RAnew = RA + deltaRA/cos(Dec)
    hms: if True, then output HHhMMmSS.Ss +DDdMMmSS.Ss instead of using colons
    Returns: a sexagesimal string
    """
    if (type(radec) in [str, np.bytes_]):
        rarad, decrad = radec2rad(radec)
    elif (type(radec) == list):
        if type(radec[1]) in [str, np.bytes_]:
            if radec[1].find('J2000')==0:
                radec[1] = radec[1].replace('J2000','')
        rarad, decrad = radec
    else:
        print("type(radec) = ", type(radec))
        print("radec must be either a string ('hh:mm:ss.s dd:mm:ss') or a list in radians [ra,dec]")
        return
    if (mas):
        rao *= 0.001
        deco *= 0.001
    rao = np.radians(rao/3600.)
    deco = np.radians(deco/3600.)
    if useEulerAngles:
        Pl = [np.cos(rao)*np.cos(deco), np.sin(rao)*np.cos(deco), np.sin(deco)]
        Ps = rotationEuler(Pl, rarad, decrad)
        newrarad = np.arctan2(Ps[1], Ps[0])
        if (newrarad < 0): newrarad += 2*np.pi
        newdecrad = np.arcsin(Ps[2])
    else:
        newrarad = rarad + rao/np.cos(decrad)
        newdecrad = decrad + deco
    mystring = rad2radec(newrarad, newdecrad, replaceDecDotsWithColons=replaceDecDotsWithColons,
                         prec=prec, verbose=verbose, delimiter=delimiter, hmsdms=hms)
    return(mystring)
           
def angularSeparationOfAllPlanetsFromSun(date='', observatory=JPL_HORIZONS_ID['ALMA'], 
                                         useJPL=True, verbose=False, extraobjects=['Pluto']):
    """
    Computes the current angular separation of the major planets from the Sun
    (in degrees) at 0 UT on the specified date.
    -Todd Hunter
    """
    separation = {}
    if date=='':
        date = getCurrentDate()
    for planet in ['Mercury','Venus','Mars','Jupiter','Saturn','Uranus','Neptune'] + extraobjects:
        separation[planet] = np.degrees(angularSeparationOfPlanets('Sun',planet,date,observatory,useJPL))
    return separation

def angularSeparationOfPlanets(planet1='', planet2='', date='',
             observatory=JPL_HORIZONS_ID['ALMA'], useJPL=True, target=None,
             returnComponents=False, verbose=False, vis='', bodyForScan='',
             frequency=None, diameter=None, returnLimbSeparation=False, 
                               asdm=''):
    """
    Computes the current angular separation of two planets at 0 UT on the 
    current date, or the exact specified date string.  Default viewing 
    location is ALMA.
    If 'target' is specified as a valid RA/Dec, then the separation between 
    it and planet1 will be computed.
    If 'vis' is specified, then it will use the time of the first scan on the
    target, or the start time of the ms if neither target is not found.
    If 'asdm' is specified, and planet1 and planet2 are blank, and Titan or 
       one of the 4 largest Jovian moons is found to be an observed field, 
       then Saturn or Jupiter is assigned as planet 1.
    If 'vis' is specified, and planet1 and planet2 are blank, and Titan is
       found to be an observed field, then Titan is assigned as planet1 and
       Saturn is assigned as planet 2.
    If 'vis' is specified, and planet1 and planet2 are blank, and Titan is not
       found to be an observed field, then Jupiter is assigned as planet 2.
    'bodyForScan' is passed to both calls to planet() to pick time of first scan
    If 'frequency' and 'diameter' are specified, these are passed to
       primaryBeamArcsec() to compute the separation in beam diameters.
    If 'vis' is specified, it will use the median dish diameter and median
       of the mean frequencies of the OBSERVE_TARGET spws.
    Required format for target:  HH[:MM:SS.S]  [+]DD[:MM:SS.S]
    date: one possible format of the date string is: '2011-10-31 11:59:59'
          or simply '2011-10-31' for 0:00 UT. A list of allowed formats for date
          is at:   http://ssd.jpl.nasa.gov/?horizons_doc#time
          
    Returns: the separation value in radians.  If the primary beam is known, it
      also returns the value in primary beam units, and a Boolean value telling
      whether it is safe to use the object as amplitude calibrator (>2*beam+25'').
    returnComponents: if True, then compute angular separation in both
         coordinates and the position angle of the separation vector on the sky
    Todd Hunter
    """
    if (planet1 == '' or planet2 == ''):
        if (vis == '' and asdm == ''):
            print("You must either specify planet1 and planet2, or asdm or vis")
            return
        elif (vis != ''):
            fields = getFields(vis)
            fieldsUpperCase = [x.upper() for x in fields]
            checkObjects = ['TITAN','CALLISTO','GANYMEDE','IO','EUROPA']
            for object in checkObjects:
                if (object in fieldsUpperCase):
                    planet1 = object
                    bodyForScan = object
                    break
            if (planet1 == ''):
                print("None of these satellites were observed: ", checkObjects)
                return
            if (planet1 == 'TITAN'):
                planet2 = 'SATURN'
            else:
                planet2 = 'JUPITER'
        elif (asdm != ''):
            fields = list(getEphemerisFieldsFromASDM(asdm).keys())
            if len(fields) > 1:
                planet1 = fields[0]
                planet2 = fields[1]
            elif fields[0] == 'Titan':
                planet1 = 'Saturn'
                planet2 = 'Titan'
            elif fields[0] in ['Ganymede','Io','Europa','Callisto']:
                planet1 = 'Jupiter'
                planet2 = fields[0]
            else:
                print("This planet is not yet implemented")
                return
    data1 = planet(planet1, date=date, observatory=observatory, useJPL=useJPL, verbose=verbose,vis=vis, bodyForScan=bodyForScan, asdm=asdm)
    if (data1 == None): return
    if (target == None):
        data2 = planet(planet2, date=date, observatory=observatory, useJPL=useJPL, verbose=verbose,vis=vis, bodyForScan=bodyForScan, asdm=asdm)
    else:
        results = target.split()
        if (len(results) != 2):
            print("Required format for target:  HH[:MM:SS.S]  [+]DD[:MM:SS.S]")
            return
        ra,dec = results
        if (ra.find(':') > 0):
            ratokens = ra.split(':')
            ra = float(ratokens[0])
            if (ratokens > 1):
                ra += float(ratokens[1])/60.
            if (ratokens > 2):
                ra += float(ratokens[2])/3600.
        else:
            print("Required format for target:  HH[:MM:SS.S]  [+]DD[:MM:SS.S]")
            return
        
        if (dec.find(':') > 0):
            dectokens = dec.split(':')
            dec = abs(float(dectokens[0]))
            if (dectokens > 1):
                dec += float(dectokens[1])/60.
            if (dectokens > 2):
                dec += float(dectokens[2])/3600.
            if (dectokens[0].find('-') >= 0):
                dec = -dec
        else:
            print("Required format for target:  HH[:MM:SS.S]  [+]DD[:MM:SS.S]")
            return
        data2 = {'directionRadians': [float(ra)*np.pi/12.0, float(dec)*np.pi/180]}
#    print data1['directionRadians'][0], data1['directionRadians'][1], data2['directionRadians'][0], data2['directionRadians'][1]
    result = angularSeparationRadians(data1['directionRadians'][0], data1['directionRadians'][1], 
                                      data2['directionRadians'][0], data2['directionRadians'][1], returnComponents)
    if (returnComponents):
        rad, raRadians, decRadians, raRadiansCosDec = result
        positionAngle = 90-np.degrees(math.atan2(decRadians, raRadiansCosDec))
        print("RA Separation: radian = %g, degrees = %f, arcsec = %f" % (raRadiansCosDec, 
                                                                         np.degrees(raRadiansCosDec),
                                                                         np.degrees(raRadiansCosDec)*3600))
        print("Dec Separation: radian = %g, degrees = %f, arcsec = %f" % (decRadians, 
                                                                          np.degrees(decRadians),
                                                                          np.degrees(decRadians)*3600))
        print("Position angle: %g deg E of N" % (positionAngle))
    else:
        rad = result
    print("Separation of centers = %g rad = %g deg = %g arcsec" % (rad, rad*180/math.pi, rad*3600*180/math.pi))
    print("RA separation of centers = %g hours" % (12*(data1['directionRadians'][0] - data2['directionRadians'][0])/math.pi))
    radLimbs = rad-np.radians(0.5*(data1['angularDiameter']+data2['angularDiameter'])/3600.)
    print("Separation of limbs = %g rad = %g deg = %g arcsec" % (radLimbs, radLimbs*180/math.pi, radLimbs*3600*180/math.pi))
    if (returnLimbSeparation):
        rad = radLimbs
    if (vis != '' or (frequency!=None and diameter!=None)):
        if (vis != ''):
            primaryBeam = primaryBeamArcsec(vis=vis, showEquation=False)
        else:
            primaryBeam = primaryBeamArcsec(frequency=frequency, diameter=diameter, showEquation=False)
        beams = rad*3600*180/math.pi / primaryBeam
        print("%.1f primary beams" % (beams))
        separationArcsec = rad*3600*180/math.pi
        if (separationArcsec > 2*primaryBeam + 25):  # 25 is the kludged value used by CSV for planet half-diameter
            safe = True
        else:
            safe = False
        return(result, beams, safe)
    else:
        return(result)
    
def angularSeparationOfDirections(dir1,dir2,returnComponents=False):
    """
    Accepts two direction dictionaries and returns the separation in radians.
    It computes great circle angle using the Vincenty formula.
    --Todd Hunter
    """
    rad = angularSeparationRadians(dir1['m0']['value'], dir1['m1']['value'], dir2['m0']['value'], dir2['m1']['value'],returnComponents)
    return(rad)

def angularSeparationOfDirectionsArcsec(dir1,dir2,returnComponents=False):
    """
    Accepts two direction dictionaries and returns the separation in arcsec.
    It computes great circle angle using the Vincenty formula.
    Todd Hunter
    """
    retval = angularSeparationOfDirections(dir1, dir2, returnComponents)
    if (returnComponents):
        retval = np.array(retval) * 180*3600 / np.pi
    else:
        retval *= 180*3600 / np.pi
    return(retval)

def angularSeparationRadiansTuples(pos0,pos1,returnComponents=False):
    """
    Computes the great circle angle between two celestial coordinates.
    using the Vincenty formula (from wikipedia) which is correct for all
    angles, as long as you use atan2() to handle a zero denominator.  
       See  http://en.wikipedia.org/wiki/Great_circle_distance
    Input and output are in radians.  The input must be in the form of
    tuples: [ra0,dec0], [ra1,dec1], such as read from the FIELD table.
    It also works for the az,el coordinate system.
    returnComponents=True will return: [separation, raSeparation, decSeparation, raSeparationCosDec]
    See also angularSeparation() and angularSeparationRadians().
    """
    return(angularSeparationRadians(pos0[0],pos0[1], pos1[0],pos1[1],returnComponents))
           
def angularSeparationRadians(ra0,dec0,ra1,dec1,returnComponents=False,returnPositionAngle=False):
  """
  Computes the great circle angle between two celestial coordinates.
  using the Vincenty formula (from wikipedia) which is correct for all
  angles, as long as you use atan2() to handle a zero denominator.  
     See  http://en.wikipedia.org/wiki/Great_circle_distance
  Input and output are in radians.  It also works for the az,el coordinate system.
  returnComponents=True will return: [separation, raSeparation, decSeparation, raSeparationCosDec]
     if returnPositionAngle is also True, it will return:
        [separation, raSeparation, decSeparation, raSeparationCosDec, positionAngleRadians]
  See also angularSeparation()
  -- Todd Hunter
  """
  result = angularSeparation(ra0*180/math.pi, dec0*180/math.pi, ra1*180/math.pi, dec1*180/math.pi,returnComponents,returnPositionAngle)
  if (returnComponents):
      return(np.radians(np.array(result)))
  else:
      return(np.radians(result))

def angularSeparationOfStringsFromFile(filename, verbose=True, arcsec=False, kpc=None,
                                       radec=None, returnDict=False, arcmin=False):
    """
    Reads a text file and sends each line to angularSeparationOfStrings after
    stripping off the leading source name.  Required format:
        sourcename RA1 Dec1 RA2 Dec2 optional_comments
    where the sexagesimal components of RA/Dec can be either colon-delimited
    or space-delimited.
    radec: if specified, then use this single position as 'RA2 Dec2'
    returnDict: if True, then return a dictionary keyed by separation with
         values being the first token and the tokens after Dec2 (or after 
         Dec1 if radec!=None)
    Returns: an array of the separations in degrees, unless arcsec==True.
       or arcmin=True or if kpc is specified, in which case, the units are AU
    - Todd Hunter
    """
    if (os.path.exists(filename) == False):
        print("File not found.")
        return
    f = open(filename,'r')
    sep = []
    comment = []
    returnComponents = False  # True will return more than one value
    for line in f.readlines():
        tokens = line.split()
        name = tokens[0]
        line = ' '.join(tokens[1:]) # pull off the leading name
        line = line.replace(':',' ').replace('&',' ')
        tokens = line.split()
        if radec is None:
            comment.append(' '.join([name]+tokens[12:]).strip())
            sep.append(angularSeparationOfStrings(' '.join(tokens[:6]), ' '.join(tokens[6:12]),
                                                  returnComponents,verbose))
        else:
            comment.append(' '.join([name]+tokens[6:]).strip())
            sep.append(angularSeparationOfStrings(' '.join(tokens[:6]), radec,
                                                  returnComponents,verbose))
    f.close()
    result = np.array(sep)
    comment = np.array(comment)
    if (arcsec):
        result *= 3600
    elif arcmin:
        result *= 60
    elif (kpc is not None):
        result *= 3600*kpc*1000
    if returnDict:
        idx = np.argsort(result)
        result = result[idx]
        comment = comment[idx]
        mydict = {}
        for i in range(len(result)):
            mydict[result[i]] = comment[i]
        return mydict
    else:
        return(result)

def plotRandomErrors(nvalues=100000, bins=100, markPercentiles=[25,75], plotfile='', nsigma=[-2,5.5]):
    """
    Plots a Gaussian distribution of random numbers with sigma=1 (FWHM=2.355).
    Overlays vertical lines corresponding to two specified percentile scores, and
    subsequent thresholds, as used by computeUVThreshold for science target flagging in CASR-326.
    markPercentiles: a list of scores at which to draw red vertical dashed lines;
       the first two define a range of values
    nsigma: a list of factors to apply to the range of values in units of sigma
       whose product will be drawn as green vertical dashed lines
    -Todd Hunter
    """
    pb.clf()
    values = pickRandomErrors(nvalues)
    pb.hist(values,bins=bins)
    y = pb.ylim()[1]
    x = []
    for mP in markPercentiles:
        x.append(scoreatpercentile(values,mP))
        pb.plot(2*[x[-1]],[0,y],'r--')
    myrange = x[1]-x[0]
    for ns in nsigma:
        pb.plot(2*[ns*myrange], [0,y], 'g--')
        print("Plotting x=%f" % (ns*myrange))
    pb.title('red: percentiles of %s, green: %s*red_xrange' % (markPercentiles,nsigma))
    pb.xlabel('sigma')
    pb.ylabel('Number of occurrences')
    pb.draw()
    if plotfile != '':
        pb.savefig(plotfile)

def pickRandomErrors(nvalues=1, seed=None):
    """
    Picks a series of random values from a Gaussian distribution with mean 0 and standard 
    deviation = 1 and returns it as an array.
    -Todd Hunter
    """
    p = []
    for i in range(nvalues):
        if i>0:
            seed = None
        p.append(pickRandomError(seed))
    return(np.array(p))

def pickRandomError(seed=None):
    """
    Picks a random value from a Gaussian distribution with mean 0 and standard deviation = 1.
    seed: if specified, then first reseed with random.seed(seed)
    -Todd Hunter
    """
    w = 1.0
    if seed is not None:
        random.seed(seed)
    while ( w >= 1.0 ):
      x1 = 2.0 * random.random() - 1.0
      x2 = 2.0 * random.random() - 1.0
      w = x1 * x1 + x2 * x2

    w = np.sqrt( (-2.0 * np.log( w ) ) / w )
    y1 = x1 * w
    y2 = x2 * w
    return(y1)

def angularSeparationOfPB(vis, img, fieldname='', verbose=False):
    """
    Given a measurement set and a CASA image of the primary beam, computes the offset between 
    the primary beam center (defined by the peak of the pb image) and the phase center (defined 
    by au.getRADecForField which uses ms.getfielddirmeas).
    vis: measurement set
    img: CASA image of the primary beam
    fieldname: field name or integer ID or string ID; if blank, try to read it from img header
    -Todd Hunter
    """
    if not os.path.exists(vis):
        print("Could not find measurement set: ", vis)
        return
    if not os.path.exists(img):
        print("Could not find primary beam image.")
        return
    if fieldname == '':
        fieldname = imhead(img, mode='get', hdkey='object')
        if fieldname == '':
            fieldname = getScienceTargets(vis)
            if len(fieldname) == 0:
                print("No object name in image header and no science target in dataset. Please set fieldname parameter")
                return
            fieldname = fieldname[0]
        if verbose:
            print("Got fieldname = ", fieldname)
    iPeak = imagePeak(img, returnPosition='radec', verbose=verbose)[1]
    radec = getRADecForField(vis, fieldname, hms=True, verbose=verbose)
    separation, longsep, latsep, longsepcosdec, pa = angularSeparationOfStrings(iPeak, radec,
                                                                                returnComponents=True, verbose=verbose)
    result = getFitsBeam(img) #, omitBeam=True)
    longsep *= -1
    longsepcosdec *= -1
    print("   RA separation = %g deg = %g arcsec = %g pixels" % (longsepcosdec, longsepcosdec*3600, longsepcosdec*3600/abs(result[3])))
    print("  Dec separation = %g deg = %g arcsec = %g pixels" % (latsep, latsep*3600, latsep*3600/abs(result[4])))
    print("Total separation = %g deg = %g arcsec = %g pixels" % (separation, separation*3600, separation*3600/result[4]))
                                         

def angularSeparationOfStrings(radec0,radec1='',returnComponents=False,verbose=True,
                               uncertainties=None,date=None,observatory='ALMA',
                               returnArcsec=False, searchFluxVerbose=False, debug=False):
    """
    Accepts input of the form: '23:29:17.70000, -47:30:19.211595'
                            or '23:29:17.70000  -47:30:19.211595'
                            or '23:29:17.70000, -47.30.19.211595'
                            or '23:29:17.70000  -47.30.19.211595'
                            or '23 29 17.70000  -47 30 19.211595'
                            or '23h29m17.70000s -47d30m19.211595'
    and computes the angular separation.  Returns it in degrees.
    Leading spaces are removed from both coordinates.
    If radec1 is not specified, then radec0 must contain 4 values: 'ra0 dec0 ra1 dec1'
    If the first character is J/j/N/n/B/b or the second character is C/c, then it 
       calls searchFlux to translate the source name into an RA/Dec string.
    If a date is specified, it also converts the input
         coordinates to Az/El, then computes the deltaAz and deltaEl
    date: can be specified as a string, e.g. 2014-03-15T10:24:48.417
          or a float, which is interpreted as MJD
    If returnComponents==True, then it also returns the separation in 
       longitude and latitude, the longitude separation with cos(averageDec) applied,
       as well as the position angle (in degrees).
    If returnArcsec=True, return all separations in arcsec
    If uncertainties is a list of 4 numbers, then run a Monte-Carlo simulation 
      using these values as ra0unc, dec0unc, ra1unc, dec1unc (all in arcsec)
      and also return the standard deviations of the separation and the position angle
    """
    radec0 = radec0.replace('&',' ')  # allow pasting from Latex tables
    if radec1 == '':
        if len(radec0.split()) == 4:
            radec1 = ' '.join(radec0.split()[2:])
            radec0 = ' '.join(radec0.split()[:2])
        else:
            print("You must either specify radec1, or give 4 values in radec0.")
            return
    radec0 = radec0.replace('?','-')  # openoffice cut&paste mangles -- into ?
    radec0 = radec0.replace(';',' ')  # allow pasting from VLA Obsprep tool import/export files
    radec0 = radec0.replace('h',':')  # allow NED output table format
    radec0 = radec0.replace('d',':')  # allow NED output table format
    radec0 = radec0.replace('m',':')  # allow NED output table format
    radec0 = radec0.replace('s',' ')  # allow NED output table format
    radec1 = radec1.replace('&',' ')  # allow pasting from Latex tables
    radec1 = radec1.replace('?','-')  # openoffice cut&paste mangles -- into ?
    radec1 = radec1.replace(';',' ')  # allow pasting from VLA Obsprep tool import/export files
    radec1 = radec1.replace('h',':')  # allow NED output table format
    radec1 = radec1.replace('d',':')  # allow NED output table format
    radec1 = radec1.replace('m',':')  # allow NED output table format
    radec1 = radec1.replace('s',' ')  # allow NED output table format
    radec0 = radec0.strip()
    radec1 = radec1.strip()
    if (radec0[0].upper() in ['J','B','N'] or radec0[1].upper() in ['C']):
        radec0 = searchFlux(radec0, returnPosition=True, verbose=searchFluxVerbose)
    if (radec1[0].upper() in ['J','B','N'] or radec1[1].upper() in ['C']):
        radec1 = searchFlux(radec1, returnPosition=True, verbose=searchFluxVerbose)
    if (radec0.find(',')>0):
        (ra,dec) = radec0.split(',')
    else:
        tokens = radec0.split()
        if (len(tokens) == 2):
            (ra,dec) = tokens
        elif (len(tokens) == 6):
            ra = tokens[0] + ':' + tokens[1] + ':' + tokens[2]
            dec = tokens[3] + ':' + tokens[4] + ':' + tokens[5]
        else:
            print("Confusing input for first position.  Need either 2 or 6 tokens: ", radec0)
            return
    if debug:
        print("Processing ra1 = ", ra)
        print("Processing dec1 = ", dec)
    (h,m,s) = ra.lstrip().split(':')
    hours = float(h)+float(m)/60. + float(s)/3600.
    ra0 = hours*15

    if (dec.find(':')>0):
        (d,m,s) = dec.lstrip().split(':')
    else:
        try:
            (d,m,s) = dec.lstrip().split('.')
        except:
            (d,m,s,sfraction) = dec.lstrip().split('.')
            s = s+'.'+sfraction
    dec0 = abs(float(d))+float(m)/60.+float(s)/3600.
    if (dec.lstrip().find('-') == 0):
        dec0 = -dec0

    if (radec1.find(',') > 0):
        (ra,dec) = radec1.split(',')
    else:
        tokens = radec1.split()
        if (len(tokens) == 2):
            (ra,dec) = tokens
        elif (len(tokens) == 6):
            ra = tokens[0] + ':' + tokens[1] + ':' + tokens[2]
            dec = tokens[3] + ':' + tokens[4] + ':' + tokens[5]
        else:
            print("Confusing input for second position.  Need either 2 or 6 tokens")
            return
    if debug:
        print("Processing ra2 = ", ra)
        print("Processing dec2 = ", dec)
    (h,m,s) = ra.lstrip().split(':')
    hours = float(h)+float(m)/60. + float(s)/3600.
    if (dec.find(':') > 0):
        (d,m,s) = dec.lstrip().split(':')
    else:
        try:
            (d,m,s) = dec.lstrip().split('.')
        except:
            (d,m,s,sfraction) = dec.lstrip().split('.')
            s = s + '.' + sfraction
    dec1 = abs(float(d))+float(m)/60.+float(s)/3600.
    if (dec.lstrip().find('-') == 0):
        dec1 = -dec1
    ra1 = hours*15
#    print ra0/15., dec0, ra1/15., dec1
    if (returnComponents):
        if (uncertainties is not None):
            if (len(uncertainties) != 4):
                print("uncertainties must be a list of 4 values in arcsec")
                return
            trials = 1000
        else:
            trials = 1
            dra0 = 0
            dra1 = 0
            ddec0 = 0
            ddec1 = 0
        degArray = []
        raArray = []; radegreesCosDecArray = []
        decArray = []
        positionAngleArray = []
        for t in range(trials):
            if (uncertainties is not None):
                dra0 = uncertainties[0]*pickRandomError()/3600.
                dra1 = uncertainties[1]*pickRandomError()/3600.
                ddec0 = uncertainties[2]*pickRandomError()/3600.
                ddec1 = uncertainties[3]*pickRandomError()/3600.
            degrees, radegrees, decdegrees, radegreesCosDec = angularSeparation(ra0+dra0,dec0+ddec0,ra1+dra1,dec1+ddec1,returnComponents)
            positionAngle = 90-math.atan2(decdegrees*math.pi/180., radegreesCosDec*math.pi/180.)*180/math.pi
            if (positionAngle > 180):
                positionAngle -= 360
            if (positionAngle < -180):
                positionAngle += 360
            retval = degrees, radegrees, decdegrees, radegreesCosDec, positionAngle
            raArray.append(radegrees)
            decArray.append(decdegrees)
            degArray.append(degrees)
            radegreesCosDecArray.append(radegreesCosDec)
            positionAngleArray.append(positionAngle)
            if (verbose):
                print("RA Separation: radian = %g, degrees = %f, arcsec = %f" % (radegreesCosDec*math.pi/180., 
                                                                                 radegreesCosDec, radegreesCosDec*3600))
                print("Dec Separation: radian = %g, degrees = %f, arcsec = %f" % (decdegrees*math.pi/180., 
                                                                                  decdegrees, decdegrees*3600))
                print("Position angle: %g deg E of N" % (positionAngle))
        if (trials > 1):
            retval = np.median(degArray), np.median(raArray), np.median(decArray), np.median(radegreesCosDecArray), np.median(positionAngleArray), np.std(degArray), np.std(positionAngleArray)
            print("separation = %f +- %f deg, position angle = %f +- %f deg" % (np.median(degArray), np.std(degArray), np.median(positionAngleArray), np.std(positionAngleArray)))
            print("separation = %f +- %f arcsec, position angle = %f +- %f deg" % (3600*np.median(degArray), 3600*np.std(degArray), np.median(positionAngleArray), np.std(positionAngleArray)))
    else:
        degrees = angularSeparation(ra0,dec0,ra1,dec1,returnComponents)
        retval = degrees
    if (verbose):
        print("Separation: radian = %g, degrees = %f = %g, arcsec = %f = %g" % (degrees*math.pi/180., 
                                                                                degrees, degrees, degrees*3600, degrees*3600))
    if (date is not None):
        if (type(date) == str):
            mjd = dateStringToMJD(date)
        else:
            mjd = date
        # convert ra/decs to az/el, then recompute separation
        az0,el0 = computeAzElFromRADecMJD([ra0*np.pi/180.,dec0*np.pi/180.],mjd,observatory)
        az1,el1 = computeAzElFromRADecMJD([ra1*np.pi/180.,dec1*np.pi/180.],mjd,observatory)
        total = angularSeparationRadians(az0,el0,az1,el1)
        print("Initial az/el = %f, %f deg" % (az0*180/np.pi, el0*180/np.pi))
        print("Delta azimuth = %f deg,  Delta elevation = %f deg  (total = %f deg)" % ((az1-az0)*180/np.pi, (el1-el0)*180/np.pi, total*180/np.pi)) 
    if returnArcsec:
        retval = np.array(retval)
        retval *= 3600
        if (returnComponents):
            # convert degrees*3600 back to degrees
            retval[-1] = retval[-1]/3600.
            if uncertainties is not None:
                retval[-3] = retval[-3]/3600.
    return(retval)

def angularSeparation(ra0,dec0,ra1,dec1, returnComponents=False, 
                      returnPositionAngle=False, returnArcsec=False, 
                      verbose=False):
  """
  Computes the great circle angle between two celestial coordinates.
  using the Vincenty formula which is correct for all angles, as 
  long as you use atan2() to handle a zero denominator.  
     See  http://en.wikipedia.org/wiki/Great_circle_distance
  ra0,dec0,ra1,dec1 must be given in degrees, either as floating point values 
        or sexagesimal strings.  Output will be in floating point degrees.
  It also works for the az,el coordinate system.
  Component separations are field_0 minus field_1.
  returnComponents: if True, then also compute angular separation in both
         coordinates, in which case the return values are:
         totalSeparation, raSeparation, decSeparation, raSeparation*cos(dec)
     and if returnPositionAngle is True, then also return
         the position angle of the separation vector on the sky (in degrees)
  returnArcsec: if True, then return all values in arcsec (except position 
        angle, it will always be returned in degrees)
  See also angularSeparationRadians() and angularSeparationOfStrings()
  -- Todd Hunter
  """
  if type(ra0) == str:
      ra0 = dmsToDegrees(ra0)
      if verbose: print("ra0 = ", ra0)
  if type(ra1) == str:
      ra1 = dmsToDegrees(ra1)
      if verbose: print("ra1 = ", ra1)
  if type(dec0) == str:
      dec0 = dmsToDegrees(dec0)
      if verbose: print("dec0 = ", dec0)
  if type(dec1) == str:
      dec1 = dmsToDegrees(dec1)
      if verbose: print("dec1 = ", dec1)
  ra0 *= math.pi/180.
  dec0 *= math.pi/180.
  ra1 *= math.pi/180.
  dec1 *= math.pi/180.
  deltaLong = ra0-ra1
  argument1 = (((np.cos(dec1)*np.sin(deltaLong))**2) +
               ((np.cos(dec0)*np.sin(dec1)-np.sin(dec0)*np.cos(dec1)*np.cos(deltaLong))**2))**0.5
  argument2 = np.sin(dec0)*np.sin(dec1) + np.cos(dec0)*np.cos(dec1)*np.cos(deltaLong)
  angle = np.arctan2(argument1, argument2) / (math.pi/180.)
  if (angle > 360):
      angle -= 360
  if (returnComponents):
      cosdec = np.cos((dec1+dec0)*0.5)
      radegreesCosDec = np.degrees(ra0-ra1)*cosdec
      radegrees = np.degrees(ra0-ra1)
      decdegrees = np.degrees(dec0-dec1)
      if (radegrees > 360):
          radegrees -= 360
      if (radegreesCosDec > 360):
          radegreesCosDec -= 360
      if (decdegrees > 360):
          decdegrees -= 360
      if (radegrees < -180):
          radegrees += 360
          radegreesCosDec = (np.degrees(ra0-ra1)+360)*cosdec
      if returnPositionAngle:
          positionAngle = np.degrees(-math.atan2(np.radians(decdegrees), np.radians(radegreesCosDec)))
          retval = angle,radegrees,decdegrees, radegreesCosDec, positionAngle
      else:
          retval = angle,radegrees,decdegrees, radegreesCosDec
      if type(radegrees) == np.ndarray and type(angle) != np.ndarray:
          retval[0] = np.array(angle)
  else:
      retval = angle
  if returnArcsec:
      retval = np.array(retval)
      retval *= 3600
      if (returnComponents):
          # convert position angle in degrees*3600 back to degrees
          retval[-1] = retval[-1]/3600.
  return(retval)

def sun(observatory='' ,mjdsec='', mjd='', date=None, verbose=False, 
        latitude=None, longitude=None):
    """
    Determines the az/el of the Sun for the specified observatory and specified
    time in MJD seconds (or MJD) or date/time string.  
    date: Any of these formats is valid: 2011/10/15 05:00:00
                                         2011/10/15-05:00:00
                                         2011-10-15 05:00:00
                                         2011-10-15T05:00:00
                                         2011-Oct-15T05:00:00
    verbose: if True, then print the RA,Dec of the sun
    observatory: string name of observatory
    Alternative location is latitude and longitude (in degrees) where
    negative longitude is west of Greenwich.
    If no information is given, it defaults to ALMA and 'now'.
    Other observatories available:
      ARECIBO  ATCA  BIMA  CLRO  DRAO  DWL  GB  GBT  GMRT  IRAM PDB  IRAM_PDB
      JCMT  MOPRA  MOST  NRAO12M  NRAO_GBT  PKS  SAO SMA  SMA  VLA  VLBA  WSRT
      ATF  ATA  CARMA  ACA  OSF  OVRO_MMA  EVLA  ASKAP  APEX  SMT  NRO  ASTE
      LOFAR  MeerKAT  KAT-7  EVN  LWA1  PAPER_SA  PAPER_GB  e-MERLIN  MERLIN2
    Returns az, el in degrees.

    For further help and examples, see https://safe.nrao.edu/wiki/bin/view/ALMA/Sun
    -- Todd Hunter
    """
    printCurrent = False
    if (mjdsec=='' and mjd=='' and date is None):
        printCurrent = True
        mjdsec = getCurrentMJDSec()
    elif (mjdsec=='' and date is None):
        mjdsec = np.double(mjd)*86400
    elif (mjd=='' and date is None):
        mjdsec = np.double(mjdsec)
    elif (mjd=='' and mjdsec==''):
        mjdsec = dateStringToMJDSec(date)
    else:
        print("Too many dates specified")
        return

    mjd = mjdsec/86400.
    datestring = mjdToUT(mjd)
    if (observatory==''):
        if latitude is None or longitude is None:
            observatory = 'ALMA'
        else:
            observatory = 'custom'
    if observatory != 'custom':
        try:
            [latitude,longitude,observatory] = getObservatoryLatLong(observatory)
            if (printCurrent):
                print("Found location for %s: %f, %f degrees" % (observatory,longitude,latitude))
        except:
            print("Did not find this observatory=%s, using ALMA instead." % (observatory))
        
    (az,el) = ComputeSolarAzElLatLong(mjdsec, latitude, longitude, verbose)
    if (printCurrent):
        print("At %s, the Sun is currently at azim=%.3f, elev=%.3f" % (observatory,az,el))
    if verbose:
        print("MJD = %f = %f seconds = %s" % (mjd, mjdsec, datestring))
    return(az,el)

def plotIERSpredict(datapath='', plotfile='', delimiter=',', plotdate=False, 
                    ls='None', use_site_packages=True):
    """
    Reads and plots the contents of the IERSpredict file in the geodetic 
    directory of the CASA data repository.
    datapath: either a CASA table, or a text file of delimited format used
            in PRTSPR-27515,  '' --> the table for the current CASA
    delimiter: relevant when datapath is a text file
    plotfile: string or True -> 'IERSpredict.png'
    plotdate: if True, use plot_date to show month/year on the x-axis
    use_site_packages: if False, use CASAPATH+'/data'; if True, then
           in CASA >= 6, use: os.path.dirname(casatools.utils.utils().resolve('geodetic'))
                    else use: CASAPATH+'/data'
    ls: line style for errorbar and plot_date
    -Todd Hunter
    """
    if os.path.isdir(datapath) or datapath == '':
        result = readIERSpredict(datapath, use_site_packages)
        if result is None:
            return
        mjd, x, Dx, y, Dy, dUT1, DdUT1, path, vs_date, vs_version = result
    else:
        if not os.path.exists(datapath):
            print("File not found: %s" % (datapath))
            return
        f = open(datapath, 'r')
        lines = f.readlines()
        f.close()
        path = datapath
        mjd = []; x = []; Dx = []; y = []; Dy = []; dUT1 = []; DdUT1 = []
        for line in lines:
            token = line.split(delimiter)
            if len(token) == 7:
                mjd.append(float(token[0]))
                x.append(float(token[1]))
                y.append(float(token[2]))
                dUT1.append(float(token[3]))
                Dx.append(float(token[4]))
                Dy.append(float(token[5]))
                DdUT1.append(float(token[6]))
    pb.clf()
    adesc = pb.subplot(311)
    xlim = [np.min(mjd), np.max(mjd)]
    Formatter = ScalarFormatter(useOffset=False)
    if plotdate:
        list_of_date_times = mjdSecondsListToDateTime(mjd*86400)
        timeplot = pb.date2num(list_of_date_times)
        loc = matplotlib.dates.AutoDateLocator()
        adesc.xaxis.set_major_locator(loc)
        adesc.xaxis.set_major_formatter(matplotlib.dates.DateFormatter('%b%Y')) # AutoDateFormatter(loc))
        pb.errorbar(timeplot, x, yerr=Dx, ls=ls)
        resizeFontsOnly(adesc,11)
    else:
        pb.errorbar(mjd, x, yerr=Dx, ls=ls)
        pb.xlim(xlim)
        adesc.xaxis.set_major_formatter(Formatter)
    pb.title(path[-68:])
    pb.ylabel('x (arcsec)')
    bdesc = pb.subplot(312)
    if plotdate:
        bdesc.xaxis.set_major_locator(loc)
        bdesc.xaxis.set_major_formatter(matplotlib.dates.DateFormatter('%b%Y')) # AutoDateFormatter(loc))
        pb.errorbar(timeplot, y, yerr=Dy, ls=ls)
        resizeFontsOnly(bdesc, 11)
    else:
        pb.errorbar(mjd, y, yerr=Dy, ls=ls)
        pb.xlim(xlim)
        bdesc.xaxis.set_major_formatter(Formatter)
    pb.ylabel('y (arcsec)')
    cdesc = pb.subplot(313)
    if plotdate:
        cdesc.xaxis.set_major_locator(loc)
        cdesc.xaxis.set_major_formatter(matplotlib.dates.DateFormatter('%b%Y')) # AutoDateFormatter(loc))
        pb.errorbar(timeplot, dUT1, yerr=DdUT1, ls=ls)
        resizeFontsOnly(cdesc,11)
        pb.xlabel('Date')
    else:
        pb.errorbar(mjd, dUT1, yerr=DdUT1, ls=ls)
        cdesc.xaxis.set_major_formatter(Formatter)
        pb.xlim(xlim)
        pb.xlabel('MJD')
    pb.ylabel('dUT1 (sec)')
    pb.draw()
    if plotfile != '':
        if plotfile == True:
            plotfile = 'IERSpredict.png'
        pb.savefig(plotfile)
        print("Wrote ", plotfile)
    
def readIERSpredict(datapath='', use_site_packages=True):
    """
    Reads the contents of the IERSpredict file in the geodetic 
    directory of the CASA data repository.
    x and y are the nutation angles, and dUT1 is the time value
    use_site_packages: if False, use CASAPATH+'/data'; if True, then
           in CASA >= 6, use: os.path.dirname(casatools.utils.utils().resolve('geodetic'))
                    else use: CASAPATH+'/data'
    Returns: MJD, x, Dx, y, Dy, dUT1, DdUT1, pathToTable, vs_date, vs_version
    -Todd Hunter
    """
    mytb = createCasaTool(tbtool)
    if datapath == '':
        if use_site_packages:
            mypath = getCasaDataPath()
        else:
            mypath = os.getenv("CASAPATH").split()[0] + '/data'
            if not os.path.exists(mypath):
                mypath = os.getenv("CASAPATH").split()[0] + '/__data__' #  modular casa
        if casaVersion < '5.9.9':
            print("Checking casa %s r%s = %s, %s" % (casaVersion, getCasaSubversionRevision(), casadef.__file__, mypath))
        else:
            print("Checking casa %s, %s" % (casaVersion, mypath))
    else:
        mypath = datapath
    mypath += "/geodetic/IERSpredict" 
    if not os.path.exists(mypath):
        print("Could not open table: %s" % (mypath))
        return
    mytb.open(mypath)
    vs_date = mytb.getkeyword('VS_DATE')
    vs_version = mytb.getkeyword('VS_VERSION')
    mjd = mytb.getcol('MJD')
    x = mytb.getcol('x')
    Dx = mytb.getcol('Dx')
    y = mytb.getcol('y')
    Dy = mytb.getcol('Dy')
    dUT1 = mytb.getcol('dUT1')
    DdUT1 = mytb.getcol('DdUT1')
    return mjd, x, Dx, y, Dy, dUT1, DdUT1, mypath, vs_date, vs_version

def IERSeop2000lastDateComparedToVSDate(datapath='', use_site_packages=True):
    """
    Computes the gap in time between VS_DATE and the final entry in the MJD column.
    datapath: either the path to a casa /data directory or a text file with
              a list of casa directories, one per line
    use_site_packages: if False, use CASAPATH+'/data'; if True, then
           in CASA >= 6, use: os.path.dirname(casatools.utils.utils().resolve('geodetic'))
                    else use: CASAPATH+'/data'
    -Todd Hunter
    """
    if datapath == '':
        datapath = getCasaDataPath()
    if not os.path.isdir(datapath):
        f = open(datapath,'r')
        dirs = f.readlines()
        f.close()
    else:
        dirs = [datapath]
    for datapath in dirs:
        datapath = datapath.strip()
        result = readIERSeop2000(datapath,  use_site_packages)
        vsdate = result[-2]
        vsdateMJD = dateStringToMJD(vsdate,verbose=False)
        lastdateMJD = np.max(result[0])
        gap = vsdateMJD - lastdateMJD
        print("gap=%.1f days; VS_DATE = %.1f  finalEntry = %.1f (%s)" % (gap, vsdateMJD,lastdateMJD,datapath))

def readIERS(datapath='',  use_site_packages=True):
    """
    Displays the date and version code of the IERSeop2000 and IERS predict 
    tables in the specified CASA repository.
    datapath: path to data; default = repository for your current CASA
    use_site_packages: if False, use CASAPATH+'/data'; if True, then
           in CASA >= 6, use: os.path.dirname(casatools.utils.utils().resolve('geodetic'))
                    else use: CASAPATH+'/data'
    -Todd Hunter
    """
    result = readIERSeop2000(datapath, use_site_packages)
    print("IERSeop2000: %s  %s" % (result[-2],result[-1]))
    result = readIERSpredict(datapath, use_site_packages)
    print("IERSpredict: %s  %s" % (result[-2],result[-1]))
    result = readTAIUTC(datapath, use_site_packages)
    print("TAI_UTC: %s %s" % (result[-2],result[-1]))

