    print(" IFLo1    LSB=(","%5.3f" %(if1max),"-","%5.3f" %(if1min),")GHz  and  USB=(","%5.3f" %(if1min),"-","%5.3f" %(if1max),")GHz ")
    print(" ")
    # print "                   BB_1(L)    BB_2(L)    BB_3(U)    BB_4(U)" 
