class stuffForScienceDataReduction:
    """
    Collection of utilities specifically for ALMA science data reduction
    """

    def __init__(self):
        self.swInfo = {}

    def locatePath(self, pathEnding):
        # This method will locate any file in the active analysisUtils
        # "science" subdirectory tree. You need to call it with the
        # trailing part of the path beyond the ~/AIV/science/ directory.
        # e.g. 'PadData/almaAntPos.txt'
        #
#        print "Looking for %s in the analysisUtils area" % (pathEnding)
        tokens = __file__.split('/')
        mypath = ''
        for i in range(len(tokens)-len(pathEnding.split('/'))):
            mypath += tokens[i] + '/'
        mypath += pathEnding
        return(mypath)

    def correctMyAntennaPositions(self, msNames, obsTime='', verbose=True, checkForAntennaMoves=True, 
                                  lbc=False, search='auto', maxSearchDays='auto', minPosDiff=50e-6, 
                                  thresh=5, useTMCDB=False, logLowSNRPositions=False, outfile='antennapos.csv', 
                                  TMCDB_URL='http://asa.alma.cl/axis2/services/TMCDBAntennaPadService?wsdl',
                                  maskFirstIntegration=True):
        """
        This function is called by the manual calibration script generator: almaqa2csg.py.
        msNames: either a single ms name, a python list of ms names, or a comma-delimited string of names
        obsTime: optional, string format: '%Y-%m-%dT%H:%M:%S' e.g. '2007-01-01T02:03:04')
        checkForAntennaMoves: if True, then exit python with an error stating the inconsistency in the text files
        lbc: if True, sets search='both_latest' and maxSearchDays=30 (overrides command-line values, including 'auto')
                 default was changed to True on 29-Sep-2022 for start of Cycle 9
        search: specifies the direction in time by which to search for the desired position measurement.
               The options are 'backward', 'forward', 'both_closest', 'both_next', 'both_latest', 'auto'
               'auto' will invoke 'both_closest' if the date of first ms is Cycle 9 onward, otherwise 'both_latest'
        maxSearchDays: an integer or 'auto'; 
           integer: ignores measurements older than and/or newer than this many days relative to the observation
           'auto': equivalent to specifying 30 (days)
        minPosDiff: in meters, only report corrections whose 3D value is larger than this threshold
        thresh: S/N threshold for using a solution; sqrt of sum of squares of individual axis SNRs 
                must be greather than this value
        useTMCDB: if True, then use the TMCDBAntennaPadService?wsdl web server; if False, use the AIV text files
        TMCDB_URL: The default URL points to the old SOAP interface which was replaced by a REST interface (see ICT-10558).
                   If you want to use the new service, run correctMyAntennaPositions_2
        logLowSNRPositions: if True, then create a file whose name encodes the number of antenna positions 
             rejected by the thresh criterion, if there are more than zero; e.g. '<vis>_5_lowSNRPositions'
        outfile: default='antennapos.csv'; if a different name is given, basename of ms will be used in the csv file
        maskFirstIntegration: if True, then ignore measurements whose ASDM name include "_firstIntegration"
        Assorted actions: 
        * Examines the AIV text files: almaAntPos.txt and antennaMoves.txt.  It first looks for them in your private AIV area (~AIV/science/PadData, if it exists), otherwise it looks in the area that you imported analysisUtils from.
        * Creates a filed called antennapos.csv in the current working directory, intended for pipeline use
        Returns: the gencal call produced.
        """

        if type(msNames).__name__ in ['str',np.bytes_,np.str_]:
            msNames = msNames.split(',')

        if search not in ['auto', 'backward', 'forward', 'both_closest', 'both_next', 'both_latest']: sys.exit('ERROR: unexpected value for search parameter.')

        if lbc == True:
            search = 'both_latest'
            maxSearchDays = 30

        # SCIREQ-2684 -------------------------------------
        if search == 'auto':
            if surmiseCycle(msNames[0]) < 9:
                search = 'both_latest'
            else:
                search = 'both_closest'
            print("Set search mode to ", search)
        if maxSearchDays == 'auto':
            maxSearchDays = 30
#            band = getFirstScienceSpwBand(msNames[0])
#            if band is not None:
#                if band >= 8:
#                    maxSearchDays = 14
            print("Set maxSearchDays to ", maxSearchDays)
        # 0---------------------------------------------------

        f = open(outfile, 'w')
        print('name,antenna,xoff,yoff,zoff,comment', file=f)
        f.close()

        #casaCmd = 'print "# Correcting for antenna position errors."\n\n'
        casaCmd = ''
        mytb = createCasaTool(tbtool)
        ASDMsUsed = {}  # dictionary baseline run ASDMs with values of antenna names
        for msName in msNames:
            ASDMsUsed[msName] = {}
            lowSNRPositions = 0
            rejectJAOaccepted = 0
            totalPositionErrors = []
            totalPositionSNRs = []
            totalPositions = []
            antennaPad = []
            if len(msNames) > 1: obsTime = ''
            scienceDate = getObservationStartDate(msName)

            mytb.open(msName)
            if 'ASDM_ANTENNA' not in mytb.keywordnames() or 'ASDM_STATION' not in mytb.keywordnames():
                sys.exit('ERROR: The ANTENNA and/or STATION tables from the ASDM were not transferred to the MS.')
            mytb.close()
            try:
                f=open(os.path.expanduser('~/AIV/science/PadData/almaAntPos.txt'), 'r')
            except:
                try:
                    mypath = self.locatePath('PadData/almaAntPos.txt')
                    f=open(mypath)
                except:
                    print("Failed to find path=%s" % (mypath))

            almaAntPos=XmlObjectifier.XmlObject(f.read())
            f.close()

            try:
                g=open(os.path.expanduser('~/AIV/science/PadData/antennaMoves.txt'), 'r')
            except:
                try:
                    mypath = self.locatePath('PadData/antennaMoves.txt')
                    g=open(mypath)
                except:
                    print("Failed to find path=%s" % (mypath))

            gc=g.read().splitlines()
            g.close()

            gc=sorted(gc)

            ij=-1
            antMoves={}
            for line in gc:
                line=line.strip()
                if (len(line) < 1): continue  # added by T. Hunter
                if line[0] == '#': continue
                ele=line.split()
                ij=ij+1
                antMoves[ij]={}
                antMoves[ij]['Date']=datetime.datetime.strptime(ele[0], '%Y-%m-%dT%H:%M')
                antMoves[ij]['Antenna']=ele[1]
                antMoves[ij]['From']=ele[2]
                antMoves[ij]['To']=ele[3]

            baseRunObj = almaAntPos.AntennaPositions.BaselineRun
            if not isinstance(baseRunObj, list): baseRunObj = [baseRunObj]
#            if not isinstance(baseRunObj, types.ListType): baseRunObj = [baseRunObj]

            measTime=[]
            for i in range(len(baseRunObj)):
                baseRunObj1 = baseRunObj[i]
                measTime.append(datetime.datetime.strptime(baseRunObj1.getAttribute('measTime'), '%Y-%m-%dT%H:%M:%S'))

            measTime = sorted(enumerate(measTime), key=operator.itemgetter(1), reverse=True)

            sort1 = []
            for i in range(len(measTime)):
                sort1.append(measTime[i][0])

            if obsTime == '':
                mytb.open(msName+'/OBSERVATION')
                obsTimeRange = mytb.getcol('TIME_RANGE')
                obsTime = (obsTimeRange.max()+obsTimeRange.min())/2.0
                obsTime = ((obsTime/86400.0)+2400000.5-2440587.5)*86400.0
                obsTime = timeUtilities.strftime('%Y-%m-%dT%H:%M:%S', timeUtilities.gmtime(obsTime))
                obsTime = datetime.datetime.strptime(obsTime, '%Y-%m-%dT%H:%M:%S')
                mytb.close()
            else:
                obsTime = datetime.datetime.strptime(obsTime, '%Y-%m-%dT%H:%M:%S')
#            print "%s obsTime = " % (msName), obsTime

#           Fix for antenna position mismatches due to switch to CWS (August 2023; SACM-2156)
            CWSfix_time1 = datetime.datetime.strptime('2023-08-21T05:29:08', '%Y-%m-%dT%H:%M:%S') # time of the ingestion of last multi-wx antpos data
            CWSfix_time2 = datetime.datetime.strptime('2023-08-26T17:06:23', '%Y-%m-%dT%H:%M:%S') # start time of the first execution following deployment of SCCB-1303 (switch delay server to single WX)
            CWSfix_time3 = datetime.datetime.strptime('2023-08-31T07:23:50', '%Y-%m-%dT%H:%M:%S') # time of the 8/31/23 antpos ingestion (first single wx antpos data)
            if (obsTime > datetime.datetime.strptime('2023-08-01T00:00:00', '%Y-%m-%dT%H:%M:%S')) & (obsTime <= CWSfix_time1):
                search = 'both_latest'
                maxSearchDays = 22 - obsTime.day
                print("WARNING: within timerange of antpos issues due to change to CWS (SACM-2156)")
                print("WARNING: Setting search to {} and maxSearchDays to {}".format(search, str(maxSearchDays)))
            elif (obsTime > CWSfix_time1) & (obsTime < CWSfix_time2):
                search = 'backward'
                print("WARNING: within timerange of antpos issues due to change to CWS (SACM-2156)")
                print("WARNING: Setting search to {}".format(search))
            elif (obsTime > CWSfix_time2) & (obsTime < CWSfix_time3):
                search = 'forward'
                print("WARNING: within timerange of antpos issues due to change to CWS (SACM-2156)")
                print("WARNING: Setting search to {}".format(search))

            mytb.open(msName+'/ANTENNA')
            antNames = mytb.getcol('NAME')
            padNames = mytb.getcol('STATION')
            mytb.close()

            msAntPos = {}
            for i in range(len(antNames)):
                msAntPos[antNames[i]] = {}
                msAntPos[antNames[i]]['pad'] = padNames[i]

            mytb.open(msName+'/ASDM_ANTENNA')
            asdmAntNames = mytb.getcol('name')
            asdmAntPositions = mytb.getcol('position')
            mytb.close()

            for i in range(len(antNames)):
                if antNames[i] not in asdmAntNames: sys.exit('ERROR: Antenna not found.')
                for j in range(len(asdmAntNames)):
                    if asdmAntNames[j] == antNames[i]:
                        msAntPos[antNames[i]]['antPos'] = [asdmAntPositions[0][j], asdmAntPositions[1][j], asdmAntPositions[2][j]]
                        break

            mytb.open(msName+'/ASDM_STATION')
            asdmPadNames = mytb.getcol('name')
            asdmPadPositions = mytb.getcol('position')
            mytb.close()

            for i in range(len(antNames)):
                if padNames[i] not in asdmPadNames: sys.exit('ERROR: Pad not found.')
                for j in range(len(asdmPadNames)):
                    if asdmPadNames[j] == padNames[i]:
                        msAntPos[antNames[i]]['padPos'] = [asdmPadPositions[0][j], asdmPadPositions[1][j], asdmPadPositions[2][j]]
                        break

            for i in range(len(antNames)):

                ij = -1
                antMoves1 = {}
                for j in range(len(antMoves)):
                    if antMoves[j]['Antenna'] == antNames[i]:
                        ij = ij+1
                        antMoves1[ij] = antMoves[j]

                if len(antMoves1) == 0:
                    sys.exit("ERROR: No antenna move information available for "+str(antNames[i]))
                if obsTime < antMoves1[0]['Date']:
                    sys.exit("ERROR: No antenna move information available for "+str(antNames[i]))

                for j in range(len(antMoves1)-1, -1, -1):
#                    print "%s Checking " % (antNames[i]), antMoves1[j]['Date']
                    if antMoves1[j]['Date'] <= obsTime: break

                if antMoves1[j]['To'] != padNames[i]:
                    if checkForAntennaMoves == True:
                        sys.exit("ERROR: Current data file has antenna "+str(antNames[i])+" on pad "+str(padNames[i])+" while latest move recorded is on pad "+str(antMoves1[j]['To']))
                    else:
                        print("ERROR: Current data file has antenna "+str(antNames[i])+" on pad "+str(padNames[i])+" while latest move recorded is on pad "+str(antMoves1[j]['To']))
                        msAntPos.pop(antNames[i])
                        continue

                msAntPos[antNames[i]]['putInTime'] = antMoves1[j]['Date']

                if j+1 in list(antMoves1.keys()):
                    msAntPos[antNames[i]]['putOutTime'] = antMoves1[j+1]['Date']
                else:
                    msAntPos[antNames[i]]['putOutTime'] = datetime.datetime.strptime('9999-01-01T00:00:00', '%Y-%m-%dT%H:%M:%S')

            if useTMCDB == True:
                from suds.client import Client
                client = Client(TMCDB_URL)
                TMCDBoutput = client.service.getAntennaPositions("CURRENT.AOS", ' '.join(sorted(msAntPos.keys())), datetime.datetime.strftime(obsTime, '%Y-%m-%dT%H:%M:%S'))

            msAntCorr = {}
            gcAntParam1 = []
            missingAntennas = []
            for i in msAntPos:

                found = 0

                if useTMCDB == False:

                    ij = []  
                    # build a list of indices that match the desired time range
                    for j in range(len(baseRunObj)):
                        baseRunASDM = baseRunObj[sort1[j]].getAttribute('asdm')
                        if '_firstIntegration' in baseRunASDM:
                            if maskFirstIntegration:  # SCIREQ-2684
                                if verbose and False:
                                    print("Ignoring ", baseRunASDM)
                                continue
                        baseRunObj1 = baseRunObj[sort1[j]]
                        measTime1 = datetime.datetime.strptime(baseRunObj1.getAttribute('measTime'), '%Y-%m-%dT%H:%M:%S')

                        if measTime1 >= msAntPos[i]['putInTime'] and measTime1 <= msAntPos[i]['putOutTime']:

                            wsTime1 = datetime.datetime.strptime('2017-09-15T02:00:00', '%Y-%m-%dT%H:%M:%S') # this is about the time when the weather stations were enabled
                            wsTime2 = datetime.datetime.strptime('2017-09-15T19:00:00', '%Y-%m-%dT%H:%M:%S') # this is about the time when the tmcdb was updated with the new antenna positions
                            if obsTime > wsTime1 and obsTime < wsTime2: continue
                            if obsTime < wsTime1 and measTime1 > wsTime1: continue
                            if obsTime > wsTime2 and measTime1 < wsTime1: continue

                            delta1 = measTime1-obsTime
                            delta1 = delta1.days*86400 + delta1.seconds

                            if maxSearchDays != '':
                                if abs(delta1) > maxSearchDays*86400: continue

                            if search == 'backward':
                                if delta1 <= 0:
                                    ij.append(tuple([j, abs(delta1)]))

                            if search == 'forward':
                                if delta1 >= 0:
                                    ij.append(tuple([j, delta1]))

                            if search == 'both_closest':
                                ij.append(tuple([j, abs(delta1)]))

                            if search == 'both_next':
                                ij.append(tuple([j, 1./delta1]))

                            if search == 'both_latest':
                                ij.append(tuple([j, delta1]))

                    if len(ij) > 0:

                        ij = sorted(ij, key=lambda x:x[1])

                        if search == 'both_next' and ij[-1][1] > 0:
                            ij = sorted(ij, key=lambda x:x[1], reverse=True)

                        if search == 'both_latest':
                            ij = sorted(ij, key=lambda x:x[1], reverse=True)

                        for j in range(len(ij)):

                            baseRunObj1 = baseRunObj[sort1[ij[j][0]]]
                            measTime1 = datetime.datetime.strptime(baseRunObj1.getAttribute('measTime'), '%Y-%m-%dT%H:%M:%S')

                            antObj = baseRunObj1.Antenna

                            if type(antObj) == type([]):
                                lenAntObj = len(antObj)
                            else:
                                lenAntObj = 1

                            for k in range(lenAntObj):

                                if type(antObj) == type([]):
                                    antObj1 = antObj[k]
                                else:
                                    antObj1 = antObj

                                if antObj1.getAttribute('name') == i and antObj1.getAttribute('pad') == msAntPos[i]['pad']:
                                    found = 1
                                    padPosObj = antObj1.PadPosition
                                    brPadPos = [padPosObj.getAttribute('X'), padPosObj.getAttribute('Y'), padPosObj.getAttribute('Z')]
                                    antVecObj = antObj1.AntennaVector
                                    brAntVec = [antVecObj.getAttribute('X'), antVecObj.getAttribute('Y'), antVecObj.getAttribute('Z')]
                                    posErrObj = antObj1.PositionError
                                    brPosErr = [posErrObj.getAttribute('X'), posErrObj.getAttribute('Y'), posErrObj.getAttribute('Z')]
                                    thisASDM = baseRunObj1.getAttribute('asdm')
                                    if thisASDM not in list(ASDMsUsed[msName].keys()):
                                        ASDMsUsed[msName][thisASDM] = []
                                    ASDMsUsed[msName][thisASDM].append(antObj1.getAttribute('name'))
                                    break

                            if found == 1: break # modified

                else:

                    for j in range(len(TMCDBoutput['antennaPositionList'])):
                        if TMCDBoutput['antennaPositionList'][j]['name'] == i:
                            if TMCDBoutput['antennaPositionList'][j]['completion']['status'] == 'true':
                                found = 1
                                measTime1 = 'from TMCDB'
                                brPadPos = [float(TMCDBoutput['antennaPositionList'][j]['pad']['position']['x']), float(TMCDBoutput['antennaPositionList'][j]['pad']['position']['y']), float(TMCDBoutput['antennaPositionList'][j]['pad']['position']['z'])]
                                brAntVec = [float(TMCDBoutput['antennaPositionList'][j]['position']['x']), float(TMCDBoutput['antennaPositionList'][j]['position']['y']), float(TMCDBoutput['antennaPositionList'][j]['position']['z'])]
                                brPosErr = [1e-10, 1e-10, 1e-10]
                            break

                if found != 1:

#                     casaCmd = casaCmd + '# Note: no baseline run found for antenna '+i+'.\n\n'

                    missingAntennas.append(str(i))  # str() is fix for py3.12

                else:

                    if brPadPos[0] == msAntPos[i]['padPos'][0] and brPadPos[1] == msAntPos[i]['padPos'][1] and brPadPos[2] == msAntPos[i]['padPos'][2]:

                        if brAntVec[0] != msAntPos[i]['antPos'][0] or brAntVec[1] != msAntPos[i]['antPos'][1] or brAntVec[2] != msAntPos[i]['antPos'][2]:

                            posDiff = []
                            for j in range(3):
                                posDiff.append(brAntVec[j] - msAntPos[i]['antPos'][j])

                            if brPosErr[0] == 0 or brPosErr[1] == 0 or brPosErr[2] == 0:
                        
                                print("ERROR: Some baseline observing run position errors are null.")

                            else:
                                totalPositionSNR = pb.sqrt((posDiff[0]/brPosErr[0])**2 + (posDiff[1]/brPosErr[1])**2 + (posDiff[2]/brPosErr[2])**2)
                                totalPositionError = np.linalg.norm(brPosErr)
                                if totalPositionSNR >= thresh:

                                    brLat = math.asin(brPadPos[2]/np.sqrt(brPadPos[0]**2+brPadPos[1]**2+brPadPos[2]**2))
                                    brLon = math.atan2(brPadPos[1], brPadPos[0])

                                    posDiff1 = []
                                    posDiff1.append(-math.sin(brLon)*posDiff[0]-math.cos(brLon)*math.sin(brLat)*posDiff[1]+math.cos(brLon)*math.cos(brLat)*posDiff[2])
                                    posDiff1.append(math.cos(brLon)*posDiff[0]-math.sin(brLon)*math.sin(brLat)*posDiff[1]+math.sin(brLon)*math.cos(brLat)*posDiff[2])
                                    posDiff1.append(math.cos(brLat)*posDiff[1]+math.sin(brLat)*posDiff[2])

                                    if np.linalg.norm(posDiff1) > 2e-3: casaCmd = casaCmd + '# Note: the correction for antenna '+i+' is larger than 2mm.\n\n'

                                    if np.linalg.norm(posDiff1) >= minPosDiff:

                                        msAntCorr[i] = {}
                                        msAntCorr[i]['posDiff'] = posDiff1
                                        if verbose == True: casaCmd = casaCmd + '# Position for antenna '+i+' is derived from baseline run made on '+str(measTime1)+'.\n\n' # modified
                                        gcAntParam1.append(tuple(['# '+i+' %15.5e%15.5e%15.5e%15.5e%25s' % (posDiff1[0], posDiff1[1], posDiff1[2], np.linalg.norm(posDiff1), measTime1), np.linalg.norm(posDiff1)]))
                                else:
                                    lowSNRPositions += 1
                                    totalPositionSNRs.append(totalPositionSNR)
                                    totalPositionErrors.append(totalPositionError)
                                    antennaPad.append(baseRunObj1.getAttribute('measTime') + ' ' + str(i) + ' ' + antObj1.getAttribute('pad'))
                                    # repeat the calculations from the True branch
                                    brLat = math.asin(brPadPos[2]/np.sqrt(brPadPos[0]**2+brPadPos[1]**2+brPadPos[2]**2))
                                    brLon = math.atan2(brPadPos[1], brPadPos[0])
                                    myposDiff1 = []
                                    myposDiff1.append(-math.sin(brLon)*posDiff[0]-math.cos(brLon)*math.sin(brLat)*posDiff[1]+math.cos(brLon)*math.cos(brLat)*posDiff[2])
                                    myposDiff1.append(math.cos(brLon)*posDiff[0]-math.sin(brLon)*math.sin(brLat)*posDiff[1]+math.sin(brLon)*math.cos(brLat)*posDiff[2])
                                    myposDiff1.append(math.cos(brLat)*posDiff[1]+math.sin(brLat)*posDiff[2])
                                    totalPositions.append(np.linalg.norm(myposDiff1))
                    else:
                        brLat = math.asin(brPadPos[2]/np.sqrt(brPadPos[0]**2+brPadPos[1]**2+brPadPos[2]**2))
                        brLon = math.atan2(brPadPos[1], brPadPos[0])

                        brPosTot = []
                        brPosTot.append(brAntVec[0] + -math.sin(-brLon)*brPadPos[0]-math.cos(-brLon)*math.sin(-brLat)*brPadPos[1]+math.cos(-brLon)*math.cos(-brLat)*brPadPos[2])
                        brPosTot.append(brAntVec[1] + math.cos(-brLon)*brPadPos[0]-math.sin(-brLon)*math.sin(-brLat)*brPadPos[1]+math.sin(-brLon)*math.cos(-brLat)*brPadPos[2])
                        brPosTot.append(brAntVec[2] + np.cos(-brLat)*brPadPos[1]+np.sin(-brLat)*brPadPos[2])

                        msLat = math.asin(msAntPos[i]['padPos'][2]/np.sqrt(msAntPos[i]['padPos'][0]**2+msAntPos[i]['padPos'][1]**2+msAntPos[i]['padPos'][2]**2))
                        msLon = math.atan2(msAntPos[i]['padPos'][1], msAntPos[i]['padPos'][0])

                        msPosTot = []
                        msPosTot.append(msAntPos[i]['antPos'][0] + -math.sin(-msLon)*msAntPos[i]['padPos'][0]-math.cos(-msLon)*math.sin(-msLat)*msAntPos[i]['padPos'][1]+math.cos(-msLon)*math.cos(-msLat)*msAntPos[i]['padPos'][2])
                        msPosTot.append(msAntPos[i]['antPos'][1] + math.cos(-msLon)*msAntPos[i]['padPos'][0]-math.sin(-msLon)*math.sin(-msLat)*msAntPos[i]['padPos'][1]+math.sin(-msLon)*math.cos(-msLat)*msAntPos[i]['padPos'][2])
                        msPosTot.append(msAntPos[i]['antPos'][2] + math.cos(-msLat)*msAntPos[i]['padPos'][1]+math.sin(-msLat)*msAntPos[i]['padPos'][2])

                        posDiff = []
                        for j in range(3):
                            posDiff.append(brPosTot[j] - msPosTot[j])

                        if brPosErr[0] == 0 or brPosErr[1] == 0 or brPosErr[2] == 0:
                    
                            print("Note: some errors are null.")

                        else:
                            totalPositionSNR = pb.sqrt((posDiff[0]/brPosErr[0])**2 + (posDiff[1]/brPosErr[1])**2 + (posDiff[2]/brPosErr[2])**2)
                            totalPositionError = np.linalg.norm(brPosErr)
                            if totalPositionSNR >= thresh:

                                brPosTot1 = []
                                brPosTot1.append(brPadPos[0] + -math.sin(brLon)*brAntVec[0]-math.cos(brLon)*math.sin(brLat)*brAntVec[1]+math.cos(brLon)*math.cos(brLat)*brAntVec[2])
                                brPosTot1.append(brPadPos[1] + math.cos(brLon)*brAntVec[0]-math.sin(brLon)*math.sin(brLat)*brAntVec[1]+math.sin(brLon)*math.cos(brLat)*brAntVec[2])
                                brPosTot1.append(brPadPos[2] + math.cos(brLat)*brAntVec[1]+math.sin(brLat)*brAntVec[2])

                                msPosTot1 = []
                                msPosTot1.append(msAntPos[i]['padPos'][0] + -math.sin(msLon)*msAntPos[i]['antPos'][0]-math.cos(msLon)*math.sin(msLat)*msAntPos[i]['antPos'][1]+math.cos(msLon)*math.cos(msLat)*msAntPos[i]['antPos'][2])
                                msPosTot1.append(msAntPos[i]['padPos'][1] + math.cos(msLon)*msAntPos[i]['antPos'][0]-math.sin(msLon)*math.sin(msLat)*msAntPos[i]['antPos'][1]+math.sin(msLon)*math.cos(msLat)*msAntPos[i]['antPos'][2])
                                msPosTot1.append(msAntPos[i]['padPos'][2] + math.cos(msLat)*msAntPos[i]['antPos'][1]+math.sin(msLat)*msAntPos[i]['antPos'][2])

                                posDiff1 = []
                                for j in range(3):
                                    posDiff1.append(brPosTot1[j] - msPosTot1[j])

                                if np.linalg.norm(posDiff1) > 2e-3: casaCmd = casaCmd + '# Note: the correction for antenna '+i+' is larger than 2mm.\n\n'

                                if np.linalg.norm(posDiff1) >= minPosDiff:

                                    msAntCorr[i] = {}
                                    msAntCorr[i]['posDiff'] = posDiff1
                                    if verbose == True: casaCmd = casaCmd + '# Position for antenna '+i+' is derived from baseline run made on '+str(measTime1)+'.\n\n' # modified
                                    gcAntParam1.append(tuple(['# '+i+' %15.5e%15.5e%15.5e%15.5e%25s' % (posDiff1[0], posDiff1[1], posDiff1[2], np.linalg.norm(posDiff1), measTime1), np.linalg.norm(posDiff1)]))
                            else:
                                lowSNRPositions += 1
                                totalPositionSNRs.append(totalPositionSNR)
                                totalPositionErrors.append(totalPositionError)
                                antennaPad.append(baseRunObj1.getAttribute('measTime') + ' ' + str(i) + ' ' + antObj1.getAttribute('pad'))
                                # repeat the calculations from the True branch
                                brPosTot1 = []
                                brPosTot1.append(brPadPos[0] + -math.sin(brLon)*brAntVec[0]-math.cos(brLon)*math.sin(brLat)*brAntVec[1]+math.cos(brLon)*math.cos(brLat)*brAntVec[2])
                                brPosTot1.append(brPadPos[1] + math.cos(brLon)*brAntVec[0]-math.sin(brLon)*math.sin(brLat)*brAntVec[1]+math.sin(brLon)*math.cos(brLat)*brAntVec[2])
                                brPosTot1.append(brPadPos[2] + math.cos(brLat)*brAntVec[1]+math.sin(brLat)*brAntVec[2])
                                msPosTot1 = []
                                msPosTot1.append(msAntPos[i]['padPos'][0] + -math.sin(msLon)*msAntPos[i]['antPos'][0]-math.cos(msLon)*math.sin(msLat)*msAntPos[i]['antPos'][1]+math.cos(msLon)*math.cos(msLat)*msAntPos[i]['antPos'][2])
                                msPosTot1.append(msAntPos[i]['padPos'][1] + math.cos(msLon)*msAntPos[i]['antPos'][0]-math.sin(msLon)*math.sin(msLat)*msAntPos[i]['antPos'][1]+math.sin(msLon)*math.cos(msLat)*msAntPos[i]['antPos'][2])
                                msPosTot1.append(msAntPos[i]['padPos'][2] + math.cos(msLat)*msAntPos[i]['antPos'][1]+math.sin(msLat)*msAntPos[i]['antPos'][2])
                                myposDiff1 = []
                                for j in range(3):
                                    myposDiff1.append(brPosTot1[j] - msPosTot1[j])
                                totalPositions.append(np.linalg.norm(myposDiff1))

            gcAntList = []
            for i in sorted(msAntCorr.keys()): gcAntList.append(i)
            gcAntList = ','.join(gcAntList)

            gcAntParam = []
            gcAntParam0 = []
            for i in sorted(msAntCorr.keys()):
                for j in range(3):
    #                 gcAntParam.append(str(msAntCorr[i]['posDiff'][j]))
                    gcAntParam.append('%.5e' % msAntCorr[i]['posDiff'][j])
                    gcAntParam0.append('0')
            gcAntParam = ','.join(gcAntParam)
            gcAntParam0 = ','.join(gcAntParam0)

#            print('Used the following measurementASDMs: ')
            for baselineAsdm in list(ASDMsUsed[msName].keys()):
                antennaList = ASDMsUsed[msName][baselineAsdm]
                print(os.path.basename(msName), '"'+baselineAsdm+'"', antennaList)
            
            f = open(outfile, 'a')

#             print >> f, 'name,antenna,xoff,yoff,zoff,comment'

            if gcAntList != '':

                for i in sorted(msAntCorr.keys()):
#                     print >> f, msName+','+i+','+str(msAntCorr[i]['posDiff'][0])+','+str(msAntCorr[i]['posDiff'][1])+','+str(msAntCorr[i]['posDiff'][2])+','
                    if logLowSNRPositions or outfile != 'antennapos.csv':
                        writeMsName = os.path.basename(msName)
                    else:
                        writeMsName = msName
                    print('%s,%s,%.5e,%.5e,%.5e,' % (writeMsName, i, msAntCorr[i]['posDiff'][0], msAntCorr[i]['posDiff'][1], msAntCorr[i]['posDiff'][2]), file=f)
        
            f.close()

            if gcAntList != '' or lbc == True or len(missingAntennas) != 0:

                casaCmd = casaCmd + "os.system('rm -rf %s.antpos') \n"%(msName)  # Added by CLB
                casaCmd = casaCmd + "gencal(vis = '"+msName+"',\n"
                casaCmd = casaCmd + "  caltable = '"+msName+".antpos',\n"
                casaCmd = casaCmd + "  caltype = 'antpos',\n"

                if gcAntList == '':
                    casaCmd = casaCmd + "  antenna = '"+antNames[0]+"',\n"
                else:
                    casaCmd = casaCmd + "  antenna = '"+gcAntList+"',\n"

                obsTime1 = datetime.datetime.strftime(obsTime, '%Y-%m-%dT%H:%M:%S')

                if (obsTime1 >= '2015-05-12T00:00:00' and obsTime1 <= '2015-06-01T00:00:00') or lbc == True:

                    if gcAntList == '' and lbc == True:
                        casaCmd = casaCmd + "#  parameter = ["+gcAntParam0+"])\n"
                        casaCmd = casaCmd + "  parameter = [0,0,0])\n"
                    else:
                        casaCmd = casaCmd + "#  parameter = ["+gcAntParam0+"])\n"
                        casaCmd = casaCmd + "  parameter = ["+gcAntParam+"])\n"

                elif datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S') >= '2017-09-11 00:00:00':

                    if gcAntList == '':
                        casaCmd = casaCmd + "#  parameter = ["+gcAntParam0+"])\n"
                        casaCmd = casaCmd + "  parameter = [0,0,0])\n"
                    else:
                        casaCmd = casaCmd + "#  parameter = ["+gcAntParam0+"])\n"
                        casaCmd = casaCmd + "  parameter = ["+gcAntParam+"])\n"

                else:

                    if gcAntList == '':
                        casaCmd = casaCmd + "#  parameter = ["+gcAntParam0+"])\n"
                        casaCmd = casaCmd + "  parameter = [0,0,0])\n"
                    else:
                        casaCmd = casaCmd + "  parameter = ["+gcAntParam0+"])\n"
                        casaCmd = casaCmd + "#  parameter = ["+gcAntParam+"])\n"

                casaCmd += '\n\n# antenna x_offset y_offset z_offset total_offset baseline_date\n'
                for ij in sorted(gcAntParam1, key=lambda x:x[1], reverse=True):
                    casaCmd += ij[0]+'\n'

                if len(missingAntennas) != 0: casaCmd = '# Warning: no baseline run found for following antenna(s): '+str(missingAntennas)+'.\n\n' + casaCmd

                if len(msNames) == 1 and not logLowSNRPositions:
                    return casaCmd

            else:

                print("Note: I could not find any offset between the antenna positions in the ASDM and in the database, so I am not including any gencal call.")

            if (logLowSNRPositions):
                if (lowSNRPositions > 0):
                    # measurement can be lowSNR but also below the minPosDiff, but these cases may be rare
                    outliers = len(np.where(np.abs(totalPositions) > minPosDiff)[0])
                    if outliers > 0:
                        severeOutliers = len(np.where(np.abs(totalPositions) > 10*minPosDiff)[0]) # i.e. 500e-6
                        # These are points that were rejected by correctMyAntennaPositions but not by EOC
                        rejectJAOaccepted = len(np.where(np.abs(totalPositionErrors) < 300e-6)[0])
                        snrfile = os.path.basename(msName)+'_severe%d_rejectJAOaccepted%d_%d_%d_lowSNRPositions' % (severeOutliers,rejectJAOaccepted,outliers,lowSNRPositions)
                        lowSNRFile = open(snrfile, 'w')
                        lowSNRFile.write('#Measurement time  antenna  pad  vectorLength(m)  uncertainty(m)  %s\n' % (scienceDate))
                        for ij, err in enumerate(totalPositionErrors):
                            lowSNRFile.write('%s %f %f\n' % (antennaPad[ij], totalPositions[ij],err))
                        lowSNRFile.close()
                        print("Wrote ", snrfile)
                    else:
                        print("%d Low SNR positions found but none were more than %f microns" % (lowSNRPositions,10*1e6*minPosDiff))
                else:
                    print("No low SNR positions encountered in %s." % (os.path.basename(msName)))
                if len(msNames) == 1: 
                    return casaCmd
        # end 'for' loop over msNames

    def correctMyAntennaPositions_2(self, msNames, obsTime='', verbose=True, checkForAntennaMoves=True, lbc=True, search='both_latest', maxSearchDays=30, minPosDiff=50e-6, thresh=5, useTMCDB=False, logLowSNRPositions=False, outfile='antennapos.csv'):
        """
        As far as I know, this function is not used in Operations. - TRH 2024/09/23
        msNames: either a single ms name, or a python list of ms names
        obsTime: optional, string format: '%Y-%m-%dT%H:%M:%S' e.g. '2007-01-01T02:03:04')
        checkForAntennaMoves: if True, then exit python with an error stating the inconsistency in the text files
        lbc: if True, sets search='both_latest' and maxSearchDays=30 (overrides command-line values)
        search: specifies the direction in time by which to search for the desired position measurement.
                The options are 'backward', 'forward', 'both_closest', 'both_next', 'both_latest'
        maxSearchDays: ignores measurements older than and/or newer than this many days relative to the observation
        minPosDiff: in meters, only report corrections whose 3D value is larger than this threshold
        thresh: S/N threshold for using a solution; sqrt of sum of squares of individual axis SNRs 
                must be greather than this value
        useTMCDB: if True, then use the antenna uncertainties web server (ICT-12116) at https://asa.alma.cl/uncertainties-service; if False, use the AIV text files
        logLowSNRPositions: if True, then create a file whose name encodes the number of antenna positions 
                rejected by the thresh criterion, if there are more than zero; e.g. '<vis>_5_lowSNRPositions'
        Assorted actions: 
        * Examines the AIV text files: almaAntPos.txt and antennaMoves.txt
        * Creates a filed called antennapos.csv in the current working directory, intended for pipeline use
        """

        if type(msNames).__name__ == 'str': msNames = [msNames]

        if search not in ['backward', 'forward', 'both_closest', 'both_next', 'both_latest']: sys.exit('ERROR: unexpected value for search parameter.')

        if lbc == True:
            search = 'both_latest'
            maxSearchDays = 30

        f = open(outfile, 'w')
        print('name,antenna,xoff,yoff,zoff,comment', file=f)
        f.close()

        #casaCmd = 'print "# Correcting for antenna position errors."\n\n'
        casaCmd = ''
        mytb = createCasaTool(tbtool)
        
        for msName in msNames:
            lowSNRPositions = 0
            rejectJAOaccepted = 0
            totalPositionErrors = []
            totalPositionSNRs = []
            totalPositions = []
            antennaPad = []
            if len(msNames) > 1: obsTime = ''
            scienceDate = getObservationStartDate(msName)

            mytb.open(msName)
            if 'ASDM_ANTENNA' not in mytb.keywordnames() or 'ASDM_STATION' not in mytb.keywordnames():
                sys.exit('ERROR: The ANTENNA and/or STATION tables from the ASDM were not transferred to the MS.')
            mytb.close()

            if useTMCDB is False:
                try:
                    f=open(os.path.expanduser('~/AIV/science/PadData/almaAntPos.txt'), 'r')
                except:
                    try:
                        mypath = self.locatePath('PadData/almaAntPos.txt')
                        f=open(mypath)
                    except:
                        print("Failed to find path=%s" % (mypath))

                almaAntPos=XmlObjectifier.XmlObject(f.read())
                f.close()
            else:
                import json
                import ssl
                import certifi
                ANTENNA_UNCERTAINTIES_SERVER = 'https://asa.alma.cl/uncertainties-service'
                response = urlopen('{}/uncertainties/versions/last'.format(ANTENNA_UNCERTAINTIES_SERVER),context=ssl.create_default_context(cafile=certifi.where()))
                almaAntPos = json.loads(response.read())
                #print(almaAntPos)

            try:
                g=open(os.path.expanduser('~/AIV/science/PadData/antennaMoves.txt'), 'r')
            except:
                try:
                    mypath = self.locatePath('PadData/antennaMoves.txt')
                    g=open(mypath)
                except:
                    print("Failed to find path=%s" % (mypath))

            gc=g.read().splitlines()
            g.close()

            gc=sorted(gc)

            ij=-1
            antMoves={}
            for line in gc:
                line=line.strip()
                if (len(line) < 1): continue  # added by T. Hunter
                if line[0] == '#': continue
                ele=line.split()
                ij=ij+1
                antMoves[ij]={}
                antMoves[ij]['Date']=datetime.datetime.strptime(ele[0], '%Y-%m-%dT%H:%M')
                antMoves[ij]['Antenna']=ele[1]
                antMoves[ij]['From']=ele[2]
                antMoves[ij]['To']=ele[3]

            if useTMCDB is False:
                baseRunObj = almaAntPos.AntennaPositions.BaselineRun
            else:
                baseRunObj = almaAntPos['baselines']


            if not isinstance(baseRunObj, list): baseRunObj = [baseRunObj]
    #            if not isinstance(baseRunObj, types.ListType): baseRunObj = [baseRunObj]

            measTime=[]
            for i in range(len(baseRunObj)):
                baseRunObj1 = baseRunObj[i]

                if useTMCDB is False:
                    measTime.append(datetime.datetime.strptime(baseRunObj1.getAttribute('measTime'), '%Y-%m-%dT%H:%M:%S'))
                else:
                    measTime.append(datetime.datetime.strptime(baseRunObj1['measTime'], '%Y-%m-%dT%H:%M:%S'))

            measTime = sorted(enumerate(measTime), key=operator.itemgetter(1), reverse=True)

            sort1 = []
            for i in range(len(measTime)):
                sort1.append(measTime[i][0])

            if obsTime == '':
                mytb.open(msName+'/OBSERVATION')
                obsTimeRange = mytb.getcol('TIME_RANGE')
                obsTime = (obsTimeRange.max()+obsTimeRange.min())/2.0
                obsTime = ((obsTime/86400.0)+2400000.5-2440587.5)*86400.0
                obsTime = timeUtilities.strftime('%Y-%m-%dT%H:%M:%S', timeUtilities.gmtime(obsTime))
                obsTime = datetime.datetime.strptime(obsTime, '%Y-%m-%dT%H:%M:%S')
                mytb.close()
            else:
                obsTime = datetime.datetime.strptime(obsTime, '%Y-%m-%dT%H:%M:%S')
    #            print "%s obsTime = " % (msName), obsTime
            mytb.open(msName+'/ANTENNA')
            antNames = mytb.getcol('NAME')
            padNames = mytb.getcol('STATION')
            mytb.close()

            msAntPos = {}
            for i in range(len(antNames)):
                msAntPos[antNames[i]] = {}
                msAntPos[antNames[i]]['pad'] = padNames[i]

            mytb.open(msName+'/ASDM_ANTENNA')
            asdmAntNames = mytb.getcol('name')
            asdmAntPositions = mytb.getcol('position')
            mytb.close()

            for i in range(len(antNames)):
                if antNames[i] not in asdmAntNames: sys.exit('ERROR: Antenna not found.')
                for j in range(len(asdmAntNames)):
                    if asdmAntNames[j] == antNames[i]:
                        msAntPos[antNames[i]]['antPos'] = [asdmAntPositions[0][j], asdmAntPositions[1][j], asdmAntPositions[2][j]]
                        break

            mytb.open(msName+'/ASDM_STATION')
            asdmPadNames = mytb.getcol('name')
            asdmPadPositions = mytb.getcol('position')
            mytb.close()

            for i in range(len(antNames)):
                if padNames[i] not in asdmPadNames: sys.exit('ERROR: Pad not found.')
                for j in range(len(asdmPadNames)):
                    if asdmPadNames[j] == padNames[i]:
                        msAntPos[antNames[i]]['padPos'] = [asdmPadPositions[0][j], asdmPadPositions[1][j], asdmPadPositions[2][j]]
                        break

            for i in range(len(antNames)):

                ij = -1
                antMoves1 = {}
                for j in range(len(antMoves)):
                    if antMoves[j]['Antenna'] == antNames[i]:
                        ij = ij+1
                        antMoves1[ij] = antMoves[j]

                if len(antMoves1) == 0:
                    sys.exit("ERROR: No antenna move information available for "+str(antNames[i]))
                if obsTime < antMoves1[0]['Date']:
                    sys.exit("ERROR: No antenna move information available for "+str(antNames[i]))

                for j in range(len(antMoves1)-1, -1, -1):
    #                    print "%s Checking " % (antNames[i]), antMoves1[j]['Date']
                    if antMoves1[j]['Date'] <= obsTime: break

                if antMoves1[j]['To'] != padNames[i]:
                    if checkForAntennaMoves == True:
                        sys.exit("ERROR: Current data file has antenna "+str(antNames[i])+" on pad "+str(padNames[i])+" while latest move recorded is on pad "+str(antMoves1[j]['To']))
                    else:
                        print("ERROR: Current data file has antenna "+str(antNames[i])+" on pad "+str(padNames[i])+" while latest move recorded is on pad "+str(antMoves1[j]['To']))
                        msAntPos.pop(antNames[i])
                        continue

                msAntPos[antNames[i]]['putInTime'] = antMoves1[j]['Date']

                if j+1 in list(antMoves1.keys()):
                    msAntPos[antNames[i]]['putOutTime'] = antMoves1[j+1]['Date']
                else:
                    msAntPos[antNames[i]]['putOutTime'] = datetime.datetime.strptime('9999-01-01T00:00:00', '%Y-%m-%dT%H:%M:%S')


            msAntCorr = {}
            gcAntParam1 = []
            missingAntennas = []

            for i in msAntPos:

                found = 0

                ij = []

                for j in range(len(baseRunObj)):

                    baseRunObj1 = baseRunObj[sort1[j]]

                    if useTMCDB is False:
                        measTime1 = datetime.datetime.strptime(baseRunObj1.getAttribute('measTime'), '%Y-%m-%dT%H:%M:%S')
                    else:
                        measTime1 = datetime.datetime.strptime(baseRunObj1['measTime'], '%Y-%m-%dT%H:%M:%S')

                    if measTime1 >= msAntPos[i]['putInTime'] and measTime1 <= msAntPos[i]['putOutTime']:

                        wsTime1 = datetime.datetime.strptime('2017-09-15T02:00:00', '%Y-%m-%dT%H:%M:%S') # this is about the time when the weather stations were enabled
                        wsTime2 = datetime.datetime.strptime('2017-09-15T19:00:00', '%Y-%m-%dT%H:%M:%S') # this is about the time when the tmcdb was updated with the new antenna positions
                        if obsTime > wsTime1 and obsTime < wsTime2: continue
                        if obsTime < wsTime1 and measTime1 > wsTime1: continue
                        if obsTime > wsTime2 and measTime1 < wsTime1: continue

                        delta1 = measTime1-obsTime
                        delta1 = delta1.days*86400 + delta1.seconds

                        if maxSearchDays != '':
                            if abs(delta1) > maxSearchDays*86400: continue

                        if search == 'backward':
                            if delta1 <= 0:
                                ij.append(tuple([j, abs(delta1)]))

                        if search == 'forward':
                            if delta1 >= 0:
                                ij.append(tuple([j, delta1]))

                        if search == 'both_closest':
                            ij.append(tuple([j, abs(delta1)]))

                        if search == 'both_next':
                            ij.append(tuple([j, 1./delta1]))

                        if search == 'both_latest':
                            ij.append(tuple([j, delta1]))

                if len(ij) > 0:

                    ij = sorted(ij, key=lambda x:x[1])

                    if search == 'both_next' and ij[-1][1] > 0:
                        ij = sorted(ij, key=lambda x:x[1], reverse=True)

                    if search == 'both_latest':
                        ij = sorted(ij, key=lambda x:x[1], reverse=True)

                    for j in range(len(ij)):

                        baseRunObj1 = baseRunObj[sort1[ij[j][0]]]

                        if useTMCDB is False:
                            measTime1 = datetime.datetime.strptime(baseRunObj1.getAttribute('measTime'), '%Y-%m-%dT%H:%M:%S')
                            antObj = baseRunObj1.Antenna
                        else:
                            measTime1 = datetime.datetime.strptime(baseRunObj1['measTime'], '%Y-%m-%dT%H:%M:%S')
                            antObj = baseRunObj1['antennas']


                        if type(antObj) == type([]):
                            lenAntObj = len(antObj)
                        else:
                            lenAntObj = 1

                        for k in range(lenAntObj):

                            if type(antObj) == type([]):
                                antObj1 = antObj[k]
                            else:
                                antObj1 = antObj

                            if useTMCDB is False:
                                if antObj1.getAttribute('name') == i and antObj1.getAttribute('pad') == msAntPos[i]['pad']:
                                    found = 1
                                    padPosObj = antObj1.PadPosition
                                    brPadPos = [padPosObj.getAttribute('X'), padPosObj.getAttribute('Y'), padPosObj.getAttribute('Z')]
                                    antVecObj = antObj1.AntennaVector
                                    brAntVec = [antVecObj.getAttribute('X'), antVecObj.getAttribute('Y'), antVecObj.getAttribute('Z')]
                                    posErrObj = antObj1.PositionError
                                    brPosErr = [posErrObj.getAttribute('X'), posErrObj.getAttribute('Y'), posErrObj.getAttribute('Z')]
                                    break
                            else:
                                if antObj1['name'] == i and antObj1['pad']['name'] == msAntPos[i]['pad']:
                                    found = 1
                                    padPosObj = antObj1['pad']['position']
                                    brPadPos = [padPosObj['x'], padPosObj['y'], padPosObj['z']]
                                    antVecObj = antObj1['vector']
                                    brAntVec = [antVecObj['x'], antVecObj['y'], antVecObj['z']]
                                    posErrObj = antObj1['positionError']
                                    brPosErr = [posErrObj['x'], posErrObj['y'], posErrObj['z']]
                                    break

                        if found == 1: break # modified


                if found != 1:

    #                     casaCmd = casaCmd + '# Note: no baseline run found for antenna '+i+'.\n\n'

                    missingAntennas.append(i)

                else:

                    if brPadPos[0] == msAntPos[i]['padPos'][0] and brPadPos[1] == msAntPos[i]['padPos'][1] and brPadPos[2] == msAntPos[i]['padPos'][2]:

                        if brAntVec[0] != msAntPos[i]['antPos'][0] or brAntVec[1] != msAntPos[i]['antPos'][1] or brAntVec[2] != msAntPos[i]['antPos'][2]:

                            posDiff = []
                            for j in range(3):
                                posDiff.append(brAntVec[j] - msAntPos[i]['antPos'][j])

                            if brPosErr[0] == 0 or brPosErr[1] == 0 or brPosErr[2] == 0:
                        
                                print("ERROR: Some baseline observing run position errors are null.")

                            else:
                                totalPositionSNR = pb.sqrt((posDiff[0]/brPosErr[0])**2 + (posDiff[1]/brPosErr[1])**2 + (posDiff[2]/brPosErr[2])**2)
                                totalPositionError = np.linalg.norm(brPosErr)
                                if totalPositionSNR >= thresh:

                                    brLat = math.asin(brPadPos[2]/np.sqrt(brPadPos[0]**2+brPadPos[1]**2+brPadPos[2]**2))
                                    brLon = math.atan2(brPadPos[1], brPadPos[0])

                                    posDiff1 = []
                                    posDiff1.append(-math.sin(brLon)*posDiff[0]-math.cos(brLon)*math.sin(brLat)*posDiff[1]+math.cos(brLon)*math.cos(brLat)*posDiff[2])
                                    posDiff1.append(math.cos(brLon)*posDiff[0]-math.sin(brLon)*math.sin(brLat)*posDiff[1]+math.sin(brLon)*math.cos(brLat)*posDiff[2])
                                    posDiff1.append(math.cos(brLat)*posDiff[1]+math.sin(brLat)*posDiff[2])

                                    if np.linalg.norm(posDiff1) > 2e-3: casaCmd = casaCmd + '# Note: the correction for antenna '+i+' is larger than 2mm.\n\n'

                                    if np.linalg.norm(posDiff1) >= minPosDiff:

                                        msAntCorr[i] = {}
                                        msAntCorr[i]['posDiff'] = posDiff1
                                        if verbose == True: casaCmd = casaCmd + '# Position for antenna '+i+' is derived from baseline run made on '+str(measTime1)+'.\n\n' # modified
                                        gcAntParam1.append(tuple(['# '+i+' %15.5e%15.5e%15.5e%15.5e%25s' % (posDiff1[0], posDiff1[1], posDiff1[2], np.linalg.norm(posDiff1), measTime1), np.linalg.norm(posDiff1)]))
                                else:
                                    lowSNRPositions += 1
                                    totalPositionSNRs.append(totalPositionSNR)
                                    totalPositionErrors.append(totalPositionError)

                                    if useTMCDB is False:
                                        antennaPad.append(baseRunObj1.getAttribute('measTime') + ' ' + str(i) + ' ' + antObj1.getAttribute('pad'))
                                    else:
                                        antennaPad.append(baseRunObj1['measTime'] + ' ' + str(i) + ' ' + antObj1['pad']['name'])

                                    # repeat the calculations from the True branch
                                    brLat = math.asin(brPadPos[2]/np.sqrt(brPadPos[0]**2+brPadPos[1]**2+brPadPos[2]**2))
                                    brLon = math.atan2(brPadPos[1], brPadPos[0])
                                    myposDiff1 = []
                                    myposDiff1.append(-math.sin(brLon)*posDiff[0]-math.cos(brLon)*math.sin(brLat)*posDiff[1]+math.cos(brLon)*math.cos(brLat)*posDiff[2])
                                    myposDiff1.append(math.cos(brLon)*posDiff[0]-math.sin(brLon)*math.sin(brLat)*posDiff[1]+math.sin(brLon)*math.cos(brLat)*posDiff[2])
                                    myposDiff1.append(math.cos(brLat)*posDiff[1]+math.sin(brLat)*posDiff[2])
                                    totalPositions.append(np.linalg.norm(myposDiff1))
                    else:
                        brLat = math.asin(brPadPos[2]/np.sqrt(brPadPos[0]**2+brPadPos[1]**2+brPadPos[2]**2))
                        brLon = math.atan2(brPadPos[1], brPadPos[0])

                        brPosTot = []
                        brPosTot.append(brAntVec[0] + -math.sin(-brLon)*brPadPos[0]-math.cos(-brLon)*math.sin(-brLat)*brPadPos[1]+math.cos(-brLon)*math.cos(-brLat)*brPadPos[2])
                        brPosTot.append(brAntVec[1] + math.cos(-brLon)*brPadPos[0]-math.sin(-brLon)*math.sin(-brLat)*brPadPos[1]+math.sin(-brLon)*math.cos(-brLat)*brPadPos[2])
                        brPosTot.append(brAntVec[2] + np.cos(-brLat)*brPadPos[1]+np.sin(-brLat)*brPadPos[2])

                        msLat = math.asin(msAntPos[i]['padPos'][2]/np.sqrt(msAntPos[i]['padPos'][0]**2+msAntPos[i]['padPos'][1]**2+msAntPos[i]['padPos'][2]**2))
                        msLon = math.atan2(msAntPos[i]['padPos'][1], msAntPos[i]['padPos'][0])

                        msPosTot = []
                        msPosTot.append(msAntPos[i]['antPos'][0] + -math.sin(-msLon)*msAntPos[i]['padPos'][0]-math.cos(-msLon)*math.sin(-msLat)*msAntPos[i]['padPos'][1]+math.cos(-msLon)*math.cos(-msLat)*msAntPos[i]['padPos'][2])
                        msPosTot.append(msAntPos[i]['antPos'][1] + math.cos(-msLon)*msAntPos[i]['padPos'][0]-math.sin(-msLon)*math.sin(-msLat)*msAntPos[i]['padPos'][1]+math.sin(-msLon)*math.cos(-msLat)*msAntPos[i]['padPos'][2])
                        msPosTot.append(msAntPos[i]['antPos'][2] + math.cos(-msLat)*msAntPos[i]['padPos'][1]+math.sin(-msLat)*msAntPos[i]['padPos'][2])

                        posDiff = []
                        for j in range(3):
                            posDiff.append(brPosTot[j] - msPosTot[j])

                        if brPosErr[0] == 0 or brPosErr[1] == 0 or brPosErr[2] == 0:
                    
                            print("Note: some errors are null.")

                        else:
                            totalPositionSNR = pb.sqrt((posDiff[0]/brPosErr[0])**2 + (posDiff[1]/brPosErr[1])**2 + (posDiff[2]/brPosErr[2])**2)
                            totalPositionError = np.linalg.norm(brPosErr)
                            if totalPositionSNR >= thresh:

                                brPosTot1 = []
                                brPosTot1.append(brPadPos[0] + -math.sin(brLon)*brAntVec[0]-math.cos(brLon)*math.sin(brLat)*brAntVec[1]+math.cos(brLon)*math.cos(brLat)*brAntVec[2])
                                brPosTot1.append(brPadPos[1] + math.cos(brLon)*brAntVec[0]-math.sin(brLon)*math.sin(brLat)*brAntVec[1]+math.sin(brLon)*math.cos(brLat)*brAntVec[2])
                                brPosTot1.append(brPadPos[2] + math.cos(brLat)*brAntVec[1]+math.sin(brLat)*brAntVec[2])

                                msPosTot1 = []
                                msPosTot1.append(msAntPos[i]['padPos'][0] + -math.sin(msLon)*msAntPos[i]['antPos'][0]-math.cos(msLon)*math.sin(msLat)*msAntPos[i]['antPos'][1]+math.cos(msLon)*math.cos(msLat)*msAntPos[i]['antPos'][2])
                                msPosTot1.append(msAntPos[i]['padPos'][1] + math.cos(msLon)*msAntPos[i]['antPos'][0]-math.sin(msLon)*math.sin(msLat)*msAntPos[i]['antPos'][1]+math.sin(msLon)*math.cos(msLat)*msAntPos[i]['antPos'][2])
                                msPosTot1.append(msAntPos[i]['padPos'][2] + math.cos(msLat)*msAntPos[i]['antPos'][1]+math.sin(msLat)*msAntPos[i]['antPos'][2])

                                posDiff1 = []
                                for j in range(3):
                                    posDiff1.append(brPosTot1[j] - msPosTot1[j])

                                if np.linalg.norm(posDiff1) > 2e-3: casaCmd = casaCmd + '# Note: the correction for antenna '+i+' is larger than 2mm.\n\n'

                                if np.linalg.norm(posDiff1) >= minPosDiff:

                                    msAntCorr[i] = {}
                                    msAntCorr[i]['posDiff'] = posDiff1
                                    if verbose == True: casaCmd = casaCmd + '# Position for antenna '+i+' is derived from baseline run made on '+str(measTime1)+'.\n\n' # modified
                                    gcAntParam1.append(tuple(['# '+i+' %15.5e%15.5e%15.5e%15.5e%25s' % (posDiff1[0], posDiff1[1], posDiff1[2], np.linalg.norm(posDiff1), measTime1), np.linalg.norm(posDiff1)]))
                            else:
                                lowSNRPositions += 1
                                totalPositionSNRs.append(totalPositionSNR)
                                totalPositionErrors.append(totalPositionError)

                                if useTMCDB is False:
                                    antennaPad.append(baseRunObj1.getAttribute('measTime') + ' ' + str(i) + ' ' + antObj1.getAttribute('pad'))
                                else:
                                    antennaPad.append(baseRunObj1['measTime'] + ' ' + str(i) + ' ' + antObj1['pad']['name'])

                                # repeat the calculations from the True branch
                                brPosTot1 = []
                                brPosTot1.append(brPadPos[0] + -math.sin(brLon)*brAntVec[0]-math.cos(brLon)*math.sin(brLat)*brAntVec[1]+math.cos(brLon)*math.cos(brLat)*brAntVec[2])
                                brPosTot1.append(brPadPos[1] + math.cos(brLon)*brAntVec[0]-math.sin(brLon)*math.sin(brLat)*brAntVec[1]+math.sin(brLon)*math.cos(brLat)*brAntVec[2])
                                brPosTot1.append(brPadPos[2] + math.cos(brLat)*brAntVec[1]+math.sin(brLat)*brAntVec[2])
                                msPosTot1 = []
                                msPosTot1.append(msAntPos[i]['padPos'][0] + -math.sin(msLon)*msAntPos[i]['antPos'][0]-math.cos(msLon)*math.sin(msLat)*msAntPos[i]['antPos'][1]+math.cos(msLon)*math.cos(msLat)*msAntPos[i]['antPos'][2])
                                msPosTot1.append(msAntPos[i]['padPos'][1] + math.cos(msLon)*msAntPos[i]['antPos'][0]-math.sin(msLon)*math.sin(msLat)*msAntPos[i]['antPos'][1]+math.sin(msLon)*math.cos(msLat)*msAntPos[i]['antPos'][2])
                                msPosTot1.append(msAntPos[i]['padPos'][2] + math.cos(msLat)*msAntPos[i]['antPos'][1]+math.sin(msLat)*msAntPos[i]['antPos'][2])
                                myposDiff1 = []
                                for j in range(3):
                                    myposDiff1.append(brPosTot1[j] - msPosTot1[j])
                                totalPositions.append(np.linalg.norm(myposDiff1))

            gcAntList = []
            for i in sorted(msAntCorr.keys()): gcAntList.append(i)
            gcAntList = ','.join(gcAntList)

            gcAntParam = []
            gcAntParam0 = []
            for i in sorted(msAntCorr.keys()):
                for j in range(3):
    #                 gcAntParam.append(str(msAntCorr[i]['posDiff'][j]))
                    gcAntParam.append('%.5e' % msAntCorr[i]['posDiff'][j])
                    gcAntParam0.append('0')
            gcAntParam = ','.join(gcAntParam)
            gcAntParam0 = ','.join(gcAntParam0)

            f = open(outfile, 'a')

    #             print >> f, 'name,antenna,xoff,yoff,zoff,comment'

            if gcAntList != '':

                for i in sorted(msAntCorr.keys()):
    #                     print >> f, msName+','+i+','+str(msAntCorr[i]['posDiff'][0])+','+str(msAntCorr[i]['posDiff'][1])+','+str(msAntCorr[i]['posDiff'][2])+','
                    if logLowSNRPositions or outfile != 'antennapos.csv':
                        writeMsName = os.path.basename(msName)
                    else:
                        writeMsName = msName
                    print('%s,%s,%.5e,%.5e,%.5e,' % (writeMsName, i, msAntCorr[i]['posDiff'][0], msAntCorr[i]['posDiff'][1], msAntCorr[i]['posDiff'][2]), file=f)
        
            f.close()

            if gcAntList != '' or lbc == True or len(missingAntennas) != 0:

                casaCmd = casaCmd + "os.system('rm -rf %s.antpos') \n"%(msName)  # Added by CLB
                casaCmd = casaCmd + "gencal(vis = '"+msName+"',\n"
                casaCmd = casaCmd + "  caltable = '"+msName+".antpos',\n"
                casaCmd = casaCmd + "  caltype = 'antpos',\n"

                if gcAntList == '':
                    casaCmd = casaCmd + "  antenna = '"+antNames[0]+"',\n"
                else:
                    casaCmd = casaCmd + "  antenna = '"+gcAntList+"',\n"

                obsTime1 = datetime.datetime.strftime(obsTime, '%Y-%m-%dT%H:%M:%S')

                if (obsTime1 >= '2015-05-12T00:00:00' and obsTime1 <= '2015-06-01T00:00:00') or lbc == True:

                    if gcAntList == '' and lbc == True:
                        casaCmd = casaCmd + "#  parameter = ["+gcAntParam0+"])\n"
                        casaCmd = casaCmd + "  parameter = [0,0,0])\n"
                    else:
                        casaCmd = casaCmd + "#  parameter = ["+gcAntParam0+"])\n"
                        casaCmd = casaCmd + "  parameter = ["+gcAntParam+"])\n"

                elif datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S') >= '2017-09-11 00:00:00':

                    if gcAntList == '':
                        casaCmd = casaCmd + "#  parameter = ["+gcAntParam0+"])\n"
                        casaCmd = casaCmd + "  parameter = [0,0,0])\n"
                    else:
                        casaCmd = casaCmd + "#  parameter = ["+gcAntParam0+"])\n"
                        casaCmd = casaCmd + "  parameter = ["+gcAntParam+"])\n"

                else:

                    if gcAntList == '':
                        casaCmd = casaCmd + "#  parameter = ["+gcAntParam0+"])\n"
                        casaCmd = casaCmd + "  parameter = [0,0,0])\n"
                    else:
                        casaCmd = casaCmd + "  parameter = ["+gcAntParam0+"])\n"
                        casaCmd = casaCmd + "#  parameter = ["+gcAntParam+"])\n"

                casaCmd += '\n\n# antenna x_offset y_offset z_offset total_offset baseline_date\n'
                for ij in sorted(gcAntParam1, key=lambda x:x[1], reverse=True):
                    casaCmd += ij[0]+'\n'

                if len(missingAntennas) != 0: casaCmd = '# Warning: no baseline run found for following antenna(s): '+str(missingAntennas)+'.\n\n' + casaCmd

                if len(msNames) == 1 and not logLowSNRPositions:
                    return casaCmd

            else:

                print("Note: I could not find any offset between the antenna positions in the ASDM and in the database, so I am not including any gencal call.")

            if (logLowSNRPositions):
                if (lowSNRPositions > 0):
                    # measurement can be lowSNR but also below the minPosDiff, but these cases may be rare
                    outliers = len(np.where(np.abs(totalPositions) > minPosDiff)[0])
                    if outliers > 0:
                        severeOutliers = len(np.where(np.abs(totalPositions) > 10*minPosDiff)[0]) # i.e. 500e-6
                        # These are points that were rejected by correctMyAntennaPositions but not by EOC
                        rejectJAOaccepted = len(np.where(np.abs(totalPositionErrors) < 300e-6)[0])
                        snrfile = os.path.basename(msName)+'_severe%d_rejectJAOaccepted%d_%d_%d_lowSNRPositions' % (severeOutliers,rejectJAOaccepted,outliers,lowSNRPositions)
                        lowSNRFile = open(snrfile, 'w')
                        lowSNRFile.write('#Measurement time  antenna  pad  vectorLength(m)  uncertainty(m)  %s\n' % (scienceDate))
                        for ij, err in enumerate(totalPositionErrors):
                            lowSNRFile.write('%s %f %f\n' % (antennaPad[ij], totalPositions[ij],err))
                        lowSNRFile.close()
                        print("Wrote ", snrfile)
                    else:
                        print("%d Low SNR positions found but none were more than %f microns" % (lowSNRPositions,10*1e6*minPosDiff))
                else:
                    print("No low SNR positions encountered in %s." % (os.path.basename(msName)))
                if len(msNames) == 1: 
                    return casaCmd
        # end 'for' loop over msNames







    def getSpwInfo(self, msName, intent='OBSERVE_TARGET', caching=False):
        """
        Return a dictionary with the properties of the SPWs in the given MS
        for the data with the given intent(s)

        If caching is True (default False), the determined return values
        for the particular (msName, intent) pair are cached and the method 
        returns the cached values (rather then recomputing them) 
        in case it is called again with the same parameters.

        For msName='', intent='', caching=True the entire cache is erased.
        """

        print('getSpwInfo for MS '+msName+', intent "'+intent+'"')

        ### cacheing mechanism for speeding up the processing (DP, May 2020)
        if (msName in self.swInfo.keys()) and (intent in self.swInfo[msName].keys()):
            if not caching:
                print('  Re-determining getSpwInfo result ...')
            else:
                print('  Re-using cached getSpwInfo result.')
                return self.swInfo[msName][intent]

        elif msName=='' and intent=='':
            if caching:
                self.swInfo.clear()
                print('Entire getSpwInfo cache erased.')
                return {}
            else:
                print('Error: empty msName and intent.')
                return {}
        ###

        print('Running getSpwInfo ...')

        mytb = createCasaTool(tbtool)
        mytb.open(msName+'/STATE')
        obsModes = mytb.getcol('OBS_MODE')
        mytb.close()

        obsModes1 = []
        for i in range(len(obsModes)):
            if re.search(intent, obsModes[i]) is not None:
                obsModes1.append(i)

        if len(obsModes1) == 0:
            if 'OBSERVE_TARGET' in intent: # this is mainly for the cal survey reduction
                print('WARNING: There seems to be no OBSERVE_TARGET intent in the data.')
                print('WARNING: I will try with the intent CALIBRATE_PHASE. THIS MAY BE WRONG!!')
                obsModes1 = []
                for i in range(len(obsModes)):
                    if re.search('CALIBRATE_PHASE', obsModes[i]) is not None:
                        obsModes1.append(i)
                if len(obsModes1) == 0:
                    print('WARNING: There seems to be no CALIBRATE_PHASE intent in the data.')
                    print('WARNING: I will try with the intents CALIBRATE_AMPLI and CALIBRATE_FLUX. THIS MAY BE WRONG!!')
                    obsModes1 = []
                    for i in range(len(obsModes)):
                        if re.search('CALIBRATE_AMPLI|CALIBRATE_FLUX', obsModes[i]) is not None:
                            obsModes1.append(i)
                    if len(obsModes1) == 0: sys.exit('ERROR: Intent not found.')
            else:
                #sys.exit('ERROR: Intent not found.')
                print('WARNING: Intent not found.')
                return {}

        mytb.open(msName+'/PROCESSOR')
        tb1 = mytb.query("SUB_TYPE == 'ALMA_CORRELATOR_MODE' OR SUB_TYPE == 'ALMA_BASELINE' OR SUB_TYPE == 'ALMA_ACA' OR SUB_TYPE == 'ALMA_ACASPEC'")
        procIds = tb1.rownumbers()

        if (type(procIds) == int):
            # Added by T. Hunter to prevent crash at 'for' loop when only one value is returned.
            procIds = [procIds]
        tb1.close()
        mytb.close()

        mytb.open(msName+'/DATA_DESCRIPTION')
        spwIds = mytb.getcol('SPECTRAL_WINDOW_ID')
        spwIds = [int(i) for i in spwIds] # fix for python3.12
        mytb.close()

        mytb.open(msName)
        dataDescIds = []
        for i in procIds:
            for j in obsModes1:
                tb1 = mytb.query('PROCESSOR_ID == '+str(i)+' AND STATE_ID == '+str(j))
                dataDescIds1 = sorted(dict.fromkeys(tb1.getcol('DATA_DESC_ID')).keys())
                dataDescIds.extend(dataDescIds1)
                tb1.close()
        mytb.close()

        dataDescIds = sorted(dict.fromkeys(dataDescIds).keys())
        if intent in ['OBSERVE_TARGET', 'OBSERVE_TARGET|CALIBRATE_BANDPASS']:

            mytb.open(msName)
            integTime = []
            for i in dataDescIds:
                tb1 = mytb.query('DATA_DESC_ID == '+str(i))
                integTime1 = list(dict.fromkeys(tb1.getcol('EXPOSURE')).keys())
                if len(integTime1) != 1:
                    print("WARNING: DATA ASSOCIATED TO DATA_DESC_ID="+str(i)+" IN "+msName+" HAVE MORE THAN ONE INTEGRATION TIME.")
                integTime.append(integTime1[0])
                tb1.close()
            mytb.close()

        mytb.open(msName+'/SPECTRAL_WINDOW')
        numChans = mytb.getcol('NUM_CHAN')
        spwName = mytb.getcol('NAME')
        refFreqCol = mytb.getcol('REF_FREQUENCY')
        bbcNoCol = mytb.getcol('BBC_NO')
        spwInfo = {}
        for i in range(len(dataDescIds)):
            if numChans[spwIds[dataDescIds[i]]] != 1 and 'CH_AVG' not in spwName[spwIds[dataDescIds[i]]]:
                spwInfo[spwIds[dataDescIds[i]]] = {}
                spwInfo[spwIds[dataDescIds[i]]]['numChans'] = numChans[spwIds[dataDescIds[i]]]
                spwInfo[spwIds[dataDescIds[i]]]['refFreq'] = refFreqCol[spwIds[dataDescIds[i]]] # refFreq[spwIds[dataDescIds[i]]]
                spwInfo[spwIds[dataDescIds[i]]]['basebandNum'] = bbcNoCol[spwIds[dataDescIds[i]]]
                spwInfo[spwIds[dataDescIds[i]]]['meanFreq'] = np.mean(mytb.getcell('CHAN_FREQ', spwIds[dataDescIds[i]]))
                spwInfo[spwIds[dataDescIds[i]]]['meanAbsChanWidth'] = np.mean(np.abs(mytb.getcell('CHAN_WIDTH', spwIds[dataDescIds[i]])))
                if intent in ['OBSERVE_TARGET', 'OBSERVE_TARGET|CALIBRATE_BANDPASS']: spwInfo[spwIds[dataDescIds[i]]]['integTime'] = integTime[i]

        mytb.close()

        ### cacheing mechanism for speeding up processing (DP, May 2020)
        if caching:
            if msName not in self.swInfo.keys():
                self.swInfo[msName] = {}
            self.swInfo[msName][intent] = spwInfo
        ###

        return spwInfo


    def getCalWeightStats(self, msName, chanFrac=None):
        """
        chanFrac: fraction of the channels to plot OR channel selection string
           examples:  
               0.2  (as a float) will only plot the central 20% of the channels in each SPW
               '60~80' (as a string) will only plot channels 60 to 80
           default: None - plot all channels
        """

        sciSpwInfo = self.getSpwInfo(msName, intent='OBSERVE_TARGET|CALIBRATE_BANDPASS', caching=True)

        for i in sciSpwInfo:
            myspw = str(i)
            if chanFrac != None and chanFrac != '':
                if type(chanFrac)==float:
                    numChan = sciSpwInfo[i]['numChans']
                    minchan = max(0, int(numChan/2 - chanFrac * numChan/2))
                    maxchan = min(numChan-1, int(numChan/2 + chanFrac * numChan/2))
                    myspw = str(i)+":"+str(minchan)+"~"+str(maxchan)                    
                elif type(chanFrac) == str:
                    myspw = str(i)+":"+chanFrac

            print("Plotting SPW ", myspw, " ...")

            plotms(vis = msName, xaxis = 'time', yaxis = 'weight', spw = myspw, xselfscale = True, yselfscale = True,
                coloraxis = 'field', plotfile = msName + '_weights_spw'+str(i)+'.png', overwrite = True)

        return

