    def plotAntennas(self, vis, plotfile=''):
        """
        Plot antenna/pad positions in ANTENNA table.
        vis: measurement set
        plotfile: default name is <vis>.plotAntennas.png
        """
        (sitelon, sitelat) = (pb.radians(-67.75), pb.radians(-23.02))
