def DrawAntennaLegend(desc, antennaNames, medianValues=None, colors=overlayColors):
    """
    Draws colored antenna names down the right edge of a matplotlib plot.
    desc: descriptor for the plot (i.e. from pb.subplot())
    antennaNames: list of antenna names
    medianValues: dictionary with integer keys corresponding to 0..number of antennaNames; 
          if specified, then also draw the names on right edge of the plot at specified level
    Called by: snrFromCaltable()
    -Todd Hunter
    """
    print("Median values: ", medianValues)
    for i,name in enumerate(antennaNames):
        y = 1.0 - float(i)/np.min([50,len(antennaNames)])
        mysize = np.min([10,400/len(antennaNames)])
        pb.text(1.01, y, name, color=colors[i], transform=desc.transAxes, ha='left', 
                size=mysize)
        if medianValues is not None:
            blendedTrans = matplotlib.transforms.blended_transform_factory(desc.transAxes, 
                                                                           desc.transData)
            pb.text(0.99, medianValues[i], name, ha='right', color=colors[i], 
                    transform=blendedTrans, size=mysize+2)
    return

def DrawSourceLegend(yrange, fieldsToPlot, msFound, vm, subplotRows, mysrcsize, mymsmd=None):
    """
    Called by plotWVRSolutions
    """
    (xlim,ylim,myxrange,myyrange) = GetLimits()
    if (yrange[0] == 0 and yrange[1] == 0):
        # Make space for source labels at the bottom of the plot
        pb.ylim([ylim[0] - myyrange*0.25, ylim[1]])
        (xlim,ylim,myxrange,myyrange) = GetLimits()
    for f in range(len(fieldsToPlot)):
        field = fieldsToPlot[f]
        if (msFound):
            if (mymsmd is None):
                myfieldstring = '%d: %s' % (field, vm.getFieldNamesForFieldId(field))
            else:
                myfieldstring = '%d: %s' % (field, mymsmd.namesforfields(field)[0])
        else:
            myfieldstring = 'field %d' % (field)
        if (f < (1+len(fieldsToPlot))/2):
            myxpos = 0.05
            myypos = (f+0.3)*0.03*subplotRows  # 0.02, 0.078 0.137
        else:
            myxpos = 0.50
            myypos = (f-int((1+len(fieldsToPlot))/2)+0.3)*0.03*subplotRows
        pb.text(myxpos, myypos, myfieldstring, color=overlayColors[field],
                size=mysrcsize, transform=pb.gca().transAxes)

def GetLimits():
    """
    Gets the current plot limits and ranges and returns them.
    -- Todd Hunter
    """
    xlim = pb.xlim()
    ylim = pb.ylim()
    myxrange = xlim[1]-xlim[0]
    myyrange = ylim[1]-ylim[0]
    return(xlim,ylim,myxrange,myyrange)

def wrapPhase(phase):
    """
    This is meant to be run after taking the difference between two
    -pi..pi phase streams, so that the difference remains in -pi..pi,
    so that subsequent phase unwrap algorithms will work properly.
    -Todd Hunter
    """
    idx = np.where(phase > np.pi)
    phase[idx] -= 2*np.pi
    idx = np.where(phase < -np.pi)
    phase[idx] += 2*np.pi
    return(phase)

def phaseUnwrapDifferences(phase):
    """
    Algorithm from Richard Hills called from plotWVRSolutions. Accepts angle
    in radians, and returns angle in radians.
    Method: successive differences
    WARNING: still under development!
    - Todd Hunter
    """
    for i in range(1,len(phase)):
        testwrap = phase[i] - phase[i-1] 
        if (testwrap < -np.pi):
            phase[i] += np.pi*2
        elif (testwrap > np.pi):
            phase[i] -= np.pi*2
    return(phase)

def phaseUnwrapExtrapolate(phase, f=0.3, requireTwo=False):
    """
    Algorithm from Richard Hills called from plotWVRSolutions. Accepts angle
    in radians, and returns angle in radians.
    Method: extrapolate from past to future
    Inputs:
    requireTwo: if True, two successive points must agree to indicate a wrap
    WARNING: still under development!
    - Todd Hunter
    """
    for i in range(1,len(phase)-2):
        # e.g.  150, 170, -170 --> -170-(170+0.3*(170-150)) --> -170-(176)=-346
        #  so, one would add 360 to -170 = +190
        testwrap = phase[i+1] - (phase[i] + f*(phase[i]-phase[i-1]))
        testwrap2 = phase[i+2] - (phase[i] + f*(phase[i]-phase[i-1]))
        if (testwrap < -np.pi and (testwrap2 < -np.pi or requireTwo==False)):
            phase[i+1:] += np.pi*2
        elif (testwrap > np.pi and (testwrap2 > np.pi or requireTwo==False)):
            phase[i+1:] -= np.pi*2
    return(phase)

def phaseUnwrapInterpolate(phase, g=0.4):
    """
    Algorithm from Richard Hills called from plotWVRSolutions. Accepts angle
    in radians, and returns angle in radians.
    Method: extrapolate from past to future
    g: for smooth data g should be 0.5;  for noisy data, 0.3
    WARNING: still under development!
    - Todd Hunter
    """
    for i in range(1,len(phase)-2):
        testwrap = (phase[i+1] - g*(phase[i+2] - phase[i+1])) - (phase[i]+g*(phase[i]-phase[i-1]))
        if (testwrap < -np.pi):
            phase[i+1:] += np.pi*2
        elif (testwrap > np.pi):
            phase[i+1:] -= np.pi*2
    return(phase)

def phaseUnwrap(phase):
   """
   Algorithm from Ed Fomalont called from plotWVRSolutions.  Accepts angle in radians.
   Take phase difference, adds 4.5 turns, mods by 1 turn, subtract 0.5 turns. 
   - Todd Hunter
   """
   for i in range(1,len(phase)):
       phaseDiff = phase[i]-phase[i-1]
       pd = np.mod(phaseDiff + 4.5*(2*np.pi), 2*np.pi) - np.pi
       phase[i] = phase[i-1]+pd
   return(phase)
   
def checkTimeAgreement(a,b,t1,t2, fid):
    """
    Initially used by plotWVRSolutions to confirm that times match between antennas.
    But not currently used.  -- Todd Hunter
    """
    failures = []
    for i in range(len(t1)):
        if (fid != 0):
            fid.write('%2d %2d %.2f %.2f\n'%(a,b,t1[i],t2[i]))
        if (np.abs(t1[i] - t2[i]) > 1):
            failures.append(i)
    if (len(failures) > 0):
        return(False, failures)
    else:
        return(True, failures)

def scaleWeightSpectrum(vis, wtfac=1.0, antenna='', square=False, 
                        squareroot=False, spw='', obsid=-1, column='WEIGHT_SPECTRUM'):
    """
    scaleWeightSpectrum: scale data weight spectrum column by a user supplied 
          factor (or square or square root them).  See also scaleweights.
    Note: this function assumes equivalence between spw and data_descriptor_id.
         If this is not the case for your data, email the maintainer.         
    * wtfac =  multiplicative weight factor
    * antenna = restrict scaling to baselines including this single 
                        antenna ID (int or string)
    * square = Boolean, if True, then square the weights 
    * squareroot = Boolean, if True, then take the square root of the weights 
    * spw = integer or string or list of spws to process
    * obsid = integer or string or comma-delimited list of obsids to process
    """
    if (os.path.exists(vis) == False):
        print("Could not find ms file = ", vis)
        return(2)
    if type(wtfac) is not types.FloatType and type(wtfac) is not types.IntType:
        print('ERROR: wtfac must be a float or integer')
        return(1)
    if (square == False and squareroot == False):
        print('Will scale weights by a factor of '+str(wtfac))
    elif (square and squareroot):
        print("You cannot select both square and squareroot")
        return
    elif (square):
        print("Will square the existing weights")
    elif (squareroot):
        print("Will square root the existing weights")
    if (obsid != -1):
        obsidlist = [int(i) for i in str(obsid).split(',')]
    else:
        obsidlist = []
    # Find number of data description IDs
    mytb = createCasaTool(tbtool)
    mytb.open(vis+"/DATA_DESCRIPTION")
    ddspwlist = mytb.getcol("SPECTRAL_WINDOW_ID")
    ddpollist = mytb.getcol("POLARIZATION_ID")
    mytb.close()
    ndd = ddspwlist.__len__()
    print('Found '+str(ndd)+' DataDescription IDs')
    # Now the polarizations (number of correlations in each pol id)
    mytb.open(vis+"/POLARIZATION")
    ncorlist = mytb.getcol("NUM_CORR")
    mytb.close()
    #
    ntotrow=0
    ntotpts=0
    spw = parseSpw(vis,spw)
    print("Will process spws = ", spw)
    mytb.open(vis,nomodify=False)
    for idd in range(ndd):
      if (idd in spw):
        # Find number of correlations in this DD
        pid = ddpollist[idd]
        ncorr = ncorlist[pid]
        # Select this DD (after reset if needed)
        if (len(obsidlist) > 0):
            myt = mytb.query('DATA_DESC_ID==%d && OBSERVATION_ID in %s'%(idd,str(obsidlist)))
        else:
            myt = mytb.query('DATA_DESC_ID==%d'%(idd))
        nwchan=0
        # get the weights
        recw = myt.getcol(column)
        antenna1 = myt.getcol('ANTENNA1')
        antenna2 = myt.getcol('ANTENNA2')
        if (len(recw.shape) < 3):
            myt.close()
            mytb.close()
            if (len(obsidlist) > 0):
                print("No matching data found for this combination of ObsID and spw.")
            else:
                print("No matching data found for this spw.")
            continue
        (npol,nchan,ni) = recw.shape
        doscale = False
        if (antenna == ''):
            doscale = True
        elif (str(antenna) == str(antenna1[j]) or str(antenna) == str(antenna2[j])):
            doscale = True
        if (doscale):
            if (square):
                recw = np.square(recw)
            elif (squareroot):
                recw = np.sqrt(recw)
            else:
                recw *= wtfac
            nwchan += nchan*ni
        myt.putcol(column, recw)
        myt.close()
        ntotrow += ni
        ntotpts += nwchan
        print('Scaled '+str(nwchan)+' spectral points in '+str(ni)+' rows in DD='+str(idd))
    #
    print('Scaled Total '+str(ntotpts)+' spectral points in '+str(ntotrow)+' rows')
    mytb.close()
    return

def compareTAIUTC(path1, path2, tablename='data/geodetic/TAI_UTC'):
    """
    path1: path to a CASA build ('/data/geodetic/TAI_UTC' shall be appended)
    path2: path to a different build ('/data/geodetic/TAI_UTC' shall be appended)
    """
    if not os.path.exists(path1):
        print("path1 not found")
        return
    if not os.path.exists(path2):
        print("path2 not found")
        return
    path1 = os.path.join(path1,tablename)
    path2 = os.path.join(path2,tablename)
    mytb = createCasaTool(tbtool)
    mytb2 = createCasaTool(tbtool)
    mytb.open(path1)
    mytb2.open(path2)
    names = mytb.getkeywords()
    for name in names:
        val1 = mytb.getkeyword(name)
        val2 = mytb2.getkeyword(name)
        if val1 == val2:
            print("keyword %s matches" % (name))
        else:
            print("keyword %s differs: %s vs. %s" % (name, str(val1), str(val2)))
    names = mytb.colnames()
    for name in names:
        val1 = mytb.getcol(name)
        val2 = mytb2.getcol(name)
        if np.array_equal(val1, val2):
            print("column %s matches" % (name))
        else:
            print("column %s differs" % (name))
    mytb.close()
    mytb2.close() 

def brightestMosaicField(vislist, spw='', fields='', pol=[0,1], axis='amp', 
                         datacolumn='corrected_data', useflags=True, 
                         stat='median', intent='OBSERVE_TARGET#ON_SOURCE', 
                         takeNumpyAbsolute=False, weightedMean=True, 
                         use_tbcalc=False, useFullNameAsKey=False, quiet=True,
                         makeHistograms=False, outdir='', ignoreTargetMS=True,
                         verbose=False):
    """
    Runs meanVisibility on a specified list of fields for each specified EB and
    returns a dictionary containing the brightest continuum field among them 
    for each EB.
    -Todd Hunter
    vislist: a python list or a wildcard string for glob; each vis will be 
             assessed and reported independently
    spw: string or int (default is to average flux over all science spws)
    fields: list of field integer IDs or string IDs, or a comma-delimited string
    pol: 0, 1, [0,1] (for mean of both), or None (None means [0,1])
    useflags: default=True means to ignore flagged data (which is what you want for flux density)
    intent: specify a value to limit scans to a single intent;  default = 'PHASE'
        The value of intent will be surrounded by '*', so short names 'PHASE' will work.
    takeNumpyAbsolute: default=False for vector average (which is what you want for flux density)
    weightedMean: if True, use weight column in weights parameter of np.average()
    use_tbcalc: True or False (uses ms.select) give virtually the same answer but False is 2x faster
    quiet and verbose: passed to meanVisibility
    outdir: for the histograms, blank --> put it where the vis is; './' = cwd
    """
    if vislist.find('*') >= 0:
        vislist = sorted(glob.glob(vislist))
        if ignoreTargetMS:
            newvislist = []
            for vis in vislist:
                if vis.find('_target.ms') < 0:
                    newvislist.append(vis)
            vislist = newvislist
    elif type(vislist) in [str, np.str_]:
        vislist = vislist.split(',')
    a = {}; brightest = {}
    if type(fields) in [str, np.str_]:
        if len(fields) > 0:
            fields = [int(i) for i in fields.split(',')]
    mymsmd = createCasaTool(msmdtool)
    for vis in vislist:
        mymsmd.open(vis)
        if len(fields) == 0:
            myfields = getScienceTargets(vis, returnNames=False, mymsmd=mymsmd)
            print("Found %d field IDs for %s" % (len(myfields),os.path.basename(vis)))
        else:
            myfields = fields
        a[vis] = {}
        if type(spw) == str:
            if spw == '':
                myspw = getScienceSpws(vis, mymsmd=mymsmd)
            spwlist = myspw.split(',')
        elif type(spw) in [int, np.int32, np.int64]:
            spwlist = [spw] 
        for field in myfields:
            vs = []
            for myspw in spwlist:
                if not quiet:
                    print("\n*** Calling au.meanVisibility('%s', spw=%d, field=%d, pol=%s, intent='%s')" % (vis,myspw,field,str(pol),intent))
                v = meanVisibility(vis, myspw, field, pol, axis, datacolumn, useflags,
                                   stat, intent, takeNumpyAbsolute, weightedMean,
                                   use_tbcalc, quiet=quiet, mymsmd=mymsmd, verbose=verbose)
                if not quiet:
                    print("Back")
                if v is not None:
                    vs.append(v)
            mysum = 0
            for v in vs:
                mysum += v[0]
            if len(vs) > 0:
                a[vis][field] = mysum/float(len(vs))
                if (len(vs)) > 1:
                    if verbose:
                        print("Averaging flux over %d spws" % (len(vs)))
        if len(a[vis].values()) == 0:
            print("blank list for vis=%s" % (vis))
            return
        idx = np.argmax(list(a[vis].values()))
        flux = np.max(list(a[vis].values()))
        field = myfields[idx]
        if makeHistograms:
            pb.clf()
            bins = pb.hist(list(a[vis].values()), color='lightblue')[1]
            if spw == '':
                pb.title(os.path.basename(vis) + ' average over science spws')
            else:
                pb.title(os.path.basename(vis) + ' spw%02d'%spw)
            pb.xlabel('Flux density (Jy)')
            pb.ylabel('Number of fields')
            binfill = np.zeros(1+len(bins))
            for i,myfield in enumerate(myfields):
                if myfield in list(a[vis].keys()):
                    # avoid crashing when a field is fully flagged
                    fluxDensity = a[vis][myfield]
                    mybin = np.where(bins > fluxDensity)[0]
                    if len(mybin) == 0:
                        mybin = len(bins)
                    else:
                        mybin = mybin[0]
                    binfill[mybin] += 1
                    pb.text(a[vis][myfield], binfill[mybin]-0.5, '%d'%(myfield), 
                            ha='center', va='center', size=10)
            if outdir == '':
                png = vis + '.fluxhist.png'
            else:
                png = os.path.basename(vis) + '.fluxHistogram.png'
            pb.savefig(png)
            print("Wrote ", png)
        if useFullNameAsKey:
            brightest[vis] = {'field': field, 'flux': flux}
        else:
            brightest[os.path.basename(vis)] = {'field': field, 'flux': flux}
        mymsmd.close()
    return brightest

def meanVisibility(vis, spw='', field='', pol=[0,1], axis='amp', 
                   datacolumn='corrected_data', useflags=True, stat='mean', 
                   intent='CALIBRATE_PHASE#ON_SOURCE', takeNumpyAbsolute=False,
                   weightedMean=True, use_tbcalc=False, channel='',
                   returnAllErrorEstimates=False, showOldCalculation=False, 
                   verbose=False, mymsmd=None, scan='', quiet=False):
    """
    Uses getCorrectedData to compute the vector average across channels, then uses np.mean
    (or np.median if stat=='median') to compute the mean or median across baselines and 
    timestamps to achieve the mean visibility amplitude (i.e. expected flux density), and 
    its standard deviation.
    spw: string or int (default is first science spw)
    field: string or int (can be blank if intent is set)
    pol: 0, 1, [0,1] (for mean of both), or None (None means [0,1])
    datacolumn: will revert to 'data' if 'corrected_data' is not present
    useflags: default=True means to ignore flagged data (which is what you want for flux density)
    intent: specify a value to limit scans to a single intent;  default = 'PHASE'
        The value of intent will be surrounded by '*', so short names 'PHASE' will work.
    takeNumpyAbsolute: default=False for vector average (which is what you want for flux density)
    weightedMean: if True, use weight column in weights parameter of np.average()
    use_tbcalc: True or False (uses ms.select) give virtually the same answer but False is 2x faster
    channel: either blank (average all channels) or a single channel (integer or string integer)
    scan: limit the data examined to this scan or list of scans
          (does not work with the combination of channel='' with use_tbcalc=True)
    stat: 'median' or any other string -> 'mean'
    returnAllErrorEstimates: if True, returns 3 estimates of standard deviation of the mean:
           sigma/sqrt(Nbaselines*Nvisibilities)   
           sigma/sqrt(Nantennas*Nvisibilities)   
           sigma/sqrt(mean([Nantennas,Nbaselines])*Nvisibilities))
        if False, then only the final value is returned, which is what Pipeline2020 uses
    Returns: 2 floats: flux density and standard deviation (in Jy)
       Note: if all data are flagged, then it returns a single value of None
    """
    if not os.path.exists(vis):
        print("meanVisibility(): Could not find measurement set: ", vis)
        return
    if pol is None:
        pol = [0,1]
    if channel == '':
        averageChannel = True
    else:
        averageChannel = False
    needToClose = False
    if spw == '':
        if mymsmd is None:
            mymsmd = createCasaTool(msmdtool)
            mymsmd.open(vis)
            needToClose = True
        spw = getScienceSpws(vis, returnString=False, mymsmd=mymsmd)[0]
        print("Using first science spw: ", spw)
    if datacolumn == 'corrected_data':
        myColumns = dataColumns(vis)
        if datacolumn.upper() not in myColumns:
            print("%s column is not in this dataset (%s), reverting to 'data'" % (datacolumn,myColumns))
            datacolumn = 'data'
    result = getCorrectedData(vis, spw, field, pol, averageChannel=averageChannel, 
                              column=datacolumn, intent=intent, use_tbcalc=use_tbcalc,
                              takeNumpyAbsolute=takeNumpyAbsolute, returnWeight=True, 
                              channel=channel, verbose=verbose, useflags=useflags, mymsmd=mymsmd, scan=scan, quiet=quiet)
    if needToClose:
        mymsmd.close()
    if result is None:
        if verbose:
            print("None returned by getCorrectedData")
        return
    if len(result) == 4:  # single pol
        uvdist, visibilities, Nantennas, weight = result
        N = len(visibilities)
        if N == 0:
            return None
        Nbaselines = Nantennas*(Nantennas-1)//2
        Nintegrations = N//Nbaselines
        M = Nintegrations * Nantennas
        L = np.mean([N,M])
        if weightedMean:
            meanFlux = np.abs(np.average(visibilities, weights=weight))
            if not quiet:
                print("singlepol) meanFlux = ", meanFlux)
            meanStd = np.sqrt(np.average((np.abs(visibilities)-meanFlux)**2, weights=weight)) / np.sqrt(L)
            meanStd1 = np.sqrt(np.average((np.abs(visibilities)-meanFlux)**2, weights=weight)) / np.sqrt(N)
            meanStd2 = np.sqrt(np.average((np.abs(visibilities)-meanFlux)**2, weights=weight)) / np.sqrt(M)
            meanStd3 = np.sqrt(np.average((np.abs(visibilities)-meanFlux)**2, weights=weight)) / np.sqrt(L)
        else:
            if stat == 'median':
                meanFlux = np.abs(np.median(visibilities))
                meanStd = MAD(np.abs(visibilities))
            else:
                meanFlux = np.abs(np.mean(visibilities))
                meanStd = np.sqrt(np.mean((visibilities-meanFlux)**2)) / np.sqrt(L)
    elif len(result) == 7:  # dual pol
        uvdist, visibilities, Nantennas, weight, uvdist1, visibilities1, weight1 = result
        N = len(visibilities)
        if N == 0:
            return None
        Nbaselines = Nantennas*(Nantennas-1)//2
        Nintegrations = N//Nbaselines
        M = Nintegrations * Nantennas
        L = np.mean([N,M])
        if weightedMean:
            meanFlux = np.abs(np.average(visibilities, weights=weight))
            meanFlux1 = np.abs(np.average(visibilities1, weights=weight1))
            oldStd0 = np.sqrt(np.average((visibilities-meanFlux)**2, weights=weight))
            oldStd1 = np.sqrt(np.average((visibilities1-meanFlux)**2, weights=weight1))
            snr0 = meanFlux/oldStd0
            snr1 = meanFlux1/oldStd1
            if showOldCalculation:
                print("Code used to create the big PDF in CASR-534 did not properly treat complex numbers:")
                print("meanFlux = np.abs(np.average(visibilities, weights=weight))")
                print("oldStd0 = np.sqrt(np.average((visibilities-meanFlux)**2, weights=weight))")
                print("oldStd0 =  ", oldStd0)
                print("oldStd1 =  ", oldStd1)
                print("oldsnr0 = ", snr0)
                print("oldsnr1 = ", snr0)
                print("oldStd0 = %g, meanFlux0=%s, SNR=%s" % (oldStd0,str(meanFlux),str(snr0)))
                print("oldStd1 = %g, meanFlux1=%s, SNR=%s" % (oldStd1,str(meanFlux1),str(snr1)))
                print("But because the errorbar plotting used the real part of the complex number, the apparent SNR was huge:")
                print("old SNR = ", meanFlux/np.real(oldStd0))
                print("old SNR = ", meanFlux/np.real(oldStd1))
                print("\n")
            std0 = np.sqrt(np.average((np.abs(visibilities)-meanFlux)**2,weights=weight))
            std1 = np.sqrt(np.average((np.abs(visibilities1)-meanFlux1)**2,weights=weight1))
            snr = meanFlux/std0
            snr1 = meanFlux/std1
            if not quiet:
                print("Code in Pipeline2020:")
                print("meanFlux = np.abs(np.average(visibilities, weights=weight)) = %f" % (meanFlux))
                print("std = np.sqrt(np.average((np.abs(visibilities)-meanFlux)**2,weights=weight))")
                print("pol0 meanFlux = %.6f +- %.6f (SNR=%f)" % (meanFlux,std0,snr))
                print("pol1 meanFlux = %.6f +- %.6f (SNR=%f)" % (meanFlux1,std1,snr1))
            if False:  # alternative calculation (not used anywhere)
                if not quiet:
                    print("meanVisibility = np.average(visibilities, weights=weight)")
                    print("std = np.sqrt(np.average(np.abs(visibilities-meanVisibility)**2,weights=weight))")
                meanVisibility = np.average(visibilities, weights=weight)
                meanVisibility1 = np.average(visibilities1, weights=weight1)
                std0 = np.sqrt(np.average(np.abs(visibilities - meanVisibility)**2, weights=weight))
                std1 = np.sqrt(np.average(np.abs(visibilities1 - meanVisibility)**2, weights=weight1))
                snr0 = meanFlux/std0
                snr1 = meanFlux1/std1
                if not quiet:
                    print("new pol0 meanFlux = %s +- %s (SNR=%s)" % (meanFlux,std0,snr0))
                    print("new pol1 meanFlux = %s +- %s (SNR=%s)" % (meanFlux1,std1,snr1))

            meanStd = np.sqrt(np.mean([np.average((np.abs(visibilities)-meanFlux)**2,weights=weight), 
                                       np.average((np.abs(visibilities1)-meanFlux1)**2,weights=weight1)]))
            snr = np.mean([meanFlux,meanFlux1]) / meanStd
            if not quiet:
                print("new mean across pols: %s +- %s (SNR=%s)" % (np.mean([meanFlux,meanFlux1]), meanStd, snr))
                print("\nNow we must scale by some appropriate factor to estimate the standard deviation of the mean.")
                print("Here are 3 options:")
                print("1) Assume uncorrelated errors: scale by 1/sqrt(N) where N = Nvisibilities = Nbaselines*Nintegrations = %d would yield:" % N)
            meanStd1 = meanStd / np.sqrt(N)
            snr = np.mean([meanFlux,meanFlux1]) / (meanStd / np.sqrt(N))
            if not quiet:
                print("    %s +- %s (SNR=%s)" % (np.mean([meanFlux,meanFlux1]), meanStd1, snr))
            meanStd2 = meanStd / np.sqrt(M)
            snr = np.mean([meanFlux,meanFlux1]) / meanStd2
            if not quiet:
                print("2) Assume antenna-based errors: scale by 1/sqrt(M) where M = Nantennas*Nintegrations = %d would yield:" % M)
                print("    %s +- %s (SNR=%s)" % (np.mean([meanFlux,meanFlux1]), meanStd2, snr))
            meanStd3 = meanStd / np.sqrt(L)
            snr = np.mean([meanFlux,meanFlux1]) / meanStd3
            if not quiet:
                print("3) The mean of the two approaches: scale by 1/sqrt(L) where L = mean([N,M]) = %d would yield:" % L)
                print("    %s +- %s (SNR=%s)" % (np.mean([meanFlux,meanFlux1]), meanStd3, snr))
                if not returnAllErrorEstimates:
                    print("Returning option (3) to match Pipeline2020.")
        else:  # use the unweighted mean
            if stat == 'median':
                meanFlux = np.abs(np.median(visibilities))
                meanFlux1 = np.abs(np.median(visibilities1))
            else:
                meanFlux = np.abs(np.mean(visibilities))
                meanFlux1 = np.abs(np.mean(visibilities1))
            meanStd = np.sqrt(np.mean([np.nanstd(visibilities), np.nanstd(visibilities1)]))
            meanMAD = np.sqrt(np.mean([MAD(visibilities), MAD(visibilities1)])) / np.sqrt(L)
        meanFlux = np.mean([meanFlux, meanFlux1])
    else:
        print("Unexpected number of parameters returned (not 3 or 6)")
    if returnAllErrorEstimates and weightedMean:
        return meanFlux, meanStd1, meanStd2, meanStd3
    else:
        return meanFlux, meanStd
    
def visstatDifferences(workingdir1, workingdir2, stats=['sum','max'], vis='', useflags=True, 
                       axis='amp', field='', useTargetMS=False, scan='', perscan=False,
                       datacolumns=['corrected'], intent='OBSERVE_TARGET*'):
    """
    workingdir1: either a pipeline run parent directory or a working directory
    vis: for multi-EB projects, use this partial string to select one particular ms
    field: by default, it uses the first science field name, unless perscan=True
    intent: passed to getScienceTargets if perscan==False and field==''; and 
       to getScienceScans (if perscan==True)
       Wildcards work, e.g. '*PHASE*', as do simple names 'PHASE', and it's case insensitive
    stats: a list of which statistics you want to compare
    datacolumns: either a python list of strings, or a single comma-delimited string
        'data', 'corrected' or 'model', i.e. what the visstat task expects, 
        *not* the actual column names of 'DATA', 'CORRECTED_DATA' or 'MODEL_DATA'
    Returns: dictionary, keyed by spw ID and stat, with values of fractional differenct (vis1-vis2)/vis2
    """
    if workingdir1.find('working') < 0:
        workingdir1 = findPipelineWorkingDirectory(workingdir1)
    project, mous = getProjectMOUSFromDir(workingdir1)
    vislist = sorted(glob.glob(os.path.join(workingdir1,'*.ms')))
    vis1list = []
    for myvis in vislist:
        if useTargetMS:
            if myvis.find('_target') > 0: 
                if vis == '' or myvis.find(vis) >= 0:
                    vis1list.append(myvis)
        else:
            if myvis.find('_target') < 0: 
                if vis == '' or myvis.find(vis) >= 0:
                    vis1list.append(myvis)
    if workingdir2.find('working') < 0:
        workingdir2 = findPipelineWorkingDirectory(workingdir2)
    vislist = sorted(glob.glob(os.path.join(workingdir2,'*.ms')))
    vis2list = []
    for myvis in vislist:
        if useTargetMS:
            if myvis.find('_target') > 0: 
                if vis == '' or myvis.find(vis) >= 0:
                    vis2list.append(myvis)
        else:
            if myvis.find('_target') < 0: 
                if vis == '' or myvis.find(vis) >= 0:
                    vis2list.append(myvis)
    if len(vis1list) < 0:
        print("no vis found in workingdir1")
        return
    if len(vis2list) < 0:
        print("no vis found in workingdir2")
        return
    if len(vis1list) > 1:
        print("More than one ms matches in workingdir1.  Use the vis parameter to limit to one of them (minimum match string)")
        for i in vis1list:
            print(os.path.basename(i))
        return
    if len(vis2list) > 1:
        print("More than one ms matches in workingdir2.  Use the vis parameter to limit to one of them (minimum match string)")
        for i in vis2list:
            print(os.path.basename(i))
        return
    vis1 = vis1list[0]
    vis2 = vis2list[0]
    if os.path.basename(vis1) != os.path.basename(vis2):
        print("You are comparing different ms, this makes no sense.")
        return
    if vis == '':
        print("Using vis1 = %s (first of %d)" % (os.path.basename(vis1), len(vis1list)))
        print("Using vis2 = %s (first of %d)" % (os.path.basename(vis2), len(vis2list)))
    else:
        print("Using vis1 = %s" % (os.path.basename(vis1)))
        print("Using vis2 = %s" % (os.path.basename(vis2)))
    if type(datacolumns) == str:
        datacolumns = datacolumns.split(',')
    # Check if desired column name exists
    mytb = createCasaTool(tbtool)
    mytb.open(vis1)
    colnames1 = mytb.colnames()
    mytb.close()
    mytb.open(vis2)
    colnames2 = mytb.colnames()
    mytb.close()
    for datacolumn in datacolumns:
        mydatacolumn = datacolumn.upper()
        if len(mydatacolumn) > 4:
            mydatacolumn += '_DATA'
        if mydatacolumn not in colnames1:
            print("vis1 has no %s column" % (mydatacolumn))
            return
        if mydatacolumn not in colnames2:
            print("vis2 has no %s column" % (mydatacolumn))
            return
    spws = getScienceSpws(vis1)
    print("Using spws = ", spws)
    if intent.find('*') < 0:
        intent = '*' + intent + '*'
    if field == '' and not perscan:
        fields = getScienceTargets(vis1, intent)
        if len(fields) < 1:
            print("No science targets found")
            return
        field = fields[0]
        print("Using field = %s" % (field))
    if perscan:
        intent = intent.upper()
        print("Running au.getScienceScans('%s',field='%s',intent='%s')" % (vis1,field,intent))
        scanlist = getScienceScans(vis1, field, intent)
        if scanlist is None: return
        if len(scanlist) < 1:
            return
        print("Doing each scan individually: ", scanlist)
    else:
        scanlist = ['']
    mydict = {}
    mymsmd = createCasaTool(msmdtool)
    mymsmd.open(vis1)
    fracDiffs = {}
    for myscan in scanlist:
        if perscan:
            fracDiffs[myscan] = []
        if myscan != '':
            mydict[myscan] = {}
        mydictscan = {}
        skip = False
        for datacolumn in datacolumns:
            mydictscan[datacolumn] = {}
            if perscan: 
                scan = str(myscan)
            print("vis1: Running visstat('%s', useflags=%s, spw='%s', datacolumn='%s', field='%s', scan='%s')" % (vis1,useflags,spws,datacolumn, field, scan))
            try:
                mydict1 = visstat(vis1, useflags=useflags, axis=axis, spw=spws, datacolumn=datacolumn, field=field, scan=scan)
            except:
                print("No vis1 data found for scan %s" % (scan))
                skip = True
            print("vis2: Running visstat('%s', useflags=%s, spw='%s', datacolumn='%s', field='%s', scan='%s')" % (vis2,useflags,spws,datacolumn, field, scan))
            try:
                mydict2 = visstat(vis2, useflags=useflags, axis=axis, spw=spws, datacolumn=datacolumn, field=field, scan=scan)
            except:
                print("No vis2 data found for scan %s" % (scan))
                skip = True
            if skip: break
            dds = sorted(mydict1.keys())
            for dd in dds:
                spw = mymsmd.spwfordatadesc(int(dd.split('=')[1]))
                mydictscan[datacolumn][spw] = {}
                for stat in stats:
                    if mydict2[dd][stat] != 0.0:
                        mydiff = (mydict1[dd][stat]-mydict2[dd][stat]) / mydict2[dd][stat]
                    elif mydict1[dd][stat] != 0.0:
                        mydiff = (mydict1[dd][stat]-mydict2[dd][stat]) / mydict1[dd][stat]
                    else:
                        mydiff = 0.0
    #                print("%9s: spw=%d %s fractional difference = %e" % (datacolumn, spw, stat, mydiff))
                    print("%2s %9s: spw=%2d %s: val1 = %.2e, val2 = %.2e, frac.diff. = %+.2e" % (myscan, datacolumn, spw, stat, mydict1[dd][stat], mydict2[dd][stat], mydiff))
                    mydictscan[datacolumn][spw][stat] = mydiff
                    if perscan:
                        fracDiffs[myscan].append(mydiff)
        if myscan != '':
            mydict[myscan] = mydictscan
        else:
            mydict = mydictscan
    mymsmd.close()
    if perscan:
        print("Summary for %s for %s, MOUS: %s, useflags=%s" % (intent, project, mous, useflags))
        mymax = 0
        for scan in sorted(list(fracDiffs.keys())):
            if len(fracDiffs[scan]) > 0:
                myvalue = fracDiffs[scan][np.argmax(np.abs(fracDiffs[scan]))]
                print("scan %2d: %+.2e" % (scan, myvalue))
                if np.abs(myvalue) > np.abs(mymax):
                      mymax = myvalue
        print("   Max: %+.2e" % (mymax))
    return mydict

def visstatParse(vis, scan, antenna, spw, reportingaxes='integration', returnDatestring=True, useflags=True, intent=''):
    """
    Computes mean time of data
    returnDatestring: if False, then return in MJD seconds
    Returns: date in string format or mjdsec
    -Todd Hunter
    """
    mydict = visstat(vis, scan=scan, antenna=antenna, spw=spw, reportingaxes=reportingaxes, useflags=useflags, intent=intent)
    mjdsec = []
    masked = 0
    weighted = 0
    total = 0
    for key in list(mydict.keys()):
        mjdsec.append(float(key.split('=')[1]))
        if mydict[key]['isMasked']:
            masked += 1
        if mydict[key]['isWeighted']:
            weighted += 1
        total += 1
    print("%d/%d masked = %f%%" % (masked,total,100.*masked/total))
    print("%d/%d weighted = %f%%" % (weighted,total,100.*weighted/total))
    mjdsec = np.mean(mjdsec)
    if returnDatestring:
        return mjdsecToDatestring(mjdsec)
    return mjdsec

def scaleModel(vis, field, antenna='', toCorrected=True, factor=None, spw='', datacolumn='model', 
               stat='median', verbose=False):
    """
    Scales a column of a dataset for a specified field, optionally to match the median of the 
    corrected column, using the task visstat.
    WARNING: does not (yet) perform the scaling! (because au.scaleweights does not take field parameter)
    Instead, try: au.scaleWeightSpectrum(column='model')
    datacolumn: column to scale
    stat: which visstat statistic to use
    field: list of names or IDs
    -Todd Hunter
    """
    if not os.path.exists(vis):
        print("Could not find measurement set: ", vis)
        return
    mymsmd = createCasaTool(msmdtool)
    mymsmd.open(vis)
    if spw == '':
        spwlist = getScienceSpws(vis, mymsmd=mymsmd, returnString=False)
    else:
        spwlist = parseSpw(vis, spw, mymsmd)
    scaleFactor = {}
    ids, names = parseFieldArgument(vis, field, mymsmd=mymsmd)
    mymsmd.close()
    field = ','.join([str(i) for i in ids])
    print("Processing field: '%s'" % (field))
    for spw in spwlist:
        scaleFactor[spw] = factor
    if toCorrected:
        for spw in spwlist:
            if verbose:
                print("running visstat('%s', datacolumn='corrected', field='%s', antenna='%s', spw='%s')" % (vis, field, antenna, str(spw)))
            value = visstat(vis, datacolumn='corrected', field=field, antenna=antenna, spw=str(spw))['CORRECTED'][stat]
            if verbose:
                print("running visstat('%s', datacolumn='model', field='%s', antenna='%s', spw='%s')" % (vis, field, antenna, str(spw)))
            model = visstat(vis, datacolumn='model', field=field, antenna=antenna, spw=str(spw))['MODEL'][stat]
            print("spw %d %s corrected=%f  %s=%f" % (spw, stat, value, datacolumn, model))
            scaleFactor[spw] = model/value
    return
    for spw in spwlist:
        # Need to restrict to field before we remove the 'return' above here!
        print("Applying scaleFactor = %f for spw %d" % (scaleFactor[spw], spw))
        scaleweights(vis, scaleFactor[spw], antenna=antenna, spw=spw, column='model')

def scaleWeightsPerAntenna(vis, weightDict, spw='', column='weight', verbose=True):
    """
    Calls scaleweights for each antenna in a dataset using the supplied dictionary
    of scaling factors.
    weightDict: e.g. {'ea01': 1.23, ...}
    """
    names = getAntennaNames(vis)
    antennas = range(len(names))
    myms = createCasaTool(mstool)    
    myms.open(vis,nomodify=False)
    mymsmd = createCasaTool(msmdtool)    
    mymsmd.open(vis)
    for antenna in antennas:
        if names[antenna] in weightDict:
            print("Scaling antenna %d: %s by %f" % (antenna, names[antenna], weightDict[names[antenna]]))
            scaleweights(vis, weightDict[names[antenna]], antenna, spw=spw, column=column, verbose=verbose, 
                         myms=myms, mymsmd=mymsmd)
        else:
            print("Antenna %d: %s not in scaling dictionary" % (antenna, names[antenna]))
    myms.close()
    mymsmd.close()

def scaleweights(vis, wtfac=1.0, antenna='', square=False, squareroot=False,
                 spw='', column='weight', verbose=True, myms=None, mymsmd=None):
    """
    scaleweights:  scale data weights by a user supplied factor (or square or 
                   square root them).  See also scaleWeightSpectrum.
    Originally created by S.T. Myers 2011-08-23  v1.0 from flagaverage.py 
                     (CAS-2422)
    Improved and maintained by Todd Hunter 2014
    Note: this function assumes equivalence between spw and data_descriptor_id.
         If this is not the case for your data, email the maintainer.         
    Inputs:
    * vis: measurement set
    * wtfac =  multiplicative weight factor
    * antenna = restrict scaling to baselines including this single 
                        antenna ID (int or string)
    * square = Boolean, if True, then square the weights 
    * squareroot = Boolean, if True, then take the square root of the weights 
    * spw = integer or string or list of spws to process
    For examples, see https://safe.nrao.edu/wiki/bin/view/ALMA/Scaleweights
    """
    if (os.path.exists(vis) == False):
        print("Could not find ms file = ", vis)
        return(2)
    if type(wtfac) is not types.FloatType and type(wtfac) is not types.IntType:
        print('ERROR: wtfac must be a float or integer')
        return(1)
    if (square == False and squareroot == False):
        print('Will scale weights by a factor of '+str(wtfac))
    elif (square and squareroot):
        print("You cannot select both square and squareroot")
        return
    elif (square):
        print("Will square the existing weights")
    elif (squareroot):
        print("Will square root the existing weights")
    needToClose = False
    if mymsmd is None:
        mymsmd = createCasaTool(msmdtool)    
        try:
            mymsmd.open(vis)
            needToClose = True
        except:
            print("ERROR: failed to open ms tool on file "+vis)
            mymsmd.close()
        return(4)
    spw = parseSpw(vis,spw,mymsmd)
    if needToClose:
        myms.close()
    needToClose = False
    if myms is None:
        myms = createCasaTool(mstool)    
        try:
            myms.open(vis,nomodify=False)
            needToClose = True
        except:
            print("ERROR: failed to open ms tool on file "+vis)
            myms.close()
        return(3)
    # Find number of data description IDs
    mytb = createCasaTool(tbtool)
    mytb.open(vis+"/DATA_DESCRIPTION")
    ddspwlist = mytb.getcol("SPECTRAL_WINDOW_ID")
    ddpollist = mytb.getcol("POLARIZATION_ID")
    mytb.close()
    ndd = ddspwlist.__len__()
    if verbose:
        print('Found '+str(ndd)+' DataDescription IDs')
    # Now the polarizations (number of correlations in each pol id)
    mytb.open(vis+"/POLARIZATION")
    ncorlist = mytb.getcol("NUM_CORR")
    mytb.close()
    #
    ntotrow=0
    ntotpts=0
    if verbose:
        print("Will process spws = ", spw)
    for idd in range(ndd):
        if (idd in spw):
            # Find number of correlations in this DD
            pid = ddpollist[idd]
            ncorr = ncorlist[pid]
            # Select this DD (after reset if needed)
            if idd>0: myms.selectinit(reset=True)
            myms.selectinit(idd)
            #myms.selecttaql('SUM(WEIGHT)<'+str(wtcut))
            nwchan=0
            #recf = myms.getdata(["flag"])
            #(nx,nc,ni) = recf['flag'].shape
            # get the weights
            recw = myms.getdata([column])
            antenna1 = myms.getdata(['ANTENNA1'])['antenna1']
            antenna2 = myms.getdata(['ANTENNA2'])['antenna2']
            (nx,ni) = recw[column].shape
            for j in range(ni):
                doscale = False
                if (antenna == ''):
                    doscale = True
                elif (str(antenna) == str(antenna1[j]) or str(antenna) == str(antenna2[j])):
                    doscale = True
                if (doscale):
                    for i in range(nx):
                        if (square):
                            recw[column][i,j] = np.square(recw[column][i,j])
                        elif (squareroot):
                            recw[column][i,j] = np.sqrt(recw[column][i,j])
                        else:
                            recw[column][i,j] *= wtfac
                        nwchan += 1
            myms.putdata(recw)
            ntotrow += ni
            ntotpts += nwchan
            print('Scaled '+str(nwchan)+' spectral points in '+str(ni)+' rows in DD='+str(idd))
    #
    if verbose:
        print('Scaled Total '+str(ntotpts)+' spectral points in '+str(ntotrow)+' rows')
    if needToClose:
        myms.close()
    if verbose:
        print("new median weight: %f" % (getMeanWeights(vis, antenna=antenna, reportMedian=True)))
    return

def countVisibilities(vis):
    """
    Sums the number of visibilities in a measurement set, one spw at a time, and
    reports the total.
    -Todd Hunter
    """
    mytb = createCasaTool(tbtool)
    mytb.open(vis+"/DATA_DESCRIPTION")
    ddspwlist = mytb.getcol("SPECTRAL_WINDOW_ID")
    ddpollist = mytb.getcol("POLARIZATION_ID")
    mytb.close()
    ndd = ddspwlist.__len__()
    print('Found '+str(ndd)+' DataDescription IDs')
    # Now the polarizations (number of correlations in each pol id)
    mytb.open(vis+"/POLARIZATION")
    ncorlist = mytb.getcol("NUM_CORR")
    mytb.close()
    #
    ntotrow=0
    ntotpts=0
    nvis = 0
    mytb.open(vis)
    for idd in range(ndd):
        print("Working on %d/%d" % (idd+1,ndd))
        myt = mytb.query('DATA_DESC_ID == %d' % idd)
        mycell = myt.getcell('DATA',0)
        myshape = np.shape(mycell)
        nvis += myt.nrows() * np.product(myshape)
        myt.close()
    mytb.close()
    return nvis

def scaleEffectiveBandwidth(vis, spw, factor=2.667):
    """
    Scales the effective bandwidth of a spectral window in the SPECTRAL_WINDOW
    table of a measurement set.  For test purposes only!  See also 
    scaleEffectiveResolution.
    spw: integer or string integer
    -Todd Hunter
    """
    if (not os.path.exists(vis+'/SPECTRAL_WINDOW')):
        print("Could not find ms (or at least its SPECTRAL_WINDOW table).")
        return
    mytb = createCasaTool(tbtool)
    mytb.open(vis+'/SPECTRAL_WINDOW', nomodify=False)
    spw = int(spw)
    ebw = mytb.getcell('EFFECTIVE_BW', spw)
    mytb.putcell('EFFECTIVE_BW', spw, ebw*factor)
    print("Changed value from %f to %f" % (np.median(ebw), np.median(ebw)*factor))
    mytb.close()

def scaleEffectiveBandwidthASDM(asdm, spw, factor=2.667, 
                                keepOld=False, verbose=False):
    """
    Scales the effective bandwidth of a spectral window in the 
    SpectralWindow.xml file of an ASDM.  For test purposes only!
    spw: integer or string integer (as it would appear in measurement set)
    -Todd Hunter
    """
    if (not os.path.exists(asdm)):
        print("Could not find ASDM: ", asdm)
        return
    spwtable = asdm+'/SpectralWindow.xml'
    if (not os.path.exists(spwtable)):
        print("Could not find SpectralWindow.xml.")
        return
    mydict = getSpwsFromASDM(asdm)
    if spw not in list(mydict.keys()):
        print("spw %d is not in the ASDM" % (spw))
        return
    asdmspw = mydict[spw]['spectralWindowId']
    if verbose: print("Translated spw %d to asdm spw %d" % (spw, asdmspw))
    fin = open(spwtable,'r')
    lines = fin.readlines()
    fin.close()
    newspwtable = spwtable + '.new'
    fout = open(newspwtable,'w')
    lookingForEffectiveBW = False
    replaced = 0
    for line in lines:
        if lookingForEffectiveBW:
            loc = line.find('<effectiveBwArray>')
            loc2 = line.find('<effectiveBw>')
            if (loc >= 0):
                token = line[loc:].split('>')[1].split('<')[0].split()
                nchan = int(token[1])
                outline = line.split('<')[0] + '<effectiveBwArray>%s %s' % (token[0],token[1])
                for chan in range(nchan):
                    outline += ' %E' % (factor*float(token[chan+2]))
                outline += '</effectiveBwArray>\n'
                fout.write(outline)
                replaced += 1
                lookingForEffectiveBW = False
            elif (loc2 >= 0):
                token = line[loc2:].split('>')[1].split('<')[0]
                outline = line.split('<')[0] + '<effectiveBw>'
                outline += '%E</effectiveBw>\n' % (float(token)*factor)
                fout.write(outline)
                replaced += 1
                lookingForEffectiveBW = False
            else:
                fout.write(line)
        else:
            if (line.find('>SpectralWindow_%d<' % asdmspw) > 0):
                lookingForEffectiveBW = True
            fout.write(line)
    fout.close()
    if verbose: print("Replaced %d lines." % (replaced))
    if keepOld:
        os.rename(spwtable, spwtable+'.old')
    else:
        os.remove(spwtable)
    os.rename(newspwtable, spwtable)

