def getObservationStartDateFromASDMs(asdmlist, outfile='asdm_dates.txt',
                                     getAntennas=False, getSBFrequencies=False):
    """
    For a list of ASDMs, writes a file containing the start date/time of each.
    asdmlist: either a list of strings, or a string containing a wildcard pattern
    getAntennas: if True, then also list the antennas
    -- Todd Hunter
    """
    if (type(asdmlist)==str):
        asdmlist = sorted(glob.glob(asdmlist))
    f = open(outfile,'w')
    for asdm in asdmlist:
        if (asdm.find('.ms') > 0): continue
        if (asdm.find('.txt') > 0): continue
        utdate, mjdsec = getObservationStartDateFromASDM(asdm)
        if (getAntennas):
            antennas = ','.join(readAntennasFromASDM(asdm))
        else:
            antennas = ''
        mf = getMeanFreqFromASDM(asdm)
        if (getSBFrequencies):
            lsb = str(np.round(mf['lsb']['meanfreq']*1e-9, 1))
            usb = str(np.round(mf['usb']['meanfreq']*1e-9, 1))
        else:
            lsb = ''
            usb =''
        f.write("%s %s %s %s %s\n" % (asdm,utdate,antennas,lsb,usb))
        
    f.close()
    print("Result left in %s" % (outfile))

def getObservationMJDSecRange(vis):
    """
    Returns 2 floating point values in MJD seconds, using the tb tool.
    - Todd Hunter
    """
    return([getObservationStart(vis),getObservationStop(vis)])

def getObservationMJDSecRangeFromASDM(asdm, useMinidom=False):
    """
    Returns 2 floating point values in MJD seconds.
    useMinidom: if True, then parse the .xml file even if the ASDM python
                bindings are available
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    - Todd Hunter
    """
    start = getObservationStartDateFromASDM(asdm, useMinidom)[1]
    stop = getObservationEndDateFromASDM(asdm, useMinidom)[1]
    return([start,stop])

def getObservationLength(vis):
    """
    Returns length of measurement set in minutes, using tb tool.
    -Todd Hunter
    """
    start, stop = getObservationMJDSecRange(vis)
    return (stop-start)/60.
    
def getObservationLengthFromASDM(asdm, useMinidom=False):
    """
    Returns length of ASDM in minutes.
    useMinidom: if True, then parse the .xml file even if the ASDM python
                bindings are available
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    -Todd Hunter
    """
    start,stop = getObservationMJDSecRangeFromASDM(asdm, useMinidom)   # binary-ready
    return (stop-start)/60.

def getObservationDateRangeFromASDM(asdm, useMinidom=False):
    """
    Returns a string: '2015-10-22 00:16:44 UT to 2015-10-22 01:14:31 UT'
    useMinidom: if True, then parse the .xml file even if the ASDM python
                bindings are available
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    - Todd Hunter
    """
    start = getObservationStartDateFromASDM(asdm, useMinidom)[0]
    stop = getObservationEndDateFromASDM(asdm, useMinidom)[0]
    return(start + ' to ' + stop)

def getObservationSummaryFromASDM(asdm, useMinidom=False):
    """
    Gather information to send to Bill Shillue: antennas used, start and stop times
    useMinidom: if True, then parse the .xml file even if the ASDM python
                bindings are available
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    -Todd Hunter
    """
    if (type(asdm) != list):
        if (asdm.find('*') >= 0):
            asdm = glob.glob(asdm)
        else:
            asdm = [asdm]
    mystring = []
    for a in asdm:
        try:
            antennas = readAntennasFromASDM(a, False, False, useMinidom=useMinidom)  # binary-ready
        except:
            continue
        daterange = getObservationDateRangeFromASDM(a) # binary-ready
        mystring.append(daterange + ', ' + str(antennas))
    if (len(asdm) == 1):
        mystring = mystring[0]
    return(mystring)
        
def getObservationStartDateFromASDM(asdm, useMinidom=False):
    """
    Returns the start date/time and MJD seconds in the specified ASDM.
    example:  ('2016-05-12 07:14:19 UT', 4969754058.985001)
    useMinidom: if True, then parse the .xml file even if the ASDM python
                bindings are available
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    -- Todd Hunter
    """
#    uid___A002_X54d35d_X761/ExecBlock.xml:    <startTime>ALMA</startTime>
    execblock = asdm + '/ExecBlock.xml'
    if (os.path.exists(execblock) == False):
        print("Could not open %s" % (execblock))
        return
    if not asdmLibraryAvailable or useMinidom:
        import au_noASDMLibrary
        mjdsec = au_noASDMLibrary.getObservationStartDateFromASDM_minidom(asdm)
        utdate = mjdsecToUT(mjdsec)
    else:
        a = ASDM()
        parser = ASDMParseOptions()
        parser.asALMA()
        parser.loadTablesOnDemand(True)
        a.setFromFile(asdm,parser)
        execBlockTable = a.execBlockTable().get()
        for row in execBlockTable:
            mjdsec = row.startTime().get() * 1e-9
            utdate = mjdsecToUT(mjdsec)
    return(utdate, mjdsec)

