def getObservatoryName(ms):
    """
    Returns the observatory name in the specified ms, using the tb tool.
    -- Todd Hunter
    """
    antTable = ms+'/OBSERVATION'
    try:
        mytb = createCasaTool(tbtool)
        mytb.open(antTable)
        myName = mytb.getcell('TELESCOPE_NAME')
        mytb.close()
    except:
        print("Could not open OBSERVATION table to get the telescope name: %s" % (antTable))
        myName = ''
    return(myName)

def computeAzElFromRADecHourAngle(raDec, hourangle, observatory='ALMA', date=None, degrees=False,
                                  verbose=False):
    """
    radec: string of the form "hh:mm:ss.sss -dd:mm:ss.ss", or [ra,dec] in radians; 
        or just the declination: "-dd:mm:ss.ss" or floating point value in radians 
    hourangle: in floating-point hours
    -Todd Hunter
    """
    if type(raDec) in [int, float, np.float64, np.float32]:
        raDec = [0,raDec]
    if (type(raDec) == str):
        # Then assume it is of the format "hh:mm:ss.sss -dd:mm:ss.ss"
        tokens = raDec.split()
        if (len(tokens) < 2):
            tokens = raDec.split(',')
            if (len(tokens) < 2):
                if len(tokens) < 0:
                    print("If you give a string, it must be of the format: hh:mm:ss.sss -dd:mm:ss.ss" or "-dd:mm:ss.ss")
                    return
                raDec = '0:0:0 ' + tokens[0]
        raDec = radec2rad(raDec)
        if (verbose):
            print("RA Dec in radians = ", raDec)
    lst = np.pi*hourangle/12. + raDec[0]
    return computeAzElFromRADecLST(raDec, lst, observatory, date, degrees, verbose)

def computeAzElFromRADecLST(raDec, lst=None, observatory='ALMA', date=None, 
                            degrees=False, verbose=False):
    """
    Computes the az/el for a specified source position, LST and observatory.
    raDec must either be a tuple in radians: [ra,dec],
           or a string of the form "hh:mm:ss.sss -dd:mm:ss.ss"
    date: YYYYMMDD or YYYY/MM/DD where '/' is any delimiting character or space
    lst: in Radians, or a string in "hh:mm:ss";  if lst is not specified, then 
         the date is interpreted as a full date+time string (see au.ComputeLST)
    degrees: if False, returns Az,El in radians;  otherwise return them in degrees
    Returns: [Az,El] in radians
    """
    if ((lst==None or lst=='') and (date==None or date=='')):
        lst = ComputeLST(observatory=observatory,hms=True)
        date = getCurrentDate(delimiter='-')
        print("Using current LST and date = %s,%s" % (lst,date))
    elif (lst==None or lst==''): # only date is specified
        lst = ComputeLST(date=date,hms=True,observatory=observatory)
        if verbose:
            print("Computed LST = ", lst)
    elif (date==None or date==''): # only LST is specified
        date = getCurrentDate(observatory=observatory)
    elif (len(date) > 10):
        print("WARNING: Ignoring the time portion of the date (since lst has been specified)")
    mjd = lst2mjd(lst, date, longitudeDegrees=getObservatoryLatLong(observatory)[1], verbose=verbose)
    az,el = computeAzElFromRADecMJD(raDec, mjd, observatory)
    if (degrees):
        az *= 180/np.pi
        el *= 180/np.pi
    return([az,el])

def computeAzElForScan(vis, scan, forcePositiveAzim=True, mymsmd=None):
    """
    Returns the theoretical azimuth and elevation for the first integration of
    the specified scan.  Uses direction and observatory location, not the 
    pointing table.
    -Todd Hunter
    """
    if not os.path.exists(vis):
        print("Could not find ms")
        return
    if mymsmd is None:
        mymsmd = createCasaTool(msmdtool)
        mymsmd.open(vis)
        needToClose = True
    else:
        needToClose = False
    observatory = mymsmd.observatorynames()[0]
    field = mymsmd.fieldsforscan(scan)[0]
    raDecString = direction2radec(mymsmd.phasecenter(field))
    tfs = mymsmd.timesforscan(scan)/86400.
    if needToClose:
        mymsmd.close()
    mjd =  np.min(tfs)
    az0,el0 = computeAzElFromRADecMJD(raDecString, mjd, observatory, 
                                      degrees=True, frame='AZELGEO',
                                      forcePositiveAzim=forcePositiveAzim)
    return az0, el0

def computeAzElForMS(vis, value='mean', forcePositiveAzim=True, verbose=False,
                     ignorePointingSBAtmScans=True):
    """
    Computes the min/max/mean or median azim and elev for a measurement set using
    the RA/Dec and MJD of each scan. Works for ALMA and VLA data.
    vis: measurement set
    value: 'min', 'max', 'mean' or 'median'
    verbose: if True, then print the per scan values
    Returns: 2 values (azim and elev)
    -Todd Hunter
    """
    mymsmd = createCasaTool(msmdtool)
    mymsmd.open(vis)
    scans = callscannumbers(mymsmd)
    if (ignorePointingSBAtmScans):
        pointingScans = list(mymsmd.scansforintent('CALIBRATE_POINTING*'))
        sbScans = list(mymsmd.scansforintent('CALIBRATE_SIDEBAND*'))
        atmScans = list(mymsmd.scansforintent('CALIBRATE_ATMOSPHERE*'))
        calscans = sorted(pointingScans + sbScans + atmScans)
        if (len(calscans) > 0):
            print("Dropping pointing+sideband+atmosphere scans: ", calscans)
            scans = [x for x in scans if x not in calscans]
            if verbose:
                print("Kept scans: ", scans)
    observatory = mymsmd.observatorynames()[0]
    func = np.mean
    if value == 'median':
        func = np.median
    elif value == 'min':
        func = np.min
    elif value == 'max':
        func = np.max
    az = []
    el = []
    for scan in scans:
        field = mymsmd.fieldsforscan(scan)[0]
        raDecString = direction2radec(mymsmd.phasecenter(field))
        tfs = mymsmd.timesforscan(scan)/86400.
        mjd =  np.min(tfs)
        az0,el0 = computeAzElFromRADecMJD(raDecString, mjd, observatory, 
                                          degrees=True, frame='AZELGEO',
                                          forcePositiveAzim=forcePositiveAzim)
        mjd =  np.max(tfs)
        az1,el1 = computeAzElFromRADecMJD(raDecString, mjd, observatory, 
                                          degrees=True, frame='AZELGEO',
                                          forcePositiveAzim=forcePositiveAzim)
        az.append(func([az0,az1]))
        el.append(func([el0,el1]))
        if verbose:
            print("scan %d = %s, az=%f, el=%f" % (scan, raDecString, az[-1], el[-1]))
    mymsmd.close()
    return func(az), func(el)

def radecToEcliptic(radec, degrees=False):
    """
    Uses the CASA measures tool to convert from equatorial to ecliptic coords.
    radec: string of the form "hh:mm:ss.sss -dd:mm:ss.ss", or [ra,dec] in rad
    Returns: longitude and latitude in radians, unless degrees=True
    -Todd Hunter
    """
    if (type(radec) == str):
        # Then assume it is of the format "hh:mm:ss.sss -dd:mm:ss.ss"
        tokens = radec.split()
        if (len(tokens) < 2):
            tokens = radec.split(',')
            if (len(tokens) < 2):
                print("If you give a string, it must be of the format: hh:mm:ss.sss -dd:mm:ss.ss")
                return
        radec = radec2rad(radec)
    myme = createCasaTool(metool)
    myqa = createCasaTool(qatool)
    mydir = myme.direction('J2000',myqa.quantity(radec[0],'rad'), 
                           myqa.quantity(radec[1],'rad'))
    mjd = getMJD() # this really does not matter
    observatory = 'ALMA' # this really does not matter 
    myme.doframe(myme.epoch('mjd',myqa.quantity(mjd,'d')))
    myqa.done()
    myme.doframe(myme.observatory(observatory))
    mydir = myme.measure(mydir,'ECLIPTIC')
    longrad = mydir['m0']['value']
    if (longrad < 0): longrad += 2*np.pi
    latrad = mydir['m1']['value']
    if degrees:
        return np.degrees(longrad), np.degrees(latrad)
    else:
        return longrad, latrad

def radec2ra(radec):
    """
    Takes a sexagesimal RA string or RA,Dec (space or comma-delimited)
    and returns just the RA part.
    -Todd Hunter
    """
    return radec.split()[0].split(',')[0]

def mjdToUnixtime(mjd):
    """
    Converts MJD to unixtime, using ComputeJulianDayFromUnixTime for a specific time and
    offseting to the requested value.
    -Todd Hunter
    """
    jd = ComputeJulianDayFromUnixTime(1e9)
    unixtime = 1e9 + (mjd-jdToMJD(jd))*86400
    return unixtime

def transitTimeUnix(ra=None, vis=None, field=None, date='', observatory='ALMA'):
    """
    Computes transit time in unixtime for specifed date (or today if not specified)
    ra: sexagesimal string of RA or RA, Dec (where Dec is ignored); or RA in radians
    date: string of format YYYY-MM-DD, default = today
    vis: measurement set
    field: ID or name, use its sky position
    """
    mjd = transitTime(ra, vis, field, date, observatory, returnMJD=True)
    unixtime = mjdToUnixtime(mjd)
    return unixtime

def transitTime(ra=None, vis=None, field=None, date='', observatory='ALMA', 
                returnMJD=False, verbose=True):
    """
    Computes the UT time of transit of a target on a specific date.
    ra: sexagesimal string of RA or RA, Dec; or RA in radians
    vis: measurement set
    field: ID or name, use its sky position
    date: string of format YYYY-MM-DD, default = today
    -Todd Hunter
    """
    if ra is not None:
        if type(ra) is str:
            ra = radec2ra(ra)
        else:
            # convert radians to hms string
            ra = rad2radec(ra,0).split(',')[0]
    elif vis is not None:
        if field is None:
            fields = getScienceTargets(vis)
            if len(fields) == 0:
                print("You must specify a field ID or name.")
                return
            else:
                field = fields[0]
                print("Using first science target: ", field)
        ra = radec2ra(getRADecForField(vis,field,hms=True))
    else:
        print("You must specify either ra or vis+field")
        return
    if date == '':
        date = getCurrentDate()
    hours = hmsToHours(ra)
    longitude = getObservatoryLongitude(observatory)
    print("transitTime(): longitude = ", longitude)
    ut = lstToUT(hours, date, longitude, observatory)[0]
    if verbose:
        print("  Transit time: ", ut)
    mjd = dateStringToMJD(ut, verbose=False)
    if verbose:
        if observatory in ['ALMA',JPL_HORIZONS_ID['ALMA']] :
            print("    Chile time: ", mjdToChileTime(mjd))
        elif observatory in ['VLA',JPL_HORIZONS_ID['VLA']]:
            print(" Mountain time: ", mjdToMountainTime(mjd))
        elif observatory in ['GBT',JPL_HORIZONS_ID['GBT']]:
            print("  Eastern time: ", mjdToEasternTime(mjd))
    if returnMJD:
        return mjd
    else:
        return ut

def computeAzElFromRADecDate(raDec, date, observatory='ALMA', verbose=False, 
                             degrees=True):
    """
    Computes the az/el for a specified J2000 RA/Dec, date and observatory using
    the CASA measures tool.
    Input date format: 2011/10/15 05:00:00  or   2011/10/15-05:00:00
                    or 2011-10-15 05:00:00  or   2011-10-15-05:00:00
                    or 2011-10-15T05:00:00  or   2011-Oct-15 etc.
                    or 2011-10-15_05:00:00
    observatory: ALMA, VLA, SMA, etc.
    """
    mjd = dateStringToMJD(date)
    return computeAzElFromRADecMJD(raDec, mjd, observatory, verbose, degrees)

def callComputeAzElFromRADecMJD(raDec, mjd, observatory='ALMA', verbose=False, 
                            degrees=False, frame='AZEL', 
                            forcePositiveAzim=False, myme=None):
    """
    Calls computeAzElFromRADecMJD, but suppresses the "Position" message in the casa
    log, which is otherwise somehow generated *after* the function completes.
    """
    casalog.filterMsg('Position:')  # method 1
#    casalog.filter('SEVERE') # method 2
#    logfile = casalog.logfile() ; casalog.setlogfile(filename='junk.log')  # method 3
    result = computeAzElFromRADecMJD(raDec, mjd, observatory, verbose, 
                                     degrees, frame, 
                                     forcePositiveAzim, myme)
#    casalog.setlogfile(filename=logfile) ; os.remove('junk.log') # method 3
#    casalog.filter('INFO') # method 2
    casalog.clearFilterMsgList() # method 1
    return result

def computeAzElFromRADecMJD(raDec, mjd, observatory='ALMA', verbose=False, 
                            degrees=False, frame='AZEL', 
                            forcePositiveAzim=False, myme=None):
    """
    Computes the az/el for a specified J2000 RA/Dec, MJD and observatory using
    the CASA measures tool.

    raDec must either be a tuple in radians: [ra,dec],
        or a string of the form "hh:mm:ss.sss -dd:mm:ss.ss"
    mjd must either be in days, or a date string of the form:
               2011/10/15 05:00:00  or   2011/10/15-05:00:00
            or 2011-10-15 05:00:00  or   2011-10-15-05:00:00
    observatory: must be either a name recognized by the CASA me tool, or a JPL Horizons
          ID listed in the JPL_HORIZONS_ID dictionary at the top of this module.
          or an me.direction instance 
    degrees: if False, returns Az,El in radians;  otherwise degrees
    frame: 'AZEL' or 'AZELGEO'
    - Todd Hunter
    """
    if type(observatory) == str:
        if (observatory == 'MAUNAKEA'):
            # Convert from a value known to JPL Horizons to a value known to CASA
            observatory = 'SMA'
        elif (observatory in list(JPL_HORIZONS_ID.values())):
            observatory = list(JPL_HORIZONS_ID.keys())[list(JPL_HORIZONS_ID.values()).index(str(observatory))]
        if (observatory.lower().find('geo') == 0):
            observatory = 'geo'
    needToClose = False
    if myme is None:
        myme = createCasaTool(metool)
        needToClose =  True
    if type(raDec) in [str,np.bytes_,np.str_]:
        # Then assume it is of the format "hh:mm:ss.sss -dd:mm:ss.ss"
        tokens = raDec.split()
        if (len(tokens) < 2):
            tokens = raDec.split(',')
            if (len(tokens) < 2):
                print("If you give a string, it must be of the format: hh:mm:ss.sss -dd:mm:ss.ss (tokens=%s)"%(tokens))
                return
        raDec = radec2rad(raDec)
        if (verbose):
            print("RA Dec in radians = ", raDec)
    if (type(mjd) == str or type(mjd) == np.bytes_):
        mjd = dateStringToMJD(mjd)
        if (mjd is None):
            print("Invalid date string")
            return
        print("MJD = ", mjd)
    myqa = createCasaTool(qatool)
    raQuantity = myqa.quantity(raDec[0], 'rad')
    decQuantity = myqa.quantity(raDec[1], 'rad')
    mydir = myme.direction('J2000', raQuantity, decQuantity)
    myframe = myme.doframe(myme.epoch('mjd', myqa.quantity(mjd, 'd')))
    if type(observatory) in [str, np.bytes_]:
        if observatory != 'geo':
            if observatory not in listAvailableObservatories(False):
                if observatory not in list(extraObservatories.keys()):
                    print("Observatory %s unrecognized by CASA and extraObservatories" % (observatory))
                    return
                else:
                    mydict = extraObservatories[observatory]
                    myme.doframe(mydict)
            else:
                if verbose: 
                    casalog.post("Calling me.observatory(%s)" % (observatory))
                myobservatory = myme.observatory(observatory)
                myme.doframe(myobservatory)  # will not throw an exception if observatory not recognized
        else:
            if verbose: 
                print("Calling me.position('ITRF',0m,0m,0m)")
            geo = myme.position('ITRF',myqa.quantity([0],'m'),myqa.quantity([0],'m'),myqa.quantity([0],'m'))
            myme.doframe(geo)
    else:
        # this is an ITRF or WGS84 antenna or pad position
        myme.doframe(observatory)
    myqa.done()
    myazel = myme.measure(mydir,frame)
    if needToClose:
        myme.done()
    myaz = myazel['m0']['value']
    myel = myazel['m1']['value']
    if (forcePositiveAzim and myaz < 0):
        myaz += 2*np.pi
    if (verbose):
        print("%s: Azim = %.6f deg   Elev = %.6f deg" % (observatory, myaz*180/np.pi, myel*180/np.pi))
    if (degrees):
        myaz *= 180/np.pi
        myel *= 180/np.pi
    return([myaz,myel])

def mjdToLocalTime(mjd, tz):
    """
    Converts an MJD to a local time as a datetime structure.
    tz: a string (See http://stackoverflow.com/questions/13866926/python-pytz-list-of-timezones)
    Examples: 'US/Eastern', 'US/Mountain', 'US/Hawaii', 'America/Santiago'
    -Todd Hunter
    """
    utc = mjdListToDateTime([float(mjd)])[0]
    utc_dt = pytz.utc.localize(utc)
    local_dt = utc_dt.astimezone(pytz.timezone(tz))
    return(local_dt)
    
def mjdToChileTime(mjd=None):
    """
    Converts an MJD to America/Santiago time as a datetime structure. 
    Default = now.
    -Todd Hunter
    """
    if (mjd==None): mjd=getMJD()
    localtime = mjdToLocalTime(float(mjd), 'America/Santiago') # used to be Chile/Continental
    if (57137 <= mjd < 57523):  
        # as of 2015-04-26, no longer going back from -3h
        # but repealed before the change that happened on 2016-05-15
        localtime = mjdToLocalTime(float(mjd), 'America/Buenos_Aires')
    return(localtime)

def mjdToMountainTime(mjd):
    """
    Converts an MJD to US Mountain time as a datetime structure.  Default = now.
    -Todd Hunter
    """
    if (mjd==None): mjd=getMJD()
    return(mjdToLocalTime(float(mjd), 'US/Mountain'))

def mjdToEasternTime(mjd):
    """
    Converts an MJD to US Eastern time as a datetime structure.  Default = now.
    -Todd Hunter
    """
    if (mjd==None): mjd=getMJD()
    return(mjdToLocalTime(float(mjd), 'US/Eastern'))

def hoursToHM(hours):
    """
    Converts decimal hours into HH:MM.  See also hoursToHMS and hmsToHours.
    Todd Hunter
    """
    h,m,s = hoursToHMS(hours).split(':')
    return('%02d:%02d'%(int(h),int(m)))
    
def hoursToHMS(hours, prec=3):
    """
    Converts decimal hours (or a list of hours) into HH:MM:SS.    See also hmsToHours.
    Todd Hunter
    """
    if (type(hours) != list and type(hours) != np.ndarray):
        hrs = [hours]
    else:
        hrs = hours
    mystring = []
    for h in hrs:
        minutes = int(60*(h-int(h)))
        seconds = 3600.*(h-int(h)-minutes/60.)
        if prec == 0:
            mystring.append('%02d:%02d:%02.0f' % (int(h), minutes, seconds))
        else:
            mystring.append('%02d:%02d:%0*.*f' % (int(h), minutes, prec+3, prec, seconds))    
    if (type(hours) != list and type(hours) != np.ndarray):
        mystring = mystring[0]
    return(mystring)
        
def hmsToDegrees(hms, delimiter=':'):
    """
    Convert RA string into floating point degrees. Uses 15*hmsToHours(hms)
    -Todd Hunter
    """
    return 15*hmsToHours(hms, delimiter)

def hmsToHours(hms, delimiter=':'):
    """
    Converts string (or list of strings) of "HH", "HH:MM", "HH:MM:SS" or
    "HH:MM:SS.S" (with any number of trailing digits) or "HHhMMmSSs" into
    floating point hours.  Also works for converting dmsToDegrees.  
    If delimiter is not found in dms, then if there is more than one '.' in 
    dms, it will automatically set delimiter to '.'; otherwise, set it to ' '.
    See also hoursToHMS.
    -Todd Hunter
    """
    if delimiter not in hms:
        if hms.count('.')>1:
            delimiter = '.'
        elif hms.find('h') > 0:
            hms = hms.replace('h',':').replace('m',':').replace('s','')
        else:
            delimiter = ' '
    if (type(hms) == str):
        h = [hms]
    else:
        h = hms
    hours = []
    for x in h:
        myhours = sum(abs(float(t)) * 60 ** (2-i) for i,t in enumerate(x.split(delimiter)[:3]))/3600.
        if x.count(delimiter) >= 3:
            # handle 17.20.53.3 correctly
            myhours += float('0.'+x.split(delimiter)[3])/3600.
        if (x.find('-')>=0):
            myhours = -myhours
        hours.append(myhours)
    if (type(hms) == str):
        hours = hours[0]
    return(hours)
        
def dmsToDegrees(dms, delimiter=':'):
    """
    Converts string (or list of strings) of "DD", "DD:MM", "DD:MM:SS" or
    "DD:MM:SS.S" (with any number of trailing digits) into
    floating point degrees.  Note that it simply calls au.hmsToHours().
    If delimiter is not found in dms, then if there is more than one '.' in 
    dms, it will automatically set delimiter to '.'; otherwise, set it to ' '.
    -Todd Hunter
    """
    if delimiter not in dms:
        if dms.count('.')>1:
            delimiter = '.'
        else:
            delimiter = ' '
    return hmsToHours(dms, delimiter)
        
def computeLSTForElevation(elevation, radec=None, date='', mjd=0, observatory='ALMA',
                           intervalMinutes=5, vis=None, field=None, useJPL=False):
    """
    Computes the LST that an object passes the specified elevation at the specified
    observatory.
    -Todd Hunter
    """
    value = computeUTForElevation(elevation, radec, date, mjd, observatory,
                                  intervalMinutes, vis, field, useJPL)
    if (value == [] or value is None): return
    riseTime, setTime = value
    riseLST = ComputeLST(riseTime, longitude=getObservatoryLatLong(observatory)[1][0])
    setLST = ComputeLST(setTime, longitude=getObservatoryLatLong(observatory)[1][0])
    print("LST of rise = %f = %s" % (riseLST, hoursToHMS(riseLST,prec=0)))
    print("LST of set  = %f = %s" % (setLST, hoursToHMS(setLST,prec=0)))
    return(riseLST, setLST)

def getUT():
    """
    Returns the current UT in hours.
    """
    return(mjdVectorToUTHours(getMJD()))

def computeUTForElevation(elevation, radec=None, date='', mjd=0,
                          observatory='ALMA',
                          intervalMinutes=15, vis=None, field=None,
                          useJPL=False, verbose=True,
                          finestSearch=1.0):
    """
    For a specified RA/Dec, date/MJD, and elevation, compute the UT time that the
    object will cross that point.
    raDec must either be a tuple in radians: [ra,dec],
        or a string of the form: hh:mm:ss.sss -dd:mm:ss.ss
    mjd: modified Julian date (optional, default = today)
    date: string date (optional)
        Either of these formats is valid: 2011/10/15, 2011-10-15
    The time portion is optional.
    elevation: in degrees
    observatory: location to run the calculation for
    intervalMinutes: initial grid size to use in the search
    finestSearch: final grid to use (in minutes)
    vis: the measurement set from which to read the field coordinates
    field: the field ID or name in the measurement set to use, or name of a planet
            if a planet, then find its position on the specified date (or today)
    useJPL: if True, query JPL Horizons for planets instead of casa ephemerides
    Returns:
    [riseTime,setTime] as MJD seconds
    -Todd Hunter
    """
#    startTime = timeUtilities.time()
    mindiffRising = 1e9
    mindiffSetting = 1e9
    if (mjd==0 and date==''):
        mjd = getMJD()
    elif (date != ''):
        mjd = dateStringToMJD(date, verbose=False)
    previousEl = None
    if (radec is None):
        if (vis==None and field is None):
            print("You must specify either radec, field or (vis and field)")
            return
        if (field is None):
            print("If you specify vis, then you must also specify field ID or field name.")
            return
        if (vis is None):
            print("Since vis has not been specified, I will assume that %s is a planet." % (field))
            radec = planet(field,mjd=mjd,useJPL=useJPL)['directionRadians']
        else:
            mymsmd = createCasaTool(msmdtool)
            mymsmd.open(vis)
            try:
                field = int(field)
                fieldname = mymsmd.namesforfields(field)[0]
            except:
                fieldname = field
                if (fieldname not in mymsmd.namesforfields()):
                    print("%s is not in the measurement set" % (fieldname))
                    return
                field = mymsmd.fieldsforname(field)[0]
            mymsmd.close()
            myms = createCasaTool(mstool)
            myms.open(vis)
            radec = direction2radec(myms.getfielddirmeas(fieldid=field))
            myms.close()
            print("Got field %d = %s at %s" % (field,fieldname,radec))
    for m in np.arange(mjd, mjd+1, intervalMinutes/1440.):
        az,el = computeAzElFromRADecMJD(radec, m, observatory, verbose=False)
        diff = abs(elevation-np.degrees(el))
        if (previousEl is not None):
            if (el > previousEl):
                if (diff < mindiffRising):
                    mindiffRising = diff
                    mjdAtMinDiffRising = m
            else:
                if (diff < mindiffSetting):
                    mindiffSetting = diff
                    mjdAtMinDiffSetting = m
        previousEl = el
    if (mindiffRising < finestSearch): # degrees
        # Now find a rising value accurate to 1 minute
        mindiffRising = 1e9
        previousEl = np.pi
        for m in np.arange(mjdAtMinDiffRising-(finestSearch+0.5*intervalMinutes)/1440.,
                           mjdAtMinDiffRising+(finestSearch+0.5*intervalMinutes)/1440., 1.0/1440.):
            az,el = computeAzElFromRADecMJD(radec, m, observatory, verbose=False)
            diff = abs(elevation-np.degrees(el))
            if (previousEl < np.pi):
                if (el > previousEl):
                    if (diff < mindiffRising):
                        mindiffRising = diff
                        mjdAtMinDiffRising = m
            previousEl = el
        # Now find a setting value accurate to 1 minute
        mindiffSetting = 1e9
        previousEl = np.pi
        for m in np.arange(mjdAtMinDiffSetting-(finestSearch+0.5*intervalMinutes)/1440.,
                           mjdAtMinDiffSetting+(finestSearch+0.5*intervalMinutes)/1440., finestSearch/1440.):
            az,el = computeAzElFromRADecMJD(radec, m, observatory, verbose=False)
            diff = abs(elevation-np.degrees(el))
            if (previousEl < np.pi):
                if (el < previousEl):
                    if (diff < mindiffSetting):
                        mindiffSetting = diff
                        mjdAtMinDiffSetting = m
            previousEl = el

        if (observatory == 'ALMA'):
            local_dt = mjdToChileTime(mjdAtMinDiffRising)
            localrise = " = %s Chile time" % (local_dt.strftime('%H:%M'))
            local_dt = mjdToChileTime(mjdAtMinDiffSetting)
            localset = " = %s Chile time" % (local_dt.strftime('%H:%M'))
        elif (observatory.find('VLA') >= 0):
            local_dt = mjdToMountainTime(mjdAtMinDiffRising)
            localrise = " = %s Mountain time" % (local_dt.strftime('%H:%M'))
            local_dt = mjdToMountainTime(mjdAtMinDiffSetting)
            localset = " = %s Mountain time" % (local_dt.strftime('%H:%M'))
        elif (observatory.find('GBT') >= 0):
            local_dt = mjdToEasternTime(mjdAtMinDiffRising)
            localrise = " = %s Eastern time" % (local_dt.strftime('%H:%M'))
            local_dt = mjdToEasternTime(mjdAtMinDiffSetting)
            localset = " = %s Eastern time" % (local_dt.strftime('%H:%M'))
        else:
            localrise = ''
            localset = ''
        riseTime = mjdsecToUTHM(mjdAtMinDiffRising*86400)
        setTime = mjdsecToUTHM(mjdAtMinDiffSetting*86400)
        if verbose:
            print(" rising: %s UT %s" % (riseTime, localrise))
            print("setting: %s UT %s" % (setTime, localset))
                
        return([mjdAtMinDiffRising*86400, mjdAtMinDiffSetting*86400])
    else:
        print("mindiffRising = ", mindiffRising)
        maxElevation = 90-abs(radec2deg(radec)[1] - getObservatoryLatLong(observatory)[0])
        if (maxElevation < elevation):
            print("Object never crosses that elevation.  Highest = %f deg" % (maxElevation))
        else:
            print("maxElevation=%f >= el=%f" % (maxElevation,elevation))
            print("Object does not remain above that elevation for more than %d minutes." % (intervalMinutes))
        return([])
    
def nutation(radec=None, mjdsec=None, vis=None, fieldId=None):
    """
    Computes the effect of nutation on celestial equatorial coordinates, based on the formula
    of Hohenkerek et al. 1992 (see Rick Fisher's home page), which is good to about an arc

    second.
    inputs:
       radec: a tubple in radians or a sexagesimal string ('hh:mm:ss.s +dd:mm:ss.s')
       mjdsec: time in MJD seconds (default = now)
    returns:
       deltaRa and deltaDec in arc seconds
    -Todd Hunter
    """
    if (radec is not None):
        if (type(radec) == str):
            ra,dec = radec2rad(radec)
            radec = [ra,dec]
        if (mjdsec is None):
            mjdsec = getCurrentMJDSec()
    elif (vis is None):
        print("You must either give radec or vis+fieldId")
        return
    else:
        radec = getRADecForField(vis, fieldId, usemstool=True)
        ra = radec[0][0]
        dec = radec[1][0]
        radec = [ra,dec]
        mymsmd = createCasaTool(msmdtool)
        mymsmd.open(vis)
        mjdsec = np.mean(mymsmd.timesforfield(fieldId))
        mymsmd.close()

    d = mjdToJD(mjdsec/86400) - 2451545.0
    dL = -17.3 * np.sin((125.0 - 0.5295*d)*np.pi/180.) - 1.4*np.sin((200.0 + 1.97129*d)*np.pi/180.)
    dE = 9.4 * np.cos((125-0.05295*d)*np.pi/180) + 0.7*np.cos((200.0 + 1.97129*d)*np.pi/180.)
    dRA = (0.9175 + 0.3978*np.sin(radec[0])*np.tan(radec[1]))*dL - np.cos(radec[0])*np.tan(radec[1])*dE
    dDec = 0.3978*np.cos(radec[0])*dL + np.sin(radec[0])*dE
    return([dRA, dDec])
                        
def refraction(elevationDegrees, pressure=563, temperature=273, RH=20):
    """
    Computes the radio refraction angle in arc seconds,
    using the formula of Ulich (1981) and Brussaard & Watson (1995).
                    1981IJIMW...2..293U 
    Should add the formulae from CSV-2934 once it is resolved.
    Inputs:
    elevationDegrees: in degrees
    temperature: in Kelvin
    pressure: in mbar
    RH: in percentage
    -Todd Hunter
    """
    Pdry = pressure
    T = temperature
    esat = 6.105*np.exp(25.22*(T-273)/T - 5.31*np.log(T/273))
    Pw = 0.01*RH/esat
    elev = np.radians(elevationDegrees)
    f = np.cos(elev)/(np.sin(elev) + 0.00175*np.tan(np.radians(87.5-elevationDegrees)))
    Ro = 16.01*Pdry/T - 1.15*Pw/T + (7.734937e4)*Pw/(T**2)
    Rsec = Ro*f
    return(Rsec)

def computeRADecFromAzElUnixtime(filename, outname=None, timeColumn=1,
                                 azimuthColumn=2, elevationColumn=3,
                                 observatory='ALMA', cofa=''):
    """
    Reads an ASCII file with unixtime, azimuth and elevation as columns
    and produces a new file with UT, right ascension, hour angle and
    declination.
    timeColumn: the column number containing time (columns start at zero)
                in unix time (seconds since 1970)
    azimuthColumn: the column number containing azimuth in degrees
    elevationColumn: the column number containing elevation in degrees
    observatory: the name of the observatory for the azimuth, elevation values.
                 Must be either a name recognized by the CASA me tool, or a
                 JPL Horizons ID listed in the JPL_HORIZONS_ID dictionary at
                 the top of this module.
    cofa: if specifed as [x,y,z], use this ITRF position as array center
    - Todd Hunter
    """
    f = open(filename,"r")
    if (outname is None):
        outname = filename + ".radec"
    o = open(outname,'w')
    unixtime = []
    azimuth = []
    elevation = []
    ra = []
    dec = []
    o.write('# Minutes  UnixTime(sec)  Az(degree) El(degree)  MJD  UT(hrs)  RA(hours) Dec(degree) HA(hours)\n')
    [latitude, longitude, obs] = getObservatoryLatLong(observatory)  
    for line in f.readlines():
        tokens = line.split()
        if (len(tokens) < max([timeColumn,azimuthColumn,elevationColumn])):
            continue
        unixtime.append(float(tokens[timeColumn]))
        azimuth.append(float(tokens[azimuthColumn])*np.pi/180.)
        elevation.append(float(tokens[elevationColumn])*np.pi/180.)
        mjd = jdToMJD(ComputeJulianDayFromUnixTime(unixtime[-1]))
        ut = 24*(mjd-np.floor(mjd))
        LST = ComputeLST(mjd*86400, longitude)
        a,b = computeRADecFromAzElMJD([azimuth[-1], elevation[-1]],
                                      mjd, observatory=observatory,
                                      verbose=False, cofa=cofa)
        ra.append(a*12/np.pi)
        dec.append(b*180/np.pi)
        hourAngle = LST-ra[-1]
        if (hourAngle > 12): hourAngle -= 24
        o.write(line[:-1] + ' %.4f %.4f %.6f %.6f %.4f\n'%(mjd,ut,ra[-1],dec[-1],hourAngle))
    f.close()
    o.close()
    if (len(unixtime) < 1):
        print("No data found in file")
        return
    print("Results left in file = ", outname)

def hourAngleForField(vis, field, verbose=True):
    """
    Computes the range and mean of hour angles for a specified field
    in a measurement set. If there are multiple ObsIDs, it computes
    the range for each one, then computes the join min/max/mean
    - Todd Hunter
    vis: measurement set
    field: field ID or string name
    verbose: if True, then print the derived time range
    Returns: a dictionary of hour angles (in hours),
             keyed by 'min', 'max', and 'mean'
    """
    if (not os.path.exists(vis)):
        print("Could not find measurement set: ", vis)
        return
    obsIDs = getObservationIDs(vis)
    if len(obsIDs) > 1:
        days = np.diff(getObservationMJDSecRange(vis))[0]/86400.
        print("There are %d obsIDs spread over %.2f days" % (len(obsIDs), days))
    mymsmd = createCasaTool(msmdtool)
    mymsmd.open(vis)
    fieldnames = mymsmd.fieldnames()
    if (type(field) == str):
        if (field.isdigit()):
            field = int(field)
        elif field not in fieldnames:
            print("Field %s not present. Valid fields: %s" % (field,fieldnames))
            return
        else:
            fields = mymsmd.fieldsforname(field)
            field = fields[0]
            if (len(fields) > 1):
                print("This source has multiple fields. Picking first one: %d." % (field))
    nfields = mymsmd.nfields()
    if (field < 0 or field >= nfields):
        print("Invalid field ID.  There are only %d fields in ms." % (nfields))
        return
    direction = getRADecForField(vis, field, usemstool=True, forcePositiveRA=True)
    mjd = mymsmd.timesforfield(field) / 86400.
    minHourAngles = []
    maxHourAngles = []
    for o in obsIDs:
        t = mymsmd.timerangeforobs(o)
        t0 = t['begin']['m0']['value']
        t1 = t['end']['m0']['value']
        print("type(mjd) = ", type(mjd))
        print("type(t0) = ", type(t0))
        idx = np.where((t0 < mjd) * (mjd < t1))
        minmjd = np.min(mjd[idx])
        meanmjd = np.mean(mjd[idx])
        maxmjd = np.max(mjd[idx])
        minLST = ComputeLST(minmjd*86400, observatory=getObservatoryName(vis))
        maxLST = ComputeLST(maxmjd*86400, observatory=getObservatoryName(vis))
        minHourAngle = minLST - direction[0][0]*12/np.pi
        maxHourAngle = maxLST - direction[0][0]*12/np.pi
        if len(obsIDs) > 1 or verbose:
            print("%d) minMJD=%f, maxMJD=%f" % (o,minmjd,maxmjd))
            print("%d) minLST=%f, maxLST=%f" % (o,minLST,maxLST))
            print("%d) minHA=%f, maxHA=%f" % (o,minHourAngle,maxHourAngle))
        minHourAngles.append(minHourAngle)
        maxHourAngles.append(maxHourAngle)
    minHourAngle = np.min(minHourAngles)
    maxHourAngle = np.max(maxHourAngles)
    mydict = {'min': minHourAngle, 'max': maxHourAngle, 
              'mean': 0.5*(minHourAngle+maxHourAngle)}
    return(mydict)

def getFeedTableTimes(vis, subtractValue=0):
    """
    Prints the unique values in the TIME column of the FEED table of a measurement set.
    -Todd Hunter
    """
    if (not os.path.exists(vis)):
        print("Could not find measurement set: ", vis)
        return
    feed = vis + '/FEED'
    if (not os.path.exists(feed)):
        print("Could not find FEED table.")
        return
    mytb = createCasaTool(tbtool)
    mytb.open(feed)
    times = np.unique(mytb.getcol('TIME')) - subtractValue
    mytb.close()
    for t in times:
        print("%f = %s" % (t, mjdSecondsToMJDandUT(t)))
    return(times)

def fixFeedTableTimes(vis):
    """
    Copies the time in the first row of a FEED table to all rows.
    -Todd Hunter
    """
    if (not os.path.exists(vis)):
        print("Could not find measurement set: ", vis)
        return
    feed = vis + '/FEED'
    if (not os.path.exists(feed)):
        print("Could not find FEED table.")
        return
    mytb = createCasaTool(tbtool)
    mytb.open(feed, nomodify=False)
    times = mytb.getcol('TIME')
    times = times[0] * np.ones(len(times))
    mytb.putcol('TIME',times)
    print("Wrote %f to all rows" % (times[0]))
    mytb.close()

def fixReceptorAngles(vis, antenna='', angles=[]):
    """
    In the FEED table of the specified measurement set, replace RECEPTOR_ANGLEs 
    of [0,90] with the specified value, or the median of all the non-[0,90] values.
    antenna: limit any changes to the specified antenna list (ID or name)
    angles: if specified, use this tuple as the new feed angle [X,Y]
    -Todd Hunter
    """
    if (not os.path.exists(vis)):
        print("Could not find measurement set: ", vis)
        return
    if (angles == []):
        angles = receptorAngles(vis, verbose=False)
    mytb = createCasaTool(tbtool)
    mytb.open(vis+'/FEED', nomodify=False)
    currentAngles = np.transpose(mytb.getcol('RECEPTOR_ANGLE'))
    antennaIDs = mytb.getcol('ANTENNA_ID')
    uniqueAntennaIDs = np.unique(antennaIDs)
    mymsmd = createCasaTool(msmdtool)
    mymsmd.open(vis)
    antennaNames = mymsmd.antennanames(uniqueAntennaIDs)
    mymsmd.close()
    antennaIDsToFix = parseAntenna(vis, antenna)
    if (antennaIDsToFix is None): return
    fixed = 0
    for i,a in enumerate(antennaIDs):
        if (currentAngles[i][0] == 0 and currentAngles[i][1] == 90):
            if (antenna == '' or a in antennaIDsToFix):
                currentAngles[i][0] = angles[0]
                currentAngles[i][1] = angles[1]
                fixed += 1
    mytb.putcol('RECEPTOR_ANGLE', np.transpose(currentAngles))
    mytb.close()
    print("Fixed %d rows" % (fixed))

def dropZeroNinety(angles):
    """
    Takes a list of N feed angles (of shape = 2, N), and returns the index of 
    entries that are not [0,90] and not [0,pi/2].  Called by receptorAngles.
    -Todd Hunter
    """
    t_angles = np.transpose(angles)
    idx1 = np.where(angles[0] == 0.0)[0]
    idx2 = np.where(angles[1] == 90.0)[0]
    idx3 = np.where(angles[1] == np.pi/2.0)[0]
    idxA = np.intersect1d(idx1,idx2)
    idxB = np.intersect1d(idx1,idx3)
    idx = np.union1d(idxA,idxB)
    nondefault = np.ones(len(t_angles))
    nondefault[idx] = 0
    idx = np.where(nondefault == 1)[0]
    return(idx)

def cryostatCartridgeLocation(band):
    """
    Returns the distance (in mm) from the center of the cryostat.
    Based on Table 2 of FEND-40.02.00.00-035-B-REP.
    -Todd Hunter
    """
    radius = {1: 295, 2: 295, 3: 335, 4: 335, 5: 295, 6: 295, 7:150, 8: 150, 9: 150, 10: 150}
    if band not in list(radius.keys()):
        print("Invalid band: ", band)
        return
    return radius[band]
    
def cryostatWindowLocation(band):
    """
    Returns the distance (in mm) from the center of the cryostat.
    Based on Table 2 of FEND-40.02.00.00-035-B-REP.
    -Todd Hunter
    """
    radius = {1: 255, 2: 255, 3: 310.7, 4: 310.7, 5: 245, 6: 245, 7:100, 8: 103.3, 9: 100, 10: 100}
    if band not in list(radius.keys()):
        print("Invalid band: ", band)
        return
    return radius[band]
    
def defaultReceptorAngles(band):
    """
    band: integer from 1..10
    Returns the 2-element list in degrees (in which the values differ
       typically by 90.0 deg)  Values extracted from ICT-20919.
    if band is not 1..10, then return the dictionary of values
    -Todd Hunter
    """
    angle = {1: [135, 225],
             2: [45,  135],
             3: [-10,  80],
             4: [-170,-80],
             5: [-45,  45],
             6: [-135,-45],
             7: [-53.55, 36.45],
             8: [-180,-90],
             9: [-180,-90],
             10: [ 90,180],
    }
    if band in list(angle.keys()):
        return angle[band]
    return(angle)
    
def validateReceptorAngle(vis, verbose=False):
    """
    Runs receptorAngles, converts the results to degrees, rounds the values 
    to the nearest degree, and compares them to defaultReceptorAngles().
    verbose: passed to receptorAngles, True prints the values per antenna.
    -Todd Hunter
    """
    angles = list(np.round(np.degrees(np.array(receptorAngles(vis, verbose)))))
    band = getFirstScienceSpwBand(vis)
    defaultAngles = defaultReceptorAngles(band)
    if defaultAngles != angles:
        print("Mismatch: vis=%s,  default=%s" % (str(angles),str(defaultAngles)))
    else:
        print("Values match: %s" % (str(angles)))
    
def receptorAngles(vis, verbose=True):
    """
    Reads and prints the RECEPTOR_ANGLE column of the FEED table of a
    measurement set.  Returns the median value as an array of 2 values,
    unless that median is [0,90] or [0,pi/2] in which case it
    returns None, since that is the default value in the control system.
    -Todd Hunter
    """
    if (not os.path.exists(vis)):
        print("Could not find measurement set: ", vis)
        return
    if (not os.path.exists(vis+'/FEED')):
        print("Could not find FEED table.  Is this a measurement set?")
        return
    mytb = createCasaTool(tbtool)
    mytb.open(vis+'/FEED')
    angles = mytb.getcol('RECEPTOR_ANGLE')
    t_angles = np.transpose(angles)
    antennaIDs = mytb.getcol('ANTENNA_ID')
    uniqueAntennaIDs = np.unique(antennaIDs)
    mytb.close()
    mymsmd = createCasaTool(msmdtool)
    mymsmd.open(vis)
    antennaNames = mymsmd.antennanames(uniqueAntennaIDs)
    mymsmd.close()
    if verbose:
        print("Antenna Receptor_angle (= converted to degrees)")
    for a in uniqueAntennaIDs:
        idx = np.where(antennaIDs == a)[0]
        a_angles = t_angles[idx]
        angle = np.unique(a_angles)
        degrees = np.degrees(angle)
        if verbose:
            print("%2d %4s %s ( = %s)" % (a,antennaNames[a],angle, degrees))
    idx = dropZeroNinety(angles)
    if (len(idx) < 1):
        print("All values are default, so you need to set the angles parameter.")
        return(None)
    medianValue = np.median(t_angles[idx], axis=0)
    return(medianValue)

def pipelineParentDirFromWorkingDir(workingdir, basename=False):
    """
    Returns name of pipeline parent directory
    basename: if True, then strip off the leading directories, e.g. '2019.1.00146.S_2020_02_28T02_16_26.940'
    """
    mydir = '/'.join(workingdir.rstrip('/').split('/')[:-4])
    if basename:
        mydir = os.path.basename(mydir) 
    return mydir

def plotParallacticAngleForPipeline(pipelinedir, plotfile='', showgui=False, fast=True):
    """
    Plots the parallactic angle coverage the polarization calibrator in a pipeline run.
    It does not discriminate between different sessions (if there are multiple sessions).
    pipelinedir: either the parent directory or working directory of a pipeline run
    fast: passed to au.findPipelineWorkingDirectory
    plotfile: string or True (True will create os.path.basename(pipelinedir)+'_parallacticAngle.png')
    -Todd Hunter
    """
    if pipelinedir[-9:].find('/working') >= 0:
        workingdir = pipelinedir
        if plotfile == True:
            plotfile = pipelineParentDirFromWorkingDir(pipelinedir, basename=True) + '_parallacticAngle.png'
            print("Set plotfile to ", plotfile)
    else:
        if plotfile == True:
            plotfile = os.path.basename(pipelinedir.rstrip('/')) + '_parallacticAngle.png'
            print("Set plotfile to ", plotfile)
        workingdir = findPipelineWorkingDirectory(pipelinedir, fast=fast)
        print("Found working directory: ", workingdir)
    vislist = findoPipelineMeasurementSets(workingdir)
    if len(vislist) == 0:
        print("No measurement sets found.")
        return
    plotParallacticAngleAcrossMOUS(vislist, plotfile=plotfile, showgui=showgui)

def plotParallacticAngleAcrossMOUS(vislist, field='', verbose=True, antenna='',
                                   intent='POLARIZATION', showgui=False, 
                                   plotfile='', overwrite=True):
    """
    See also: plotParallacticAngleForPipeline (automatically finds vislist)
    Uses plotms to overlay parallactic angle vs. time of the specified 
    calibrator from a list of measurement sets
    intent: any CALIBRATE intent
    showgui: Note that True does not work, it crashes plotms (CAS-12935)
    plotfile: string or True (True will create 'vis[0]_parallacticAngle.png')
    -Todd Hunter
    """
    if type(vislist) == str:
        if vislist.find('*') >= 0:
            vislist = sorted(glob.glob(vislist))
        else:
            vislist = sorted(vislist.split(','))
    if len(vislist) == 0:
        print("No measurement sets found")
        return
    antenna = str(antenna)
    field = getCalibrators(vislist[0], intent=intent)
    if len(field) == 0:
        return
    field = field[0]
    print("Field = ", field)
    if plotfile == True:
        plotfile = os.path.basename(vislist[0]).replace('.ms','') + '_parallacticAngle.png'
    for i,vis in enumerate(vislist):
        spws = getScienceSpws(vis, returnString=False)
        if i == 0:
            clearplots = True
        else:
            clearplots = False
        if i == len(vislist)-1:
            myplotfile = plotfile
        else:
            myplotfile = ''
        spw = ','.join(['%d:32' % (j) for j in spws])
        print("Running plotms('%s', spw='%s', plotfile='%s', clearplots=%s, plotindex=%d, yaxis='parang', xaxis='time', coloraxis='field', title='%s', intent='CALIBRATE_%s#ON_SOURCE', antenna='%s', plotrange=[0,0,0,360], showgui=%s, overwrite=%s)" % (vis,spw,myplotfile,clearplots,i,field,intent,antenna,showgui,overwrite))
        plotms(vis, spw=spw, plotfile=myplotfile, clearplots=clearplots,
               plotindex=i, yaxis='parang', xaxis='time', coloraxis='field',
               title='%s'%(field), intent='CALIBRATE_%s#ON_SOURCE*'%(intent), 
               antenna=antenna, plotrange=[0,0,0,360], showgui=showgui, overwrite=overwrite)
 
def parallacticAngleForPipelineRun(pipelinedir, fast=True):
    """
    Returns the parallactic angle range of the polarization calibrator in a pipeline run.
    It does not discriminate between different sessions (if there are multiple sessions).
    pipelinedir: either the parent directory or working directory of a pipeline run
    fast: passed to au.findPipelineWorkingDirectory
    -Todd Hunter
    """
    if pipelinedir[-9:].find('/working') >= 0:
        workingdir = pipelinedir
    else:
        workingdir = findPipelineWorkingDirectory(pipelinedir, fast=fast)
        print("Found working directory: ", workingdir)
    vislist = findPipelineMeasurementSets(workingdir)
    if len(vislist) == 0:
        print("No measurement sets found.")
        return
    myrange = parallacticAngleForFieldAcrossMOUS(vislist)
    print("range=%f deg" % (myrange))
    return myrange

def parallacticAngleForFieldAcrossMOUS(vislist, field='', verbose=True, 
                                       intent='POLARIZATION',
                                       restrictToIntent=True):
    """
    Runs parallacticAngleForField for multiple measurement sets.
    vislist: a python list, or a comma-delimited string, or a wildcard string
    Returns: the parallactic angle range as a scalar angle in degrees
    -Todd Hunter
    """
    if type(vislist) == str:
        if vislist.find('*') >= 0:
            vislist = sorted(glob.glob(vislist))
        else:
            vislist = sorted(vislist.split(','))
    if len(vislist) == 0:
        print("No measurement sets found")
        return
    values = []
    for vis in vislist:
        mydict = parallacticAngleForField(vis, field, verbose, intent, restrictToIntent)
        if mydict is None: continue  # i.e., no scan with this intent found
        # append the parallactic angles at the first and final integrations
        values += [mydict['min'], mydict['max']] 
    signed = []
    positiveDefinite = []
    for value in values:
        if value > 180:
            positiveDefinite.append(value)
            signed.append(value-360)
        elif value < 0:
            positiveDefinite.append(value+360)
            signed.append(value)
        else:
            positiveDefinite.append(value)
            signed.append(value)
    myrange1 = np.max(signed) - np.min(signed)
    myrange2 = np.max(positiveDefinite) - np.min(positiveDefinite)
    # take the smaller of the two ranges
    myrange = np.min([myrange1, myrange2])
    return(myrange)

def parallacticAngleForField(vis, field='', verbose=True, intent='POLARIZATION',
                             restrictToIntent=True, mymsmd='', scan=None):
    """
    Computes the range of parallactic angles for a specified field
    in a measurement set. If the field has intent <restrictToIntentIfPresent>,
    then restrict the times to that intent.
    vis: measurement set
    field: field ID or string name, if blank, use the POLARIZATION calibrator
    verbose: if True, then print the derived time range
    intent: if field not specified, use first field with this intent
    restrictToIntent: only consider times with field and intent
    scan: if specified with restrictToIntent, then restrict to this single scan
    Returns: a dictionary of parallactic angles (in degrees),
       keyed by 'min', 'max', 'mean', and 'range'
    - Todd Hunter
    """
    if (not os.path.exists(vis)):
        print("Could not find measurement set: ", vis)
        return
    if mymsmd == '':
        mymsmd = createCasaTool(msmdtool)
        mymsmd.open(vis)
        needToClose = True
    else:
        needToClose = False
    if (type(field) == str):
        if len(field) == 0:
            if len(intent) == 0:
                print("You must specify at least one of: field or intent")
                if needToClose:
                    mymsmd.close()
                return
            fields = mymsmd.fieldsforintent('*'+intent+'*')
            if len(fields) == 0:
                print("No field found with intent = %s in %s" % (intent,os.path.basename(vis)))
                if needToClose:
                    mymsmd.close()
                return
            field = str(fields[0])
            fieldname = mymsmd.namesforfields(fields[0])[0]
            print("parallacticAngleForField(%s): Will use field %s = %s" % (os.path.basename(vis),field,fieldname))
        if (field.isdigit()):
            field = int(field)
        else:
            fields = mymsmd.fieldsforname(field)
            field = fields[0]
            if (len(fields) > 1):
                print("This source has multiple fields. Picking first one: %d." % (field))
    nfields = mymsmd.nfields()
    if (field < 0 or field >= nfields):
        print("Invalid field ID.  There are only %d fields in ms." % (nfields))
        if needToClose:
            mymsmd.close()
        return
    direction = getRADecForField(vis, field, usemstool=True, forcePositiveRA=True)
    mjd = mymsmd.timesforfield(field) / 86400.
#    print("Found %d times for field %s" % (len(mjd), str(field)))
    myintents = mymsmd.intentsforfield(field)
    mymjd = None
    if restrictToIntent:
        for myintent in myintents:
            if myintent.find(intent) >= 0:
                intent = myintent  # timesforintent requires full intent name
                mymjd = mymsmd.timesforintent(intent) / 86400.
#                print("Found %d times for %s" % (len(mymjd), intent))
                mjd = np.intersect1d(mjd,mymjd)
                if scan is not None:
                    mymjd2 = mymsmd.timesforscan(scan) / 86400.
                    mjd = np.intersect1d(mjd, mymjd2)
#                print("Found %d common times" % (len(mjd)))
                break
        if mymjd is None:
            print("No times for this field have intent=%s, ignoring restriction." % (intent))
    if needToClose:
        mymsmd.close()
    if len(mjd) < 1:
        return
    minmjd = np.min(mjd)
    meanmjd = np.mean(mjd)
    maxmjd = np.max(mjd)
    if verbose:
        print("MJD: %f-%f = %s-%s UT" % (minmjd, maxmjd, 
                                         mjdToUT(minmjd).split()[1],
                                         mjdToUT(maxmjd).split()[1]))
    myme = createCasaTool(metool)
    myqa = createCasaTool(qatool)
    mydir = myme.direction('J2000',myqa.quantity(direction[0],'rad'), 
                           myqa.quantity(direction[1],'rad'))
    hadec_pole = myme.direction('J2000', '0deg', '+90deg')
    myme.doframe(myme.observatory(getObservatoryName(vis)))
    myme.doframe(myme.epoch('mjd', myqa.quantity(minmjd,'d')))
    mydir_azel = myme.measure(mydir, 'AZEL')
    hadec_pole_azel = myme.measure(hadec_pole, 'AZEL')
    minParAngle = headerToDegree(myme.posangle(mydir_azel, hadec_pole_azel))
    myme.doframe(myme.epoch('mjd', myqa.quantity(maxmjd,'d')))
    mydir_azel = myme.measure(mydir, 'AZEL')
    maxParAngle = headerToDegree(myme.posangle(mydir_azel, hadec_pole_azel))
    myme.doframe(myme.epoch('mjd', myqa.quantity(meanmjd,'d')))
    myqa.done()
    mydir_azel = myme.measure(mydir, 'AZEL')
    # The pole does not move very much, but may as well recompute it.
    hadec_pole_azel = myme.measure(hadec_pole, 'AZEL')
    meanParAngle = headerToDegree(myme.posangle(mydir_azel, hadec_pole_azel))
    myme.done()
    if minParAngle > maxParAngle:
        swap = maxParAngle*1.0
        maxParAngle = minParAngle
        minParAngle = swap
    parAngleRange = maxParAngle-minParAngle
    if (parAngleRange > 180):
        parAngleRange = 360-parAngleRange
    mydict = {'min': minParAngle, 'mean': meanParAngle, 'max': maxParAngle, 'range': parAngleRange}
    return(mydict)

def J2000ToICRSgrid(ra_inc=0.5, dec_inc=5, separation=5.0):
    """
    Computes a grid of conversions and provides statistics.
    ra_inc: increment of RA grid in hours
    dec_inc: increment of Dec grid in degrees
    separation: angle to calibrator (at random p.a.) for computing diff
    -Todd Hunter
    """
    mas = []
    delta = []
    for ra in np.arange(0,24,ra_inc):
        for dec in np.arange(-90,90,dec_inc):
            radec = hours2radec(ra,dec, verbose=False)
            icrs = J2000ToICRS(radec, verbose=False)
            mas1 = angularSeparationOfStrings(radec, icrs, verbose=False) * 3600000 # deg2mas
            mas.append(mas1)
            pa = 2*np.pi*random.random()
            delta_ra = separation*np.cos(pa)/(15.0/np.cos(np.radians(dec)))  # hours
            delta_dec = separation*np.sin(pa)
            radec2 = hours2radec(ra+delta_ra,dec+delta_dec, verbose=False)
            icrs2 = J2000ToICRS(radec2, verbose=False)
            mas2 = angularSeparationOfStrings(radec2, icrs2, verbose=False) * 3600000 # deg2mas
            delta.append(np.abs(mas1-mas2))
    print("Grid of %d directions: Max=%f, Min=%f, Median=%f, Mean=%f mas" % (len(mas),np.max(mas),np.min(mas),np.median(mas),np.mean(mas)))
    print("Deltas for %.1f deg offset: Max=%f, Min=%f, Median=%f, Mean=%f mas" % (separation,np.max(delta),np.min(delta),np.median(delta),np.mean(delta)))
    
def J2000ToICRS(radec, date='', verbose=True):
    """
    Converts a direction from J2000 to ICRS and computes the angular separation.
    radec: sexagesimal string format
    date: optional -- CASA shows no date dependence in this calculation!
      Any of these formats is valid: 2011/10/15 05:00:00
    (The time portion is optional.)  2011/10/15-05:00:00
                                     2011-10-15 05:00:00
                                     2011-10-15T05:00:00
                                     2011-Oct-15T05:00:00
    -Todd Hunter
    """
    if (not radec[0].isdigit()):
        print("radec parameter must be a sexagesimal string.  Maybe you want au.imageHeaderToICRS?")
        return
    direction = radec2rad(radec)
    myme = createCasaTool(metool)
    mjd = dateStringToMJD(date, verbose=False)
    myqa = createCasaTool(qatool)
    myme.doframe(myme.epoch('mjd', myqa.quantity(mjd,'d')))
    mydir = myme.direction('J2000', myqa.quantity(direction[0],'rad'), 
                           myqa.quantity(direction[1],'rad'))
    myqa.done()
    mydir_icrs = myme.measure(mydir, 'ICRS')
    newradec = direction2radec(mydir_icrs)
    sep = angularSeparationOfStrings(radec, newradec, verbose=verbose)
    return(newradec)

def ICRSToJ2000(radec, date='', verbose=True):
    """
    Uses the CASA measures tool to converts a direction from ICRS to J2000 
    and computes the angular separation of the two directions.
    radec: sexagesimal string format
    date: optional -- CASA shows no date dependence in this calculation!
      Any of these formats is valid: 2011/10/15 05:00:00
    (The time portion is optional.)  2011/10/15-05:00:00
                                     2011-10-15 05:00:00
                                     2011-10-15T05:00:00
                                     2011-Oct-15T05:00:00
    -Todd Hunter
    """
    if (not radec[0].isdigit()):
        print("radec parameter must be a sexagesimal string.  Maybe you want au.imageHeaderToJ2000?")
        return
    direction = radec2rad(radec)  # convert sexagesimal to radians
    myme = createCasaTool(metool)
    myqa = createCasaTool(qatool)
    mydir = myme.direction('ICRS',myqa.quantity(direction[0],'rad'), 
                           myqa.quantity(direction[1],'rad'))
    mjd = dateStringToMJD(date, verbose=False)
    myme.doframe(myme.epoch('mjd', myqa.quantity(mjd,'d')))
    myqa.done()
    mydir_icrs = myme.measure(mydir, 'J2000')
    newradec = direction2radec(mydir_icrs)  # convert direction object to sexagesimal
    sep = angularSeparationOfStrings(radec, newradec, verbose=verbose)
    return(newradec)

def checkGeodeticTableDate(tablename='TAI_UTC', datapath=''):
    """
    Returns the keywords for a specified geodetic table located at
    CASA < 6: os.getenv("CASAPATH").split()[0] + "/data/geodetic/" 
    CASA 6: os.path.dirname(casatools_utils.utils().resolve('geodetic'))
    -Todd Hunter
    """
    mytb = createCasaTool(tbtool)
    if datapath == '':
        datapath = getCasaDataPath()
    datapath += '/geodetic/'+tablename
    if not os.path.exists(datapath):
        print("This path does not exist: ", datapath)
        return
    mytb.open(datapath)
    keywords = mytb.getkeywords()
    mytb.close()
    return keywords

def getSourceFrame(vis):
    """
    Reads the DIRECTION column's MEASINFO keyword reference value
    Returns: typically 'J2000' or 'ICRS'
    -Todd Hunter
    """
    if not os.path.exists(vis):
        print("Could not find ms=%s." % (vis))
        return
    mytb = createCasaTool(tbtool)
    mytb.open(vis+'/SOURCE')
    frame = mytb.getcolkeyword('DIRECTION','MEASINFO')
    mytb.close()
    return(frame['Ref'])

def changeSourceFrame(vis, toref='ICRS'):
    """
    Relabels the DIRECTION column's MEASINFO reference frame
    toref: either 'ICRS' or 'J2000'
    Note that there is only one value, so it applies to all fields!
    """
    if not os.path.exists(vis):
        print("Could not find ms=%s." % (vis))
        return
    mytb = createCasaTool(tbtool)
    mytb.open(vis+'/SOURCE', nomodify=False)
    frame = mytb.getcolkeyword('DIRECTION','MEASINFO')
    print("Changing from %s to %s" % (frame['Ref'], toref))
    frame['Ref'] = toref
    mytb.putcolkeyword('DIRECTION','MEASINFO', frame)
    mytb.close()

def convertfieldframe(vis, fieldid, toref='J2000', nomodify=True):
    """
    Change the reference code for a given field in the FIELD table of the 
    given MS.  Returns the new direction for the PHASE_DIR. 
    Only actually changes the field table if nomodify=False
    To convert an image header, see au.imageHeaderToJ2000, imageHeaderToICRS
       vis - MeasurementSet name

       fieldid - numerical ID of the field (as an int)

       toref - reference frame to convert to
          default: 'J2000' which is code 0 (note that 'ICRS' is code 21)

       nomodify - if False, the value in the FIELD tables will be overwritten
          default: True

    Examples:

      convertfieldframe('uid___A002_Xd0f5d5_X12aa.ms.split.cal', 1, 'ICRS', False)

         converts the direction columns for field ID 1 in the given MS to frame "ICRS".

      convertfieldframe('uid___A002_Xd0f5d5_X12aa.ms.split.cal', 1, 'J2000')

         only computes the new direction value for the PHASE_DIR and returns it as a measure
         but does not change the FIELD table

    D. Petry (ESO), Feb 2019, Mar 2023
    """
    tbt = tbtool()
    tbt.open(vis+'/FIELD')
    theolddir = tbt.getcell('PHASE_DIR',fieldid)
    ra1 = theolddir[0]
    dec1 = theolddir[1]
    pcol = tbt.getcol('PhaseDir_Ref')
    theoldref = pcol[fieldid]
    oldrefstrindex = tbt.getcolkeyword('PHASE_DIR', 'MEASINFO')['TabRefCodes'].tolist().index(theoldref)
    oldrefstr = tbt.getcolkeyword('PHASE_DIR', 'MEASINFO')['TabRefTypes'][oldrefstrindex]
    tbt.close()
    myqa = createCasaTool(qatool)
    print('Input value ', myqa.time(myqa.quantity(ra1, 'rad'), form='hms', prec=12)[0], myqa.angle(myqa.quantity(dec1,'rad'), prec=12)[0], ' Ref: ', oldrefstr)
    myme = createCasaTool(metool)
    thedir1=myme.measure(myme.direction(oldrefstr, myqa.quantity(ra1, 'rad'), myqa.quantity(dec1,'rad')), toref)
    print('Output value ', myqa.time(thedir1['m0'], form='hms', prec=12)[0], myqa.angle(thedir1['m1'], prec=12)[0], ' Ref: ', toref)

    if not nomodify and oldrefstr != toref:

        dircols = ['PHASE_DIR', 'DELAY_DIR', 'REFERENCE_DIR']
        refcols = ['PhaseDir_Ref', 'DelayDir_Ref', 'RefDir_Ref']

        tbt.open(vis+'/FIELD', nomodify=False)
        thenames = tbt.colnames()
        for myrefcol in refcols:
            if not myrefcol in thenames:
                casalog.post('ERROR: FIELD table does not contain standard reference frame column '+myrefcol, 'SEVERE')
                tbt.close()
                return thedir1

        for mycol in dircols:

            print(mycol)

            refindex = dircols.index(mycol)
            theolddir = tbt.getcell(mycol, fieldid)
            ra1=theolddir[0]
            dec1=theolddir[1]
            prcol = tbt.getcol(refcols[refindex])
            theoldref = prcol[fieldid]
            oldrefstrindex = tbt.getcolkeyword(mycol, 'MEASINFO')['TabRefCodes'].tolist().index(theoldref)
            oldrefstr = tbt.getcolkeyword(mycol, 'MEASINFO')['TabRefTypes'][oldrefstrindex]

            thedir1=myme.measure(myme.direction(oldrefstr, myqa.quantity(ra1, 'rad'), myqa.quantity(dec1,'rad')), toref)

            newrefindex = tbt.getcolkeyword(mycol, 'MEASINFO')['TabRefTypes'].tolist().index(toref)
            newrefcode =  tbt.getcolkeyword(mycol, 'MEASINFO')['TabRefCodes'][newrefindex]
            prcol[fieldid] = newrefcode
            tbt.putcol(refcols[refindex], prcol)

            pcol = tbt.getcol(mycol)
            pcol[0][0][fieldid] =  thedir1['m0']['value']
            pcol[1][0][fieldid] =  thedir1['m1']['value']
            tbt.putcol(mycol, pcol)
            
        tbt.close()
        print("All direction columns in FIELD table updated.")
    myqa.done()
    myme.done()
    return thedir1

def imageConversionSystem(img):
    """
    Returns the conversion system (J2000 or ICRS, etc.)
    """
    if not os.path.exists(img):
        print("Could not find image")
        return
    myia = iatool()
    myia.open(img)
    record = myia.torecord()
    frame = record['coordsys']['coordsys']['direction0']['conversionSystem']
    myia.close()
    return frame

def imageHeaderToJ2000(img, outfile='', overwrite=False):
    """
    Uses imhead to set the equinox in a CASA image to J2000.  It sets the header value
    as well as: ia.torecord()['coordsys']['coordsys']['direction0']['conversionSystem']
    To set it in a measurement set's FIELD table instead, see au.convertfieldframe
    outfile: if set to a string, then first copy the image to this name;
             if set to True, then use '<img>.J2000.image'
             if left blank, then use '<img>.J2000'
    overwrite: if True, then overwrite an image if the same name already exists
    Returns: name of new image
    To simply view the value in an image, use au.imageConversionSystem(img)
    -Todd Hunter
    """
    if not os.path.exists(img):
        print("Could not find image")
        return
    if not os.path.isdir(img):
        print("This is not a CASA image. This function does not work on .fits files")
        return
    if outfile == '':
        outfile = img + '.J2000'
        if overwrite:
            removeImageIfPresent(outfile)
        elif os.path.exists(outfile):
            print("outfile %s already exists.  Set overwrite=True to replace it." % (outfile))
            return
    else:
        if outfile==True:
            outfile = img + '.J2000.image'
            # the final replace is to remove any earlier appearance of ICRS in the name
            outfile = outfile.replace('image.J2000','J2000').replace('ICRS','')
        if overwrite:
            removeImageIfPresent(outfile)
        elif os.path.exists(outfile):
            print("outfile already exists.  Set overwrite=True to replace it.")
            return
    shutil.copytree(img, outfile)
    img = outfile
    imhead(img, mode='put', hdkey='equinox', hdvalue='J2000')
    myia = iatool()
    myia.open(img)
    record = myia.torecord()
    if (record['coordsys']['coordsys']['direction0']['conversionSystem'] == 'J2000'):
        print("ia.torecord()['coordsys']['coordsys']['direction0']['conversionSystem'] is already J2000.")
    else:
        record['coordsys']['coordsys']['direction0']['conversionSystem'] = 'J2000'
        myia.setcoordsys(record['coordsys'])
    myia.close()
    if outfile != '':
        return img

