def compareGfluxscaleflagCommands(working1, working2, outfile='',
                                  showDifference=False, vis=''):
    """
    Uses extractTimegaincalSummaryFromCasaCommandsLog to compare the gaincal
    commands in the hifa_gfluxscaleflag task between two different pipeline runs.
    vis: limit the display to lines containing the specified string
    - Todd Hunter
    """
    compareGaincalCommands(working1, working2, 'hifa_gfluxscaleflag', showDifference, outfile, vis)

def compareGaincalCommands(working1, working2, task='hifa_gfluxscale', 
                           showDifference=True, outfile='', vis=''):
    """
    Uses extractTimegaincalSummaryFromCasaCommandsLog to compare the gaincal
    commands in the specified task between two different pipeline runs.
    task: only works (so far) for hifa_timegaincal, hifa_gfluxscale, and
          hifa_gfluxscaleflag.
    vis: limit the listing to only those lines that contain this string
    - Todd Hunter
    """
    cmd1 = extractTimegaincalSummaryFromCasaCommandsLog(working1, task, vis=vis)
    if cmd1 is None:
        return
    print("---------")
    cmd2 = extractTimegaincalSummaryFromCasaCommandsLog(working2, task, vis=vis)
    if outfile != '':
        f = open(outfile,'w')
        for cmd in cmd1:
            f.write(cmd+'\n')
        f.write('------\n')
        for cmd in cmd2:
            f.write(cmd+'\n')
        f.close()
        print("Wrote ", outfile)
    if cmd2 is None:
        return
    if (cmd1 == cmd2):
        print("All %d commands match" % (len(cmd1)))
    else:
        if len(cmd1) != len(cmd2):
            print("Different number of commands %d vs. %s" % (len(cmd1),len(cmd2)))
            if showDifference:
                for cmd in cmd1:
                    if cmd not in cmd2:
                        print(cmd)
        else:
            print("Not all %d commands match." % (len(cmd1)))
            if showDifference:
                idx = np.where(np.array(cmd1) != np.array(cmd2))[0]
                for i,v in enumerate(idx):
                    print("%d) %s != %s" % (i, cmd1[v], cmd2[v]))

def extractTimegaincalSummaryFromCasaCommandsLog(mylog, tasks=['hifa_gfluxscale','hifa_timegaincal'],
                                                 outdir='', debug=False, vis='',
                                                 showSpws=False, showFields=False, showIntents=False):
    """
    Parses the casa_commands.log and generates a shorthand display of
    the gaincal calls in a specific pipeline task. Relies on msmd and the ms.
    It works correctly for multiple phase calibrators.
    mylog: either the full path to casa_commands.log, or full path to the
           working directory of the pipeline run
    tasks: either 'hifa_timegaincal', 'hifa_gfluxscale' or 
           'hifa_gfluxscaleflag' or a list or comma-delimited string
    outdir: if not blank, then write a file called
          <project>_<MOUS>_<task>Summary.txt in this directory
           where <task> = 'gaincal' if tasks is a list of length > 1
    vis: if specified, limit the display of lines to those containing this string
 1) X1b32, PHASE, T, p, inf, combine=spw, into s17_2
 2) X1b32, BP/FL, T, p, inf, combine=spw, into s17_2
 3) X1b32, BP/FL, G, p, int, , into s17_3
 4) X1b32, PHASE, T, p, int, combine=spw, into s17_4
 5) X1b32, PHASE, T, a, inf, , into s17_5
 6) X1b32, BP/FL, T, a, inf, , into s17_5
 7) X1b32, PHASE, T, a, int, , into s17_6
 8) X1b32, BP/FL, T, a, int, , into s17_6
 9) X1b32, PHASE, G, p, inf, , into offsets
10) X1b32, BP/FL, G, p, inf, , into offsets
    -Todd Hunter
    """
    if os.path.isdir(mylog):
        mydir = mylog[:]
        project, MOUS = getProjectMOUSFromDir(mylog, fast=True)
        mylog = findPipelineCasaCommandsLog(mylog)
        if mylog is None:
            # try searching current directory
            if os.path.exists(os.path.join(mydir,'casa_commands.log')):
                mylog = os.path.join(mydir,'casa_commands.log')
        if not os.path.exists(mylog):
            print("Could not find %s in the current directory nor assuming this is the working directory" % (mylog))
            return
    else:
        project = ''; MOUS = ''; mydir = ''
    outlines = []
    if type(tasks) == str:
        tasks = tasks.split(',')
    if outdir != '':
        if len(tasks) == 1:
            filename = os.path.join(outdir,'%s_%s_%sSummary.txt'%(project,MOUS,task))
        else:
            filename = os.path.join(outdir,'%s_%s_gaincalSummary.txt'%(project,MOUS))
        f = open(filename,'w')
    for task in tasks:
        cmdlist = extractTimegaincalCommandsFromCasaCommandsLog(mylog, task=task)
        if debug:
            print("Found %d commands in %s: " % (len(cmdlist),task), cmdlist)
        if cmdlist is None: return
        pars = extractGaincalParameters(cmdlist, mylog, debug, task)
        # print("Parsed %d commands in %s" % (len(pars),task))
        if len(tasks) > 1:
            outlines.append(task+':')
            print(outlines[-1])
            if outdir != '':
                f.write(task+':\n')
        preapplies = []
        for i,par in enumerate(pars):
            if par['preapplyBrief'] != '':
                preapplies.append(par['preapplyBrief'])
        preapplies = np.unique(preapplies)
        for i,par in enumerate(pars):
            allTables = calLibraryCaltables(os.path.join(mydir,par['visBrief']), True, True)
            unused = ''
            if allTables is not None: # skip this in case we only have the ms
                if debug:
                    print("allTables for %s: " % (par['visBrief']), list(allTables.keys()))
                if par['caltableBrief'] in list(allTables.keys()):
                    callibIntents = allTables[par['caltableBrief']]
                else:
                    callibIntents = []
                if debug:
                    print("%s intents=%s" % (par['caltableBrief'], callibIntents))
                if par['caltableBrief'] not in preapplies and par['caltableBrief'] != 'offsets':
                    if debug:
                        print("%s not in %s" % (par['caltableBrief'], preapplies))
                    if par['caltableBrief'] not in list(allTables.keys()):
                        if debug:
                            print("%s not in %s" % (par['caltableBrief'], allTables))
                        if task == 'hifa_timegaincal':
                            unused = " (not applied)"
                    else:
                        if par['calibrator'] in callibIntents or (par['calibrator'] == 'BP/FL' and 'BANDPASS' in callibIntents and 'FLUX' in callibIntents):
                            unused = " (hif_applycal)"
                else:  
                    if par['caltableBrief'] in list(allTables.keys()):
                        if par['calibrator'] in callibIntents or (par['calibrator'] == 'BP/FL' and 'BANDPASS' in callibIntents and 'FLUX' in callibIntents):
                            unused = " (hif_applycal)"
            if showSpws:
                spwString = 'spw%s, ' % (par['spw'][0])
            else:
                spwString = ''
            if showIntents and 'actualintent' in par:
                actualIntentString = '%5s, ' % (par['actualintent'][:5])
            else:
                actualIntentString = ''
            if showFields:
                fieldString = 'fld:%s, ' % (par['field'])
            else:
                fieldString = ''
            outline = "%2d) %s, %5s, %s%s%s%s, %s, %s %s, %s, %s into %s%s"  % (i+1, par['visBrief'], par['calibrator'][:5],actualIntentString,fieldString,spwString,par['gaintype'], par['calmode'], par['solint'], par['combine'].replace('spw','combine=spw'), par['spwmapFinalScience'].replace('[','spwmap=[').replace('spwmap=[]',''), par['preapplyBrief'].replace('s','preapply s',1), par['caltableBrief'], unused)
            if vis == '' or outline.find(vis) > 0:
                if i == 0:
                    if showIntents:
                        print(" #)  vis ,target,intent, fieldname")
                print(outline)
                if outdir != '':
                    f.write(outline+'\n')
                outlines.append(outline)
    if outdir != '':
        f.close()
        print("Wrote ",filename)
    return outlines

def extractGaincalParameters(cmdlist, mylog='', debug=False, task='hifa_timegaincal'):
    """
    Takes a list of gaincal commands and generates a shorthand notation
    of the important parameters.  It works correctly for multiple phase 
    calibrators.
    mylog: full path to casa_commands.log
    -Todd Hunter
    """
    valList = []
    caldict = {}; caldictFieldIDs = {}; caldictNames = {}; caldictFieldIDsStrings = {}
    for cmd in cmdlist:
        if debug:
            print("cmd: ", cmd)
        if len(cmdlist) == 1:  # for debugging purpose
            print(cmd)
        vals = {}
        pars = ['vis','field', 'intent', 'solint', 'combine', 'calmode', 'gaintype', 'caltable', 'gaintable', 'spwmap', 'spw']
        for par in pars:
            if debug:
                print("par = ", par)
            loc = cmd.find("%s=" % (par))
            if loc >= 0: 
                mychar = cmd[loc+len(par)+1]  # this is usually a ' or a [
                if mychar == '[':
                    mychar = ']'
#                print("mychar=%s, cmd = " % (mychar), cmd)
                contents = cmd[loc+len(par)+2:].split(mychar+",")[0]
#                print("contents = ", contents)
                vals[par] = contents
                if par == 'caltable':
                    if contents.find('offsets') > 0:
                        vals['caltableBrief'] = 'offsets'
                    else:
                        vals['caltableBrief'] = makeBriefCaltableName(contents, task)
                elif par == 'vis':
                    vals['visBrief'] = contents.split('_')[-1].split('.ms')[0]
                elif par == 'gaintable':
                    vals[par] = vals[par].replace("'",'')
                    vals['gaintableFinal'] = vals[par].split(',')[-1].strip()
                    if vals['gaintableFinal'].find(task) > 0:
                        if vals['gaintableFinal'].find('offsets') > 0:
                            vals['preapply'] = 'offsets'
                            vals['preapplyBrief'] = 'offsets' 
                        else:
                            # 'preapplyBrief' has same format as 'caltableBrief'
                            vals['preapplyBrief'] = makeBriefCaltableName(vals['gaintableFinal'],task)
                            vals['preapply'] = vals['preapplyBrief'].split('..')[0]
                    else:
                        vals['preapply'] = ''
                        vals['preapplyBrief'] = ''
                elif par == 'field':
                    if contents.find(',') > 0:
                        # in PL2021 gfluxscale, can be multiple flds, e.g. PHASE,CHECK
                        vals[par] = contents.split(',')
                        if debug or True:
                            print("multiple fields: ", vals[par]) 
                elif par == 'spw':
                    vals[par] = [','.join(['%2d'%(int(i)) for i in contents.split(',')])] # string containing: 7,9,11,13
                elif par == 'spwmap':
                    contents = cmd[loc+len(par)+2:].split(']],')[0].replace(' ','')
                    vals[par] = contents + ']' # re-add trailing bracket
                    vals['spwmapFinal'] = vals[par].split('],')[-1]
                    if debug:
                        print(vals[par])
                        print(vals['spwmapFinal'])
                    if vals['spwmapFinal'] != '[]':
                        spws = vals['spwmapFinal'][1:-1].split(',')
                        vals['spwmapFinalScience'] = '['+','.join([spws[i] for i in scienceSpws]).replace(' ','')+']'
                        if debug:
                            print("scienceSpws = ", scienceSpws)
                    else:
                        vals['spwmapFinalScience'] = vals['spwmapFinal']
                elif par == 'intent':
                    vals['actualintent'] = contents.split(',')
                    if len(vals['actualintent']) == 1:
                        vals['actualintent'] = getPrimaryIntent(vals['actualintent'][0])
                    else:
                        intentString = ''
                        for i,v in enumerate(vals['actualintent']):
                            if i > 0: intentString += '/'
                            intentString += getPrimaryIntent(v)[:1]
                        vals['actualintent'] = intentString
                    if debug:
                        print("vals['actualintent'] = ", vals['actualintent'])
            else:
                vals[par] = ''
        # determine target type from field and intent
        intentList = vals['intent'].split(',')
        if len(intentList[0]) == 0:
            print("intent list: ", intentList)
            print("cmd: ", cmd)
        primaryIntent = getPrimaryIntent(intentList[0], pointingFirst=False, atmosphereLast=True)
#  This is my first attempt to show all intents, but needs work.
#        primaryIntent = ','.join([getShortIntent(getPrimaryIntent(i)) for i in intentList])
        if len(intentList) < 2 and primaryIntent not in ['PHASE']:  # ,'CALIBRATE_PHASE#ON_SOURCE']:
            vals['calibrator'] = primaryIntent
        else:
            myvis = vals['vis']
            if not os.path.exists(myvis):
                myvis = os.path.join(os.path.dirname(mylog), '../../', myvis)
            if myvis not in list(caldict.keys()):
                mymsmd = createCasaTool(msmdtool)
                mymsmd.open(myvis)
                scienceSpws = getScienceSpws(myvis, returnString=False, mymsmd=mymsmd)
                print("scienceSpws = ", scienceSpws)
                caldict[myvis] = getCalibrators(myvis, returnDict=True, mymsmd=mymsmd)
                caldictNames[myvis] = getCalibrators(myvis, returnNames=True, returnDict=False, mymsmd=mymsmd)
                caldictFieldIDs[myvis] = getCalibrators(myvis, returnNames=False, returnDict=False, mymsmd=mymsmd)
                mymsmd.close()
                caldictFieldIDsStrings[myvis] = [str(i) for i in caldictFieldIDs[myvis]]
            calnames = list(caldict[myvis].values())
            calintents = list(caldict[myvis].keys())
            ci = []
            cns = []
            foundList = False
            for i,cn in enumerate(calnames):
                if type(cn) == list:
                    for j in range(len(cn)):
                        ci.append(calintents[i])
                        cns.append(cn[j])
                    foundList = True
                else:
                    ci.append(calintents[i])
                    cns.append(cn)
            if foundList:
                if debug: 
                    print("old intent list: ", calintents)
                calintents = ci
                calnames = cns
                if debug:
                    print("new intent list: ", calintents)
            # flatten the list, in case there are multiple calibrators
#            calnames = [item for sublist in calnames for item in sublist]
            if foundList and debug:
                print("Flattened intents: ", calintents)
                print("Flattened names: ", calnames)
            if type(vals['field']) == list:
                # multiple fields, e.g. those with intent PHASE and CHECK
                print("vals['field'] = ", vals['field'])
                vals['calibrator'] = []
                for fld in vals['field']:
                    if fld not in calnames:
                        if not fld.isdigit():
                            print("%s is not in %s" % (fld,calnames))
                        else:
                            # it will get here if one or more fields is an ID rather than a name
                            idx = caldictFieldIDsStrings[myvis].index(fld)
                            myfield = caldictNames[myvis][idx]
                            vals['field'] = '%s=%s' % (fld,myfield)
                            vals['calibrator'] = calintents[idx]
                            if debug or True:
                                print("Identified %s as a field ID for %s with intents = %s" % (fld,myfield,calintents[idx]))
                if len(vals['calibrator']) == 0:
                    for fld in vals['field']:
                        idx = calnames.index(fld)
                        vals['calibrator'].append(calintents[idx][:2])
                if vals['calibrator'] not in ['PHASE','CALIB','BANDP']:
                    vals['calibrator'] = '/'.join(vals['calibrator'])
            elif vals['field'] in calnames:
                idx = calnames.index(vals['field'])
                vals['calibrator'] = calintents[idx]
                if vals['calibrator'] == 'BANDPASS':
                    if caldict[myvis]['FLUX'] == vals['field']:
                        vals['calibrator'] = 'BP/FL'
                    elif caldict[myvis]['PHASE'] == vals['field']:
                        vals['calibrator'] = 'BP/PH'
                elif vals['calibrator'] == 'FLUX':
                    if caldict[myvis]['PHASE'] == vals['field']:
                        vals['calibrator'] = 'FL/PH'
            elif vals['field'].isdigit():
                idx = caldictFieldIDsStrings[myvis].index(vals['field'])
                myfield = caldictNames[myvis][idx]
                if debug:
                    print("Identified %s as a field ID for %s" % (vals['field'],myfield))
                vals['field'] = myfield
                vals['calibrator'] = calintents[idx]
            else:
                vals['calibrator'] =  ''
                # check for multiple calibrators
                for calintent in calintents:
#                    print("caldict[%s][%s] = %s" % (myvis,calintent,caldict[myvis][calintent]))
                    if type(caldict[myvis][calintent]) == list:
#                        print("there are multiple %s calibrators" % (calintent))
                        if vals['field'] in caldict[myvis][calintent]:
                            vals['calibrator'] = calintent[:4] + str(1+caldict[myvis][calintent].index(vals['field']))
                        elif vals['field'] in caldictFieldIDsStrings[myvis]:
                            print("Found %s as a field ID" % (vals['field']))
                            idx = caldictFieldIDsStrings[myvis].index(vals['field'])
                            vals['field'] = caldictNames[myvis][idx]
                            vals['calibrator'] = calintent[:4] + str(1+caldict[myvis][calintent].index(vals['field']))
                        else:
                            print("%s not in fieldID list: %s" % (vals['field'], caldictFieldIDsStrings[myvis]))
                    else:
                        print("caldict[vis][%s] = %s is not a list" % (calintent, caldict[myvis][calintent]))
                if vals['calibrator'] == '':
                    print("Could not map field=%s to an intent" % (vals['field']))
        valList.append(vals)
    # done 'for' loop over cmdlist
    return valList

def extractTimegaincalCommandsFromCasaCommandsLog(mylog='casa_commands.log', outfile='', overwrite=False, task='hifa_timegaincal'):
    """
    Reads a casa_commands.log file and returns a list of python strings
    that contain all the gaincal commands from hifa_timegaincal.
    mylog: either a casa_commands.log file or the path to a PL working directory
    task: pipeline task to use (will also work for hifa_gfluxscale and
          hifa_gfluxscaleflag)
    -Todd Hunter
    """
    if os.path.exists(outfile) and not overwrite:
        print("The output file exists: %s" % (outfile))
        return
    if os.path.isdir(mylog):
        mylog = findPipelineCasaCommandsLog(mylog)
        if not os.path.exists(mylog):
            print("Could not find %s in the current directory nor assuming this is the working directory" % (mylog))
            return
    if not os.path.exists(mylog):
        print("Could not find: ", mylog)
        return
    f = open(mylog,'r')
    lines = f.readlines()
    command = ''
    commands = []
    insideDesiredTask = False
    for line in lines:
        if line.find(task) >= 0:
            if task!='hifa_gfluxscale' or line.find('flag') < 0: 
                # avoid going into hifa_gfluxscaleflag from hifa_gfluxscale
                insideDesiredTask = True
        elif line.find('hif_applycal') >= 0 or (task=='hifa_gfluxscale' and line.find('hifa_timegaincal') >= 0) or (task=='hifa_gfluxscaleflag' and (line.find('gfluxscale(') >= 0 or line.find('polcalflag') >= 0)):
            break
        if insideDesiredTask:
            if command != '':
                if line.find(')') >= 0:
                    command += line
                    commands.append(command.replace('\n',''))
                    command = ''
                else:
                    command += line
            if line.find('gaincal(vis') >= 0:
                command += line
    if outfile != '':
        f = open(outfile,'w')
        for command in commands:
            f.write(command + '\n')
        f.close()
    return commands

def makeBriefCaltableName(caltable, task=''):
    """
    Creates a name like s13_3..solintinf.bcal  or s6_1.tsyscal
    task: if not specified, then parse it from the name, i.e., after '.ms.'
    """
    if task == '':
        task = caltable.split('.ms.')[1].split('.')[0]
    brief = 's' + caltable.split(task+'.s')[1].split('.')[0]
    if caltable.find('solint') > 0:
        brief += '..solint' + caltable.split('.solint')[1].split('.tbl')[0]    
    else:
        brief += '.' + caltable.split('.')[-2]
    return brief

def calLibraryCaltables(vis, brief=False, returnDict=False, debug=False):
    """
    Generates a list of caltables that appear in the final cal library, i.e. the
    one used by hif_applycal.
    """
    mydir = os.path.dirname(vis)
    libraries = []; stages = []
    searchpath = os.path.join(mydir,'*%s*.callibrary'%(os.path.basename(vis)))
#    print("searchpath = ", searchpath)
    allLibraries = glob.glob(searchpath)
    if len(allLibraries) < 1:
        if debug:
            print("No libraries found in ", searchpath)
        return
    if debug:
        print("Found %d cal libraries" % (len(allLibraries)))
    for i in sorted(allLibraries):
        stages.append(int(extractPipelineStage(i)))
        libraries.append(i)
    if debug:
        print("pipeline stages with cal libraries = ", stages)
    idx = np.argmax(stages)
    callibrary = libraries[idx]
    f = open(callibrary, 'r')
    lines = f.readlines()
    f.close()
    caltables = []
    mydict = {}
    for line in lines:
        loc = line.split("caltable='")
        if len(loc) > 1:
            mycaltable = loc[1].split("'")[0]
            if brief:
                caltables.append(makeBriefCaltableName(mycaltable))
            else:
                caltables.append(mycaltable)
            if caltables[-1] not in mydict:
                mydict[caltables[-1]] = []
            intentString = line.split("intent='")[1].split("'")[0]
            intents = intentString.split(',')
            for intent in intents:
                mydict[caltables[-1]].append(getPrimaryIntent(intent))
    # end 'for' line in lines
    if returnDict:
        return mydict
    else:
        return np.unique(caltables)

def compareCalLibraries(callib1, callib2=None, reverse=False, debug=False):
    """
    callib1: string containing a cal library filename
    callib2: string containing a cal library filename
    reverse: same effect as swapping the first two callib parameters
    if callib2 == None, then callib1 is considered a filename which contains:
           1) the first callibrary (possibly multiple lines)
           2) a blank line
           3) the second callibrary (possibly multiple lines)
    Returns: dictionary of parameters that differ, e.g. {'calwt_14': ['False','True']}
        where the _X means line X of the input file.
        Parameters that are missing from one table will appear as None for that table.
    -Todd Hunter
    """
    diff = {}
    buildString = ''
    if not os.path.exists(callib1):
        print("callib1 does not exist")
        return
    if reverse:
        swap = callib1[:]
        callib1 = callib2[:]
        callib2 = swap
    f = open(callib1, 'r')
    lines =  f.readlines()
    f.close()
    call1 = ''
    if callib2 is None:
        for line in lines:
            if line[0] == '#': continue
            if len(line) > 0 and line != '\n':
                if call2 is None:
                    call1 += line
                else:
                    call2 += line
            else:
                call2 = ''
                # now it will append to call2
        if debug:
            print("call1 = ", call1)
            print("call2 = ", call2)
    else:
        if not os.path.exists(callib2):
            print("callib2 file does not exist")
            return
        for line in lines:
            if line[0] == '#': continue
            if len(line) > 0 and line != '\n':
                call1 += line
        f = open(callib2, 'r')
        lines =  f.readlines()
        f.close()
        call2 = ''
        for line in lines:
            if line[0] == '#': continue
            if len(line) > 0 and line != '\n':
                call2 += line
    args1 = call1.split(' ')
    arg1 = {}
    buildingUp = False
    commaReplacement = '+'
    line = 0
    for arg in args1:
        if debug:
            print("Parsing arg1: %s." % (arg))
        if arg.strip() == '\\':
            continue
        if arg.find('=') > 0:
            parameter, value = arg.split('=')
            parameter = parameter.strip()
            if parameter == 'caltable':
                line += 1
            parameter_line = parameter+'_%d'%(line)
            arg1[parameter_line] = value.rstrip().rstrip(')')
            buildingUp = False
            buildString = value
        else:
            buildingUp = True
            buildString += ',' + arg.strip().rstrip(')')
            buildString = buildString.replace(',,',',')
            parameter_line = parameter+'_%d'%(line)
            if debug: print("buildString1 = ", buildString)
            # by the time we are done, this will be correct
            arg1[parameter_line] = buildString
    args2 = call2.split(' ')
    arg2 = {}
    buildingUp = False
    line = 0
    for arg in args2:
        if arg.strip() == '\\':
            continue
        if debug:
            print("Parsing arg2: %s." % (arg))
        if arg.find('=') > 0:
            parameter, value = arg.split('=')
            parameter = parameter.strip()
            if parameter == 'caltable':
                line += 1
            parameter_line = parameter+'_%d'%(line)
            arg2[parameter_line] = value.strip().rstrip(')')
            buildingUp = False
            buildString = value
        else:
            buildingUp = True
            buildString += ',' + arg.strip().rstrip(')')
            buildString = buildString.replace(',,',',')
            parameter_line = parameter+'_%d'%(line)
            if debug: print("buildString2[%s] = " % (parameter_line), buildString)
            # by the time we are done, this will be correct
            arg2[parameter_line] = buildString
    if debug:
        print("arg1 = ", arg1)
        print()
        print("arg2 = ", arg2)
    # Find values in arg2 that differ from arg1
    line = 0
    for parameter in list(arg2.keys()):
        value = arg2[parameter]
        if parameter.find('spwmap') >= 0 and debug:
            print("   %s-2: %s" % (parameter,value))
        if parameter in list(arg1):
            if arg1[parameter] != value:
                diff[parameter] = [arg1[parameter], arg2[parameter]]
        else:
            diff[parameter] = [None, value]
    line = 0
    for parameter in list(arg1):
        value = arg1[parameter]
        if parameter.find('spwmap') >= 0 and debug:
            print("   %s-1: %s" % (parameter,value))
        if parameter in list(arg2):
            if arg2[parameter] != value:
                diff[parameter] = [arg1[parameter], arg2[parameter]]
                if debug and parameter.find('spwmap') >= 0:
                    print("  diff:", diff[parameter])
        else:
            diff[parameter] = [value, None]
            
    return(diff)

def applySetjyToPipelineRestoration(workingdir, workingdirForCasaCommandsLog='', sso_only=False):
    """
    Finds the casa_commands.log, extracts the setjy commands, and runs them.
    You must have permission to write in the working directory.
    workingdir: directory containing the measurement set you want to fix
    workingdirForCasaCommandsLog: optionally different working directory that
      contains the casa_commands.log (in pipeline-XXXX/html)
    """
    if not os.path.exists(workingdir):
        print("Could not find path to workingdir")
        return
    if workingdirForCasaCommandsLog == '':
        workingdirForCasaCommandsLog = workingdir
    mylog = findPipelineCasaCommandsLog(workingdirForCasaCommandsLog)
    if mylog is None: return
    commands = extractSetJyCommandsFromCasaCommandsLog(mylog, sso_only=sso_only)
    cwd = os.getcwd()
    if not os.access(workingdir, os.W_OK):
        print("No write permission in workdingdir")
        return
    os.chdir(workingdir)
    for command in commands:
        print("Running: ", command)
        exec(command)
    os.chdir(cwd)

def applyQA0FlagsToCaltable(caltable, vis='', tbuff=0.002):
    """
    Reads the FLAG_CMD column from a measurement set, writes an ASCII text
    file using the flagcmd task, filters out the non-QA0 flags from the file, 
    and then applies it to a caltable using the flagdata task.
    -Todd Hunter
    """
    if (not os.path.exists(caltable)):
        print("Could not find caltable")
        return
    if (vis == ''):
        vis = getMeasurementSetFromCaltable(caltable)
    if (not os.path.exists(vis)):
        print("Could not find associated measurement set = ", vis)
        return
    flagtable = vis+'.flagcmd.txt'
    os.system('rm '+flagtable)
    flagcmd(vis, useapplied=True, action='list', savepars=True,
            outfile=flagtable, flagbackup=False)
    remaining = removeLines(flagtable, keys='QA0', negate=True)
    if (remaining > 0):
        flagdata(caltable, action='apply', inpfile=flagtable, 
                 flagbackup=False, tbuff=tbuff, mode='list')
    else:
        print("There were no QA0 flags in this dataset.")

def fluxcalScansFromASDM(asdm):
    """
    Returns a list of CALIBRATE_FLUX scans in an ASDM.
    -Todd Hunter
    """
    return atmcalScansFromASDM(asdm, 'FLUX')

def bandpasscalScansFromASDM(asdm):
    """
    Returns a list of CALIBRATE_BANDPASS scans in an ASDM.
    -Todd Hunter
    """
    return atmcalScansFromASDM(asdm, 'BANDPASS')

def atmcalScansFromASDM(asdm, intent='ATMOSPHERE', useMinidom=False):
    """
    Returns a list of atmospheric calibration scans in an ASDM.
    useMinidom: if True, then parse the .xml file even if the ASDM python
                bindings are available
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    -Todd Hunter
    """
    mydict = readscans(asdm, useMinidom=useMinidom)[0]
    scans = list(mydict.keys())
    calscans = []
    for scan in scans:
        if (mydict[scan]['intent'].find(intent) >= 0):
            calscans.append(scan)
    return(calscans)

def numberOfPolarizationsInSyscalXML(asdm, useMinidom=False):
    """
    Reports the number of polarizations in the SysCal.xml file of the
    specified ASDM.
    useMinidom: if True, then parse the .xml file even if the ASDM python
            bindings are available; This option only works for very old ALMA 
            data when SysCal.xml contained all the data instead of SysCal.bin
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    -Todd Hunter
    """
    if os.path.exists(asdm+'/SysCal.xml'):
        mydict = getTsysFromSysCal(asdm, useMinidom=useMinidom)
        if mydict is None:
            return
        spws = list(mydict[0].keys())
        scans = list(mydict[0][spws[0]]['scans'].keys())
        npol = len(list(mydict[0][spws[0]]['scans'][scans[0]].keys()))
    else:
        print("SysCal.xml does not exist.  Assuming 2 polarizations.")
        npol = 2
    return npol

def numberOfPolarizationsInSyscalTable(vis):
    """
    Reports the number of polarizations in the SYSCAL table of the
    specified measurement set.
    -Todd Hunter
    """
    if (not os.path.exists(vis)):
        print("Could not find measurement set: ", vis)
        return
    mytb = createCasaTool(tbtool)
    syscal = vis
    if (vis.find('SYSCAL') < 0):
        syscal += '/SYSCAL'
    mytb.open(syscal)
    n = len(mytb.getcell('TSYS_SPECTRUM',0))
    mytb.close()
    return n

def qa0flags(dataset, verbose=False, flags=['AFD','PFD'],
             listThresholdMinutes='half', autoExport=True, useMinidom=False):
    """
    Summarizes the number of QA0 flags of different types in a measurement set.
    dataset: ASDM or measurement set
    verbose: if True, then print all of them to the screen, first.
    listThresholdMinutes: value in minutes, or 'half' for half the length of the dataset
    flags: restrict flags to show to those with names containing these strings
           (if verbose==True)
    useMinidom: if True, then parse the .xml file even if the ASDM python
                bindings are available
    Set ASDM_LIBRARY_PATH in ~/.casa/startup.py to point to ASDM python bindings
    Todd Hunter
    """
    if (not os.path.exists(dataset)):
        if autoExport:
            asdmExport(dataset,'-m')
            if (not os.path.exists(dataset)):
                print("Could not export dataset from archive.")
                return
        else:
            print("Could not find dataset on disk.")
            return
    if (not os.path.exists(dataset+'/Flag.xml')):  # measurement set
        if (not os.path.exists(dataset+'/table.dat')):
            print("This does not appear to be an ASDM nor a measurement set.")
            return
        mytb = createCasaTool(tbtool)
        mytb.open(dataset+'/FLAG_CMD')
        commands = mytb.getcol('COMMAND')
        reasons = mytb.getcol('REASON')
        mymsmd = createCasaTool(msmdtool)
        mymsmd.open(dataset)
        allPossibleAntennas = mymsmd.antennanames()
        calscans = len(mymsmd.scansforintent('*ATMOSPHERE*'))
        npol = numberOfPolarizationsInSyscalTable(dataset)
        if npol is None:
            # assume it is 2
            npol = 2
        calscans *= npol
        mymsmd.close()
    else:  # ASDM
        totalAntennas = len(readAntennasFromASDM(dataset, verbose=False, useMinidom=useMinidom))
        if not asdmLibraryAvailable or useMinidom:
            import au_noASDMLibrary
            reasons, commandsInt, tsys, trx, tsysAntennas, tsysBasebands, tsysPols, trxAntennas, trxBasebands, trxPols = au_noASDMLibrary.qa0flags_minidom(dataset)
            durations = []; commands = []
            for cmd in commandsInt:
                startTime = mjdNanosecondsToMJDandUT(cmd[0],prec=9,delimiter='/')[1].rstrip(' UT')
                endTime = mjdNanosecondsToMJDandUT(cmd[1],prec=9,delimiter='/')[1].rstrip(' UT')
                durations.append(dateStringDifference(startTime, endTime))
                commands.append('~'.join([startTime,endTime]))
        else:
            a = ASDM()
            parser = ASDMParseOptions()
            parser.asALMA()
            parser.loadTablesOnDemand(True)
            a.setFromFile(dataset,parser)
            flagTable = a.flagTable().get()
            reasons = []; commands = []; durations = []
            tsys = 0; trx = 0
            tsysAntennas = []; tsysBasebands = []; tsysPols = []
            trxAntennas = []; trxBasebands = []; trxPols = []
            for i,row in enumerate(flagTable):
                start = row.startTime().get()
                end = row.endTime().get()
                reason = row.reason().strip()
                reasons.append(reason.replace(' ','_'))
                if reasons[i].find('AFD05') > 0:
                    if reasons[i].find('TSYS') > 0:
                        tsys += 1
                        tsysAntennas.append(reasons[i].split('Ant_')[1].split('_')[0])
                        tsysBasebands.append(int(reasons[i].split('(BB_')[1].split(')')[0]))
                        tsysPols.append(reasons[i].split('_Pol_')[1].split('_')[0])
                    elif reasons[i].find('TRX') > 0:
                        trx += 1
                        trxAntennas.append(reasons[i].split('Ant_')[1].split('_')[0])
                        trxBasebands.append(int(reasons[i].split('(BB_')[1].split(')')[0]))
                        trxPols.append(reasons[i].split('_Pol_')[1].split('_')[0])
                startTime = mjdNanosecondsToMJDandUT(start)[1]
                endTime = mjdNanosecondsToMJDandUT(end)[1]
                commands.append(startTime + '~' + endTime)
                durations.append(dateStringDifference(startTime, endTime))
        reasons = np.array(reasons)
        calscans = len(atmcalScansFromASDM(dataset, useMinidom=useMinidom))  # binary-ready
        minutes = np.array(durations)
        if listThresholdMinutes == 'half':
            listThresholdMinutes = 0.5*getObservationLengthFromASDM(dataset, useMinidom) # binary-ready
        idxThreshold = np.where(minutes >= listThresholdMinutes)[0]
        idx = np.argsort(minutes)[::-1]
        if (len(idxThreshold) < 1):
            print("Longest flag = %g minutes (row %d: %s)" % (minutes[idx[0]],idx[0],reasons[idx[0]]))
            print("Shortest flag = %g minutes (row %d: %s)" % (minutes[idx[-1]],idx[-1],reasons[idx[-1]]))
        else:
            tsysAntennas = np.unique(tsysAntennas)
            trxAntennas = np.unique(trxAntennas)
            tsysBasebands = np.unique(tsysBasebands)
            trxBasebands = np.unique(trxBasebands)
            tsysPols = np.unique(tsysPols)
            trxPols = np.unique(trxPols)
            print("Num. of long Tsys flags: %d, unique antennas: %d/%d, basebands: %s %s" % (tsys,len(tsysAntennas),totalAntennas,tsysBasebands,tsysPols))
            print("Num. of long Trx  flags: %d, unique antennas: %d/%d, basebands: %s %s" % (trx,len(trxAntennas),totalAntennas,trxBasebands,trxPols))
        npol = numberOfPolarizationsInSyscalXML(dataset)
        if npol is None:  # assume it is 2
            npol = 2
        calscans *= npol
        allPossibleAntennas = readAntennasFromASDM(dataset, verbose=False, useMinidom=useMinidom) # binary-ready
    printQA0Flags(reasons, allPossibleAntennas, verbose, flags, commands, 
                  calscans)

def fixPythonScript(script, keeponly=['setjy']):
    """
    If a line does not end in a comma, then truncate at the prior comma,
    and insert the remainder on the next line.
    keeponly:  if set, then only keep the command calls in this list
    -Todd Hunter
    """
    f = open(script,'r')
    lines = f.readlines()
    f.close()
    f = open(script.replace('.py','_fixed.py'), 'w')
    removeSpaces = False
    skipToNextCommand = False
    for line in lines:
        if keeponly != '':
            if skipToNextCommand:
                if (line.find(')') >= 0):
                    skipToNextCommand = False
                continue
            elif (line.find('(') >= 0):
                command = line.lstrip().split('(')[0]
                if command not in keeponly:
                    skipToNextCommand = True
                    continue
        if (len(line) < 2):
            f.write(line)
        elif (line[-2] != ',' and line[-2] != ')'):
            print("Offending line: ", line)
            tokens = line.split(",")
            finalToken = tokens[-1]
            f.write(line.split(finalToken)[0] + '\n')
            f.write(finalToken[:-1])
            removeSpaces = True
        else:
            if removeSpaces:
                line = line.lstrip()
            f.write(line)
            removeSpaces = False
    f.close()

def filterOutLines(filename, string):
    """
    Remove lines from a file that match a specified string.
    Does not attempt to make a backup, so please beware.  If you want
    that capability, see au.removeLines
    -Todd Hunter
    """
    import fileinput
    filtered = 0
    for line in fileinput.input(r'%s'%(filename), inplace=True):
        if not re.search(r'\b%s\b'%(string),line):
#            print(line, end=' ')
            print(line, end='')
        else:
            filtered += 1
    print("Removed %d lines" % (filtered))

def removeLines(filename, keys=['QA0','HIGH_RMS','HIGHER'], negate=False):
    """
    Remove the lines of an ASCII file that contain a specified string, or any
    string from a list of strings.  The original file is first copied to *.bak.
    keys: a single string, or a list of strings
    negate: if True, then remove lines that do NOT have these strings
    Returns: the number of lines remaining
    """
    if (not os.path.exists(filename)):
        print("Could not find file = ", filename)
        return
    shutil.copyfile(filename, filename+'.bak')
    f = open(filename,'r')
    lines = f.readlines()
    f.close()
    f = open(filename,'w')
    removed = 0
    if (type(keys) != list):
        keys = [keys]
    for line in lines:
        found = False
        for key in keys:
            if (line.find(key) >= 0):
                found = True
                break
        if negate:
            if found:
                f.write(line)
            else:
                removed += 1
        else:
            if found:
                removed += 1
            else:
                f.write(line)
    f.close()
    print("Removed %d lines" % (removed))
    remaining = len(lines) - removed
    print("Remember to change the flagcmd in your script to: inpmode='list', inpfile='%s'" % (filename))
    return(remaining)

def pruneFilelist(filelist):
    """
    Reduce size of filenames in filelist to the extent that current working
    directory agrees with the path.  Remove any empty strings.
    """
    mypwd = os.getcwd() + '/'
    newfilelist = []
    for f in filelist:
        f = f.replace('//','/')
        fstart = 0
        if (f.find(mypwd) == 0):
            fstart = len(mypwd)
        if len(f[fstart:]) > 0:
            newfilelist.append(f[fstart:])
    return(newfilelist)
    
def concatenatePDFs(filelist, pdfname, pdftk='pdftk', gs='gs', cleanup=False,
                    quiet=False, papersize='', writeCommand=False):
    """
    Takes a list or a string list of PDF filenames (space-delimited), and an
    output name, and concatenates them.
    filelist: a python list of strings, a comma-delimited string, or a wildcard string
    (wildcard names will be sorted by name)
    It first tries pdftk (better quality), and if that fails, it tries
    ghostscript (more commonly installed).
    Todd Hunter
    """
    if type(filelist in [str,np.bytes_]):
        if filelist.find('*') >= 0:
            print("Sorting by name")
            filelist = sorted(glob.glob(filelist))
        else:
            filelist = filelist.split(',')
    if (type(filelist) == list):
        filelist = ' '.join(filelist)

    cmd = '%s %s cat output %s' % (pdftk, filelist, pdfname)
    concatScript = pdfname+'_concatenate.sh'
    if writeCommand:
        f = open(concatScript,'w')
        f.write('#!/bin/sh\n')
        f.write(cmd+'\n')
        f.close()
        os.system('chmod +x %s'%concatScript)
    cmds = [cmd]
    pipeCharacterLimit = 131072
    if (len(cmd) >= pipeCharacterLimit): # character limit in linux pipe
        print("Command string argument too long (%d>%d), splitting into multiple commands." % (len(cmd),pipeCharacterLimit))
        filelist = filelist.split()
        splitCounter = 2
        chunk = int(round(len(filelist)/float(splitCounter)))
        myfilelist = [' '.join(filelist[:chunk]), ' '.join(filelist[chunk:])]
        nfiles = [len(filelist[:chunk]), len(filelist[chunk:])]
        withinBounds = True
        for i in range(splitCounter):
            if len(myfilelist[i]) +len(pdftk)+18 > pipeCharacterLimit:
                withinBounds = False
        while not withinBounds:
            splitCounter += 1
            chunk = int(round(len(filelist)/float(splitCounter)))
            myfilelist = []
            nfiles = []
            for i in range(splitCounter):
                if i < splitCounter-1:
                    myfilelist += [' '.join(filelist[i*chunk:(i+1)*chunk])]
                    nfiles += [len(filelist[i*chunk:(i+1)*chunk])]
                else:
                    # final one might not be as long as the rest
                    myfilelist += [' '.join(filelist[i*chunk:])]
                    nfiles += [len(filelist[i*chunk:])]
            withinBounds = True
            for i in range(splitCounter):
                if len(myfilelist[i]) +len(pdftk)+18 > pipeCharacterLimit:
                    withinBounds = False
        cmds = []
        finalConcat = ''
        for j in range(len(myfilelist)):
            cmds += ['%s %s cat output %d.pdf' % (pdftk, myfilelist[j], j)]
            print("Command %d has %d files (%d chars)" % (j, nfiles[j], len(cmds[j])))
            finalConcat += '%d.pdf ' % (j)
            if len(cmds[j]) > pipeCharacterLimit:
                print("Command string argument still too long (%d), need to modify au.concatenatePDFs to split job further." % (len(cmds[j])))
                return(-1)
        cmds += ['%s %s cat output %s' % (pdftk, finalConcat, pdfname)]
    mystatus = 0
    if writeCommand:
        f = open(concatScript,'w')
        f.write('#!/bin/sh\n')
    for i,mycmd in enumerate(cmds):
        if writeCommand:
            f.write(mycmd+'\n')
        if not quiet: 
            print("Running command = %s (%d of %d)" % (mycmd,i+1,len(cmds)))
        mystatus += os.system(mycmd)
        if (i+1 == len(cmds) and i>0):
            for j in range(len(myfilelist)):
                if os.path.exists('%d.pdf'%j): os.remove('%d.pdf'%j)
    if writeCommand:
        f.close()
        os.system('chmod +x %s'%concatScript)
    if (mystatus != 0):
        # Try a different directory - this doesn't have the generic length solution yet.
        pdftk = '/opt/local/bin/pdftk'
        cmd = '%s %s cat output %s' % (pdftk, filelist, pdfname)
        cmds = [cmd]
        if (len(cmd) >= 131072): # character limit in linux pipe
            print("Command string argument too long (%d), splitting into two commands." % (len(cmd)))
            filelist0 = ' '.join(filelist[:len(filelist)//2])
            filelist1 = ' '.join(filelist[len(filelist)//2:])
            cmds  = ['%s %s cat output 0.pdf' % (pdftk, filelist0)]
            cmds += ['%s %s cat output 1.pdf' % (pdftk, filelist1)]
            cmds += ['%s 0.pdf 1.pdf cat output %s' % (pdftk, pdfname)]
        mystatus = 0
        for i,cmd in enumerate(cmds):
            if not quiet: print("Running command = %s (%d of %d)" % (cmd, i+1, len(cmds)))
            mystatus += os.system(cmd)
            if (i+1 == len(cmds) and i>0):
                if os.path.exists('0.pdf'): os.remove('0.pdf')
                if os.path.exists('1.pdf'): os.remove('1.pdf')
        if (mystatus != 0):
            if (gs == ''):
                print("Since os.system(%d chars) failed, trying to run from script: " % (len(cmd)), concatScript)
                os.system('./'+concatScript)
                if os.path.exists(pdfname):
                    print("Success, setting mystatus=0")
                    mystatus = 0
            else:
                if (papersize != ''):
                    papersize = '-sPAPERSIZE='+papersize
                print("status = ", mystatus)
                cmd = '%s -q %s -dNOPAUSE -dBATCH -sDEVICE=pdfwrite -sOutputFile=%s %s' % (gs,papersize,pdfname,filelist)
                print("Running command = %s" % (cmd))
                mystatus = os.system(cmd)
                if (mystatus != 0):
                    gs = '/opt/local/bin/gs'
                    cmd = '%s -q %s -dNOPAUSE -dBATCH -sDEVICE=pdfwrite -sOutputFile=%s %s' % (gs,papersize,pdfname,filelist)
                    print("Running command = %s" % (cmd))
                    mystatus = os.system(cmd)
                    if (mystatus != 0):
                        print("concatenatePDFs(): Both pdftk and gs are missing, no PDF created.")
                        cleanup = False
    if (cleanup):
        os.system('rm %s' % filelist)
    return (mystatus)

def fixWeblogPermissions(mydir):
    """
    Sets directories to chmod 755 and files to chmod 644.
    See also fixvisPermissions to operate on a single MeasurementSet.
    -Todd Hunter
    """
    cmd = r'find %s -type d -exec chmod 755 {} \;' % (mydir)
    print("Running: ", cmd)
    os.system(cmd)
    cmd = r'find %s -type f -exec chmod 644 {} \;' % (mydir)
    print("Running: ", cmd)
    os.system(cmd)

def fixvisPermissions(vis, write=False, dryrun=False):
    """
    Adds read+execute permission to all subdirectories of a measurement set
    for all users (owner, group, other).  See also fixWeblogPermissions.
    write: if True, then add write permission as well (e.g. 'drwxrwxrwx')
    dryrun: if True, then only list the commands, do not run them
    -Todd Hunter
    """
    files = glob.glob(vis+'/*')
    for f in files:
        if os.path.isdir(f):
            if write:
                cmd = 'chmod +rx %s' % (f)
            else:
                cmd = 'chmod +rwx %s' % (f)
            print(cmd)
            if not dryrun:
                os.system(cmd)

def plotSomeBaselines(vis, spw, antenna, scan='', intent='*BANDPASS*', yaxis='amp', xaxis='time', 
                      ydatacolumn='data', avgchannel='8000', coloraxis='corr', plotfile='', 
                      pdfname='', overwrite=True):
    """
    Plots a list of baselines with one baseline per output png.
    antenna: should be a list of baselines:  'DA55&DA56;DA47&DA43', will be split on ;
    """
    baselines = antenna.split(';')
    pngs = []
    for baseline in baselines:
        if plotfile == '':
            myplotfile = vis+'_%s.png' % (baseline)
        elif (plotfile.find('.png') >= 0):
            myplotfile = plotfile.replace('.png','_%s.png'%baseline)
        else:
            myplotfile += '_%s.png'%baseline
        plotms(vis, spw=spw, antenna=baseline, scan=scan, intent=intent, xaxis=xaxis, yaxis=yaxis,
               ydatacolumn=ydatacolumn, avgchannel=avgchannel, coloraxis=coloraxis, plotfile=myplotfile, 
               showgui=False, overwrite=overwrite, title=vis+' spw%s %s' % (spw,baseline))
        pngs.append(myplotfile)
    if pdfname == '':
        pdfname = vis+'.pdf'
    buildPdfFromPngs(pngs, pdfname=pdfname)
    print("Wrote ", pdfname)
                      
def plotBaselinesOneScan(vis, spw, scan, xaxis='time', yaxis='phase', 
                         correlation='', iteraxis='spw',coloraxis='corr',
                         plotrange=[0,0,0,0], pdfname='', antenna='',
                         debug=False, customflaggedsymbol=False,title='',
                         flaggedsymbolshape='nosymbol', avgchannel='10000',
                         xsharedaxis=False, ysharedaxis=False,showgui=False,
                         repeatBaselines=False, onlybuildpdf=False,
                         dropAntennas=[], overwritePdfs=True,gs='gs',gridcols=1,
                         avgtime='', antennaBased=False, maxAntennas=0):
    """
    A convenient wrapper for plotms to show all specified spws on a grid
    on one page (per baseline).
    antenna: a list of antenna names to include (default = all)
    repeatBaselines: if True, then show each baseline twice, in order in the
          list for both component antennas
    onlybuildpdf: if True, then assume that all the pngs already exist
           and so do not run plotms
    dropAntennas: do not display any baselines for these antennas
    overwritePdfs: overwrite single-page PDFs (passed to buildPdfFromPngs)
    antennaBased: if True, then only generate one plot per antenna
    gridcols: ignored if antennaBased==True, it is then calculated automatically
    iteraxis: ignored if antennaBased==True, it is set to blank
    -Todd Hunter
    """
    if (not os.path.exists(vis)):
        print("Could not open measurement set")
        return
    overwrite = True
    mymsmd = createCasaTool(msmdtool)
    mymsmd.open(vis)
    allAntennaNames = mymsmd.antennanames()
    if (antenna == '' or antenna == '*&*'):
        antennaNames = allAntennaNames
    else:
        antennaNames = antenna.split(',')
    pngs = []
    if (type(spw) == list):
        spwlist = spw
        spw = ','.join(spwlist)
    elif (type(spw) == str):
        spwlist = [int(i) for i in spw.split(',')]
    else:
        print("spw must be a comma-delimited string or an integer list")
        return
    nspw = len(spwlist)
    basebands = []
    for myspw in spwlist:
        basebands.append(mymsmd.baseband(myspw))
    mymsmd.close()
    if antennaBased:
        nAntennas = len(antennaNames)
        if maxAntennas > 0:
            nAntennas = maxAntennas
            antennaNames = antennaNames[:maxAntennas]
        gridcols = np.floor(np.sqrt(nAntennas))
        gridrows = int(np.ceil(nAntennas/gridcols))
        gridcols = int(gridcols)
        iteraxis = ''
        print("Plotting %d antennas on one page." % (len(antennaNames)))
    else:
        gridrows = int(np.ceil(1.0*nspw/gridcols))
        print("Plotting %d spws on one page per baseline. Set antennaBased=True to plot 1 spw with all antennas on one page." % (nspw))
    plotindex = -1
    colindex = -1
    rowindex = 0
    for i,a1 in enumerate(allAntennaNames):
        if (a1 in antennaNames):
            if (repeatBaselines or antenna != ''):
                j = 0
            else:
                j = i+1
            if antennaBased:
                plotindex += 1 
                colindex += 1
                if colindex >= gridcols:
                    colindex = 0
                    rowindex += 1
                iterAntenna = '*'
                plotfile = vis + '.scan%s.png' % (str(scan))
                clearplots = False
                if plotfile not in pngs:
                    pngs.append(plotfile)
            else:
                plotindex = 0
                rowindex = 0
                plotindex = 0
                clearplots = True
                iterAntenna = allAntennaNames[j:]
            for a2 in iterAntenna:
                if (a2 != a1 and a1 not in dropAntennas and a2 not in dropAntennas):
                    if not antennaBased:
                        plotfile = vis + '.%s_%s.png' % (a1,a2)
                        fullplotfile = plotfile.replace('.png','_Spw%s.png'%spw)
                        if fullplotfile not in pngs:
                            pngs.append(fullplotfile)
                    if (not onlybuildpdf):
                        title = a1 + ' & ' + a2
                        if (a2 != '*'):
                            baselineLength = getBaselineLength(vis,a1,a2,verbose=False)[0]
                            title += ' (%dm)'% (int(np.round(baselineLength)))
                        print("Running plotms(vis='%s',spw='%s',xaxis='%s',yaxis='%s',correlation='%s',antenna='%s&%s',gridrows=%d,gridcols=%d,plotrange=%s,title='%s',xsharedaxis=%s,ysharedaxis=%s,scan='%s',coloraxis='%s',plotfile='%s',iteraxis='%s',overwrite=%s,showgui=%s,flaggedsymbolshape='%s',avgchannel='%s',avgtime='%s',clearplots=%s,plotindex=%d,rowindex=%d,colindex=%d)" % (vis,spw,xaxis,yaxis,correlation,a1,a2,gridrows,gridcols,plotrange,title,xsharedaxis,ysharedaxis,str(scan),coloraxis,plotfile,iteraxis,overwrite,showgui,flaggedsymbolshape,avgchannel,avgtime,clearplots or i==0,plotindex,rowindex,colindex))
                        plotms(vis=vis, spw=spw, xaxis=xaxis, yaxis=yaxis, correlation=correlation,
                           antenna='%s&%s'%(a1,a2), gridrows=gridrows, gridcols=gridcols, plotrange=plotrange,
                           title=title, xsharedaxis=xsharedaxis, ysharedaxis=ysharedaxis,
                           scan=str(scan), coloraxis=coloraxis,
                           plotfile=plotfile, customflaggedsymbol=customflaggedsymbol,
                           iteraxis=iteraxis, overwrite=overwrite, showgui=showgui,
                           flaggedsymbolshape=flaggedsymbolshape, avgchannel=avgchannel, 
                               avgtime=avgtime, clearplots=clearplots or i==0, plotindex=plotindex,
                               rowindex=rowindex, colindex=colindex)
        else:
            print("%s not in %s" % (a1, antennaNames))
    if (len(pngs) > 0):
        if (pdfname == ''):
            pdfname = vis + '.phase_vs_time.pdf'
        buildPdfFromPngs(pngs, pdfname=pdfname, overwritePdfs=overwritePdfs, gs=gs)

def plotBaselinesSorted(vis, plotfile, spw, scan='',xaxis='freq',yaxis='phase', 
                        correlation='XX', antenna='0&*', title='', 
                        iteraxis='baseline',overwrite=True,avgtime='1e8',avgscan=False,
                        plotrange=[0,0,-180,180], pdfname='', maxrows=4,
                        field='',debug=False,customflaggedsymbol=False,showgui=False,
                        coloraxis='', flaggedsymbolshape='nosymbol', avgchannel='',
                        maxpages=-1, maxplots=-1, sort=True, overwritePdfs=True,
                        projected=True,ydatacolumn='',exportTextFiles=False,
                        fitPhaseVsFrequency=False):
    """
    Runs plotms for every baseline, sorts by baseline and compiles into
    a PDF.
    antenna: ID; if set to '', then all baselines will be plotted
    overwrite: if True, then re-create an image if it already exists
    maxplots: maximum number of PNGs to create
    maxpages: maximum number of pages in the PDF to produce
    sort: if True, then sort by baseline length
    field: the field parameter to pass to plotms (string name or ID)
    projected: if True, then use the projected baseline length of the
               (first) specified field
    exportTextFiles: if True, then also export the plots to text files
    -Todd Hunter
    """
    if (not os.path.exists(vis)):
        print("Could not find measurement set: ", vis)
        return
    if (projected and field == ''):
        print("With option projected=True, you must specify a field.")
        return
    originalAntenna = antenna
    originalPlotfile = plotfile
    mymsmd = createCasaTool(msmdtool)
    mymsmd.open(vis)
    allAntennas = mymsmd.antennaids()
    antennanames = mymsmd.antennanames(allAntennas)
    mymsmd.close()
    if antenna == '':
        antennaList = allAntennas
    else:
        if (type(antenna) == str):
            if (antenna == '*&*'):
                antennaList = allAntennas
            else:  # assume '3&*'
                antennaList = parseAntenna(vis,antenna.split('&')[0])
        elif (type(antenna) == list):
            antennaList = antenna
        else:
            antennaList = [int(antenna)]
    pngs = []
    print("antennaList = ", antennaList)
    baselineLengths = []
    if (type(scan) == list):
        scans = ','.join([str(i) for i in scan])
    else:
        scans = str(scan)
    if (type(field) != str):
        field = str(field)
    if (projected):
        mydict = getBaselineLengths(vis, field=field.split(',')[0])
    firstCommand = True
    avgchannel = str(avgchannel)
    if (fitPhaseVsFrequency):
        os.system('rm *.txt')
    for n,i in enumerate(antennaList):
        print("Starting antenna %s (%d of %d)" % (antennanames[i], n+1, len(antennaList)))
        for j in allAntennas:
            if (i == j): continue
            if (len(antennaList) == len(allAntennas) and j<i): continue
            ant = '%02d&%02d' % (i,j)
            antname = '%s_with_%s' % (antennanames[i], antennanames[j])
            if (projected):
                ants = sorted([antennanames[i],antennanames[j]])
                baselineName = '%s-%s' % (ants[0], ants[1])
                if debug:
                    print("baselineName = ", baselineName)
                    print("np.where() = ", np.where(np.array(mydict)[:,0] == baselineName))
                baselineLengths.append(mydict[np.where(np.array(mydict)[:,0] == baselineName)[0]][1])
            else:
                baselineLengths.append(getBaselineLength(vis, i, j, verbose=False)[0])
            title = antname + ' (%.0fm)' % (baselineLengths[-1])
            plotfile = originalPlotfile.replace('.png','_%s_%.0f.png' % (antname,baselineLengths[-1]))
            if (correlation != ''):
                title += ' %s pol' % correlation
            if (not os.path.exists(plotfile) or overwrite):
                if (debug or firstCommand):
                    print("Running plotms('%s', spw='%s', xaxis='%s', yaxis='%s', correlation='%s', antenna='%s', plotrange=%s, title='%s', scan='%s', plotfile='%s', field='%s', customflaggedsymbol=%s, overwrite=%s, showgui=%s, flaggedsymbolshape='%s', avgchannel='%s', coloraxis='%s', ydatacolumn='%s', avgtime='%s', avgscan=%s)" % (vis, str(spw), xaxis, yaxis, correlation, ant, str(plotrange), title, scans, plotfile, field, customflaggedsymbol, overwrite, showgui, flaggedsymbolshape, avgchannel, coloraxis, ydatacolumn,avgtime,avgscan))
                    firstCommand = False
                plotms(vis, spw=str(spw), xaxis=xaxis, yaxis=yaxis, 
                       correlation=correlation, antenna=ant, coloraxis=coloraxis,
                       plotrange=plotrange, title=title, scan=scans,
                       plotfile=plotfile, field=field, customflaggedsymbol=customflaggedsymbol,
                       overwrite=overwrite, showgui=showgui, ydatacolumn=ydatacolumn,
                       flaggedsymbolshape=flaggedsymbolshape, avgchannel=avgchannel,
                       avgtime=avgtime,avgscan=avgscan)
            if (exportTextFiles or fitPhaseVsFrequency):
                textfile = plotfile.replace('.png','.txt') 
                if (not os.path.exists(textfile) or overwrite):
                    plotms(vis, spw=str(spw), xaxis=xaxis, yaxis=yaxis, 
                           correlation=correlation, antenna=ant, coloraxis=coloraxis,
                           plotrange=plotrange, title=title, scan=scans,
                           plotfile=textfile,
                           field=field, customflaggedsymbol=customflaggedsymbol,
                           overwrite=overwrite, showgui=showgui, ydatacolumn=ydatacolumn,
                           flaggedsymbolshape=flaggedsymbolshape, avgchannel=avgchannel,
                           avgtime=avgtime,avgscan=avgscan)
            if (os.path.exists(plotfile)):
                pngs.append(plotfile)    
                if (maxplots > 0 and len(pngs) == maxplots):
                    break
            else:
                print("No plot created for %s.  Are all data flagged?" % (antname))
        if (maxplots > 0 and len(pngs) == maxplots):
            break
    if (pdfname == ''):
        if originalAntenna != '':
            if (type(antenna) == str):
                antennaArg = antenna.replace('*','All').replace('&','with')
            else:
                antennaArg = antennanames[antenna]+'withAll'
            if (maxpages < 0):
                pdfname = vis+'.%s.scan%s.baselines_%ss.pdf' % (antennaArg,scan,yaxis)
            else:
                pdfname = vis+'.%s.scan%s.baselines_%ss.%dpages.pdf' % (antennaArg,scan,yaxis,maxpages)
        else:
            pdfname = vis+'.scan%s.baseline_%ss.pdf' % (scan,yaxis)
    if (len(pngs) > 0):
        pngs = np.array(pngs)
        if (sort):
            pngs = pngs[np.argsort(baselineLengths)]
        if (len(pngs) >= maxpages and maxpages > 0):
            pngs = pngs[:maxpages]
        buildPdfFromPngs(pngs, pdfname=pdfname, overwritePdfs=overwritePdfs)
    if (fitPhaseVsFrequency):
        print("Fitting txt files for phase vs. frequency")
        png = linfitFromFiles('*.txt', title=vis)
        print("Plot left in ", png)
            
def plotBaselinesPerScan(vis, spw, scan=[], xaxis='freq', yaxis='phase', 
                         correlation='XX', antenna='0&*', gridrows=None,
                         gridcols=None, iteraxis='baseline',
                         plotrange=[0,0,-180,180], pdfname='', maxrows=4,
                         field='',allscansTogether=False, debug=False,
                         customflaggedsymbol=False, coloraxis='',
                         flaggedsymbolshape='nosymbol', avgchannel='',
                         xsharedaxis=False, ysharedaxis=False,showgui=False,
                         avgtime=''):
    """
    A convenient wrapper for plotms to show all baselines to a given antenna
    on one page.  
    scan: if more than one, it builds a multi-page pdf of one scan at a time
    allscansTogether: if True, then overlay all scans specified in the scan list
    antenna:  if '', then make build a multi-page pdf with each antenna on 
              successive pages
    -Todd Hunter
    """
    if (not os.path.exists(vis)):
        print("Could not open measurement set")
        return
    overwrite = True
    mymsmd = createCasaTool(msmdtool)
    mymsmd.open(vis)
    nantennas = mymsmd.nantennas()
    antennaNames = mymsmd.antennanames()
    scannumbers = callscannumbers(mymsmd)
    if (scan == []):
        scans = scannumbers
    elif (type(scan) != list and type(scan) != np.ndarray and type(scan) != str):
        scans = [int(scan)]
    elif (type(scan) == str):
        if (scan.find('~') >= 0):
            scans = scan.split('~')
            if (scans[1] != ''):
                scans = range(int(scans[0]), int(scans[1])+1)
            else:
                scans = range(int(scans[0]), scannumbers[-1])
        else:
            scans = [int(i) for i in scan.split(',')]
    else:
        scans = scan
    mymsmd.close()
    if (gridrows==None):
        gridrows = int(pb.sqrt(nantennas))
        if (gridrows > maxrows):
            gridrows = maxrows
        gridcols = int(np.ceil(nantennas / gridrows))
    pngs = []
    originalAntenna = antenna
    if (allscansTogether):
        scans = [','.join([str(s) for s in scans])]
    for s in scans:
        if (antenna == ''):
            antennas = [i+'&*' for i in antennaNames]
        else:
            antennas = [antenna]
        for i,antenna in enumerate(antennas):
            if debug:
                print("plotting antenna='%s', scan=%s" % (antenna,str(s)))
            antennaArg = antenna.replace('*','All').replace('&','with')
            if (allscansTogether):
                scantext = 'all'
                title = 'all scans'
            else:
                scantext = str(s)
                title = 'Scan '+str(s)
            plotfile = vis + '.%s.scan%s.baseline_%ss.png' % (antennaArg,scantext,yaxis)
            if debug:
                print("Running plotms(vis='%s', spw='%s', xaxis='%s', yaxis='%s', correlation='%s', antenna='%s', \\" % (vis,str(spw),xaxis,yaxis,correlation,antenna))
                print("   gridrows=%d, gridcols=%d, plotrange=%s, title='%s', \\" % (gridrows, gridcols,str(plotrange), title))
                print("   xsharedaxis=%s, ysharedaxis=%s, scan='%s', plotfile='%s', \\" % (xsharedaxis, ysharedaxis, str(s), plotfile))
                print("   field='%s', customflaggedsymbol=%s, iteraxis='%s', overwrite=%s, \\" % (field,customflaggedsymbol, iteraxis, overwrite))
                print("   showgui=%s, flaggedsymbolshape='%s', avgchannel='%s', coloraxis='%s', avgtime='%s')" % (showgui,flaggedsymbolshape,avgchannel,coloraxis,avgtime))
            plotms(vis=vis, spw=str(spw), xaxis=xaxis, yaxis=yaxis, correlation=correlation,
               antenna=antenna, gridrows=gridrows, gridcols=gridcols, plotrange=plotrange,
                   title=title, xsharedaxis=xsharedaxis, ysharedaxis=ysharedaxis,
                   scan=str(s), coloraxis=coloraxis,
                   plotfile=plotfile, field=field,customflaggedsymbol=customflaggedsymbol,
                   iteraxis=iteraxis, overwrite=overwrite, showgui=showgui,
                   flaggedsymbolshape=flaggedsymbolshape, avgchannel=avgchannel, avgtime=avgtime)
            pngs.append(plotfile)
    if pdfname == '':
        if originalAntenna != '':
            pdfname = vis+'.%s.scan%s.baselines_%ss.pdf' % (antennaArg,scan,yaxis)
        else:
            pdfname = vis+'.scan%s.baseline_%ss.pdf' % (scan,yaxis)
    if (len(pngs) > 0):
        buildPdfFromPngs(pngs, pdfname=pdfname)

def plotSamplersWithTsys(vis, caltable=None, channels=20, scan=None, filter='',
                         skipPlotbandpass=False, skipPlotms=False, markersize=10,
                         showatm=False):
    """
    Runs Atmcal, checkSamplers, plotbandpass, plotms, and montageTwoPngLists
    in order to create side-by-side plots of the autocorrelation on the sky
    subscan of the first ATM calibration scan (or a specified scan) and the
    corresponding Tsys, near channel zero.
    channels: The number of channels to show on the x-axis
    scan: the scan number to use
    filter: an antenna name to skip (e.g. when Tsys has no solutions for it)
    skipPlotbandpass: do not remove or generate Tsys plots
    skipPlotms: do not generate autocorrelation amplitude plots
    markersize: size of the points in the plotbandpass plots
    showatm: pass this option to plotbandpass
    Todd Hunter
    """
    if (caltable is None):
        caltable = vis+'.tsys'
        if (os.path.exists(caltable) == False):
            gencal(vis, caltype='tsys', caltable=caltable)
    elif (os.path.exists(caltable) == False):
        print("Could not find caltable.")
        return
    else:
        print("Found caltable.")
    atmcal = Atmcal(vis)
    if (scan is None):
        scan = atmcal.scans[0]
    scans = str(scan)
    if (scan not in atmcal.scans):
        print("This scan is not an ATM cal scan.  Try: %s" % (str(atmcal.scans)))
        return
    spwlist = ','.join(str(atmcal.spwsforscan_nonchanavg[scan]).strip('[').strip(']').split())
    if (skipPlotbandpass==False):
        os.system('rm %s*.png' % (caltable))
        print("Running plotbandpass('%s',xaxis='chan',scans='%s', interactive=False,subplot=11,figfile='%s.scan%s', buildpdf=True, plotrange=[-0.5,%d,0,0],showpoints=True,showBasebandNumber=True,spw='%s',markersize=%d,showatm=%s)" % (caltable,scans,caltable,scans,channels,spwlist,markersize,showatm))
        plotbandpass(caltable, xaxis='chan', scans=scans, interactive=False,subplot=11,markersize=markersize,
                     figfile=caltable+'.scan'+scans, buildpdf=True, plotrange=[-0.5,channels,0,0],showpoints=True,
                     showBasebandNumber=True,xcolor='b',ycolor='r',spw='%s'%(spwlist),showatm=showatm)
    tsysfiles = sorted(glob.glob(caltable+'.scan'+scans+'*.png'))
    mymsmd = createCasaTool(msmdtool)
    mymsmd.open(vis)
    plotfiles = []
    if (skipPlotms == False):
        samplers = checkSamplers(vis, ac=atmcal)
    sky = 1
    timerange = atmcal.timestampsString[int(scans)][sky]
    antnames = mymsmd.antennanames(range(mymsmd.nantennas()))
    for a in antnames:
        for spw in atmcal.spwsforscan_nonchanavg[scan]:
            plotfile = vis+'.%s.spw%02d.autocorr.png'%(a,spw)
            if (skipPlotms == False):
                baseband = mymsmd.baseband(spw)
                plotms(vis, spw=str(spw)+':0~%d'%(channels), xaxis='chan', interactive=False, scan=scans, timerange=timerange,
                       yaxis='amp',coloraxis='corr', avgtime='10000', iteraxis='spw',antenna=a+'&&&',overwrite=True,
                       plotfile=plotfile, plotrange=[-0.5,channels,0,0],
                       title=vis+' scan %s %s BB%d chan 0 ratios: XX=%.2f, YY=%.2f'%(scans,a,baseband,samplers[a][baseband][0],samplers[a][baseband][1]))
            plotfiles.append(plotfile)
    mymsmd.close()
    pdfname = vis+'.scan%s.autocorrsky_tsys.%dchannels.pdf' % (scans,channels)
    montageTwoPngLists(plotfiles, tsysfiles, sidebyside=False, pdfname=pdfname, filter=filter)
    return(pdfname)

def jpgWidthHeight(fname):
    """
    Returns the width and height of a JPEG file.
    -Todd Hunter
    """
    with open(fname, 'rb') as fhandle:
        head = fhandle.read(24)
        try:
            fhandle.seek(0) # Read 0xff next
            size = 2
            ftype = 0
            while not 0xc0 <= ftype <= 0xcf:
                fhandle.seek(size, 1)
                byte = fhandle.read(1)
                while ord(byte) == 0xff:
                    byte = fhandle.read(1)
                ftype = ord(byte)
                size = struct.unpack('>H', fhandle.read(2))[0] - 2
            # We are at a SOFn block
            fhandle.seek(1, 1)  # Skip `precision' byte.
            height, width = struct.unpack('>HH', fhandle.read(4))
            return width, height
        except:
            return

def pngWidthHeight(filename, ignoreCommas=False):
    """
    Reads the width and height (in pixels) of a png image or list of images.
    filename: string with wildcard, comma-delimited string, or list of files
    -Todd Hunter
    """
    if type(filename) == str:
        if filename.find('*') >= 0:
            filename = sorted(glob.glob(filename))
        elif not ignoreCommas:
            filename = filename.split(',')
        else:
            filename = [filename]
    for fname in filename:
        if not os.path.exists(fname):
            print("Cannot find file = ", fname)
            return
        f = open(fname, 'rb')
        data = f.read()
        # The second cases with byte strings are for CASA 6
        if (data[:8] == '\211PNG\r\n\032\n' or data[:4] == b'\x89PNG') and (data[12:16] == 'IHDR' or data[12:16] == b'IHDR'):
            w, h = struct.unpack('>LL', data[16:24])
            width = int(w)
            height = int(h)
        else:
            raise Exception('not a png image: %s' % (filename))
        f.close()
        if len(filename) > 1:
            print("%d x %d: %s" % (width, height, fname))
    return width, height

def pngDPI(filename, ignoreCommas=False, roundToInteger=True, identify='identify'):
    """
    Reads the DPI of a png image or list of images using imageMagick's identify function.
    filename: string with wildcard, comma-delimited string, or list of files
    identify: full path to ImageMagick's identify function
    Returns: list of two values, in units of dots per inch
    -Todd Hunter
    """
    if type(filename) == str:
        if filename.find('*') >= 0:
            filename = sorted(glob.glob(filename))
        elif not ignoreCommas:
            filename = filename.split(',')
        else:
            filename = [filename]
    for fname in filename:
        if not os.path.exists(fname):
            print("Cannot find file = ", fname)
            return
        cmd = "%s -format '%%x,%%y' %s" % (identify,fname)
        status, output = getstatusoutput(cmd)
        dpi = np.array(output.replace('PixelsPerCentimeter','').split(','), dtype='float')
        dpi *= 2.54
        if roundToInteger:
            dpi = np.array(np.round(dpi), dtype='int')
    return list(dpi)
                                            
def montage(pnglist, tile='2X2', geometry='1000x1000+0+0', plotfile='', 
            sort=True, background=None,trim=False, shave=None):
    """
    Calls the montage program with the specified arguments.
    pnglist: list of strings, or a string with a wildcard character.
    tile: number of columns X rows
    geometry: passed to the montage command
    plotfile: the name of the png file to produce
    sort: if True, and if pnglist is a string, then sort the output of glob.glob
    background: set the background color (e.g. #000000)
    trim: trim the blank areas around each image
    shave: geometry (e.g. '50x100' to remove 50 pixels from sides, 100 from top/bottom)
    """
    if (type(pnglist) == str):
        pnglist = glob.glob(pnglist)
        if (sort):
            pnglist = sorted(pnglist)
    pnglist = ' '.join(pnglist)
    if (plotfile == '' or plotfile==True):
        plotfile = 'montage.png'
    if (background is not None and background != ''):
        background = '-background ' + background
    else:
        background = ''
    if (shave is not None and shave != ''):
        shave = '-shave ' + shave
    else:
        shave = ''
    if (trim):
        trim = '-trim'
    else:
        trim = ''
    cmd = "montage -tile %s -geometry %s %s %s %s %s %s" % (tile,geometry,background,trim,shave,pnglist,plotfile)
    print("Running %s" % cmd)
    os.system(cmd)
    print("Result left in %s" % (plotfile))

def montagePngs(png1, png2='', outname='', sidebyside=True, png3=None, geometry='auto',
                trim=False, spacing=2, background='black', png4=None,
                border2=None, montage='montage', crop2=None, splice2=None, 
                tile='', png5=None, png6=None, convert='convert', density='',
                labelImages=False, pointsize=36, labelBasename=True, font='',
                verbose=False, cleanup=True, labelOverwrite=False, 
                labelBackground='white', labelColor='black', addLabel='',
                png7=None, png8=None, filetype='png', removeSourcePngs=False,
                protectOriginals=False, png9=None, png10=None, png11=None, 
                png12=None, png13=None, png14=None, png15=None, gravity='', 
                forceLabel=False, annotate='',
                order='', sort=True):
    """
    Takes 2..15 pngs (or single-page PDFs, if filetype=='pdf'), and puts them onto one page.
    Someday I need to rewrite it to accept an arbitrary number of pngs!
    Returns: name of png created
    sidebyside: if False, then put them one atop the other.
    Note: Some of the options in this task require the source pngs to be in the current
          working directory (border, crop, splice) but that could be improved.
    png1: can be a single filename, a comma-delimited list, a python list, or a string with wildcard (or a !* wildcard to avoid matching files)
    png2: can be a single filename, a comma-delimited list, a python list, or a string with wildcard 
    sort: if False, then use the natural list order given in png1 and png2
    outname: default = montagePngs.png
    tile: override the automatic tiling, e.g. '2X2' (ncolumns x nrows)
    geometry: the string to use in the '-geometry' option of the montage commands
           format =   'WidthOfSingleImage x HeightOfSingleImage + Xgap + Ygap'
             example = '900x600+20+20' for a 2x2 grid of imview square images
          default: 'auto', which for filetype=='png' uses the size of png1, 
                       (Use 'auto+10' to add 10x10 pixel gap)
                   and for filetype='pdf', it uses '1000x1000+2+2'
                 
    trim: if True, pass '-trim' to the montage commands (note: this changes file creation time)
    spacing: the gap between pngs, in pixels (if geometry is not specified)
    background: the color to use in the '-background' option of the montage commands
    border2: use convert to add a border to the second image of this many pixels
    montage: the path to the montage command
    convert: the path to the convert command
    crop2: string for the convert -crop option, to be run after -border
    splice2: string for the convert -splice option, to be run after -crop
    density: e.g. 300, '300' or '300x200'
    annotate: put text inside first image, e.g. '+500+700 "my text"'
    labelImages: if True, print the name of the png file at the top of each panel
               if it is a list of strings, then use those strings instead
    labelBasename: if True, remove any leading directory from the label
    labelOverwrite: if True, then overwrite the original png with the labelled one
    pointsize: label size (used by labelImages and addLabel)
    addLabel: if specified, add this label to top of the whole frame
          if it is a filename, read the first line of text from it
    gravity: used by addLabel and labelImages options (if specified, e.g. 'Center', 
            then '-gravity Center' will be added to the command)
    font: a string, like 'Utopia-Regular'
    cleanup: if True, remove any temporary files created by this task (border2,crop2,splice2)
    removeSourcePngs: if True, then remove png1,png2... when finished
    forceLabel: add label even if the label text is already found in the png
    order: used for wildcard case to re-order images (default is alphabetical)
          zero-based, example:  '0,2,1,3'
    Called by: montageTwoPngLists, uvplotHeterogeneous, imageModelResidual, 
               imfitplot, imviewFieldCubeEdges, asdmbitsHistograms,
               plotPointingResultsFromASDM
    -Todd Hunter
    """
    if outname == '':
        outname = 'montagePngs.'+filetype
    if verbose: print("montagePngs using outname=%s" % (outname))
    if png3 == '': png3 = None
    if png4 == '': png4 = None
    if png2 == '':
        if type(png1) == list:
            if len(png1) < 2:
                print("au.montagePngs received png1='%s', png2='%s'" % (png1,png2))
                print("You must specify png2 or set png1 to a list of 2 or more files")
                return
        else:
            if png1.find('*') < 0 and png1.find(',') < 0:
                print("You must specify png2 or include a wildcard in png1.")
                return
            if png1.find('*') >= 0:
                pnglists = png1.split(',')
                png1 = []
                for mypnglist in pnglists:
                    if mypnglist.find('!*') >= 0:
                        png1listAll = glob.glob(os.path.join(os.path.dirname(mypnglist),'*.png'))
                        png1listAvoid = glob.glob(mypnglist.replace('!',''))
                        png1list = []
                        for png in png1listAll:
                            if png not in png1listAvoid:
                                png1.append(png)
                    else:
                        png1 += sorted(glob.glob(mypnglist))
                if sort:
                    png1 = sorted(png1)
                if order != '':
                    if type(order) == str:
                        order = order.split(',')
                    if len(order) != len(png1):
                        print("Number of items in order (%d) not equal to len of png1 (%d)"% (len(order), len(png1)))
                        return
                    # convert from numpy.string to string
                    indices = np.array([int(i) for i in order])
                    print("indices = ", indices)
                    png1 = [str(i) for i in np.array(png1)[indices]]
                    print("New order: ", png1)
            else:
                png1 = png1.split(',')
                if sort:
                    png1 = sorted(png1)
        if len(png1) == 0:
            print("No images found")
            return
        print("png1 = ", png1)
        png = png1[:]
        if len(png) >= 2:
            png1 = png[0]
            png2 = png[1]
        if len(png) >= 3:
            png3 = png[2]
        if len(png) >= 4:
            png4 = png[3]
        if len(png) >= 5:
            png5 = png[4]
        if len(png) >= 6:
            png6 = png[5]
        if len(png) >= 7:
            png7 = png[6]
        if len(png) >= 8:
            png8 = png[7]
        if len(png) >= 9:
            png9 = png[8]
        if len(png) >= 10:
            png10 = png[9]
        if len(png) >= 11:
            png11 = png[10]
        if len(png) >= 12:
            png12 = png[11]
        if len(png) >= 13:
            png13 = png[12]
        if len(png) >= 14:
            png14 = png[13]
        if len(png) >= 15:
            png15 = png[14]
    elif os.path.isdir(png2):
        print("png2 is a directory, not an image file.")
        return
    if type(png1) == str or type(png1) == np.bytes_:  # png1 can already be a list (if png2=='')
        if png1.find('*') >= 0:
            png1list = glob.glob(png1)
            if len(png1list) > 1:
                print("You have specified png1 and png2, but the wildcard in png1 found more than 1 file.")
                return
            elif len(png1list) == 0:
                print("You have specified png1 and png2, but the wildcard in png1 found zero files: ", png1)
                return
            else:
                png1 = png1list[0]
    else:
        print("type(png1) = %s" % (type(png1)))
        png1list = png1
        print("Setting png1 to %s" % (png1list[0]))
        png1 = png1list[0]
    if png2.find('*') >= 0:
        png2list = glob.glob(png2)
        if len(png2list) > 1:
            print("You have specified png1 and png2, but the wildcard in png2 found more than 1 file.")
            return
        elif len(png2list) == 0:
            print("You have specified png1 and png2, but the wildcard in png2 found zero files: ", png2)
            return
        else:
            png2 = png2list[0]
    if (os.path.exists(png1) == False):
        print("Could not find file png1 = %s." % (png1))
        return
    if (os.path.exists(png2) == False):
        print("Could not find file png2 = ", png2)
        return
    if (png3 is not None):
        if (png4 is not None):
            if (png5 is not None):
                if (png6 is not None):
                    if png7 is not None:
                        if png8 is not None:
                            if png9 is not None:
                                if png10 is not None:
                                    if png11 is not None:
                                        if png12 is not None:
                                            if png13 is not None:
                                                if png14 is not None:
                                                    if png15 is not None:
                                                        npngs = 15
                                                    else:
                                                        npngs = 14
                                                else:
                                                    npngs = 13
                                                if tile == '':
                                                    tile = '3x5'
                                            else:
                                                npngs = 12
                                                if tile == '':
                                                    tile = '3x4'
                                        else:
                                            npngs = 11
                                        if tile == '':
                                            tile = '3x4'
                                    else:
                                        npngs = 10
                                        if tile == '':
                                            tile = '3x4'
                                else:
                                    npngs = 9
                                    if tile == '':
                                        tile = '3x3'
                            else:
                                npngs = 8
                                if tile == '':
                                    tile = '2x4'
                        else:
                            npngs = 7
                            if tile == '':
                                tile = '2x4'
                    else:
                        npngs = 6
                        if (tile == ''):
                            tile = '2X3'
                else:
                    npngs = 5
                    if (tile == ''):
                        tile = '2X3'
            else:
                npngs = 4
                if (tile == ''):
                    tile = '2X2'
        else:
            npngs = 3
            if (tile == ''):
                if (sidebyside):
                    tile = '3X1'
                else:
                    tile = '1X3'
    else: # png3 is None
        npngs = 2
        if (tile == ''):
            if (sidebyside):
                tile = '2X1'
            else:
                tile = '1X2'
    if (geometry is None or filetype=='pdf'):
        geometry = '1000x1000+%d+%d' % (spacing,spacing)
    elif (geometry.find('auto') >= 0):
        gap = 0
        if (geometry.find('+') > 0):
            gap = int(geometry.split('+')[1])
        if png1.find('.png') >=0 :
            geometry = 'x'.join([str(i) for i in pngWidthHeight(png1, ignoreCommas=True)])
        else:  # assume jpg
            geometry = 'x'.join([str(i) for i in jpgWidthHeight(png1)])
        if gap != 0:
            geometry += '+%d+%d' % (gap,gap)
        if verbose:
            print("geometry = ", geometry)
    if (trim):
        trim = '-trim'
    else:
        trim = ''
    removeFiles = []
    if border2 is not None:
        cmd = "%s %s -bordercolor %s -border %d border_%s" % (convert, png2, background, border2, png2)
        if verbose: print("Running %s" % (cmd))
        os.system(cmd)
        png2 = "border_" + png2
        if cleanup:
            removeFiles.append(png2)
    if crop2 is not None:
        cmd = "%s %s -crop %s crop_%s" % (convert, png2, crop2, png2)
        if verbose: print("Running %s" % (cmd))
        os.system(cmd)
        png2 = "crop_" + png2
        if cleanup:
            removeFiles.append(png2)
    if splice2 is not None:
        cmd = "%s %s -background %s -splice %s splice_%s" % (convert, png2, background, splice2, png2)
        if verbose: print("Running %s" % (cmd))
        os.system(cmd)
        png2 = "splice_" + png2
        if cleanup:
            removeFiles.append(png2)
    if trim:
        path = os.path.dirname(png1)
        if not os.access(path,os.W_OK):
            path = ''
        if len(path) > 0: path += '/'
        pcmd  = "%s -trim %s %s%s1.%s" % (convert, png1, path, filetype,filetype)
        if verbose: print("running trim1: ", pcmd)
        mystatus = os.system(pcmd)
        if mystatus != 0:
            convert = '/opt/local/bin/convert'
            print("Switching to ", convert)
            pcmd  = "%s -trim %s %s%s1.%s" % (convert, png1, path, filetype, filetype)
            print("running: ", pcmd)
            mystatus = os.system(pcmd)
            if mystatus != 0:
                convert = '/usr/local/bin/convert'
                print("Switching to ", convert)
                pcmd  = "%s -trim %s %s%s1.%s" % (convert, png1, path, filetype, filetype)
                print("running: ", pcmd)
                mystatus = os.system(pcmd)
        if protectOriginals:
            png1 = 'png1_trimmed.png'
        shutil.move('%s%s1.%s' % (path, filetype, filetype), png1)

        path = os.path.dirname(png2)
        if not os.access(path,os.W_OK):
            path = ''
        if len(path) > 0: path += '/'
        pcmd  = "%s -trim %s %s%s2.%s" % (convert, png2, path, filetype, filetype)
        if verbose: print("running trim2: ", pcmd)
        mystatus = os.system(pcmd)
        if protectOriginals:
            png2 = 'png2_trimmed.png'
        if verbose: print("moving: %s%s2.%s to %s" % (path, filetype, filetype, png2))
        shutil.move('%s%s2.%s' % (path, filetype, filetype), png2)
    if density != '':
        density = '-density %s' % (str(density))
    if gravity != '':
        gravity = '-gravity ' + gravity
    if annotate != '':
        annotate = '-annotate ' + annotate
    if annotate != '' or (labelImages != False and labelImages != ''):
        if len(font) > 0:
            font = '-font ' + font
        if labelImages == True:
            if labelBasename:
                label = os.path.basename(png1)
            else:
                label = png1
            swap = '+swap'
        elif labelImages != False:
            label = labelImages[1-1]
            swap = '+swap'
        else:
            label = ''
            swap = ''
        if len(grep(png1,label)[0]) == 0 or forceLabel:
            # Then we have not already labeled this png.
            newpng1 = png1.replace('.'+filetype,'_label01.'+filetype)
            # Note: -pointsize argument must come before label argument
            # the line below works on CASA 6.5 for pipeline paper: annotate's y-offset is keyed off of value of pointsize
            splice = (pointsize*7)//5
            pcmd = '%s %s -background %s -fill %s %s -pointsize %d -splice 0x%d -annotate +50+%d "%s" %s %s' % (convert, png2, labelBackground, labelColor, font, pointsize, splice, pointsize, label, gravity, newpng1)
            print("pcmd = ", pcmd)
            #       +swap puts the label on the top of the image, otherwise it would be on the bottom.
#            pcmd = '%s %s -background %s -fill %s %s -pointsize %d label:"%s" %s %s %s -append %s' % (convert, png1, labelBackground, labelColor, font, pointsize, label, swap, gravity, annotate, newpng1)
#   I tried the following to see if it would prevent also labeling in small font at bottom, but it did not change:
#            pcmd = '%s -background %s -fill %s %s -pointsize %d label:"%s" %s -gravity Center -append %s' % (convert, labelBackground, labelColor, font, pointsize, label, png1, newpng1)
            if verbose: print("Running: ", pcmd)
            os.system(pcmd)
            if not os.path.exists(newpng1):
                tmpnewpng1 = '/tmp/' + newpng1
                pcmd = pcmd.replace(newpng1,tmpnewpng1)
                os.system(pcmd)
                newpng1 = tmpnewpng1
                print("Wrote ", tmpnewpng1)
            if labelOverwrite:
                os.remove(png1)
                os.rename(newpng1,png1)
            else:
                png1 = newpng1
        else:
            print("We have already labeled png1: %s. Set forceLabel=True." % (png1))
        if labelImages == True:
            if labelBasename:
                label = os.path.basename(png2)
            else:
                label = png2
            swap = '+swap'
        elif labelImages != False:
            label = labelImages[2-1]
            swap = '+swap'
        else:
            swap = ''
        if len(grep(png2,label)[0]) == 0 or forceLabel:
            # Then we have not already labeled this png.
            newpng2 = png2.replace('.'+filetype,'_label02.'+filetype)
            pcmd = '%s %s -background %s -fill %s %s -splice %s -pointsize %d -annotate +0+%d "%s" %s %s %s' % (convert, png2, labelBackground, labelColor, font, (pointsize*7)//5, pointsize, pointsize, label, swap, gravity, newpng2)
            if verbose: print("Running: ", pcmd)
            os.system(pcmd)
            if not os.path.exists(newpng2):
                tmpnewpng2 = '/tmp/' + newpng2
                pcmd = pcmd.replace(newpng2,tmpnewpng2)
                os.system(pcmd)
                newpng2 = tmpnewpng2
                print("Wrote ", tmpnewpng2)
            if labelOverwrite:
                os.remove(png2)
                os.rename(newpng2,png2)
            else:
                png2 = newpng2
        else:
            print("We have already labeled png2: %s. Set forceLabel=True" % (png2))

    cmd = "%s %s %s -background %s -tile %s %s -geometry %s  %s %s "%(montage,trim,density,background,tile,gravity,geometry,png1,png2)
    if removeSourcePngs:
        removeFiles.append(png1)
        removeFiles.append(png2)
    if type(labelImages) == bool:
        nLabelImages = 2
        for i in [png3,png4,png5,png6,png7,png8,png9,png10,png11,png12,png13,png14,png15]:
            if i is not None: nLabelImages += 1
    else:
        nLabelImages = len(labelImages)
    if (png3 is not None): 
        if trim:
            path = os.path.dirname(png3)
            if not os.access(path,os.W_OK):
                path = ''
            if len(path) > 0: path += '/'
            pcmd  = "%s -trim %s %s%s3.%s" % (convert, png3, path, filetype, filetype)
            if verbose: print("Running: ", pcmd)
            mystatus = os.system(pcmd)
            if protectOriginals:
                png3 = 'png3_trimmed.png'
            shutil.move('%s%s3.%s'%(path,filetype,filetype), png3)
        if labelImages and nLabelImages > (3-1):
            newpng3 = png3.replace('.'+filetype,'_label03.'+filetype)
            if labelImages == True:
                if labelBasename:
                    label = os.path.basename(png3)
                else:
                    label = png3
            else:
                label = labelImages[3-1].replace('//','////')
            if len(grep(png3,label)[0]) == 0 or forceLabel:
                # Then we have not already labeled this png.
                pcmd = '%s %s -background %s -fill %s %s -pointsize %d label:"%s" +swap %s -append %s' % (convert, png3, labelBackground, labelColor, font, pointsize, label, gravity, newpng3)
                if verbose: print("Running: ", pcmd)
                os.system(pcmd)
                if not os.path.exists(newpng3):
                    tmpnewpng3 = '/tmp/' + newpng3
                    pcmd = pcmd.replace(newpng3,tmpnewpng3)
                    os.system(pcmd)
                    newpng3 = tmpnewpng3
                    print("Wrote ", tmpnewpng3)
                if labelOverwrite:
                    os.remove(png3)
                    os.rename(newpng3,png3)
                else:
                    png3 = newpng3
        cmd += png3 
        if removeSourcePngs:
            removeFiles.append(png3)
    if (png4 is not None): 
        if trim:
            path = os.path.dirname(png4)
            if not os.access(path,os.W_OK):
                path = ''
            if len(path) > 0: path += '/'
            pcmd  = "%s -trim %s %s%s4.%s" % (convert, png4, path, filetype, filetype)
            if verbose: print("Running: ", pcmd)
            mystatus = os.system(pcmd)
            if protectOriginals:
                png4 = 'png4_trimmed.png'
            shutil.move('%s%s4.%s'%(path,filetype,filetype), png4)
        if labelImages and nLabelImages > (4-1):
            newpng4 = png4.replace('.'+filetype,'_label04.'+filetype)
            if labelImages == True:
                if labelBasename:
                    label = os.path.basename(png4)
                else:
                    label = png4
            else:
                label = labelImages[4-1].replace('//','////')
            if len(grep(png4,label)[0]) == 0 or forceLabel:
                # Then we have not already labeled this png.
                pcmd = '%s %s -background %s -fill %s %s -pointsize %d label:"%s" +swap %s -append %s' % (convert, png4, labelBackground, labelColor, font, pointsize, label, gravity, newpng4)
                if verbose: print("Running: ", pcmd)
                os.system(pcmd)
                if not os.path.exists(newpng4):
                    tmpnewpng4 = '/tmp/' + newpng4
                    pcmd = pcmd.replace(newpng4,tmpnewpng4)
                    os.system(pcmd)
                    newpng4 = tmpnewpng4
                    print("Wrote ", tmpnewpng4)
                if labelOverwrite:
                    os.remove(png4)
                    os.rename(newpng4,png4)
                else:
                    png4 = newpng4
        cmd += ' ' + png4
        if removeSourcePngs:
            removeFiles.append(png4)
    if (png5 is not None):
        if trim:
            path = os.path.dirname(png5)
            if not os.access(path,os.W_OK):
                path = ''
            if len(path) > 0: path += '/'
            pcmd  = "%s -trim %s %s%s5.%s" % (convert, png5, path, filetype, filetype)
            if verbose: print("Running: ", pcmd)
            mystatus = os.system(pcmd)
            if protectOriginals:
                png5 = 'png5_trimmed.png'
            shutil.move(path+filetype+'5.'+filetype, png5)
        if labelImages and nLabelImages > (5-1):
            newpng5 = png5.replace('.'+filetype,'_label05.'+filetype)
            if labelImages == True:
                if labelBasename:
                    label = os.path.basename(png5)
                else:
                    label = png5
            else:
                label = labelImages[5-1].replace('//','////')
            if len(grep(png5,label)[0]) == 0 or forceLabel:
                # Then we have not already labeled this png.
                pcmd = '%s %s -background %s -fill %s %s -pointsize %d label:"%s" +swap %s -append %s' % (convert, png5, labelBackground, labelColor, font, pointsize, label, gravity, newpng5)
                if verbose: print("Running: ", pcmd)
                os.system(pcmd)
                if labelOverwrite:
                    os.remove(png5)
                    os.rename(newpng5,png5)
                else:
                    png5 = newpng5

        cmd += ' ' + png5
        if removeSourcePngs:
            removeFiles.append(png5)
    if (png6 is not None): 
        if trim:
            path = os.path.dirname(png6)
            if not os.access(path,os.W_OK):
                path = ''
            if len(path) > 0: path += '/'
            pcmd  = "%s -trim %s %s%s6.%s" % (convert, png6, path, filetype, filetype)
            if verbose: print("Running: ", pcmd)
            mystatus = os.system(pcmd)
            if protectOriginals:
                png6 = 'png6_trimmed.png'
            shutil.move(path+filetype+'6.'+filetype, png6)
        if labelImages and nLabelImages > (6-1):
            newpng6 = png6.replace('.'+filetype,'_label06.'+filetype)
            if labelImages == True:
                if labelBasename:
                    label = os.path.basename(png6)
                else:
                    label = png6
            else:
                label = labelImages[6-1].replace('//','////')
            if len(grep(png6,label)[0]) == 0 or forceLabel:
                # Then we have not already labeled this png.
                pcmd = '%s %s -background %s -fill %s %s -pointsize %d label:"%s" +swap %s -append %s' % (convert, png6, labelBackground, labelColor, font, pointsize, label, gravity, newpng6)
                if verbose: print("Running: ", pcmd)
                os.system(pcmd)
                if labelOverwrite:
                    os.remove(png6)
                    os.rename(newpng6,png6)
                else:
                    png6 = newpng6
        cmd += ' ' + png6
        if removeSourcePngs:
            removeFiles.append(png6)
    if (png7 is not None): 
        if trim:
            path = os.path.dirname(png7)
            if not os.access(path,os.W_OK):
                path = ''
            if len(path) > 0: path += '/'
            pcmd  = "%s -trim %s %s%s7.%s" % (convert, png7, path, filetype, filetype)
            if verbose: print("Running: ", pcmd)
            mystatus = os.system(pcmd)
            if protectOriginals:
                png7 = 'png7_trimmed.png'
            shutil.move(path+'%s7.%s'%(filetype,filetype), png7)
        if labelImages and nLabelImages > (7-1):
            newpng7 = png7.replace('.'+filetype, '_label07.'+filetype)
