def plotDelayUpdates(logfile, plottype='offset', plotfile='', ms=7):
    """
    Plots a text file of results generated by checkLogsForDelayUpdates
    plottype: 'offset' or 'RA/Dec'
    """
    f = open(logfile,'r')
    lines = f.readlines()
    f.close()
    t = []
    rao = []
    deco = []
    if plottype != 'offset':
        print("So far, only plottype='offset' is supported.")
        return
    for line in lines:
        if plottype == 'offset':
            loc = line.find("Equatorial offset")
            if loc > 0:
                token = line[loc:].split()
                t.append(dateStringToMJDSec(line.split()[0], verbose=False))
                r = token[3].lstrip('(').rstrip(',')
                rao.append(float(r))
                deco.append(float(token[4]))
    dt = mjdSecondsListToDateTime(t)
    pb.clf()
    desc = pb.subplot(221)
    pb.plot(dt,rao,'k.-',ms=ms)
    pb.ylabel('RA offset (arcsec)')
    pb.xlabel('Time')
    pb.title(logfile)

    pb.subplot(222)
    pb.plot(dt,deco,'k.-',ms=ms)
    pb.ylabel('Dec offset (arcsec)')
    pb.xlabel('Time')
    if plotfile == True:
        plotfile = logfile + '.png'
    if plotfile != '':
        pb.savefig(plotfile)

    pb.subplot(223)
    pb.plot(rao,deco,'ko')
    pb.ylabel('Dec offset (arcsec)')
    pb.xlabel('RA offset (arcsec)')
    if plotfile == True:
        plotfile = logfile + '.png'
    if plotfile != '':
        pb.savefig(plotfile)
        print("Wrote ", plotfile)
    
def checkLogsForDelayUpdates(vis=None, startTime=None, stopTime=None, cleanup=False, 
                             verbose=False, asdm=None, outfile=True, sort=True,
                             removeAdjacentDuplicates=True, arrayName='', overwrite=False,
                             aosdir='', searchText='RA/Dec at '):
    """
    Given a measurement set (or ASDM or time range), downloads the ALMA logs
    recorded during the execution period and checks for delay direction updates
    during that time. See au.plotDelayUpdates to plot the results.
    vis: measurement set (or ASDM name)
    asdm: ASDM name
    startTime: alternative to specifying measurement set, e.g. 2015-07-12T21:07:54
    stopTime:  alternative to specifying measurement set, e.g. 2015-07-12T22:07:54
    cleanup: if True, the remove the directory of log files it creates
    outfile: text file to generate; True -> <vis>_delay_updates.log
    sorted: if True, then sort the messages (which will then be in UT order)
    arrayName: if included, then also require this string to be present (e.g. 'Array009')
    aosdir: typical options are 'AOS', 'AOS64', 'APE1', 'APE2', 'TFINT', 'OFFLINE'
          leaving it blank will try to determine it by the date
    searchText: for example: ' source RA/Dec '
    -Todd Hunter
    """
    lines = checkALMALogs(vis, startTime, stopTime, cleanup, verbose, asdm,
#                          text='RA/Dec at ', printStartingAfter='CDATA[', insertLineBreaks=True, 
                          text=searchText, printStartingAfter=['CDATA[Equatorial source','CDATA[ Equatorial offset'], insertLineBreaks=True, 
                          arrayName=arrayName, overwrite=overwrite, aosdir=aosdir)
    if lines==None: return
    if verbose: print("Got %d lines" % len(lines))
    if outfile != '':
        if outfile == True:
            outfile = vis + '_delay_updates.log'
        f = open(outfile,'w')
        if sort:
            lines = sorted(lines)
        previousLine = ''
        for line in lines:
            line = line.strip()
            if (len(line.replace(' ','')) > 0):
                if (line != previousLine or not removeAdjacentDuplicates):
                    f.write(line+'\n')
                previousLine = line
        f.close()
        print("Wrote ", outfile)
    else:
        print("Set the outfile parameter to store these messages.")

def checkALMALogs(vis=None, startTime=None, stopTime=None, cleanup=False, 
                  verbose=False, asdm=None, text=' has been created at:', 
                  printStartingAfter='', insertLineBreaks=True, arrayName='',
                  overwrite=False, aosdir=''):
    """
    Given a measurement set (or ASDM or time range), downloads the ALMA logs
    recorded during the execution period and checks for array creation events
    during that time.
    vis: measurement set (or ASDM name)
    asdm: ASDM name
    startTime: alternative to specifying measurement set, e.g. 2015-07-12T21:07:54
    stopTime:  alternative to specifying measurement set, e.g. 2015-07-12T22:07:54
    cleanup: if True, the remove the directory of log files it creates
    text: the text for which to search
    printStartingAfter: the character string after which to start printing matches, or list of strings
    insertLineBreaks: when printStartingAfter is specified, add line breaks before
                      each match of 'text' is found
    arrayName: if included, then also require this string to be present on the line
            if 'Array' is present (e.g. 'Array009')
    aosdir: typical options are 'AOS', 'AOS64', 'APE1', 'APE2', 'TFINT', 'OFFLINE'
          leaving it blank will try to determine it by the date
               
    -Todd Hunter
    """
    if (vis is not None):
        startMJDSec = getObservationStart(vis)
        if (startMJDSec is None):
            if (os.path.exists(vis)):
                print("Checking if it is an ASDM...")
                result = getObservationStartDateFromASDM(vis)
                if (result is None): return
                startDatestamp, startMJDSec = result
                stopDatestamp, stopMJDSec = getObservationEndDateFromASDM(vis)
            else:
                return
        else:
            stopMJDSec = getObservationStop(vis)
            startDatestamp = getObservationStartDate(vis)
            stopDatestamp = getObservationStopDate(vis)
        print("start-stop = ", startDatestamp, stopDatestamp)
    elif (asdm is not None):
        result = getObservationStartDateFromASDM(asdm)
        if (result is None): return
        startDatestamp, startMJDSec = result
        stopDatestamp, stopMJDSec = getObservationEndDateFromASDM(asdm)
    elif (startTime is None or stopTime is None):
        print("You must specify either a measurement set or a start and stop time")
        return
    else:
        startDatestamp = startTime
        stopDatestamp = stopTime
        startMJDSec = dateStringToMJDSec(startTime, verbose=False)
        stopMJDSec = dateStringToMJDSec(stopTime, verbose=False)
    files = compUtils.retrieve_aos_system_logs(startDatestamp, stopDatestamp, overwrite, verbose, aosdir)
    if files is None:
        print("Try setting the aosdir parameter")
        return
    print("Grepping %d files for '%s' (any matches will be printed)...." % (len(files), text))
    if (verbose):
        print(str(files))
    returnValue = []
    filtered = 0
    for f in files:
        if (verbose):
            print("Grepping for '%s' in file: " % (text), f)
        stdout, stderr = grep(f, text)
        if verbose:
            print("  length of result: %d, len(arrayName)=%d" % (len(stdout),len(arrayName)))
        if (len(stdout) > 0):
            creationDate = stdout.split('TimeStamp="')[1].split('" File=')[0]
            creationMJDSec = dateStringToMJDSec(creationDate, verbose=False)
            if (creationMJDSec >= startMJDSec and creationMJDSec <= stopMJDSec):
                if verbose: print("Within time range")
                if printStartingAfter == '':
                    print(stdout+'\n')
                    returnValue.append(stdout)
                else:
                    lines = stdout.split('<Info')
                    for stdout in lines:
                        if verbose: print("Checking: ", stdout)
                        if (stdout.find("TimeStamp") >= 0):
                            timestamp = stdout.split("TimeStamp=")[1].split(' ')[0].strip('"')
                        else:
                            timestamp = ''
                        if type(printStartingAfter) == str:
                            startchar = stdout.find(printStartingAfter)
                        else:  # a list of possibilities was entered
                            for pSA in printStartingAfter:
                                startchar = stdout.find(pSA)
                                if startchar >= 0: break
                        if (len(arrayName) > 0):
                            if (stdout.find(arrayName) < 0 and stdout.find('Array') >= 0): 
                                if verbose: print("++++++ filtered out due to arrayName")
                                filtered += 1
                                continue
                        if (startchar >= 0):
                            mjdsec = dateStringToMJDSec(timestamp,verbose=False)
                            if (mjdsec<stopMJDSec and mjdsec>=startMJDSec):
                                myline = timestamp + ' ' + stdout[startchar+len(printStartingAfter):].split('\n')[0].replace(']]></Info>','')
                                if insertLineBreaks:
                                    myline = myline.replace(text,'\n'+text)
                                print(myline)
                                myline = myline.split('\n')
                                returnValue += myline
                            elif verbose:
                                print("message lies outside of range %.1f-%.1f" % (startMJDSec,stopMJDSec))
                        else:
                            if verbose: print("Did not find '%s'" % (printStartingAfter))
    if (filtered > 0):
        print("Skipped %d lines that were not for this array" % filtered)
    if (cleanup):
        tree = os.path.dirname(f)
        print("Removing files in %s" % (tree))
        shutil.rmtree(tree)
    return returnValue

def mostRecentPipelineParentDirectory(user='', withProducts=False):
    """
    Finds the parent directory of the most recent pipeline run of a NA user.
    withProducts: if True, then only find parents that contain a products dir
    -Todd Hunter
    """
    if (user == ''):
        user = os.getenv('USER')
    mydir = '/lustre/naasc/sciops/comm/%s/pipeline/root/20*' % user
    print("Searching ", mydir)
    mydir = sorted(glob.glob(mydir), key=os.path.getmtime, reverse=True)
    if (len(mydir) > 0):
        if withProducts:
            for d in mydir:
                searchdir = d+'/*/*/*/products'
                print("Checking for ", searchdir)
                if len(glob.glob(searchdir)) > 0:
                    return d
    print("No qualifying pipeline run directories found.")
    return
    
def mostRecentPipelineWorkingDirectory(user='', withProducts=False):
    """
    Finds the working directory of the most recent pipeline run of a NA user.
    -Todd Hunter
    """
    mydir = mostRecentPipelineParentDirectory(user, withProducts)
    sous = glob.glob(mydir+'/SOUS*')
    if (len(sous) < 1):
        print("No SOUS found")
        return
    newdir = sous[0]+'/GOUS*'
    gous = glob.glob(newdir)
    if (len(gous) < 1):
        print("No GOUS found")
        return
    newdir = gous[0]+'/MOUS*'
    mous = glob.glob(newdir)
    if (len(mous) < 1):
        print("No MOUS found")
        return
    return (mous[0] + '/working')
    
def getLineFromFile(filename, lineNumber=None):
    """
    Returns a string corresponding to the specified line number from a text file
    -Todd Hunter
    """
    if not os.path.exists(filename):
        print("File not found")
        return
    f = open(filename,'r')
    lines = f.readlines()
    f.close()
    if lineNumber is None:
        return lines
    if lineNumber >= len(lines):
        print("No such line number")
        return                               
    else:
        return lines[lineNumber]
                               
def grep(filename, arg, outfile=None, context=None, switches='-n'):
    r"""
    Runs the unix grep command in a subprocess.  
    arg: to search for either of 2 strings, set this to 'string1\|string2"
      to search for both of 2 strings, in order, set this to 'string1.*string2'
    Returns 2 items: 
    * the contents of stdout (i.e. the result of the grep -n, which begins
       with the 1-based line number)
    * the contents of stderr
    -Todd Hunter
    """
    if context is None:
        process = subprocess.Popen(['grep', switches, arg, filename], stdout=subprocess.PIPE)
    else:
        process = subprocess.Popen(['grep', switches, context, arg, filename], stdout=subprocess.PIPE)
    stdout, stderr = process.communicate()
    stdout = byteDecode(stdout)
    if stderr is not None:
        stderr = byteDecode(stderr)
    if outfile is not None:
        f = open(outfile,'w')
        f.write(str(stdout))
        f.close()
        print("Sent output to ", outfile)
    return stdout, stderr

def addToStateTable(vis, rows=1):
    """
    Appends a row to the STATE table of a measurement set.
    Puts zeroes into CAL and LOAD column, and False into FLAG_ROW and REF column, and True
    into SIG column.
    Useful for testing SMA data in CASA 4.4.
    -Todd Hunter
    """
    if (not os.path.exists(vis)):
        print("Measurement set not found: ", vis)
        return
    mytb = createCasaTool(tbtool)
    mytb.open(vis+'/STATE', nomodify=False)
    mytb.addrows(rows)
    row = mytb.nrows()-1
    mytb.putcell('CAL', row, 0)
    mytb.putcell('FLAG_ROW', row, False)
    mytb.putcell('LOAD', row, 0)
#    mytb.putcell('OBS_MODE', row, np.array([''], dtype='|S1'))
    mytb.putcell('REF', row, False)
    mytb.putcell('SIG', row, True)
#    mytb.putcell('SUB_SCAN', row, np.array([1], dtype=np.int32))
    print("There are now %d rows in the STATE table." % (mytb.nrows()))
    mytb.close()

def compareAntPosResults(antposlist='', errmax=2., antennasToPlot=[],
                         doWvrCorrection=False, dropAntennas=[], 
                         drawFits=False):
    """
    Uses Robert Lucas' modules to compare multiple results from tc_antpos
    and generate plots of XYZ vs. time and PWV like those Robert produces.
    This function is useful for examining the data and potential
    corrections due to the partial pressure of water vapor and differential
    barometric correction.  See the function averageAntPosResults for 
    producing xml files suitable for updating positions in the TMCDB.
    -Todd Hunter
    Inputs:
    errmax: maximum error (in mm) for a dataset to be plotted on 'vs. Date' plot
    antennasToPlot: an empty list means all antennas
    dropAntennas: antennas to drop when fitting for rms vs. distance
    drawFits: if True, then run it twice, drawing rms vs. distance fits
                     on the second time
    """
    if (not CAPRAvailable):
        if (casadef.python_library_directory.find('telcalsa') < 0):
            print("The TelCal libraries are not available to plain casa on this machine.")
            print("Instead, you will need to run this command in casapy-telcal.")
        else:
            print("For some reason, the TelCal libraries are not importable in au in casapy-telcal on this machine.")
        return
    if (antposlist == ''):
        antposlist = sorted(glob.glob('*WET_antpos_result'), reverse=True)
        nresults = len(antposlist)
        print("Found %d results to compare" % (nresults))
        if (nresults < 1):
            return
    elif (antposlist.find('*') >= 0):
        antposlist = sorted(glob.glob(antposlist), reverse=True)
        nresults = len(antposlist)
        print("Found %d results to compare" % (nresults))
        if (nresults < 1):
            return
    elif (type(antposlist) == str):
        antposlist = sorted(antposlist.split(','), reverse=True)
    for ant in antposlist:
        loc = ant.find('_delays_')
        asdm = ant[:loc]
        if (not os.path.exists(asdm)):
            print("Could not find ASDM=%s. Exporting it with -m." % (asdm))
            os.system('asdmExport -m '+asdm)
    c = CAPR.CompareAntPosResults()
    wet = 'WET'
    c.addResults(antposlist, wet, errmax)
    if (len(antennasToPlot) > 0):
        if (type(antennasToPlot) == str):
            antennasToPlot = antennasToPlot.split(',')
        pngs = []
        for a in antennasToPlot:
            mean, rms, distance, height = c.plotAntenna(a, errmax, doWvrCorrection=doWvrCorrection)
            station = c.station[a]
            pb.figtext(0.1, 0.95, '%s/%s d=%6.0fm h=%3.0fm %s'%\
                       (a, station, distance, height, wet), ha='left', va='top')
            png = 'XYZ_%s_%s_%s.png'%(wet, a, station)
            pb.savefig(png)
            pngs.append(png)
    else:
        pngs, [aa, xx, yy_x, yy_y, yy_z] = c.plotAll(wet, errmax, doWvrCorrection, returnRms=True)
    print("Produced per-antenna png plots in current working directory.")
    if (len(dropAntennas) > 0):
        for dropAntenna in dropAntennas:
            if dropAntenna in aa:
                idx = aa.index(dropAntenna)
                aa.pop(idx)
                xx.pop(idx)
                yy_x.pop(idx)
                yy_y.pop(idx)
                yy_z.pop(idx)
    slope_x, intercept_x = linfit().linfit(xx, yy_x, 0.1*np.array(yy_x))
    slope_y, intercept_y = linfit().linfit(xx, yy_y, 0.1*np.array(yy_y))
    slope_z, intercept_z = linfit().linfit(xx, yy_z, 0.1*np.array(yy_z))
    print("Slopes: x=%f, y=%f, z=%f, z/mean(x+y)=%f" % (slope_x, slope_y, slope_z,
                                                        2*slope_z/(slope_x+slope_y)))
    print("Intercepts: x=%f, y=%f, z=%f" % (intercept_x, intercept_y, intercept_z))
    if drawFits:
        slopes = [slope_x, slope_y, slope_z]
        intercepts = [intercept_x, intercept_y, intercept_z]
        pngs = c.plotAll(wet, errmax, doWvrCorrection, drawFits=[intercepts,slopes])
    if (len(pngs) > 1):
        buildPdfFromPngs(pngs,'XYZ_%s_all_antennas.pdf'%(wet),quiet=True)

def readAntennasFromCalPosition(xmlfile):
    """
    Reads the antenna names in a CalPosition.xml file, as written by tc_antpos, and returns
    a list of names.  Since there is no ASDM involved, there is no option for using the ADM library.
    -Todd Hunter
    """
    if (not os.path.exists(xmlfile)):
        print("Could not find file")
        return
    if (os.path.isdir(xmlfile)):
        xmlfile += '/CalPosition.xml'
    f = open(xmlfile,'r')
    antennas = []
    for line in f.readlines():
        loc = line.find('<antennaName>')
        if (loc >= 0):
            antennas.append(line[loc+len('<antennaName>'):].split('</antennaName>')[0].strip())
    f.close()
    return(np.unique(antennas))

def averageAntPosResults(antposlist='', antennas='', dropDatasets={},
                         errmax=2.0, minSnr=4.0, writeFile='', verbose=False):
    """
    This function runs Robert's CompareAntPosResults.py for a list of tc_antpos
    results files, takes the resulting weighted mean corrections, and writes
    them into a new synthetic results file that is meant to be used with
    EditPositions.py and UpdatePosition.sh.  Specific datasets can be dropped
    for specific antennas.  If you simply want to plot the comparision, then
    use au.compareAntPosResults
    -Todd Hunter
    Inputs:
    antposlist: list of results files, '' => use all in current directory
         These files are expected to be named in the following format:
              uid___XXXX_XXXXXXXX_XXXX_delays_U_refAnt_WET_antpos_result
    antennas: list of antennas to process, '' => use all in results files
    errmax: mm, passed to CompareAntPosResults.addResults()
    minSnr: passed to CompareAntPosResults.plotAntenna and used to recommend
            which antennas to update
    writeFile: (partial) name of one of the ASDM UIDs to be used when creating
               the new mean result. If not specified, then the first will be used.
    dropDatasets: dictionary keyed by antenna name, where values are the
                  datasets to ignore for that antenna.  If an antenna is not 
                  present in a dataset, then it is automatically ignored.
           Example: {'DA41':['Xc5ef'], 'DA43':['Xc5ef'], 'DA46':['Xc5ef'],
                     'DA47':['Xc5ef'], 'DA48':['Xc5ef'], 'DA49':['Xc5ef'],
                     'DA57':['Xc5ef'], 'DA59':['Xc5ef'], 'DA63':['Xc5ef'],
                     'DV01': ['Xc5ef'], 'DV20': ['Xc5ef'], 'DV21': ['Xc5ef'], 
                     'PM03':['Xa587','Xaf1b','X212a']}
    """
    if (not CAPRAvailable):
        if (casadef.python_library_directory.find('telcalsa') < 0):
            print("The TelCal libraries are not available to plain casa on this machine.")
            print("Instead, you will need to run this command in casapy-telcal.")
        else:
            print("For some reason, the TelCal libraries are not importable in au in casapy-telcal on this machine.")
        return
    if (antposlist == ''):
        # sort so that newest observation is first
        antposlist = sorted(glob.glob('*WET_antpos_result'), reverse=True)
        nresults = len(antposlist)
        print("Found %d results to compare" % (nresults))
        if (nresults < 1):
            return
    elif (antposlist.find('*') >= 0):
        # sort so that newest observation is first
        antposlist = sorted(glob.glob(antposlist), reverse=True)
        nresults = len(antposlist)
        print("Found %d results to compare" % (nresults))
        if (nresults < 1):
            return
    elif (type(antposlist) == str):
        antposlist = sorted(antposlist.split(','), reverse=True)
    from PositionEditor import PositionEditor  # used by averageAntPosResults and compareTMCDB
    threshold = 50e-6 # meters
    if (len(antennas) == 0):
        antennas = []
        for ap in antposlist:
            antennas += readAntennasFromCalPosition(ap+'/CalPosition.xml')
        antennas = np.unique(antennas)
    elif (type(antennas) == str):
        antennas = antennas.split(',')
    # Make sure that ASDM metadata is present in this directory for all datasets
    for ap in antposlist:
        asdm = ap[:ap.find('_delays')]
        if (not os.path.exists(asdm)):
            print("Exporting metadata for this asdm")
            os.system('asdmExport -m '+asdm)
    print("Found a total of %d antennas" % (len(antennas)))
    if (len(writeFile) == 0):
        writeFile = antposlist[0]
        asdm0 = writeFile[:writeFile.find('_delays')]
        newresults = writeFile + '.weightedMean'
        print("Will write results into new directory: %s" % (newresults))
    else:
        for ap in antposlist:
            if (ap.find(writeFile) >= 0):
                writeFile = ap
                asdm0 = ap[:ap.find('_delays')]
                break
        newresults = ap + '.weightedMean'
        print("Will write results into selected new directory: %s" % (newresults))
    if (os.path.exists(newresults)):
        print("Removing previous mean result")
        shutil.rmtree(newresults)
    os.mkdir(newresults)
    # Copy the three files that do not need to be changed
    for f in ['ASDM','CalData','CalReduction']:
        shutil.copyfile(writeFile+'/'+f+'.xml', newresults+'/'+f+'.xml')
    # Create a new file to receive the mean results
    f = open(newresults+'/CalPosition.xml', 'w')
    previous = open(antposlist[0]+'/CalPosition.xml','r')
    lines = previous.readlines()
    previous.close()
    # copy the first two header lines to the new file
    f.write(lines[0])
    f.write(lines[1].replace('<row>','')) # this will be written later
    means = {}
    rmss = {}
    pngs = []
    antennasToUpdate1Axis = []
    antennasToUpdate2Axes = []
    antennasToUpdate3Axes = []
    for antnum,antenna in enumerate(antennas):
        print("*******  Processing antenna %s (%d of %d) ***********" % (antenna, antnum+1, len(antennas)))
        myAntennaResults = antposlist[:]
        antennaResults = myAntennaResults[:]
        if antenna in list(dropDatasets.keys()):
            if (type(dropDatasets[antenna]) == str):
                dropDatasets[antenna] = dropDatasets[antenna].split(',')
            for dataset in dropDatasets[antenna]:
                for result in antennaResults:
                    if (result.find(dataset) >= 0):
                        print("Dropping dataset %s for %s because it contains %s" % (result, antenna,dataset))
                        myAntennaResults.remove(result)
        antennaResults = myAntennaResults[:]
        for result in antennaResults:
            myAntennas = readAntennasFromCalPosition(result+'/CalPosition.xml')
            if (antenna not in myAntennas):
                print("Dropping %s for %s because it was not in the array" % (result, antenna))
                myAntennaResults.remove(result)
        antennaResults = myAntennaResults[:]

        # Read pad and antenna position from each dataset
        asdmPad = []
        asdmPadPosition = []
        asdmAntennaPosition = []
        for result in antennaResults:
            myasdm = result[:result.find('_delays')]
            print("Processing ", myasdm)
            asdmPad.append(getAntennaPadsFromASDM(myasdm)[antenna])
            asdmPadPosition.append(getPadPositionsFromASDM(myasdm)[asdmPad[-1]])
            asdmAntennaPosition.append(readAntennaPositionFromASDM(myasdm)[antenna]['position'])
            
        # Reinstate the class for each antenna, since we may be using a different list of datasets.
        # In principle, this could be made faster by processing all antennas with no dropDatasets at once.
        c = CAPR.CompareAntPosResults()
        wet = 'WET'  # this is to emphasize that we choose the full wet path rather than the delta wet path
        c.addResults(antennaResults, wet, errmax, doWvrCorrection=False)
        station = c.station[antenna]
        if (antenna != c.refAntenna):
            print("Plotting antenna ", antenna)
            mean, rms, distance, height, meanAbsolute, recommendUpdate = c.plotAntenna(antenna, errmax, minSnr=minSnr)
            if (recommendUpdate == 1):
                antennasToUpdate1Axis.append(antenna)
            elif (recommendUpdate == 2):
                antennasToUpdate2Axes.append(antenna)
            elif (recommendUpdate == 3):
                antennasToUpdate3Axes.append(antenna)
            means[antenna] = mean  # ENU, in mm
            rmss[antenna] = rms    # ENU, in mm
            
            pb.figtext(0.1, 0.95, '%s/%s d=%6.0fm h=%3.0fm %s'%\
                       (antenna, station, distance, height, wet), ha='left', va='top')
            png = 'XYZ_%s_%s_%s.png'%(wet, antenna, station)
            pb.savefig(png)
            pngs.append(png)
        else:
            means[antenna] = [0,0,0]
            rmss[antenna] = [0,0,0]
        # Find this antenna's entry in the first antpos_result/CalPosition.xml file, read it, 
        # update the new positions, and write it to the new file in the new directory.
        # Note that the subsequent execution of EditPositions.py will not typically
        # apply all the updates due to the minSigma and threshold options.
        if (writeFile != ''):
#            previous = open(writeFile+'/CalPosition.xml','r')
            previous = open(antennaResults[0]+'/CalPosition.xml','r')
            lines = previous.readlines()
            previous.close()
            foundAntenna = False
            for line in lines:
                if (line.find('<antennaName> %s'%antenna) >= 0):
                    foundAntenna = True
                    totalChange = np.linalg.norm(means[antenna])
                    print("Putting position correction of %.3f mm for antenna %s." % (totalChange, antenna))
                    loc = line.find('positionOffset')
                    newline = line[:loc]
                    eastMeters = means[antenna][0]*0.001
                    northMeters = means[antenna][1]*0.001
                    upMeters = means[antenna][2]*0.001
                    # replace the existing offset from a single dataset with the mean values from all datasets
                    newline += 'positionOffset> 1 3 %.22f %.22f %.22f ' % (eastMeters, northMeters, upMeters)
                    newline += line[line.find('</positionOffset'):line.find('positionErr')]
                    newline += 'positionErr> 1 3 %.22f %.22f %.22f ' % (rmss[antenna][0]*0.001,
                                                                        rmss[antenna][1]*0.001,
                                                                        rmss[antenna][2]*0.001)
                    newline += line[line.find('</positionErr'):]
                    f.write('<row>\n')
                    f.write(newline)
            if not foundAntenna:
                print("Did not find an entry for %s in %s.  This should not happen, so there must be a bug." % (antenna,antennaResults[0]))
                return
    if writeFile != '':
        if (casaVersion >= '4.2' and os.path.exists(asdm0)):
            png = asdm0 + '.plotants_log.png'
            plotantsFromASDM(asdm,plotfile=png,logarithmicOnly=True)
            pngs.append(png)
        pdfname = newresults + '_averageAntPosResults.pdf'
    else:
        pdfname = 'averageAntPosResults.pdf'
    buildPdfFromPngs(pngs, pdfname, quiet=True)
    if writeFile != '':
        f.write('</CalPositionTable>\n')
        f.close()
        print("Wrote mean corrections into new directory = ", newresults)
        print("%d antennas have corrections > %.1f sigma on 1 axis: " % (len(antennasToUpdate1Axis),minSnr), antennasToUpdate1Axis)
        print("%d antennas have corrections > %.1f sigma on 2 axis: " % (len(antennasToUpdate2Axes),minSnr), antennasToUpdate2Axes)
        print("%d antennas have corrections > %.1f sigma on 3 axes: " % (len(antennasToUpdate3Axes),minSnr), antennasToUpdate3Axes)
        print("Now you can transfer this directory to red-osf and run:")
        print("  ExportPositionModel.py -c CURRENT.AOS")
        print("  EditPositions.py -f %s -i PositionModel-nnnnn.xml" % (newresults))
    return c

def findLineNumberAndTimestamp(lines, string, start=0, string2='', stopUponTcleanEnd=False):
    """
    Takes a CASA log file, locates the specified string (starting from a 
    specified line number)
    and computes the timestamp of the line that contains it.
    string2: if present, then this string must also be in the line
    Returns: line number, and value in MJD seconds
    -Todd Hunter
    """
#    print("findLineNumberAndTimestamp is calling findLineNumber(string='%s', string2='%s')" % (string, string2))
    lineNumber = findLineNumber(lines, string, start, string2, stopUponTcleanEnd)
    token = lines[lineNumber].split()
    timestamp = dateStringToMJDSec(token[0] + ' ' + token[1], verbose=False)
    return lineNumber, timestamp
    
def findLineNumber(lines, string, start=0, string2='', stopUponTcleanEnd=False):
    """
    Finds the first line number in a text file that contains the specified 
    string, starting at line number = start.
    string2: if present, then this string must also be in the line
    -Todd Hunter
    """
    startLine = -1
    for i,line in enumerate(lines[start:]):
        if line.find(string) >= 0:
            if string2 == '' or line.find(string2) >= 0:
                startLine = i+start
                break
            else:
                print("findLineNumber(): Found %s but not %s" % (string,string2))
        if stopUponTcleanEnd and line.find('End Task: tclean') > 0:
            break
    return startLine

def findImageSpwsFromCasalog(casalog, intent='OBSERVE_TARGET', debug=False):
    """
    Reads an ALMA imaging pipeline CASA log file (i.e. containing tclean commands) and 
    determines the list of spws imaged.
    casalog: either the name of a CASA log file, or a list of lines read from one.
    intent: limit the search to tclean commands that specify this intent string
    """
    if type(casalog) == str:
        f = open(casalog,'r')
        lines = f.readlines()
        f.close()
    else:
        lines = casalog
    spws = []
    cleaningPresent = False
    for line in lines:
        if (line.find('Executing tclean(') > 0):
            cleaningPresent = True
            if (line.find(intent) > 0):
                if debug: print(line)
                token = line.split(', spw=[')
                if len(token) > 1:
                    myspw = int(token[1].split(',')[0].split(':')[0].rstrip("]").strip("'"))
                    spws.append(myspw)
    if cleaningPresent and len(spws) == 0 and intent.find('OBSERVE_TARGET') == 0:
        print("Only calibrator imaging is present in this log file.")
    if not cleaningPresent:
        print("Did not find any tclean commands in this log file.")
    return sorted(np.unique(spws))

def casaVersionFromCaltable(caltable):
    """
    Returns the CASA version from the keywords of a caltable.
    Example: '5.3.0-131'
    -Todd Hunter
    """
    mytb = tbtool()
    mytb.open(caltable)
    version = mytb.getkeyword('CASA_Version')
    mytb.close()
    return version
    
def casaVersionFromLogfile(casalog, nlines=1000):
    """
    Reads the casa version from the first 1000 lines.  Returns string like: '5.3.0-104'
    or '6.0' if it is not found (because it did not write the version to the log until
    CAS-12851 was fixed).
    Todd Hunter
    """
    f = open(casalog,'r')
    version = ''
    for i in range(1000):
        line = f.readline()
        if line.find('CASA Version') > 0:
            version = line.split('CASA Version ')[1].split('\n')[0].strip()
    f.close()
    if version == '': return('6.0')
    return version

def tcleanMemoryFromLogfiles(dirlist):
    """
    dirlist: parent directory of several pipeline runs, or a python list of directories to examine
    Returns: dictionary keyed by pipeline run, with floating point value in GB
    """
    memory = {}
    if type(dirlist) == str:
        dirlist = sorted(glob.glob(os.path.join(dirlist,'*')))
    for mydir in dirlist:
        memory[os.path.basename(mydir)] = tcleanMemoryFromLogfile(mydir)
    return memory

def tcleanMemoryFromLogfile(casalog=''):
    """
    casalog: either a casa log file or a pipeline root directory, e.g. 2017.1.00508.S_YYYY_MM_DDTHH_MM_SS.SSS
    Returns: median value of all appearances of 'Available memory '
    """
    if casalog == '' or os.path.isdir(casalog):
        logs = findPipelineRunCasaLogs(casalog)
        casalog = findPipelineCasaLogfile(os.path.dirname(logs[0]),sortByModificationTime=True,fast=True)
        print("Found log: %s" % (casalog))
    f = open(casalog,'r')
    version = ''
    lines = f.readlines()
    f.close()
    memory = []
    for line in lines:
        if line.find('Available memory ') > 0:
            memory.append(float(line.split('Available memory')[1].split('(')[0]))
    print("Median: %.1f GB, max: %.1f GB, min: %.1f GB" % (np.median(memory), np.max(memory), np.min(memory)))
    return np.median(memory)

def nodeFromLogfile(casalog='', nlines=100):
    """
    Reads the pipeline version from the first 100 lines of a CASA log file.  
    casalog: either a casa log file or a pipeline root directory, e.g. 2017.1.00508.S_YYYY_MM_DDTHH_MM_SS.SSS
    Returns string like: 'cvpost040'
    Examples if pwd is a working directory:
       au.pipelineVersionFromLogfile('casa-20180521-180502.log')
       au.pipelineVersionFromLogfile()  # uses the most recent containing "Analyzing pipeline"
    Example from anywhere:
       au.pipelineVersionFromLogfile('/lustre/naasc/sciops/comm/thunter/pipeline/root/2017.1.00508.S_2018_05_21T16_50_38.786')
    -Todd Hunter
    """
    if casalog == '' or os.path.isdir(casalog):
        logs = findPipelineRunCasaLogs(casalog)
        casalog = findPipelineCasaLogfile(os.path.dirname(logs[0]),sortByModificationTime=True,fast=True)
        print("Found log: %s" % (casalog))
    f = open(casalog,'r')
    version = ''
    for i in range(100):
        line = f.readline()
        if line.find('Pipeline version') > 0:
            version = line.split('running on ')[1].split('\n')[0]
    f.close()
    return version

def pipelineVersionFromLogfile(casalog='', nlines=1000):
    """
    Reads the pipeline version from the first 1000 lines of a CASA log file.  
    Returns string like: '41483M (trunk)'  or '2020.1.0.23'
    casalog: a log file, or a pipeline working directory or a parent directory
    Examples if pwd is a working directory:
       au.pipelineVersionFromLogfile('casa-20180521-180502.log')
       au.pipelineVersionFromLogfile()  # uses the most recent containing "Analyzing pipeline"
    Example from anywhere:
       au.pipelineVersionFromLogfile('/lustre/naasc/sciops/comm/thunter/pipeline/root/2017.1.00508.S_2018_05_21T16_50_38.786')
    -Todd Hunter
    """
    if casalog == '' or os.path.isdir(casalog):
        logs = findPipelineRunCasaLogs(casalog)
        casalog = findPipelineCasaLogfile(os.path.dirname(logs[0]),sortByModificationTime=True,fast=True)
        print("Found log: %s" % (casalog))
    f = open(casalog,'r')
    version = ''
    for i in range(nlines):
        line = f.readline()
        if line.find('Pipeline version') > 0:
            version = line.split('Pipeline version ')[1].split('\n')[0].split('running')[0].strip()
    f.close()
    return version

def extractTcleanCommandsAndModify(casalog, intent='OBSERVE_TARGET', 
                                   verbose=True, extractParameter='', spw='',
                                   task='tclean', stage=-1, newRobust=None,
                                   niter='', newWidth=None, newNchan=None,
                                   imagenameAppend='.robust1',newStartfreq=None,
                                   imagenamePrepend='',visPrepend='', output='',
                                   newUsemask=None, iterImage=None, 
                                   newGrowiterations=None, newParallel=None,
                                   newSidelobethreshold=None, 
                                   newPerchanweightdensity=None,
                                   newLownoisethreshold=None, newThreshold=None,
                                   newCyclefactor=None, newCalcres=None, 
                                   newCalcpsf=None, fieldname=None):
    """
    Calls extractTcleanCommands, then modifies the robust value, and (optionally)
    the imagename and the vis names.  
    casalog: either a pipeline working directory, or a single casa log file
    stage: stage number of pipeline, e.g. 30 (cal+img_Pipeline2020) or 
          28 (cal+img_Pipeline2019) or 7 (img) for hif_findcont
    output: text file to create with the modified commands
    newRobust: set to None to not modify the robust, and ignore imagenameAppend
         (i.e. just extract the unmodified commands)
    newStartfreq: set to None to not modify the startfreq; integer channel or 
              a frequency string with units, e.g. '345.796GHz'
    newWidth: set to None to not modify the width; integer or string with units
    newNchan: set to None to not modify nchan; integer or integer string
    newUsemask: set to None to not modify usemask; string, e.g. 'user'
    newGrowiterations: set to None to not modify growiterations; integer or string
    newSidelobethreshold: set to None to not modify sidelobethreshold; float or string
    newLownoisethreshold: set to None to not modify lownoisethreshold; float or string
    newThreshold: set to None to not modify the clean threshold
    The following 3 only are changed when niter>0 in original command
    newCyclefactor: set to None to not modify cyclefactor
    newCalcres: set to None to not modify calcres setting
    newCalcpsf: set to None to not modify calcpsf setting
    newPerchanweightdensity: set to None to not modify perchanweightdensity
    newParallel: set to None to not modify parallel setting
    spw: if specified, then require the following string:  spw=['<spw>
            can also be an integer list [5,7]
    fieldname: if specified, the require the following string: field='<fieldname>'
        or field='"<fieldname>"'
    niter: if specified, then require the following string to be present:  niter=<niter>
    iterImage: integer (0,1 or 2); if present, then only return iter<iter> images
    -Todd Hunter
    """
    cmds = extractTcleanCommands(casalog, intent, verbose, extractParameter, 
                                 task, stage, fieldname=fieldname)
    newcmds = []
    if output != '':
        f = open(output, 'w')
    if (newStartfreq is not None or newWidth is not None) and newRobust is not None:
        print("Cannot set both newWidth and newChan without also setting newStartfreq")
        return
    if cmds is None:
        print("Found no commands")
        return
    for cmd in cmds:
        if spw != '':
            if type(spw) == list:
                keep = False
                for myspw in spw:
                    if cmd.find("spw=['%s'"%(str(myspw))) > 0:
                        keep = True
                        break
                if not keep:
                    continue
            else:
                if cmd.find("spw=['%s'"%(str(spw))) < 0:
                    continue
        if niter != '':
            if cmd.find("niter=%d" % (niter)) < 0:
                continue
        if iterImage is not None:
            if cmd.find("iter%d" % (iterImage)) < 0:
                continue
        if newStartfreq is not None:
            startfreq = cmd.split('start=')[1].split(',')[0]
            if type(newStartfreq) == str:
                newstart = "'%s'"%(newStartfreq)
            else: # integer channels
                newstart = "%d" % (newStartfreq)
            print("Replacing %s with %s" % (startfreq,newstart))
            newcmd = cmd.replace(startfreq,newstart)
            if newWidth is not None:
                width = newcmd.split('width=')[1].split(',')[0]
                if type(newWidth) == str:
                    newWidthString = "'%s'"%(newWidth)
                else:
                    newWidthString = "%s"%(newWidth)
                print("Replacing %s with %s" % (width,newWidthString))
                newcmd = newcmd.replace(width,newWidthString)
                if imagenameAppend == '.robust1':
                    if newStartfreq == '' and newWidth == '':
                        imagenameAppend = '.startandwidthblank'
                    elif newStartfreq == '':  # newWidth=''
                        imagenameAppend = '.startblankwidth%s' % (newWidth)
                    else:  # newStart != '' and newWidth=''
                        imagenameAppend = '.start%swidthblank' % (newstart)
            else:
                if imagenameAppend == '.robust1':
                    if newStartfreq == '':
                        imagenameAppend = '.startblank'
                    else:
                        imagenameAppend = '.start%s' % (newstart)
            if newNchan is not None:
                nchan = newcmd.split('nchan=')[1].split(',')[0]
                print("Replacing %s with %s" % (nchan,str(newNchan)))
                newcmd = newcmd.replace('='+nchan,'='+str(newNchan))
        elif newWidth is not None:
            width = cmd.split('width=')[1].split(',')[0]
            newWidthString = "'%s'"%(newWidth)
            print("Replacing %s with %s" % (width,newWidthString))
            newcmd = cmd.replace(width,newWidthString)
        elif newNchan is not None:
            nchan = cmd.split('nchan=')[1].split(',')[0]
            print("Replacing %s with %s" % (nchan,str(newNchan)))
            newcmd = cmd.replace('='+nchan,'='+str(newNchan))
        else:
            newcmd = cmd
            # do not do an automatic image rename
            if imagenameAppend == '.robust1':
                imagenameAppend = ''
        if newRobust is not None:
            robust = newcmd.split('robust=')[1].split(',')[0]
            newcmd = newcmd.replace('robust=%s'%(robust), 'robust=%s'%(str(newRobust)))
        if newUsemask is not None:
            oldusemask = newcmd.split('usemask=')[1].split(',')[0]
            newcmd = newcmd.replace('usemask=%s'%(oldusemask), "usemask='%s'"%(newUsemask))
        if newGrowiterations is not None:
            growiterations = newcmd.split('growiterations=')[1].split(',')[0]
            newcmd = newcmd.replace('growiterations=%s'%(growiterations), "growiterations=%s"%(str(newGrowiterations)))
        if newSidelobethreshold is not None:
            sidelobethreshold = newcmd.split('sidelobethreshold=')[1].split(',')[0]
            newcmd = newcmd.replace('sidelobethreshold=%s'%(sidelobethreshold), "sidelobethreshold=%s"%(str(newSidelobethreshold)))
        if newLownoisethreshold is not None:
            lownoisethreshold = newcmd.split('lownoisethreshold=')[1].split(',')[0]
            newcmd = newcmd.replace('lownoisethreshold=%s'%(lownoisethreshold), "lownoisethreshold=%s"%(str(newLownoisethreshold)))
        if newCalcres is not None:
            if newcmd.find('calcres') >= 0 and newcmd.find('niter=0') < 0:
                calcres = newcmd.split('calcres=')[1].split(',')[0]
                newcmd = newcmd.replace('calcres=%s'%(calcres), "calcres=%s"%(str(newCalcres)))
        if newCalcpsf is not None:
            if newcmd.find('calcpsf') >= 0 and newcmd.find('niter=0') < 0:
                calcpsf = newcmd.split('calcpsf=')[1].split(',')[0]
                newcmd = newcmd.replace('calcpsf=%s'%(calcpsf), "calcpsf=%s"%(str(newCalcpsf)))
        if newPerchanweightdensity is not None:
            if newcmd.find('perchanweightdensity') >= 0:
                perchanweightdensity = newcmd.split('perchanweightdensity=')[1].split(',')[0]
                newcmd = newcmd.replace('perchanweightdensity=%s'%(perchanweightdensity), "perchanweightdensity=%s"%(str(newPerchanweightdensity)))
        if newParallel is not None:
            if newcmd.find('parallel') >= 0:
                parallel = newcmd.split('parallel=')[1].split(',')[0]
                newcmd = newcmd.replace('parallel=%s'%(parallel), "parallel=%s"%(str(newParallel)))
        if newThreshold is not None:
            if newcmd.find(' threshold=') >= 0:
                threshold = newcmd.split(' threshold=')[1].split(',')[0]
                newcmd = newcmd.replace(" threshold=%s"%(threshold), " threshold='%s'"%(str(newThreshold)))
        if newCyclefactor is not None:
            if newcmd.find('niter=0') < 0:
                if newcmd.find('cyclefactor') >= 0:
                    cyclefactor = newcmd.split('cyclefactor=')[1].split(',')[0]
                    newcmd = newcmd.replace('cyclefactor=%s'%(cyclefactor), "cyclefactor=%s"%(str(newCyclefactor)))
                else:
                    print("Appending cyclefactor to end of command")
                    newcmd = newcmd[:-1] + ', cyclefactor=%s)'%(newCyclefactor)
        if imagenameAppend != '':
            imagename = newcmd.split("imagename='")[1].split("'")[0]
            newcmd = newcmd.replace(imagename,os.path.join(imagenamePrepend,imagename+imagenameAppend))
        if visPrepend != '':
            vislistString = newcmd.split("vis=[")[1].split(']')[0]
            vislist = vislistString.replace(' ','').split(',')
            print("vislist = ", vislist)
            newlist = ["'"+os.path.join(visPrepend,i.strip("'"))+"'" for i in vislist]
            print("newlist = ", str(newlist))
            newvislist = ', '.join(newlist)
            print("newvislist = ", str(newvislist))
            newcmd = newcmd.replace(vislistString, newvislist)
        newcmds.append(newcmd)
        if output != '':
            f.write(newcmd+'\n')
    if output != '':
        print("Wrote ", output)
        f.close()
    return newcmds

def extractTcleanCommands(casalog, intent='OBSERVE_TARGET', verbose=True,
                          extractParameter='', task='tclean', stage=-1, 
                          dictionaries=False, spw=None, output='', 
                          fieldname=None, includeCopyTree=False, vis=''):
    """
    Extract tclean task calls from a pipeline run (or a specific casa log)
    casalog: either a pipeline working directory, or a single casa log file
    intent: limit tclean calls to whose containing this intent
    extractParameter: if specified, then only show the value of this parameter, e.g. 'spw'
    stage: either an integer or the word 'findcont' (if casalog is directory)
    spw: if not None, then restrict matches to this single spw (integer or string integer)
    fieldname: if not None, then restrict matches to fieldname
    output: output filename to write
    vis: relevant for extractParameter='spw' which is a function of vis
         for  multi-EB projects.  minimium match is sufficient, e.g. 'X124b4'
    Assumptions: successive parameters are separated by ", "
    dictionaries: return array of dictionaries
    -Todd Hunter
    """
    if stage == 'findcont':
        if os.path.isdir(casalog):
            stage = findFindcontStageNumber(casalog)
    casalog = findCasaLogWithTclean(casalog, intent, verbose, stage)
    if casalog is None:
        return
    if includeCopyTree:
        results = grep(casalog,task+r'(\|copytree(')[0].split('\n') 
    else:
        results = grep(casalog,task+'(')[0].split('\n') 
    trimmed = []

    if dictionaries:
        intparms=['niter','nchan','chanchunks','growiterations']
        floatparms=['pblimit','sidelobethreshold','robust','minpercentchange','minbeamfrac','lownoisethreshold','noisethreshold','negativethreshold']
        boolparms=['mosweight','restoration','parallel','dogrowprune','usepointing','pbcor']
        intarrparms=['imsize']
        arrarrparms=['scan','antenna','vis','cell','spw']
        dicts = []
    searchingForCopyTree = False
    requireColon = False
    for result in results:
        token = result.split('Executing ')
        if len(token) > 1:
            if result.find('copytree(') > 0 and includeCopyTree:
                if searchingForCopyTree:
                    trimmed.append('shutil.'+result.split('Executing ')[1])
                continue
            if result.find(intent) > 0 and (stage == -1 or result.find('.s%d_'%stage) > 0) and extractParameter == '':
                searchingForCopyTree = False # we are done with any prior cmd
                if spw is None and fieldname is None:
                    trimmed.append(token[1])
                    searchingForCopyTree = True
                elif fieldname is None: # spw was set
                    myspw = token[1].split('spw=')[1].split(',')[0].replace('[','').replace(']','').replace("'",'').split(':')[0]
                    if str(spw) == myspw:
                        trimmed.append(token[1])
                        searchingForCopyTree = True
                elif spw is None:
                    myfield = token[1].split('field=')[1].split(',')[0].replace('[','').replace(']','').replace("'",'').replace('"','')
                    if str(fieldname) == myfield:
                        trimmed.append(token[1])
                        searchingForCopyTree = True
                else: # both spw and fieldname were set
                    myspw = token[1].split('spw=')[1].split(',')[0].replace('[','').replace(']','').replace("'",'').split(':')[0]
                    myfield = token[1].split('field=')[1].split(',')[0].replace('[','').replace(']','').replace("'",'').replace('"','')
                    if str(fieldname) == myfield and str(spw) == myspw:
                        trimmed.append(token[1])
                        searchingForCopyTree = True
            elif extractParameter != '':
                if extractParameter == 'spw:':
                    extractParameter = 'spw'
                    requireColon = True
                loc = token[1].find(extractParameter+'=')
                if loc > 0:
                    # find the vis order
                    vislist = token[1].split('vis=[')[1:][0].split(']')[0].replace("'",'').replace(' ','').split(',')
                    spwindex = -1
                    if vis != '':
                        vis = vis.rstrip('/')
                        for vctr,v in enumerate(vislist):
                            if v.find(vis) >= 0:
                                spwindex = vctr
                        if spwindex < 0:
                            print("Requested vis not found: %s" % (vis))
                            return
                    else:
                        spwindex = 0
                    myline = token[1].split(extractParameter)[1:][0]
                    line = myline.split('=')[1].split(', ')[spwindex].replace('[','').replace(']','').replace("'","")
                    mystring = token[1].split('spw=')[1].split(',')[0].replace('[','').replace(']','').replace("'",'')
                    colonPresent = mystring.find(':') >= 0
                    myspw = token[1].split('spw=')[1].split(',')[0].replace('[','').replace(']','').replace("'",'').split(':')[0]
                    myfield = token[1].split('field=')[1].split(',')[0].replace('[','').replace(']','').replace("'",'').replace('"','')
                    if (spw is None or str(spw) == myspw) and (fieldname is None or str(fieldname) == myfield):
                        if not requireColon or colonPresent:
                            trimmed.append(line)
                            searchingForCopyTree = True
            
        if dictionaries and len(trimmed)>0:
            if trimmed[-1].find('copytree') > 0:
                continue
            cmd=trimmed[-1][7:-1].strip(")")
            parms=[parm.split(",")[-1].strip(" ") for parm in cmd.split("=")][:-1]
            thisdict={}
            for i in range(len(parms)-1):
                thisdict[parms[i]]=cmd.split(parms[i])[1].split(parms[i+1])[0].strip("=, '")
            thisdict[parms[-1]]=cmd.split(parms[-1])[1].strip("=, ")
            # problem with noisethreshold and lownoisethreshold:
            if 'noisethreshold' in thisdict:
                x=thisdict['noisethreshold']
                if ',' in x:
                    thisdict['noisethreshold']=x.split(",")[0]
            for p in intparms:
                if p in thisdict:
                    thisdict[p]=int(thisdict[p])
            for p in boolparms:
                if p in thisdict:
                    if thisdict[p]=='True':
                        thisdict[p]=True
                    else:
                        thisdict[p]=False
            for p in floatparms:
                if p in thisdict:
                    thisdict[p]=float(thisdict[p])
            for p in intarrparms:
                if p in thisdict:
                    if thisdict[p][0]=='[':
                        thisdict[p]=[int(x.strip("' ")) for x in thisdict[p][1:-1].split(",")]
            for p in arrarrparms:
                if p in thisdict:
                    if thisdict[p][0]=='[':
                        thisdict[p]=[x.strip("', ") for x in thisdict[p][2:-2].split("'") if len(x.strip("', "))>0]

            dicts.append(thisdict)
    if output != '':
        mydir = os.path.dirname(output)
        if mydir == '':
            mydir = './'
            output = './' + output
        if not os.access(mydir,  os.W_OK):
            print("Could not write file due to access permissions on %s." % (mydir))
        else:
            f = open(output, 'w')
            if includeCopyTree:
                f.write('import shutil\n')
            for trim in trimmed:
                f.write(trim+'\n')
            f.close()
    if dictionaries:
        return dicts
    else:
        return trimmed

def findCasaLogWithTclean(casalog='', intent='OBSERVE_TARGET', verbose=True, stage=-1, task='tclean'):
    """
    Search for all logs in current directory (or wildcard path provided)
    and pick first one in time that contains a tclean command with the 
    specified intent
    casalog: either a log file or a directory containing it
    intent: limit tclean calls to whose containing this intent
    -Todd Hunter
    """
    if casalog == '' or os.path.isdir(casalog):
        if casalog == '':
            logs = sorted(glob.glob('casa*log'))
        else:
            logs = sorted(glob.glob(os.path.join(casalog,'casa*log')))
            if len(logs)<1:
                logs = sorted(glob.glob(os.path.join(casalog,'*','casa*log')))
                concatlog = os.path.join(casalog,'concatted.log')
                with open(concatlog,'wa') as f:
                    for log in logs:
                        with open(log) as infile:
                            f.write(infile.read())
                logs = [concatlog]
            casalog = ''
        if len(logs) < 1:
            print("Could not find any logs")
            return
        for log in logs:
            print("Search log: ", log)
            lines = grep(log,task+'(')[0].split('\t')
            for line in lines:
                if len(intent) > 0:
                    if line.find(intent) > 0:
                        if stage == -1 or line.find('.s%d_'%stage) > 0:
                            if verbose:
                                print("Using log: %s" % (log))
                            casalog = log
                            break
                else:
                    casalog = log
                    break
        if casalog == '':
            if stage > -1:
                print("No casa logs have %s with intent=%s and stage=%d" % (task,intent,stage))
            elif intent != '':
                print("No casa logs have %s with intent=%s" % (task,intent))
            else:
                print("No casa logs have %s" % (task))
            return
    if not os.path.exists(casalog):
        print("Could not find casa log")
        return
    return casalog

def timeTargetflag(casalog='./', task='hifa_targetflag'):
    """
    Determine the time for various pieces of the the hifa_targetflag task.
    casalog: either a log file or a directory containing it
    Returns: taskTime, plottingTime, applycalTime (all in minutes)
    -Todd Hunter
    """
    casalog = findCasaLogWithTclean(casalog,intent='',task=task)
    print("Found casalog: ", casalog)
    f = open(casalog,'r')
    lines = f.readlines()
    f.close()
    startTime = None
    applycalTime = 0
    plottingTime = 0
    startPlot = None
    startApplycal = None
    for i,line in enumerate(lines):
        if line.find('...'+task) > 0:
            print("Found start of task at line ", i)
            startTime = ' '.join(line.split()[:2])
        if startTime is None: continue
        if startPlot is None and line.find('Begin Task: plotms') > 0:
            print("Found plotms on line ", i)
            startPlotTime = ' '.join(line.split()[:2])
        if startApplycal is None and line.find('Begin Task: applycal') > 0:
            print("Found applycal start on line ", i)
            startApplycal = ' '.join(line.split()[:2])
        if line.find('End Task: plotms') > 0:
            print("Found plotms end on line ", i)
            endPlotTime = ' '.join(line.split()[:2])
            plottingTime += dateStringDifference(startPlotTime, endPlotTime)
            startPlot = None
        if line.find('End Task: applycal') > 0:
            print("Found applycal end on line ", i)
            endApplycal = ' '.join(line.split()[:2])
            applycalTime += dateStringDifference(startApplycal, endApplycal)
            startApplycal = None
        if line.find('TargetflagResults') > 0 or line.find('...hif_applycal') > 0:
            print("Found end of task at line ", i)
            endTime = ' '.join(line.split()[:2])
            break
    taskTime = dateStringDifference(startTime, endTime)
    plottingTimePercentage = 100.0*plottingTime/taskTime
    applycalTimePercentage = 100.0*applycalTime/taskTime
    print("plots take %.1f minutes = %.2f%% of the total = %.1f minutes" % (plottingTime, plottingTimePercentage,taskTime))
    print("applycal take %.1f minutes = %.2f%% of the total = %.1f minutes" % (applycalTime, applycalTimePercentage,taskTime))
    return taskTime, plottingTime, applycalTime

def timeTclean(casalog='', spw=None, majorCycle=2, showLineNumber=False, showTimestamp=True, 
               field=None, intent='OBSERVE_TARGET', debug=False, iter=1, style='cube', sourceType='sci', quiet=False):
    """
    Searches for the appearance of spw%d.cube.I.iter<iter>' in an ALMA pipeline casa log file
    and computes the time required for each stage of the specified major cycle (2 or higher)
    casalog: if not specified, then search for all logs in current directory 
           and pick first one in time that contains a tclean command with the 
           specified intent
    spw: integer or string integer; if not specified, then it will list the available spws and exit
    majorCycle: integer >= 2;  set to -1 to not search for major/minor cycles
    field: string specifying name of field to restrict the search to
    intent: limit the search to spws that had images produced with this intent.
            Note that cubes are only produced for OBSERVE_TARGET objects, so 
            this is the only sensible value to use.
    style: 'cube', 'mfs', 'cont', or 'findcont' (findcont sets majorCycle=-1)
    sourceType: '' (all), 'sci', 'bp', 'ph', 'chk'
    -Todd Hunter
    """
    styles = ['cube', 'mfs', 'cont', 'findcont']
    if style not in styles:
        print("style must be one of: ", styles)
        return
    if style == 'findcont':
        majorCycle = -1
    casalog = findCasaLogWithTclean(casalog)
    if casalog is None: return
    if debug:
        print("casalog = ", casalog)
    version = casaVersionFromLogfile(casalog)
    f = open(casalog,'r')
    lines = f.readlines()
    f.close()
    if spw is None:
        spws = findImageSpwsFromCasalog(lines, intent=intent)
        print("You must specify one spw.  Available: %s." % str(spws))
        return
    targets = []
    if style == 'cont':
        targets.append(".%s.I.iter%d'" % (style, iter))
    else:
        if field is None:
            if style == 'findcont':
                targets.append("_%s.spw%s.mfs.I.findcont'" % (sourceType, str(spw)))
            else:
                targets.append("_%s.spw%s.%s.I.iter%d'" % (sourceType, str(spw), style, iter))
        else:
            if style == findcont:
                targets.append("%s_%s.spw%s.I.findcont'" % (field,sourceType,str(spw)))
            else:
                targets.append("%s_%s.spw%s.%s.I.iter%d'" % (field,sourceType,str(spw),style,iter))
    if debug:
        print("Searching for ", targets[-1])
    if majorCycle > 0:
        targets.append('Run Major Cycle %d' % (majorCycle))
        targets.append("Setting up an auto-mask")
        if version.find('5.3.') == 0:
            targets.append("Start pruning: the initial threshold mask") # Cycle 6
        else:
            targets.append("Pruning the current mask") # Cycle 5
        targets.append("rowing the previous mask")
        if version.find('5.3.') == 0:
            targets.append("pruning: on the grow mask")
        else:
            targets.append("Pruning the growed previous mask")
            targets.append("Creating a mask for negative features")
        targets.append("Number of pixels in the clean mask")
        targets.append("Run Minor Cycle")
        targets.append("Run Major Cycle %d" % (majorCycle+1))
    targets.append("End Task: tclean")
    mjdsec = {}
    target = targets[0]
    string2 = 'tclean('
    lineNumber, mjdsec[target] = findLineNumberAndTimestamp(lines, target, string2=string2)
    if lineNumber < 0: 
        if field is not None:
            targets[0] = "%s_%s.spw%s.%s.I.iter%d'" % (field,sourceType,str(spw),style,iter)
            target = targets[0]
            lineNumber, mjdsec[target] = findLineNumberAndTimestamp(lines, target, string2='tclean(')
            if lineNumber < 0 and debug:
                print("Did not find ", target)
        if lineNumber < 0:
            if field is not None:
                # Try different number of underscores
                if debug:
                    print("Searching with a second underscore")
                targets[0] = "%s__%s.spw%s.%s.I.iter%d'" % (field,sourceType,str(spw),style,iter)
                target = targets[0]
                lineNumber, mjdsec[target] = findLineNumberAndTimestamp(lines, target, string2='tclean(')
            if lineNumber < 0:
                print("c) Could not find %s" % (target))
                if iter == 1:
                    print("   Try iter=0")
                elif iter == 2:
                    print("   Try iter=1")
                return
    myline = ''
    strchars = 34
    cube = lines[lineNumber].split("imagename='")[1].split("'")[0]
    for i, target in enumerate(targets[1:-1]):
#        print("i=%d, %s, len(targets[1:])-1=%d" % (i, target, len(targets[1:])-1))
        newLineNumber, mjdsec[target] = findLineNumberAndTimestamp(lines, target, lineNumber+1, stopUponTcleanEnd=True)
        if newLineNumber < 0: 
            if target.find('Major Cycle') >= 0:
                if debug:
                    print("a) Could not find %s from line %d" % (target, lineNumber+1))
                target = target.replace('Run ','Run (Last) ')
                newLineNumber, mjdsec[target] = findLineNumberAndTimestamp(lines, target, lineNumber+1)
                if newLineNumber < 0: 
                    print("a) Could not find %s from line %d" % (target, lineNumber+1))
                    continue
                else:
                    print("Changing '%s' to '%s', which has mjdsec=%f" % (targets[i+1],target,mjdsec[target]))
                    targets[i+1] = target
            else:
                if debug:
                    print("b) Could not find ", target)
                continue
        lineNumber = newLineNumber
        if showLineNumber:
            myline += '%d: ' % (lineNumber)
        if showTimestamp:
            myline += '%s: ' % (mjdsecToDatestring(mjdsec[targets[i]]))
        if i==0:
            myline += "tclean("
            mystrchars = strchars - len('tclean(')
        else:
            mystrchars = strchars
        myline += "%*s -- %7.1f minutes -- %-*s" % (mystrchars, targets[i][:strchars], (mjdsec[target]-mjdsec[targets[i]])/60., strchars, target[:strchars])
        if showTimestamp:
            myline += ' :%s\n' % (mjdsecToDatestring(mjdsec[target]))
        if debug:
            print("     %f to %f   (line X to %d)" % (mjdsec[targets[i]], mjdsec[target], lineNumber))
    if majorCycle < 0:
        if showLineNumber:
            myline += '%d: ' % (lineNumber)
        if showTimestamp:
            myline += '%s: ' % (mjdsecToDatestring(mjdsec[target]))
        myline += "tclean(%s\n" % (target)
        
    newLineNumber, mjdsec[targets[-1]] = findLineNumberAndTimestamp(lines, targets[-1], lineNumber+1)
    if showLineNumber:
        myline += '%d: ' % (newLineNumber)
    if showTimestamp:
        myline += "%s: " % (mjdsecToDatestring(mjdsec[targets[-1]]))
    myline += " %s\n" % targets[-1]
    if not quiet:
        print(myline)
    return mjdsec['End Task: tclean'] - mjdsec[targets[0]]

def findPipelineCasaVersions(mydirs, fast=True, searchString='Beginning pipeline'):
    """
    Runs findPipelineCasaVersion on multiple pipeline runs
    mydirs: either a python list of pipeline run directories or working directories, or a 
        comma-delimited list thereof
    -Todd Hunter
    """
    if type(mydirs) == str:
        mydirs = mydirs.split(',')
    mylist = []
    for mydir in mydirs:
        mylist.append(findPipelineCasaVersion(mydir, fast, searchString))
    return mylist

def findPipelineCasaVersion(mydir, fast=True, searchString='Beginning pipeline',
                            verbose=False, uselogfile=False):
    """
    mydir: either a working dir, or a parent dir like '2018.1.01259.S_YY_MM_DDTHH_MM_SS.SSS', or a string with wildcard
    fast: passed to findPipelineCasaLogfile
    uselogfile: if True, use casa log, otherwise parse the weblog
    Finds pipeline logfile and pulls the casa version from it.
    -Todd Hunter
    """
    if mydir in ['','./','.']:
        mydir = os.getcwd()
    if mydir.find('*'):
        mydirs = sorted(glob.glob(mydir))
    else:
        mydirs = [mydir]
    for mydir in mydirs:
        if mydir.find('working') < 0:
            mydir = findPipelineWorkingDirectory(mydir)
            if mydir is None: return
            print("Found working directory: ", mydir)
        if uselogfile:
            logfile = findPipelineCasaLogfile(mydir, fast=fast, searchString=searchString, verbose=verbose)
            if logfile is None:
                return
            print("Found log file = ", logfile)
            version = casaVersionFromLogfile(logfile)
        else:
            weblog = findWeblog(mydir)
            version = casaVersionFromWeblog(weblog)
        print("  ", version)
    return(version)

def pipelineDurationFromWeblog(weblog, fast=True, prependFullPath=True):
    """
    weblog: path to directory pipeline-YYYYMMDDTHHMMSS, or the working 
            directory above it, or the parent directory;
            If it contains a wildcard, then it will do a glob.glob(weblog) and
            treat each result like it was an individual value, in succession, ignoring
            anything that ends in .pkl, .flux.csv or .working
    prependFullPath: if True, prepend full path of t1-1.html file
    fast: passed to findPipelineWorkingDirectory
    Returns: for a single weblog value, a string containing the duration, e.g. '1 day 15:02:55'
    -Todd Hunter
    """
    if weblog.find('*') >= 0:
        weblogs = sorted(glob.glob(weblog))
        realweblogs = []
        for weblog in weblogs:
            if weblog.find('.pkl') < 0 and weblog.find('.flux.csv') < 0 and weblog.find('.working') < 0:
                realweblogs.append(weblog)
        weblogs = realweblogs
        print("Processing %d weblogs" % (len(weblogs)))
    else:
        weblogs = [weblog]
    duration = ''
    for weblog in weblogs:
        if weblog[0] != '/':
            weblog = os.path.join(os.getcwd(), weblog)
        if weblog[-9:].find('/working') >= 0:
            # We were given a working directory
            weblog = findWeblog(weblog)
        elif weblog.find('pipeline-20') < 0:
            # We were given a parent directory
            workingdir = findPipelineWorkingDirectory(weblog, fast=fast)
            print("Found working directory: ", workingdir)
            weblog = findWeblog(workingdir)
        htmlfile = os.path.join(weblog,'html/t1-1.html')
        if not os.path.exists(htmlfile):
            # Check if someone included the trailing /html
            htmlfile = os.path.join(weblog,'t1-1.html')
            if not os.path.exists(htmlfile):
                print("t1-1.html not found")
                return ''
        f = open(htmlfile,'r')
        lines = f.readlines()
        f.close()
        for i,line in enumerate(lines):
            if line.find(' Duration') > 0:
                myduration = lines[i+1].split('<td>')[1].split('</td>')[0]
                print("Summing ", myduration)
                if prependFullPath:
                    # The comma allows google spreadsheet to automatically split into 2 columns
                    myduration = ', '.join([htmlfile,myduration.replace(',','')])
                    if len(weblogs) > 1:
                        myduration += '\n'
                duration += myduration
    if len(weblogs) == 1:
        return str(duration)
    else:
        print(duration)

def casaVersionFromWeblog(weblog):
    """
    weblog: path to directory pipeline-YYYYMMDDTHHMMSS
    Returns: a string containing the version of casa used in this pipeline run
    -Todd Hunter
    """
    return versionFromWeblog(weblog, 'CASA')

def pipelineVersionFromWeblog(weblog):
    """
    weblog: path to pipeline directory or subdiretory, including the
        file itself (pipeline-YYYYMMDDTHHMMSS)
    Returns: a string containing the version of the pipeline
    -Todd Hunter
    """
    return versionFromWeblog(weblog, 'Pipeline')

def versionFromWeblog(weblog, thing):
    """
    weblog: path to pipeline parent directory or the weblog file itself: pipeline-YYYYMMDDTHHMMSS
       it will run faster if you give it the working directory (or lower)
    thing: either 'CASA' or 'Pipeline' (case insensitive)
    Returns: a string containing the version of casa or pipeline
    -Todd Hunter
    """
    if thing.upper() not in ['CASA', 'PIPELINE']:
        print("The thing parameter must be either CASA or pipeline (case insensitive)")
        return
    # allow lowercase or mixed case
    if len(thing) == 4: 
        thing = 'CASA'
    else:
        thing = 'Pipeline'
    if weblog.find('pipeline-20') < 0:
        weblog = findWeblog(weblog)
    htmlfile = os.path.join(weblog,'html/t1-1.html')
#    print("Looking for ", htmlfile)
    if not os.path.exists(htmlfile):
        print("t1-1.html not found")
        return ''
    f = open(htmlfile,'r')
    lines = f.readlines()
    f.close()
    for i,line in enumerate(lines):
        if line.find(thing+' Version') > 0:
            return lines[i+1].split('<td>')[1].split("(")[0].strip()
    return ''

def scienceScanTimeRangeFromWeblog(weblog, sourcename='', htmlname='t2-2-6.html'):
    """
    weblog: path to directory pipeline-YYYYMMDDTHHMMSS
    htmlname: name of html file in the sessionsession_X subdirectories
    Returns: a list of [startTimeEB0,startTimeEB1...],  and a list of [endTimeEB0,endTimeEB1...]
             where the times are strings of format "YYYY-MM-DD HH:MM:SS"
    -Todd Hunter
    """
    if weblog in ['', './', '.']:
        weblog = os.getcwd()
    vislist = vislistFromWeblog(weblog)
    filename = os.path.join(weblog,'html','sessionsession_*','*',htmlname) # final star is for the ms name
    filenames = removeTargetMSfromList(glob.glob(filename))
    if len(filenames) != len(vislist):
        print("Mismatch in vislist and html files")
        print("filenames: ", filenames)
        print("vislist: ", vislist)
        return
    t0 = [] # list of first science scan start time across EBs
    t1 = [] # list of final science end start time across EBs
    for vis in vislist:
        # locate the right file since order may not be preserved
        for filename in filenames:
            if filename.find(vis) > 0: break
        f = open(filename,'r')
        lines = f.readlines()
        f.close()
        lookingForTimes = False
        times = []
        for i,line in enumerate(lines):
            if line.find('Duration') > 0:
                lookingForTimes = True
            elif lookingForTimes:
                if line.count(':') == 2 and line.count('-') == 2:
                    if sourcename == '' or lines[i+4].find(sourcename) > 0 or lines[i+3].find(sourcename) > 0:
                        times.append(line.split('<td>')[1].split('</td>')[0])
        if len(times) < 1:
            print("Source not found in vis: ", vis)
            continue
        t0.append(times[0])
        t1.append(times[-1])
    return t0, t1

def removeTargetMSfromList(filenames):
    """
    Removes all _target.ms from a list of measurement sets
    -Todd Hunter
    """
    newfilenames = []
    for filename in filenames:
        if filename.find('_target.ms') < 0:
            newfilenames.append(filename)
    return newfilenames

def spwphaseupFromWeblog(weblog, stage=14, htmlname='t2-4m_details.html', verbose=True,
                         clipFieldName=False):
    """
    Supports both pre-PIPE-1154 (PL<=2021) and post-PIPE-1154 (PL>=2022)
    weblog: path to directory pipeline-YYYYMMDDTHHMMSS, or the working
            directory, and the newest-named "pipeline-" dir will be found
    stage: 14 in PL2021, 13 in cycles prior to addition of hifa_bandpassflag
    clipFieldName: if True, split field name on " (" and take first part only
    Returns: a dictionary keyed by vis, with sub-dictionary:
      PL<=2021:   {'type':  'mapping', 'combine', or 'normal'}
         'spwsUsed': [list of spw solutions used] (blank for non-mapping)
      PL>=2022:  {intent: {field: {'type':'mapping', 'combine', or 'normal',
                                   'spwsUsed': [list of spw solutions used]}} 
         'spwsUsed' is not present for non-mapping
    -Todd Hunter
    """
    if weblog in ['', './', '.']:
        weblog = os.getcwd()
    if weblog[-9:].find('/working') >= 0:
        weblog = findWeblog(weblog)
        print("found weblog = ", weblog)
    correctStage = False
    for mystage in [stage,stage+1]:
        filename = os.path.join(weblog,'html','stage%d'%(mystage),htmlname)
        if not os.path.exists(filename):
            print("Could not find spwphaseup page at %s" % (filename))
            return
        f = open(filename,'r')
        lines = f.readlines()
        f.close()
        pipe1154 = False
        for line in lines:
            if line.find('Spw Phaseup Map') > 0:
                correctStage = True
            if line.find('Scan IDs') > 0:
                pipe1154 = True
                if verbose:
                    print("This is a PL>=2022 weblog")
                break
        if not pipe1154 and verbose:
            print("This is a PL<2022 weblog.")
        if correctStage:
            break
        elif mystage == stage:
            print("Wrong stage, trying %d" % (stage+1))
    if not correctStage:
        print("Incorrect stage (tried %d and %d)" % (stage,stage+1))
        return
    vislist = vislistFromWeblog(weblog)
    mydict = {}
    for vis in vislist:
        mydict[vis] = {}
        if not pipe1154:
            mydict[vis]['type'] = 'normal'  # assume normal to start with
        for i, line in enumerate(lines):
            if line.find('Solutions Parameters') >= 0:
                break
            if line.find(vis) > 0:
                if pipe1154:
                    for intent in ['PHASE','CHECK']:
                        if lines[i+2].find('>'+intent) > 0:
                            if intent not in list(mydict[vis].keys()):
                                mydict[vis][intent] = {}
                            field = lines[i+1].split('<td>')[1].split('</td>')[0]
                            if clipFieldName:
                                field = field.split(' (')[0]
                            boolean = lines[i+4].split('<td>')[1].split('</td>')[0]
                            if boolean == 'True':
                                mydict[vis][intent][field] = {'type':'combine'}
                            else:
                                mapping = lines[i+5].split('<td>')[1].split('</td>')[0]
                                if len(mapping) > 0:
                                    mydict[vis][intent][field] = {'type':'mapping'}
                                    if mapping.find('strong') > 0:
                                        spws = mapping.split('<strong>')[1:]
                                        spwlist = []
                                        for spw in spws:
                                            spw = spw.split('</strong>')[0]
                                            spwlist.append(int(spw))
                                    mydict[vis][intent][field]['spwsUsed'] = sorted(np.unique(spwlist))
                                else:
                                    mydict[vis][intent][field] = {'type':'normal'}
                else:
                    if mydict[vis]['type'] in ['mapping','combine']:
                        if lines[i+1].find('strong') > 0:
                            spws = lines[i+1].split('<strong>')[1:]
                            spwlist = []
                            for spw in spws:
                                spw = spw.split('</strong>')[0]
                                spwlist.append(int(spw))
                            mydict[vis]['spwsUsed'] = sorted(np.unique(spwlist))
                    if line.find('using highest good') > 0:
                        mydict[vis]['type'] = 'mapping'
                    elif line.find('combined') > 0:
                        mydict[vis]['type'] = 'combine'
    return mydict

def is_floatstring(element):
    """
    Returns True if the string is all digits including one (and only one) 
    decimal point.
    -Todd Hunter
    """
    if element is None: 
        return False
    try:
        float(element)
        if element.count('.') == 1:
            return True
        else:
            return False
    except ValueError:
        return False

def compareEstimatedToActualSNRspwphaseup(workingdir, debugEstimate=False, debugActual=False):
    """
    Calls spwphaseupEstimatedSNRFromWeblog() and getAchievedSNRFromAquaReport(),
    generates an ordered pair of SNRs, and makes a scatter plot of them.
    -Todd Hunter
    """
    estimate = spwphaseupEstimatedSNRFromWeblog(workingdir, debug=debugEstimate)
    actual = getAchievedSNRFromAquaReport(workingdir, debug=debugActual)
    mydict = spwphaseupFromWeblog(workingdir, clipFieldName=True)
    vislist = list(estimate.keys())
    estimatedSNR = []
    actualSNR = []
    rxBand = []
    method = []
    myband = pipelineScienceBand(workingdir)
    for vis in vislist:
        intents = list(actual[vis].keys())
        for intent in intents:
            fields = list(actual[vis][intent].keys())
            for field in fields:
                spws = list(actual[vis][intent][field].keys())
                if debugActual or debugEstimate: print("spws = ", spws)
                for spw in spws:
                    if spw != 'spwsUsed':
                        estimateIntents = list(estimate[vis].keys())
                        if intent in estimateIntents:
                            estimatedSNR.append(estimate[vis][intent][field][spw])
                            if debugEstimate: print("spws in dict: ", list(actual[vis][intent][field].keys()))
                            actualSNR.append(actual[vis][intent][field][spw])
                            rxBand.append(myband)
                            method.append(mydict[vis][intent][field])
                        else:
                            print("%s intent not present in estimate dictionary" % (intent))
    pb.clf()
    colors = ['k','k','k','r','orange','green','goldenrod', 'cyan', 'blue', 'violet', 'k']
    for i in range(len(rxBand)):
        pb.plot([estimatedSNR[i]], [actualSNR[i]], 'o', color=colors[rxBand[i]])
    pb.draw()
    return estimatedSNR, actualSNR, rxBand, method
    
def spwphaseupEstimatedSNRFromWeblog(weblog, stage=14, htmlname='t2-4m_details.html',
                                     includeType=False, verbose=True, debug=False):
    """
    Supports post-PIPE-1154 (PL>=2022 processed datasets)
    weblog: path to directory pipeline-YYYYMMDDTHHMMSS, or the working
            directory, and the newest-named "pipeline-" dir will be found
    stage: 14 in PL2021, 13 in cycles prior to addition of hifa_bandpassflag
    includeType: if True, then include a key for 'type' and value of 'normal','mapping', or 'combine'
    Ignores _target.ms
    Returns: a dictionary keyed by vis, with sub-dictionary of field name then spw ID
        with values being estimated SNR:
    -Todd Hunter
    """
    if weblog in ['', './', '.']:
        weblog = os.getcwd()
