def findWeblog(root,debug=False): 
    """
    Returns the path to a pipeline weblog (as a string, not unicode).  
    It will run much faster if you give it the working directory
    root: a pipeline parent directory (e.g. 2018.1.01234.S_yyyy_mm_ddThh_mm_ss.sss) or any subdirectory
    Returns: the weblog directory with the most recent date/timestamp
         e.g. '2018.../S../G../M../working/pipeline-yyyymmddThhmmss'
    """
    if root == '':
        root = os.getcwd()
        print("Using current working directory: ", root)
    if not os.path.exists(root):
        print("Could not find directory "+root)
        return
    weblogdirs=[]
    maxdepth=0
    while len(weblogdirs)<1 and maxdepth<6:
        maxdepth=maxdepth+1
        findCMD = 'find -L '+root+' -maxdepth '+str(maxdepth)+' -name "pipeline-20??????T??????"' # .context"'
        if debug: print(findCMD)
        out = subprocess.Popen(findCMD,shell=True,stdin=subprocess.PIPE, 
                               stdout=subprocess.PIPE,stderr=subprocess.PIPE)
        (stdout, stderr) = out.communicate()
        weblogdirs = stdout.decode().split()

    if len(weblogdirs)<1:
        findCMD = 'find -L '+root+' -name "*weblog.tgz"'
        out = subprocess.Popen(findCMD,shell=True,stdin=subprocess.PIPE, 
                           stdout=subprocess.PIPE,stderr=subprocess.PIPE)
        (stdout, stderr) = out.communicate()
        weblogtgz = stdout.decode().split()
        if len(weblogtgz)>0:
            tmpdir=pkls[i][:-4]+".tmp"
            if not os.path.exists(tmpdir):
                os.mkdir(tmpdir)
            origdir=os.getcwd()
            os.chdir(tmpdir)
            os.system("tar -xzf "+weblogtgz[0])
            findCMD = 'find -L '+tmpdir+' -name "pipeline-20??????T??????"'
            out = subprocess.Popen(findCMD,shell=True,stdin=subprocess.PIPE, 
                                   stdout=subprocess.PIPE,stderr=subprocess.PIPE)
            (stdout, stderr) = out.communicate()
            weblogdirs = stdout.decode().split()
            os.chdir(origdir)

    if len(weblogdirs)>0:
        if debug: print("Found %d weblog dirs" % (len(weblogdirs)))
        weblogdirs.sort()
        return str(weblogdirs[-1]) # [:-8]) # but if someone ran iPL manually..

    maxdepth=0
    while len(weblogdirs)<1 and maxdepth<6:
        maxdepth=maxdepth+1
        findCMD = 'find -L '+root+' -maxdepth '+str(maxdepth)+' -name "pipeline-20??????T??????"'
        if debug: print(findCMD)
        out = subprocess.Popen(findCMD,shell=True,stdin=subprocess.PIPE, 
                               stdout=subprocess.PIPE,stderr=subprocess.PIPE)
        (stdout, stderr) = out.communicate()
        weblogdirs = stdout.decode().split()

    if len(weblogdirs)>0:
        weblogdirs.sort()
        return str(weblogdirs[-1]) # but if someone ran iPL manually..
    else:
        return ""


