def findImagePng(iminfo,itype,weblog,im_iter="iter1"):
    if im_iter=="":
        im_iter='iter1'
    xx=iminfo.split(".")
    if xx[1]=="ms":
        xx=np.append(xx[0],xx[2:])
    for ix in range(len(xx)):
        if xx[ix].count("+")>0:
            xx[ix]=xx[ix].replace("+","_")
        if xx[ix].count("-")>0:
            xx[ix]=xx[ix].replace("-","_")
                            
    if itype.count("tt0") or xx[-1].count("tt"):
        if xx[-1].count("tt"):
            searchstr = ' -name "'+xx[0]+"*"+(".".join(xx[1:]))[:-4]+'.I.'+im_iter+'.image.tt0.sky.png"'
        else:
            searchstr = ' -name "'+xx[0]+"*"+(".".join(xx[1:]))+'.I.'+im_iter+'.image.tt0.sky.png"'
    elif itype.count("image.sd"):
        searchstr = ' -name "'+xx[0]+"*"+(".".join(xx[1:]))+'.I.'+im_iter+'.'+itype+'.pol0_TP.png"'
    elif itype.count("sd"):
        if xx[3]!="all":
            searchstr = ' -name "'+xx[1]+"."+xx[3]+"."+xx[2]+'.I.sd.im.pol0_TP.png"'
        else:
            searchstr = ' -name "'+xx[1]+".*"+xx[2]+'.I.sd.im.pol0_TP.png"'
    else:
        searchstr = ' -name "'+xx[0]+"*"+(".".join(xx[1:]))+'.I.'+im_iter+'.image.sky.png"'
    for depth in range(5):
        findCMD= 'find -L '+weblog+(' -maxdepth %i'%depth) + searchstr + ' | grep -v "thumb"'
        out = subprocess.Popen(findCMD,shell=True,stdin=subprocess.PIPE, 
                               stdout=subprocess.PIPE,stderr=subprocess.PIPE)
        (stdout, stderr) = out.communicate()
        weblogpng = stdout.decode().split()
        if len(weblogpng)>0:
            return str(weblogpng[0])
    if len(weblogpng)>0:
        return str(weblogpng[0])
    else:
        print("no png found: ")
        print(findCMD)
        return ""



#---------------------------------------------------------------
def extractSensitivitiesFromContexts(weblogdir, debug=False):
    """
    gets image sensitivities from the per-stage saved_state results objects in the weblog dir
    """

    saveddir=weblogdir.strip()
    if saveddir[-1]=="/": saveddir=saveddir[:-1]
    xx=saveddir.split("/")
    if xx[-1]=="html":
        saveddir="/".join(xx[:-1])+"/saved_state/"
    else:
        saveddir=saveddir+"/saved_state/"
    resultfiles=glob.glob(saveddir+"result*pickle")
    if len(resultfiles)<1:
        print("can't find saved results pickles in")
        print(saveddir)
        return {}

    makeimageresults=[]
    for r in resultfiles:
        res=pickle.load(open(r,'rb'))
        # if debug: print(res.pipeline_casa_task)
        if res.pipeline_casa_task.split('(')[0]=='hif_makeimages':
            miresults={}
            miresults['stage_number']=res.stage_number
            miresults['pipeline_casa_task']=res.pipeline_casa_task
            miresults['inputs']=res.inputs
            miresults['results']=[]
            for rr in res.results:
#                print("rr.keys = ", dir(rr))
                miresults['results'].append(
                    {"image":rr.image,
                     "image_rms_max":rr.image_rms_max,
                     "image_rms_min":rr.image_rms_min,
                     "image_max":rr.image_max,
                     "image_min":rr.image_min,
                     "image_rms":rr.image_rms})
            makeimageresults.append(miresults)

    u=np.argsort([x['stage_number'] for x in makeimageresults])
    return np.array(makeimageresults)[u]
         
        
