def extractMetadataFromContext(contextfile):

    context_dir=os.path.dirname(contextfile)
    context=pickle.load(open(contextfile,'rb'))
    #EBs=context.observing_run.execblock_ids
    result={}
    
    # context.observing_run contains the virtual spw mapping information
    MSs=context.observing_run.get_measurement_sets()
    for MS in MSs:
        MS.name=os.path.dirname(contextfile)+"/"+os.path.basename(MS.name)
    result['MSs']=[MS.name for MS in MSs]

    # return rep information from first MS, assume all the same
    repTgt=MSs[0].representative_target
    result['repSrc']=repTgt[0]
    result['repFreq']=repTgt[1]
    result['repBW']=repTgt[2]

    goals=MSs[0].science_goals
    for k in goals.keys():
        result[k]=goals[k]
        
    # MS.representative_window will be filled eventually
    return(result)

