def finishRestoring():
    """
    after running scrpitForPI, go to the calibrated/working directory
    and run this to finish getting uv subtracted visibilities in target.ms
    """
    cwdx=os.getcwd().split("/")
    if not (cwdx[-1]=="working" and cwdx[-2]=="calibrated"):
        print("you don't appear to be in calibrated/working after running scriptForPI.  YMMV")
    if not os.path.exists("../../calibration/cont.dat"):
        print("can't find ../../calibration/cont.dat - are you in calibrated/working?")
        return
    import shutil
    shutil.copy("../../calibration/cont.dat","./")
    from pipeline.hif.cli.hif_mstransform import hif_mstransform
    from pipeline.hif.cli.hif_uvcontfit import hif_uvcontfit
    from pipeline.hif.cli.hif_uvcontsub import hif_uvcontsub
    hif_mstransform(pipelinemode="automatic")
    hif_uvcontfit(pipelinemode="automatic")
    hif_uvcontsub(pipelinemode="automatic")



