def compareHeaders(mydict0, mydict1):
    """
    Compares two dictionaries, such as returned by imhead(mode='list')
    -Todd Hunter
    """
    keys = np.unique(list(mydict1.keys())+list(mydict0.keys()))
    for key in keys:
        if key not in mydict0:
            print("%s not in mydict0" % (key))
        elif key not in mydict1:
            print("%s not in mydict1" % (key))
        else:
            if type(mydict0[key]) == np.ndarray:
                test = (mydict0[key] != mydict1[key]).any()
            else:
                test = mydict0[key] != mydict1[key]
            if test:
                print("%s is %s in mydict0" % (key, mydict0[key]))
                print("%s is %s in mydict1" % (' '*len(key), mydict1[key]))


def findDir(path,contains,doesntcontain=[],debug=False,recurse=True,depth=1):
    """
    recursively find the first subdir (uniqueness is up to the user!)
    that contains strings in the list 'contains'
    and doesn't contain strings in the list 'doesntcontain'
    """
    if path[-1]!="/": path=path+"/"
    if type(contains)==type(" "): contains=[contains]
    if type(doesntcontain)==type(" "): doesntcontain=[doesntcontain]
    if debug: print(">"*depth,path)
    for root, dirs, files in os.walk(path): 
        # first check current dir:
        for mydir in dirs:
            match=True
            for substring in contains:
                if substring not in mydir: match=False
            for substring in doesntcontain:
                if substring in mydir: match=False
            if match: return( root+mydir)
        # stop if at bottom of tree:
        if len(dirs)==0: return(None)
        if recurse:
            # check one level down (recurse=False)
            for mydir in dirs:
                result = findDir(root+mydir,contains,doesntcontain,debug=debug,recurse=False,depth=depth+1)
                if result: return(result)
            # then recurse:
            for mydir in dirs:
                result = findDir(root+mydir,contains,doesntcontain,debug=debug,recurse=recurse,depth=depth+1)
                if result: return(result)
        return(None)

def comparePipeRuns(pkls, threshold=0.1, sigthreshold=1., debug=False, verbose=False, htmldir=None, findcontthreshold=0.1, fluxdiffthresh=0.01, copyimages=True, fix_mous=True):
    """
    Compare information about pipeline runs pickled with picklePipeRun

    Information saved and compared includes:
       derived flux densities of secondary calibrators (from aqua report, 
         also uses actual ms for meta-information)
       input flux densities of QSO amp cals (from flux.csv)
       calibrator imaging QA scores (from context)
       statistics on all images created (from the directory)
    Input is an array of two outputs from picklePipeRun e.g. 
       ["run1.pkl","run2.pkl"]
    threshold is the relative change in compared quantities required to 
       print information to the screen.  Changes smaller than threshold
       will be silently not reported to you.
    sigthreshold is the relative change to report, in sigma units. 
       this is only used for image statistics, and if sigthreshold>0, 
       will override "threshold"
    findcontthreshold is the relative change for the findcont.residual
       images - it is sometimes desirable to run with a tighter tolerance for 
       the findcont dirty images than for the final product images
    fluxdiffthresh:  threshold for printing if either flux.csv or gfluxscale
       derived fluxes have changed by more than this threshold
    htmldir set to a dir will write a web page in that dir
    copyimages: copy images to htmldir (if False, just symlink them)

    -- Remy Indebetouw
    """

    import numpy as np
    # load pickles
    import pickle
    data=[]
    for i in range(len(pkls)):
        data.append(pickle.load(open(pkls[i],'rb'))) # ,encoding="bytes")) # encoding would allow loading python2 pickles in python3 but loading the xml will still fail
    is_IF=True
    # older pickles have key="metadata"; newer have a list "metadatas"
    if "metadata" in data[0]:
        metadata0.data[0]['metadata']
    elif "metadatas" in data[0]:
        metadata0=data[0]['metadatas'][0]
    else:
        print("error: can't find metadata in "+pkls[0])
    if 'ProcessingProcedure' in metadata0:
        if metadata0['ProcessingProcedure'][0:3]=='hsd':
            is_IF=False

    # try to find weblogs:
    weblogs=[]    
    metadatas=[]         
    for i in range(len(pkls)):
        if "metadata" in data[i]:
            metadatas.append([data[i]['metadata']])
        elif "metadatas" in data[i]:
            metadatas.append(data[i]['metadatas'])
        else:
            print("error: can't find metadata in "+pkls[i])
    for i in range(len(pkls)):
        theseweblogs=[]
        for j in range(len(metadatas[i])):
            theseweblogs.append(findWeblog(metadatas[i][j]['root'],debug=(debug or verbose)))
        weblogs.append(theseweblogs)

    if htmldir:
        if not os.path.exists(htmldir):
            os.mkdir(htmldir)
        hfile=open(htmldir+"/index.html",'w')
        hfile.write("<html title='"+(htmldir.split("/")[-1])+"'>\n")
        hfile.write("<style>\n    * {\n      font-family: sans-serif;\n    }\n</style>\n")
        hfile.write("<body>\n")
        for i in range(len(pkls)):
            hfile.write(pkls[i]+"<br>\n")
            outstr=""
            for j in range(len(metadatas[i])):
                outstr=outstr+"&nbsp;&nbsp;&nbsp;"+metadatas[i][j]['root']+"<br>"
                os.symlink(metadatas[i][j]['root'],htmldir+"/"+("pkl%i"%i)+("_run%i"%j))
            hfile.write(outstr+"\n")
            found_weblog=False
            outstr=""
            for j in range(len(weblogs[i])):
                if weblogs[i][j]:
                    outstr=outstr+"&nbsp;&nbsp;&nbsp;<a href='"+weblogs[i][j]+"/html/index.html'>weblog</a></br>"
                    found_weblog=True
            if not found_weblog:
                outstr=outstr+"&nbsp;&nbsp;&nbsp; weblog not found</br>"
            hfile.write(outstr+"\n")
            outstr=""
            for j in range(len(metadatas[i])):
                outstr=outstr+"&nbsp;&nbsp;&nbsp;casaversion="+metadatas[i][j]['casaversion']+"<br>"
            hfile.write(outstr+"\n")
            outstr=""
            for j in range(len(metadatas[i])):
                outstr=outstr+"&nbsp;&nbsp;&nbsp;pipeversion="+metadatas[i][j]['pipeversion']+"<br>"
            hfile.write(outstr+"<p>\n")

        
        # sensitivities 
        if "sensitivities" in data[0]:
            sens0=[]
            for s in data[0]['sensitivities']:
                mydict = {}
                for d in s:
                    mydict[d[0]] = d[1]
                sens0.append(mydict)
#                sens0.append({d[0]:d[1] for d in s})  # fails on casapy-telcal for some reason
                kk=list(sens0[-1].keys())
            n=len(sens0)
            z0rep=np.where(np.array([sens0[i]['BwMode']=='repBW' for i in range(n)]))[0]
            z0agg=np.where(np.array([sens0[i]['BwMode']=='aggBW' for i in range(n)]))[0]
        else:
            z0rep=[]
            z0agg=[]
        if "sensitivities" in data[1]:
            sens1=[]
            for s in data[1]['sensitivities']:
                mydict = {}
                for d in s:
                    mydict[d[0]] = d[1]
                sens1.append(mydict)
#                sens1.append({d[0]:d[1] for d in s})
                kk=list(sens1[-1].keys())
            n=len(sens1)
            z1rep=np.where(np.array([sens1[i]['BwMode']=='repBW' for i in range(n)]))[0]
            z1agg=np.where(np.array([sens1[i]['BwMode']=='aggBW' for i in range(n)]))[0]
        else:
            z1rep=[]
            z1agg=[]
        zs=[z0rep,z1rep,z0agg,z1agg]
        anysens=False
        for z in zs:
            if len(z)>0: anysens=True

        if anysens:
            kk.sort()
            hfile.write("<hr>\n<table border='1'><tr><td colspan='5'>imageprecheck results</td></tr>\n")
            hfile.write("<tr><td></td><td colspan='2'>repBW</td><td colspan='2'>aggBW</td></tr>\n")
            for k in kk:
                hfile.write("<tr><td>"+str(k)+"</td>")
                if len(z0rep)>0:
                    if k in sens0[z0rep[0]]:
                        hfile.write("<td>"+str(sens0[z0rep[0]][k])+"</td>")
                    else:
                        hfile.write("<td>-</td>")
                else:
                    hfile.write("<td>x</td>")
                if len(z1rep)>0:
                    if k in sens1[z1rep[0]]:
                        hfile.write("<td>"+str(sens1[z1rep[0]][k])+"</td>")
                    else:
                        hfile.write("<td>-</td>")
                else:
                    hfile.write("<td>x</td>")
                if len(z0agg)>0:
                    if k in sens0[z0agg[0]]:
                        hfile.write("<td>"+str(sens0[z0agg[0]][k])+"</td>")
                    else:
                        hfile.write("<td>-</td>")
                else:
                    hfile.write("<td>x</td>")
                if len(z1agg)>0:
                    if k in sens1[z1agg[0]]:
                        hfile.write("<td>"+str(sens1[z1agg[0]][k])+"</td>")
                    else:
                        hfile.write("<td>-</td>")
                else:
                    hfile.write("<td>x</td>")
                hfile.write("</tr>\n")    
            hfile.write("</table>\n")


    #===========================================================================
    # line up the datasets in case the order changed, also add the input fluxes
    matchdata=[]
    
    if is_IF:

        # first dataset = reference
        t0=data[0]['derivedfluxes'].copy()
    
        for idata in range(len(data)):  # written generally here, but for now only works for 2 runs
            ti=data[idata]['derivedfluxes']
    
            # if something failed, then don't proceed:
            if len(t0['I'])>0 and len(ti['I'])>0:
    
                tiout={}
                for k in list(t0.keys()):
                    tiout[k]=[]
                tiout['ampcalname']=[]
                tiout['ampcalflux']=[]
       
                nrow=len(t0['I']) # 20180921 switch from ti to t0
                # keep track of all matched in second dataset, 
                # in case any new derived fluxes show up relative to first dataset
                # (e.g. they got completely flagged the first time but not 2nd)
                # 20181010 not used so commented out
                # tifound=np.zeros(nrow,dtype="bool")
           
                isampcal=data[idata]['csvfluxes']['isampcal'].data
                for i in range(nrow):
                    if idata==0: # first dataset
                        for k in list(t0.keys()):
                            tiout[k].append(t0[k][i]) # copy fluxes to output dict
                    else:
                        # find match for each row of first derived fluxes list
                        z=np.where( np.array([t0['ms'][i]==y for y in ti['ms']])*
                                    np.array([t0['fieldname'][i]==y for y in ti['fieldname']])*
                                    (int(t0['spw'][i])==np.array(ti['spw'])) )[0]
                        if len(z)>0:
                            if len(z)>1:
                                print("warning: multiple matches for ",t1['ms'][i],ti['fieldame'][i],ti['spw'][i])
                            # tifound[z[0]]=True
                            for k in list(t0.keys()):
                                tiout[k].append(ti[k][z[0]])
                        else:
                            for k in list(t0.keys()):
                                if k=='spw':
                                    tiout[k].append(-1)
                                else:
                                    tiout[k].append("0")
                    # find a corresponding ampcal flux (only possible if context was used in the pickling)
                    fz=np.where( (isampcal)*
                                 np.array([(tiout['ms'][i]+".ms")==y for y in data[idata]['csvfluxes']['ms']])*
                                 (tiout['spw'][i]== data[idata]['csvfluxes']['spw']) )[0]
                    if len(fz)>0:
                        tiout['ampcalname'].append(data[idata]['csvfluxes']['comment'][fz[0]].split()[0].strip('"').strip("'"))
    
                        tiout['ampcalflux'].append(data[idata]['csvfluxes']['I'][fz[0]])
                    else:
                        tiout['ampcalname'].append('none')
                        tiout['ampcalflux'].append(-1)
           
                matchdata.append(tiout)
    
       
            
    
        #=================================================================
        # now list if anything changed in the derived fluxes:
        if len(matchdata)>1:
            mss =np.unique(matchdata[0]['ms'])
            if htmldir:
                hfile.write("<hr>\n")
                hfile.write("<h3>changes in flux densities:</h3>\n")
                hfile.write("  'csv' refers to differences in flux.csv files<br>\n")
                hfile.write("  'gflx' refers to differences in gfluxscale derived fluxes<br>\n")
                hfile.write("  if a flux density can't be found, x is printed<p>\n")
            # threshold
            #fluxdiffthresh=0.01  # parameter
        
            # collect 2 sets of fluxes, all spws, input and derived
            # csv file has ms,srcid,spwid,flux,0,0,0,spix,'"\'J2025+3343\' intent=AMPLITUDE'
            # dissect the name and intent part:
            csv0=data[0]['csvfluxes']
            csvfld0=[]
            csvint0=[]
            for c in csv0['comment']:
                xx=c.split()
                if c.count("intents="): # new format
                    for x in xx:
                        if "field" in x:
                            csvfld0.append(x.strip('"').strip("'"))
                            csvfld0[-1]=csvfld0[-1].split("=")[1]
                        if "intents" in x:
                            csvint0.append(x.split("intents=")[1])
                else: # old format
                    csvfld0.append(xx[0].strip('"').strip("'"))
                    csvint0.append(xx[1].split("intent=")[1])
        
            csv1=data[1]['csvfluxes']
            csvfld1=[]
            csvint1=[]
            for c in csv1['comment']:
                xx=c.split()
                for x in xx:
                    if x.count("intents="):
                        csvint1.append(x.split("intents=")[1])
                    if x.count("field="):
                        csvfld1.append(x.split("field=")[1].strip('"').strip("'"))
                        #csvfld1[-1]=csvfld1[-1].split("=")[1]
         
            der0=data[0]['derivedfluxes']
            der1=data[1]['derivedfluxes']
            # determine all unique spws and all unique srcs
            spws=np.unique(np.concatenate([der0['spw'],der1['spw'],csv0['spw'],csv1['spw']]))    
            srcs=np.unique(np.concatenate([der0['fieldname'],der1['fieldname'],csvfld0,csvfld1]))
            
            if htmldir:
                hfile.write("<table border=1><tr><td>field</td><td>intent</td>")
                for spwi in spws: hfile.write("<td colspan='2'>"+str(spwi)+"</td>")
                hfile.write("</tr>\n")
                hfile.write("<tr><td></td><td>(flux.csv)</td>")
                for spwi in spws: hfile.write("<td>csv</td><td>gflx</td>")
                hfile.write("</tr>\n")
            
            for ims in range(len(mss)):     

                if htmldir:
                    hfile.write("<tr><td colspan='6'>"+mss[ims]+":</td></tr>\n")
            
                for srci in srcs:
                    if htmldir:
                        hfile.write("<tr><td>"+str(srci)+"</td>")
                    # find intent in csv0
                    z0=np.where( np.array([mss[ims]+".ms"==y for y in csv0['ms']])*
                                 np.array([srci==y for y in csvfld0]))[0]
                    if len(z0)>0:
                        intent0i=csvint0[z0[0]]
                    else:
                        intent0i=""
                    # find intent in csv1
                    z1=np.where( np.array([mss[ims]+".ms"==y for y in csv1['ms']])*
                                 np.array([srci==y for y in csvfld1]))[0]
                    if len(z1)>0:
                        intent1i=csvint1[z1[0]]
                    else:
                        intent1i=""
                    if intent0i!=intent1i:
                        print("problem: csv files have same source, different intent")
                        pdb.set_trace()
                        # TODO: problem in pickle that makes everything atmosphere or amp
                    if htmldir:
                        if intent0i=="AMPLITUDE":
                            hfile.write("<td>"+str(intent0i)+"</td>")
                        else:
                            hfile.write("<td>*</td>")
            
                    for spwi in spws:
                        # find sources in csv0
                        z0=np.where( np.array([mss[ims]+".ms"==y for y in csv0['ms']])*
                                     np.array([srci==y for y in csvfld0])*
                                     np.array([spwi==y for y in csv0['spw']]))[0]
                        if len(z0)>0:
                            f0=float(csv0['I'][z0[0]])
                        else:
                            f0=0.
                        z1=np.where( np.array([mss[ims]+".ms"==y for y in csv1['ms']])*
                                     np.array([srci==y for y in csvfld1])*
                                     np.array([spwi==y for y in csv1['spw']]))[0]
                        if len(z1)>0:
                            f1=float(csv1['I'][z1[0]])
                        else:
                            f1=0.
                        if htmldir:
                            if f0==0. and f1==0.:
                                hfile.write("<td>x</td>") # x means not found
                            else:
                                reldiff=np.absolute(2*(f0-f1)/(f0+f1))
                                if reldiff>fluxdiffthresh:
                                    hfile.write("<td bgcolor='orange'>%6.3f&nbsp;>&nbsp;%6.3f</td>"%(f0,f1))
                                else:
                                    hfile.write("<td bgcolor='lawngreen'>=</td>")
            
                        #find sources in der0
                        z0=np.where( np.array([mss[ims]==y for y in der0['ms']])*
                                     np.array([srci==y for y in der0['fieldname']])*
                                     np.array([spwi==y for y in der0['spw']]))[0]
                        if len(z0)>0:
                            f0=float(der0['I'][z0[0]])
                        else:
                            f0=0.
