def expandMask1Chan(inmask,outmask):
    """
    expand cube mask by 1 channel
    """
    if os.path.exists(outmask):
        print(outmask," exists; exiting")
        return
    myia = createCasaTool(iatool)
    myia.open(inmask)
    maskdat=myia.getchunk()
    myia.done()
    middle=np.max(np.array([maskdat[:,:,:,1:-1],maskdat[:,:,:,:-2],maskdat[:,:,:,2:]]),axis=0)
    maskdat[:,:,:,0]=np.max(np.array([maskdat[:,:,:,0],maskdat[:,:,:,1]]),axis=0)
    maskdat[:,:,:,-1]=np.max(np.array([maskdat[:,:,:,-1],maskdat[:,:,:,-2]]),axis=0)
    maskdat[:,:,:,1:-1]=middle
    shutil.copytree(inmask,outmask)
    myia.open(outmask)
    myia.putchunk(maskdat)
    myia.done()
    




#-----------------------------------------------------------------------

def linmos(inputs=[],output=None,pbimages=[],regrid=True,debug=False,
           convolve=False,template="",spectemplate="",asvelocity=False,
           use_immath=True,input_is_pbcor=True):
    """
    given images with overlapping spectral wcs [not checked], 
    calculate spanning spatial wcs, 
    regrid each to larger imsize, 
    and average, dealing with masks properly
    pbimages = optional corresponding pb images for weighting
    if regrid=False, re-use existing inputs.regrid images (doesn't check 
      to see if they're correct)
    if template is set then use that image as the template 
    if spectemplate is set, use only the spectral part of that template
    immath: use immath; otherwise use ia.get/putchunks
    input_is_pbcor: the input images are pb-corrected
    """

    from copy import copy # python 2.7 no native list copy
    myia = createCasaTool(iatool)

    inputs1=[i.strip("/") for i in inputs]
    pbimages1=[i.strip("/") for i in pbimages]
    output1=output.strip("/")

    n=len(inputs1)
    myqa=qatool()

    if type(template)==type({}):
        if debug: print("template record")
        newtemplate=template # TODO some checks on this csys
    elif os.path.exists(template):
        if debug: print("template image= ",template)
        newtemplate=imregrid(template,template="get")
    else:
        templates=[]
        for i,inpt in enumerate(inputs1):
            templates.append(imregrid(inpt,template="get"))
            t=templates[-1]
            myia.open(inpt)
            bbx=myia.boundingbox()
            rarangei=[myqa.convert(myqa.toangle(x),t['csys']['direction0']['units'][0])['value'] for x in [bbx['blcf'].split(',')[0],bbx['trcf'].split(',')[0]]]
            derangei=[myqa.convert(myqa.toangle(x),t['csys']['direction0']['units'][0])['value'] for x in [bbx['blcf'].split(',')[1],bbx['trcf'].split(',')[1]]]
        
            if 'spectral1' in t['csys']:
                kspec='spectral1'
            elif 'spectral2' in t['csys']:
                kspec='spectral2'
        
            if i==0:
                restfreq=t['csys'][kspec]['restfreq']
                specsys =t['csys'][kspec]['system']
                rarange =copy(rarangei)
                derange =copy(derangei)
                cdelt =t['csys']['direction0']['cdelt'][1]
            else:
                theymatch=True
                if specsys!=t['csys'][kspec]['system']:
                    theymatch=False
                restfreqi=t['csys'][kspec]['restfreq']
                if np.absolute((restfreq-restfreqi)/(restfreq+restfreqi))>1e-6:
                    theymatch=False
                # TODO add other checks on specsys matching
                if not theymatch:
                        print(specsys,restfreq)
                        print(t['csys'][kspec]['system'],restfreqi)
                        print("WARN: spectral coordinates don't match, YMMV")
                if rarangei[0]>rarange[0]: rarange[0]=rarangei[0]
                if rarangei[1]<rarange[1]: rarange[1]=rarangei[1]
                if derangei[0]<derange[0]: derange[0]=derangei[0]
                if derangei[1]>derange[1]: derange[1]=derangei[1]
                if t['csys']['direction0']['cdelt'][1]<cdelt: 
                    cdelt=t['csys']['direction0']['cdelt'][1]
            myia.done()

        newtemplate=copy(t)
        newtemplate['csys']['direction0']['cdelt']=[-cdelt,cdelt]
        crval=[0.5*(rarange[0]+rarange[1]),0.5*(derange[0]+derange[1])]
        newtemplate['csys']['direction0']['crval']=crval
        imsize=[int(round((rarange[0]-rarange[1])/cdelt*np.cos(myqa.convert(myqa.quantity(crval[1],t['csys']['direction0']['units'][1]),"rad")['value']))),
                int(round((derange[1]-derange[0])/cdelt))]
        # do we need to also change pointingcenter?
        newtemplate['csys']['direction0']['crpix']=[0.5*x for x in imsize]
        newtemplate['shap'][0:2]=imsize

        newspectemplate=None
        if type(spectemplate)==type({}):
            if debug: print("spectemplate record")
            newspectemplate=spectemplate # TODO some checks on this csys
        elif os.path.exists(spectemplate):
            if debug: print("spectemplate image= ",spectemplate)
            newspectemplate=imregrid(spectemplate,template="get")

        if newspectemplate:
            def speci(t):
                for k in ['spectral2','spectral1']:
                    if k in t['csys']: return k[-1]
                return None
            def specax(t):
                return t['csys']['worldmap'+speci(t)][0]
            newtemplate['csys']['spectral'+speci(newtemplate)] = newspectemplate['csys']['spectral'+speci(newspectemplate)]
            newtemplate['csys']['worldreplace'+speci(newtemplate)] = newspectemplate['csys']['worldreplace'+speci(newspectemplate)]
            newtemplate['shap'][specax(newtemplate)] = newspectemplate['shap'][specax(newspectemplate)]


    bmareas = np.zeros(n) # beam areas
    maxbm = 0 # largest bmax

    for i,inpt in enumerate(inputs1):
        myia.open(inpt)
        bm=myia.restoringbeam()
        myia.done()
        if debug:
            print("bm=%fx%f"%(bm['major']['value'],bm['minor']['value']))
        if bm['major']['value']>maxbm:
            maxbm=bm['major']['value']
        bmareas[i]=bm['major']['value']*bm['minor']['value']*1.133

    # convolve to common(round) beam
    maxbm=maxbm*1.01 # margin TODO make >1pix diag?
    if convolve:
        suffix=".conv"
        for inpt in inputs1:
            if regrid and os.path.exists(inpt+".conv"):
                shutil.rmtree(inpt+".conv")
            if not os.path.exists(inpt+".conv"):
                if debug: print("convolving ",inpt)
                imsmooth(imagename=inpt,outfile=inpt+".conv",targetres=True,major="%farcsec"%maxbm,minor="%farcsec"%maxbm,pa="0deg")
    else:
        suffix=""

    def wcshead(img):
        myqa=qatool()
        xl=imhead(img,mode="list")
        rad=myqa.convert(myqa.quantity(xl['crval1'],xl['cunit1']),'deg')['value']
        ded=myqa.convert(myqa.quantity(xl['crval2'],xl['cunit2']),'deg')['value']
        print("%40s"%img,str(xl['shape']),"%5s %9.4f %9.4f"%(xl['equinox'],rad,ded)," %7.3fGHz"%(xl['restfreq'][0]/1e9) )

    for i,inpt in enumerate(inputs1):
        #if regrid and os.path.exists(inpt+suffix+".regrid"):
        #    shutil.rmtree(inpt+suffix+".regrid")
        if not os.path.exists(inpt+suffix+".regrid"):
            if regrid:
                if debug: print("regridding ",inpt+suffix)
                imregrid(inpt+suffix,template=newtemplate,output=inpt+suffix+".regrid",asvelocity=asvelocity)
            else:
                os.system("ln -s "+inpt+suffix+" "+inpt+suffix+".regrid")
        else:
            if debug: print("using ",inpt+suffix+".regrid")
        #if regrid and os.path.exists(inpt+".regrid.mask"):
        #    shutil.rmtree(inpt+".regrid.mask")
        if not os.path.exists(inpt+".regrid.mask"):
            makemask(mode="copy",inpimage=inpt+suffix+".regrid",inpmask=inpt+suffix+".regrid:mask0",output=inpt+".regrid.mask")
        if debug:
            wcshead(inpt+suffix+".regrid")
        
    if len(pbimages1)==len(inputs1):
        dowt=True
    else:
        dowt=False
    if dowt:
        for inpt,pb in zip(inputs1,pbimages1):
            #if regrid and os.path.exists(inpt+".regrid.wt"):
            #    shutil.rmtree(inpt+".regrid.wt")
            if not os.path.exists(inpt+".regrid.wt"):
                if regrid:
                    if debug: print("regridding ",pb)
                    imregrid(pb,template=newtemplate,output=inpt+".regrid.wt",asvelocity=asvelocity)
                else:
                    os.system("ln -s "+pb+" "+inpt+".regrid.wt")
            if convolve:
                myia.open(inpt+".regrid.wt")
                myia.setrestoringbeam(major="%farcsec"%maxbm,minor="%farcsec"%maxbm,pa="0deg")
                myia.done()
                
    maskim=output1+".mask"
    if os.path.exists(maskim): shutil.rmtree(maskim)

    if use_immath:
        wt2im=output1+".wt2"
        sumim=output1+".sum"
        if os.path.exists(wt2im): shutil.rmtree(wt2im)
        if os.path.exists(sumim): shutil.rmtree(sumim)

        # weight = pb**2
        for i,inpt in enumerate(inputs1):
            if i==0:
                if debug: print("copying first image ",inpt)
                shutil.copytree(inpt+".regrid.mask",maskim)
                if dowt:
                    immath([inpt+".regrid.wt"],expr="IM0^2",outfile=wt2im)
                    if input_is_pbcor:
                        immath([inpt+suffix+".regrid",inpt+".regrid.wt"],expr="IM0*IM1^2",outfile=sumim)
                    else:
                        immath([inpt+suffix+".regrid",inpt+".regrid.wt"],expr="IM0*IM1",outfile=sumim)
                else:
                    shutil.copytree(inpt+suffix+".regrid",sumim)
                    immath([inpt+suffix+".regrid"],expr="IM0*0+1",outfile=wt2im)
            else:
                if debug: print("adding image ",inpt)
                if os.path.exists(maskim+".tmp"):
                    shutil.rmtree(maskim+".tmp")
                os.rename(maskim,maskim+".tmp")
                immath([maskim+".tmp",inpt+".regrid.mask"],expr="max(IM0,IM1)",
                       outfile=maskim)
    
                if os.path.exists(wt2im+".tmp"):
                    shutil.rmtree(wt2im+".tmp")
                os.rename(wt2im,wt2im+".tmp")
                if os.path.exists(sumim+".tmp"):
                    shutil.rmtree(sumim+".tmp")
                os.rename(sumim,sumim+".tmp")
    
                if dowt:
                    immath([sumim+".tmp",wt2im+".tmp",inpt+suffix+".regrid",inpt+".regrid.wt"],
                           expr="iif(IM0!=0,iif(IM2!=0,IM1+IM3^2,IM1),IM3^2)",
                           outfile=wt2im)
                else:
                    immath([sumim+".tmp",wt2im+".tmp",inpt+suffix+".regrid"],
                            expr="iif(IM0!=0,iif(IM2!=0,IM1+IM2*0+1,IM1),IM2*0+1)",
                           outfile=wt2im)
                myia.open(wt2im)
                myia.maskhandler("delete",['mask0'])
                myia.done()
                makemask(mode="copy",inpimage=wt2im,inpmask=maskim,output=wt2im+":mask0",overwrite=True)
    
                if dowt:
                    if input_is_pbcor:
                        immath([sumim+".tmp",wt2im+".tmp",
                                inpt+suffix+".regrid",inpt+".regrid.wt"],
                               expr="iif(IM0!=0,iif(IM2!=0,IM0*IM1+IM2*IM3^2,IM0),IM2*IM3^2)",
                               outfile=sumim)
                    else:
                        immath([sumim+".tmp",wt2im+".tmp",
                                inpt+suffix+".regrid",inpt+".regrid.wt"],
                               expr="iif(IM0!=0,iif(IM2!=0,IM0*IM1+IM2*IM3,IM0),IM2*IM3)",
                               outfile=sumim)
                else:
                    immath([sumim+".tmp",inpt+suffix+".regrid"],expr='iif(IM0!=0,iif(IM1!=0,IM0+IM1,IM0),IM1)',outfile=sumim)
    
                myia.open(sumim)
                myia.maskhandler("delete",['mask0'])
                myia.done()
                makemask(mode="copy",inpimage=sumim,inpmask=maskim,output=sumim+":mask0",overwrite=True)

        immath([sumim,wt2im],expr="IM0/IM1",outfile=output1)
        if dowt:
            immath([wt2im],expr="sqrt(IM0)",outfile=output1+".wt")
        else:
            shutil.copytree(wt2im,output1+".wt")



    # no immath: 
    else:
        for i,inpt in enumerate(inputs1):
            if i==0:
                if debug: print("reading first image ",inpt)
                myia.open(inpt+".regrid.mask")
                maskdata=myia.getchunk()
                myia.done()
                myia.open(inpt+".regrid.wt")
                wt2data=myia.getchunk()**2
                myia.done()
                myia.open(inpt+".regrid")
                if input_is_pbcor:
                    sumwtdata=myia.getchunk()*wt2data
                else:
                    sumwtdata=myia.getchunk()*np.sqrt(wt2data)
                myia.done()
            else:
                if debug: print("adding image ",inpt)
                myia.open(inpt+".regrid.mask")
                newmaskdata=myia.getchunk()
                myia.done()
                maskdata=np.maximum(maskdata,newmaskdata)
                myia.open(inpt+suffix+".regrid")
                newimdata=myia.getchunk()
                myia.done()
 
                if dowt:
                    myia.open(inpt+".regrid.wt")
                    newwtdata=myia.getchunk()
                    myia.done()
                    wt2data=wt2data+newwtdata**2
                    if input_is_pbcor:
                        sumwtdata=sumwtdata + newimdata*newwtdata**2
                    else:
                        sumwtdata=sumwtdata + newimdata*newwtdata
                else:
                    z=np.where(newmaskdata>0)
                    wt2data[z]=wt2data[z]+1
                    sumwtdata=sumwtdata+newimdata

        # make a copy - will fill its data at the end of the loop
        shutil.copytree(inputs1[0]+".regrid.mask",maskim)
        shutil.copytree(inputs1[0]+suffix+".regrid",output1)
        shutil.copytree(inputs1[0]+suffix+".regrid.wt",output1+".wt")
        myia.open(output1)
        myia.putchunk(sumwtdata/wt2data)
        myia.done()
        myia.open(maskim)
        myia.putchunk(maskdata)
        myia.done()
        if dowt:
            myia.open(output1+".wt")
            myia.putchunk(np.sqrt(wt2data))
            myia.done()
        else:
            myia.open(output1+".wt")
            myia.putchunk(wt2data)
            myia.done()
            
        
                
    myia.open(output1)
    myia.maskhandler("delete",['mask0'])
    myia.done()
    makemask(mode="copy",inpimage=output1,inpmask=maskim,output=output1+":mask0",overwrite=True)

    myia.open(output1+".wt")
    myia.maskhandler("delete",['mask0'])
    myia.done()    
    makemask(mode="copy",inpimage=output1+".wt",inpmask=maskim,output=output1+".wt:mask0",overwrite=True)

    immath([output1,output1+".wt"],expr="IM0*IM1",outfile=output1+".nopbcor")




