# Takeshi Nakazato fix for missing pointing table

def get_cwd():
    """
    Get absolute path to current working directory.
    
    Returns:
        string -- absolute path to current working directory
    """
    return os.path.abspath(os.curdir).rstrip('/')

def is_working_dir():
    """
    Check if current directory is a pipeline "working" directory (i.e. ending in '/working').
    
    Returns:
        bool -- True if current directory is working directory
    """
    return get_cwd().endswith('/working')

def find_PPR():
    """
    Find PPR xml file. Should be run at "working" directory.
    
    Returns:
        string -- name of the PPR xml file
    """
    pprname = ''

    if is_working_dir():
        # try finding PPR at working directory
        pprlist = glob.glob('PPR*.xml')
        if len(pprlist) == 0:
            # no PPR exists. Check rawdata directory
            rawdata_dir = '../rawdata'
            if os.path.exists(rawdata_dir):
                pprlist = glob.glob('{}/PPR*.xml'.format(rawdata_dir))
        
        if len(pprlist) > 1:
            # find something. take the first one.
            pprname = pprlist[0]
    else:
        print('You should move to working directory.')

    return pprname

def get_asdm_list(ppr):
    """
    Get list of ASDM names from PPR xml file.
    
    Arguments:
        ppr {name} -- name of the PPR xml file
    
    Returns:
        string list -- list of ASDM names
    """
    import xml.etree.ElementTree as ET

    tree = ET.parse('../rawdata/PPR.xml')
    root = tree.getroot()

    asdm_list = [x.text for x in root.iter('AsdmDiskName')]

    return asdm_list

def parse_importasdm_last():
    """
    Parse importasdm.last to get configuration information 
    for importasdm.
    
    Returns:
        dict -- template of kwargs for importasdm
    """
    config = {}
    if is_working_dir():
        # importasdm.last should exist
        last = 'importasdm.last'
        if os.path.exists(last):
            with open(last, 'r') as f:
                txt = f.read()

            lines = txt.split('\n')
            keys = [x.split('=')[0].strip() for x in lines if not (x.startswith('#') or len(x) == 0)] 

            # exclude "taskname"
            if 'taskname' in keys:
                keys.pop(keys.index('taskname'))

            exec(txt)
            for k in keys:
                config[k] = locals()[k]
    return config

def run_importasdm():
    """
    Execute importasdm task on all ASDMs written in PPR.
    
    Returns:
        string list -- list of MS names
    """
    template = parse_importasdm_last()
    param_asdm = template['asdm']
    base_asdm = param_asdm[param_asdm.rfind('uid___'):]

    ppr = find_PPR()
    asdm_list = get_asdm_list(ppr)

    vislist = []
    for asdm in asdm_list:
        kwargs = copy.deepcopy(template)
        for k, v in kwargs.items():
            if isinstance(v, str):
                kwargs[k] = v.replace(base_asdm, asdm)
        #print('{}: params {}'.format(asdm, kwargs))

        # if MS doesn't exist, run importasdm
        if not os.path.exists(kwargs['vis']):
            importasdm(**kwargs)

        vislist.append(kwargs['vis'])

    return vislist

def fix_missing_pointing_for_vis(vis):
    """
    Fix missing pointing issue. This function detects antennas that do not 
    have pointing data, and does the following fixes:

        1. add dummy entry to POINTING table for antennas that do not 
           have pointing data
        2. add flag command to flag all the data associating with the 
           antennas without pointing data

    If all the antennas have pointing data, this function does nothing.

    Arguments:
        vis {string} -- MS name
    
    Raises:
        RuntimeError -- POINTING table is empty
        RuntimeError -- All antennas lack their pointing data
    """
    print('fixing {}..'.format(os.path.basename(vis.rstrip('/'))))
    
    pointing_table = vis + '/POINTING'

    antenna_table = vis + '/ANTENNA'

    # check number of antennas
    mytb = createCasaTool(tbtool)
    mytb.open(antenna_table)
    num_antenna = mytb.nrows()
    mytb.close()

    # add dummy entry to POINTING table
    mytb.open(pointing_table, nomodify=False)

    try:
        if mytb.nrows() == 0:
            # No POINTING data at all. No hope!
            raise RuntimeError('No POINTING data!')

        # check which antennas are missing
        antenna_id = mytb.getcol('ANTENNA_ID')
        antenna_list = np.unique(antenna_id)
        missing_antennas = [i for i in range(num_antenna) if i not in antenna_list]

        print('missing antennas: {}'.format(missing_antennas))

        if len(missing_antennas) == 0:
            # POINTING table is valid. Done.
            return
        
        if len(missing_antennas) == num_antenna:
            # All antennas lack pointing data. No hope!
            raise RuntimeError('All antennas lack pointing data!')

        # add dummy entry
        ref_antenna = antenna_list[0]
        tsel = mytb.query('ANTENNA_ID=={}'.format(ref_antenna))
        for missed in missing_antennas:
            nrows = mytb.nrows()
            tsel.copyrows(pointing_table)
            print('appending {} rows to POINTING table'.format(tsel.nrows()))
            nrows2 = mytb.nrows()
            print('nrow: {} nrow2: {}'.format(nrows, nrows2))
            antenna_id = mytb.getcol('ANTENNA_ID')
            antenna_id[nrows:nrows2] = missed
            mytb.putcol('ANTENNA_ID', antenna_id)
        tsel.close()
        
    finally:
        mytb.close()


    # add flag command to flag missing antennas
    flagtemplate = vis.split('.')[0] + '.flagtemplate.txt'
    flagcmds = ["mode='manual' antenna='{0}&&&' reason='QA2:no_pointing_data_for_antenna{0}'\n".format(i) for i in missing_antennas]

    with open(flagtemplate, 'a') as f:
        f.writelines(flagcmds)

def fix_missing_pointing():
    """
    Generage all MSes based on importasdm.last generated by previous 
    pipeline run. Then, apply fix_missing_pointing to all MSes.
    
    Raises:
        RuntimeError -- current directory is not "working"
    """
    # we should be in 'working' directory
    if not is_working_dir():
        raise RuntimeError('Please move to working directory')

    # get full list of MSs. generate them if not exist
    vislist = run_importasdm()

    # perform fix to each MS
    for vis in vislist:
        fix_missing_pointing_for_vis(vis)

def mapSpwChannelToTsysChannel(vis, spw, channel, field=0, mymsmd=''):
    """
    Given a science spectral window and channel number, compute the
    spw and channel number of the corresponding Tsys spw that is 
    nearest in frequency to the science channel.  Uses msmd.
    spw: integer or string integer
    channel: integer or string integer, or a list or array thereof
    field: integer ID or string integer ID (not name)
    Returns: Tsys spw number and channel number (or list if channel is list)
    -Todd Hunter
    """
    needToClose = False
    spw = int(spw)
    field = int(field)
    if mymsmd == '':
        mymsmd = createCasaTool(msmdtool)
        mymsmd.open(vis)
        needToClose = True
    tsysspw = tsysspwmapWithNoTable(vis, field, spw, mymsmd=mymsmd)    
    # get frequency from channel
    chanfreqs = mymsmd.chanfreqs(spw)
    if type(channel) == list or type(channel) == np.ndarray:
        channels = channel
    else:
        channels = [channel]
    mychannels = []
    for channel in channels:
        if int(channel) >= len(chanfreqs):
            print("Invalid channel (%d) for this spw, which has only %d channels" % (channel, len(chanfreqs)))
            if needToClose:
                mymsmd.close()
            return
        freq = chanfreqs[int(channel)]
        freqs = mymsmd.chanfreqs(tsysspw)
        mychannel = np.argmin(np.abs(freqs-freq))
        mychannels.append(mychannel)
    if needToClose:
        mymsmd.close()
    if len(mychannels) == 1:  # return single channel
        return tsysspw, mychannels[0]
    else:  # return list of channels
        return tsysspw, mychannels

def lowTransmissionChannels(vis, spw, intent='OBSERVE_TARGET#ON_SOURCE', 
                            thresholdPerScan=0.1, hanning=False, verbose=False):
    """
    Checks each scan in a dataset for its atmospheric transmission at target 
    elevation (using median PWV for whole dataset) and make a list of channels 
    which are below thresholdPerScan transmission in any scan.
    Returns: string (e.g. '0~345')
    -Todd Hunter
    """
    if not os.path.exists(vis):
        print("could not find measurement set")
        return
    mymsmd = createCasaTool(msmdtool)
    if type(intent) == str:
        intents = intent.split(',')
    else:
        intents = intent
    print("Processing ", os.path.basename(vis))
    pwv = getMedianPWV(vis)[0]
    # find all science target sources names
    # pick one field for each name
    mymsmd.open(vis)
    targets = []
    fields = []
    if intent not in mymsmd.intents():
        print("Available intents: ", mymsmd.intents())
        mymsmd.close()
        return
    for myintent in intents:
        a, b = getScienceTargets(vis, unique=True, mymsmd=mymsmd, intent=myintent)
        targets += list(a)
        fields += list(b)
    print("targets[%s] = %s" % (os.path.basename(vis),targets))
    print("fields[%s] = %s" % (os.path.basename(vis),fields))
    scans = {}
    airmass = {}
    for field in fields:
        myscans = []
        for myintent in intents:
            print("Calling au.getScienceScans('%s', '%s', intent='%s')" % (os.path.basename(vis),field,myintent))
            myresult = getScienceScans(vis, field, mymsmd=mymsmd, intent=myintent)
            myscans += list(myresult)
        scans[field] = myscans
        print("Scans = ", myscans)
        airmass[field] = {}
        # find mean airmass of each scan on this field
        for scan in myscans:
            if verbose: print("Calling au.meanAirmassForScan('%s', %d)" % (vis,scan))
            airmass[field][scan] = meanAirmassForScan(vis, scan, mymsmd=mymsmd, verbose=False)
    spwfreqs = mymsmd.chanfreqs(spw) * 1e-9 # Hz to GHz
    channels = range(len(spwfreqs))
    transmission = {}
    lowtrans = []
    for field in fields:
        for scan in scans[field]:
            if len(channels) > 256:
                # first try it at low-resolution to save time
                myspwfreqs = np.linspace(np.min(spwfreqs), np.max(spwfreqs), 128)
                freq, chans, trans, TebbSky, opacity = CalcAtmosphere(128, myspwfreqs, pwv=pwv, 
                                                      airmass=airmass[field][scan], hanning=hanning, verbose=verbose)
                mylowtrans = np.where(np.array(trans) < thresholdPerScan)[0]
                if len(mylowtrans) == 0:
                    continue
            nchan = len(spwfreqs)
            # transmission is on 0..1 scale
            freq, chans, trans, TebbSky, opacity = CalcAtmosphere(channels, spwfreqs, pwv=pwv, airmass=airmass[field][scan], hanning=hanning, verbose=verbose)
            transmission[scan] = np.array(trans)
            mylowtrans = np.where(transmission[scan] < thresholdPerScan)[0]
            #
            if len(mylowtrans) > 0:
                channel = [np.min(mylowtrans), np.max(mylowtrans)]
                tsysspw, channels = mapSpwChannelToTsysChannel(vis, spw, channel, mymsmd=mymsmd)
                chan0,chan1 = channels
                print("Scan %d (airmass=%.4f) in %d/%d channels of spw %d (Tsys spw%d: %d~%d) median trans. of flagged channels: %.4f" % (scan, airmass[field][scan], len(mylowtrans), nchan, spw, tsysspw, chan0, chan1, np.median(transmission[scan][mylowtrans])))
                lowtrans += list(mylowtrans)
            else:
                print("No low transmission channels found in spw %d on scan %d (airmass=%.2f, median transmission = %f)" % (spw, scan, airmass[field][scan], np.median(trans)))
    lowtrans = sorted(np.unique(lowtrans))
    lowtransList = channelSelectionArrayToRangeString(lowtrans) # splitListIntoContiguousLists(lowtrans, makeSingleValuesAList=True)
    mymsmd.close()
    return lowtransList

def generateLowTransmissionFlags(workingdir, thresholdPerScan=0.1, hanning=False, perScanFlags=False,
                                 thresholdGlobal=0.6, verbose=False, intent='*TARGET*'):
    """
    Written for CASR-520 (previously known as PIPE-405).o
    Given a pipeline working dir, computes a flagtemplate.txt file that flags
    low transmission channels in the OBSERVE_TARGET scans.  This file will be 
    written to the current working directory (not the pipeline working directory).  
    If you lack permission, then it will be written to /tmp.
    workingdir: either a pipeline run parent directory, or its working directory, or a single .ms, or a
         comma-delimited list of ms, or a string with wildcard
    hanning: passed to CalcAtmosphere()
    verbose: passed to CalcAtmosphere()
    perScanFlags: if True, then flag individual scans with potentially different list of channels each scan; 
                  if False, then only flag entire pws
    thresholdPerScan: used if perScanFlags==True
    thresholdGlobal: fraction of data that must be low transmission for whole spw to be flagged
    intent: a single intent, or comma-delimited list; wildcards can be used with the shortened name
    Returns: list of flagtemplate files created
    """
    if workingdir[-3:] == '.ms':
        if workingdir.find('*') >= 0:
            vislist = sorted(glob.glob(workingdir))
        else:
            vislist = workingdir.split(',')
    else:
        if workingdir.find('/working') < 0 and workingdir not in ['','./','.']:
            workingdir = findPipelineWorkingDirectory(workingdir, fast=True)
        # find list of all ms
        vislist = sorted(findPipelineMeasurementSets(workingdir))
    pwv = {}
    targets = {}
    fields = {}
    scans = {}
    spwfreqs = {}
    channels = {}
    airmass = {}
    spws = {}
    mymsmd = createCasaTool(msmdtool)
    if type(intent) == str:
        intents = intent.split(',')
    else:
        intents = intent
    for vis in vislist:
        print("Processing ", os.path.basename(vis))
        pwv[vis] = getMedianPWV(vis)[0]
        # find all science target sources names
        # pick one field for each name
        mymsmd.open(vis)
        targets[vis] = []
        fields[vis] = []
        for myintent in intents:
            a, b = getScienceTargets(vis, unique=True, mymsmd=mymsmd, intent=myintent)
            targets[vis] += list(a)
            fields[vis] += list(b)
        print("targets[%s] = %s" % (os.path.basename(vis),targets[vis]))
#        print("fields[%s] = %s" % (os.path.basename(vis),fields[vis]))
        scans[vis] = {}
        airmass[vis] = {}
        for field in fields[vis]:
            myscans = []
            for myintent in intents:
#                print("Calling au.getScienceScans('%s', '%s', intent='%s')" % (os.path.basename(vis),field,myintent))
                myresult = getScienceScans(vis, field, mymsmd=mymsmd, intent=myintent)
                myscans += list(myresult)
            scans[vis][field] = myscans
            airmass[vis][field] = {}
            # find mean airmass of each scan on this field
            for scan in myscans:
                if verbose: print("Calling au.meanAirmassForScan('%s', %d)" % (vis,scan))
                airmass[vis][field][scan] = meanAirmassForScan(vis, scan, mymsmd=mymsmd, verbose=False)
        spws[vis] = getScienceSpws(vis, mymsmd=mymsmd, returnString=False) # intent not necessary if BANDPASS or TARGET used
        spwfreqs[vis] = {}
        channels[vis] = {}
        for spw in spws[vis]:
            spwfreqs[vis][spw] = mymsmd.chanfreqs(spw) * 1e-9 # Hz to GHz
            channels[vis][spw] = range(len(spwfreqs[vis][spw]))
        mymsmd.close()
#    print(pwv, targets, fields, scans, airmass, spwfreqs)
    # compute transmission at that airmassfor each spw at native spectral resolution
    transmission = {}
    filenames = []
    visScanChannels = {}
    visScanChannelsLowTransmission = {}
    for vis in vislist:
        for spw in spws[vis]:
            # this will at least not crash when virtual spw IDs are in use; but will not combine matching spws either
            if spw not in visScanChannels:
                visScanChannels[spw] = 0
                visScanChannelsLowTransmission[spw] = 0
        print("Processing ", os.path.basename(vis))
        outlines = []
        print("Median PWV for %s is %f" % (os.path.basename(vis), pwv[vis]))
        transmission[vis] = {}
        for field in fields[vis]:
            for scan in scans[vis][field]:
                for spw in spws[vis]:
                    visScanChannels[spw] += len(channels[vis][spw])
                    if len(channels[vis][spw]) > 256:
                        # first try it at low-resolution to save time
                        myspwfreqs = np.linspace(np.min(spwfreqs[vis][spw]), np.max(spwfreqs[vis][spw]), 128)
                        freq, chans, trans, TebbSky, opacity = CalcAtmosphere(128, myspwfreqs, pwv=pwv[vis], 
                                                              airmass=airmass[vis][field][scan], hanning=hanning, verbose=verbose)
                        lowtrans = np.where(np.array(trans) < thresholdPerScan)[0]
                        if len(lowtrans) == 0:
#                            print("No low transmission channels found in low-resolution spectrum of spw %d on scan %d." % (spw, scan))
                            continue
                    nchan = len(spwfreqs[vis][spw])
                    # transmission is on 0..1 scale
                    freq, chans, trans, TebbSky, opacity = CalcAtmosphere(channels[vis][spw], spwfreqs[vis][spw], pwv=pwv[vis], 
                                                              airmass=airmass[vis][field][scan], hanning=hanning, verbose=verbose)
                    transmission[vis][scan] = np.array(trans)
                    lowtrans = np.where(transmission[vis][scan] < thresholdPerScan)[0]
                    if len(lowtrans) > 0:
                        visScanChannelsLowTransmission[spw] += len(lowtrans)
                        print("Scan %d (airmass=%.2f) in %d/%d channels of spw %d (median transmission of flagged channels = %f)" % (scan, airmass[vis][field][scan], len(lowtrans), nchan, spw, np.median(transmission[vis][scan][lowtrans])))
                        lowtransLists = splitListIntoContiguousLists(lowtrans, makeSingleValuesAList=True)
                        for lowtransList in lowtransLists:
                            outline = "mode='manual' scan='%d' spw='%d:%d~%d' reason='low_transmission'\n" % (scan, spw, lowtransList[0], lowtransList[-1])
                            outlines.append(outline)
                            if perScanFlags:
                                print(outline)
                    else:
                        print("No low transmission channels found in spw %d on scan %d (airmass=%.2f, median transmission = %f)" % (spw, scan, airmass[vis][field][scan], np.median(trans)))
        if len(outlines) > 0 and perScanFlags:
            # Here, we could consolidate the flags, for example to be the 
            # same channel ranges on all scans.
            filename = '%s.flagtemplate.txt' % (os.path.basename(vis).replace('.ms',''))
            if not os.access(os.getcwd(), os.W_OK):
                filename = os.path.join('/tmp',filename)
            f = open(filename, 'a')
            f.write(outline)
            f.close()
            filenames.append(filename)
    if not perScanFlags:
        # only flag entire spws
        for spw in visScanChannels.keys():  #spws[vislist[0]]:
            fractionLow = float(visScanChannelsLowTransmission[spw]) / visScanChannels[spw]
            if fractionLow > thresholdGlobal:
                print("Fraction meets threshold: %d/%d=%f" % (visScanChannelsLowTransmission[spw], visScanChannels[spw], fractionLow))
                outline = "mode='manual' spw='%d' reason='low_transmission'\n" % (spw)
                print(outline)
                for vis in vislist:
                    filename = '%s.flagtemplate.txt' % (os.path.basename(vis).replace('.ms',''))
                    if not os.access(os.getcwd(), os.W_OK):
                        filename = os.path.join('/tmp',filename)
                    f = open(filename, 'a')
                    f.write(outline)
                    f.close()
                    filenames.append(filename)
            else:
                print("spw%d: Fraction does not meet threshold: %d/%d=%f" % (spw, visScanChannelsLowTransmission[spw], visScanChannels[spw], fractionLow))

        
    filenames = np.unique(filenames)
    print("Created %d flag template files" % (len(filenames)))
    for f in filenames:
        print("  %s" % (f))
    return(filenames)

